/**
 * NIRVTRACK - Personal Finance Application
 * Power BI Executive Theme & Analytics Engine
 * With Dynamic Categories, Semi-Monthly Income (15th & 30th), and Theme Customization
 */

// ==========================================
// 0. NIRVTRACK PATCH NOTES & VERSION REGISTRY
// ==========================================
/**
 * NIRVTRACK PATCH NOTES & VERSION REGISTRY
 * ----------------------------------------------------------------------------
 * To log a new release / update:
 * Simply add a new patch note object to the top of APP_PATCH_NOTES below.
 * The entire application (Sidebar version pill, Settings Drawer info, Patch Notes
 * modal, Spotlight Command Palette, and NirvTrack AI Copilot) will automatically
 * sync to that version (v1.#########) and surface all new features!
 */
const APP_PATCH_NOTES = (typeof window !== 'undefined' && Array.isArray(window.APP_PATCH_NOTES) && window.APP_PATCH_NOTES.length > 0)
  ? window.APP_PATCH_NOTES
  : [];

function getAppVersion() {
  return (Array.isArray(APP_PATCH_NOTES) && APP_PATCH_NOTES.length > 0)
    ? APP_PATCH_NOTES[0].version
    : 'v1.20261019.03';
}

function getAppVersionDate() {
  return (Array.isArray(APP_PATCH_NOTES) && APP_PATCH_NOTES.length > 0)
    ? APP_PATCH_NOTES[0].date
    : 'October 19, 2026';
}

function getLatestPatchNote() {
  return (Array.isArray(APP_PATCH_NOTES) && APP_PATCH_NOTES.length > 0)
    ? APP_PATCH_NOTES[0]
    : null;
}

const APP_VERSION = getAppVersion();

function registerPatchNote(newRelease) {
  if (!newRelease || !newRelease.version) return;
  APP_PATCH_NOTES.unshift(newRelease);
  syncAppVersionUI();
}

function syncAppVersionUI() {
  const currentVer = getAppVersion();
  const currentVerDate = getAppVersionDate();

  const sidebarVerEl = document.getElementById('sidebarVersionDisplay');
  if (sidebarVerEl) sidebarVerEl.textContent = currentVer;

  // Update Browser Tab Title to include the latest version number
  try {
    document.title = `NirvTrack ${currentVer} - Monthly Budget & Expense Tracker`;
  } catch (e) {}

  // Update Brand Logo Version Badge (Desktop Sidebar & Mobile Header)
  const brandPatchEl = document.getElementById('brandPatchBadge');
  if (brandPatchEl) {
    brandPatchEl.textContent = currentVer;
    brandPatchEl.title = `Latest Release: ${currentVer} (Click to view Patch Notes)`;
  }
  const mobileBrandVerEl = document.getElementById('mobileBrandVersionBadge');
  if (mobileBrandVerEl) {
    mobileBrandVerEl.textContent = currentVer;
  }

  const sidebarBadge = document.getElementById('sidebarVersionBadge');
  if (sidebarBadge) {
    const lastSeen = localStorage.getItem('nirvtrack_seen_patch_version');
    if (lastSeen !== currentVer) {
      sidebarBadge.textContent = 'New ✨';
      sidebarBadge.classList.add('unread');
      sidebarBadge.title = `New update available (${currentVer})! Click to view patch notes.`;
    } else {
      sidebarBadge.textContent = 'Patch Notes';
      sidebarBadge.classList.remove('unread');
      sidebarBadge.title = 'View release changelog and patch notes';
    }
  }

  const drawerVerEl = document.getElementById('toolsDrawerVersionDisplay');
  if (drawerVerEl) drawerVerEl.textContent = currentVer;
  const drawerDateEl = document.getElementById('toolsDrawerVersionDate');
  if (drawerDateEl) drawerDateEl.textContent = `Released ${currentVerDate}`;

  const modalVerEl = document.getElementById('patchNotesModalVersionText');
  if (modalVerEl) modalVerEl.textContent = currentVer;

  const releaseCountEl = document.getElementById('patchNotesReleaseCount');
  if (releaseCountEl) releaseCountEl.textContent = `${APP_PATCH_NOTES.length} releases logged`;
}

let currentPatchFilter = 'all';
let currentPatchQuery = '';
let areAllPatchDetailsCollapsed = false;

function openPatchNotesModal(filter = 'all', query = '', forceExpanded = false) {
  const modal = document.getElementById('patchNotesModal');
  if (!modal) return;
  modal.classList.add('active');

  // Check saved expand state or forceExpanded
  const shouldExpand = forceExpanded || localStorage.getItem('nirvtrack_patch_modal_expanded') === 'true';
  modal.classList.toggle('patch-notes-expanded-wide', shouldExpand);
  updatePatchExpandButtonUI(shouldExpand);

  // Sync auto-show checkbox state
  const chkAuto = document.getElementById('chkAutoShowPatchNotesOnLogin');
  if (chkAuto) {
    chkAuto.checked = localStorage.getItem('nirvtrack_auto_show_patch_on_login') !== 'false';
  }

  // Mark current version as read
  const currentVer = getAppVersion();
  localStorage.setItem('nirvtrack_seen_patch_version', currentVer);
  const sidebarBadge = document.getElementById('sidebarVersionBadge');
  if (sidebarBadge) {
    sidebarBadge.textContent = 'Patch Notes';
    sidebarBadge.classList.remove('unread');
  }

  currentPatchFilter = filter || 'all';
  currentPatchQuery = query || '';

  const searchInput = document.getElementById('patchNotesSearchInput');
  if (searchInput) {
    searchInput.value = currentPatchQuery;
    const clearBtn = document.getElementById('btnClearPatchNotesSearch');
    if (clearBtn) clearBtn.style.display = currentPatchQuery ? 'block' : 'none';
  }

  const filterPills = document.querySelectorAll('.btn-patch-filter');
  filterPills.forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-filter') === currentPatchFilter);
  });

  renderPatchNotes(currentPatchQuery, currentPatchFilter);
}

function closePatchNotesModal() {
  const modal = document.getElementById('patchNotesModal');
  if (modal) modal.classList.remove('active');
}

function togglePatchNotesExpand() {
  const modal = document.getElementById('patchNotesModal');
  if (!modal) return;
  const isNowExpanded = !modal.classList.contains('patch-notes-expanded-wide');
  modal.classList.toggle('patch-notes-expanded-wide', isNowExpanded);
  localStorage.setItem('nirvtrack_patch_modal_expanded', isNowExpanded ? 'true' : 'false');
  updatePatchExpandButtonUI(isNowExpanded);
}

function updatePatchExpandButtonUI(isExpanded) {
  const btn = document.getElementById('btnPatchExpandToggle');
  const icon = document.getElementById('patchExpandToggleIcon');
  const label = document.getElementById('patchExpandToggleLabel');
  if (btn) btn.classList.toggle('active', isExpanded);
  if (icon) icon.textContent = isExpanded ? '🗂️' : '🛑';
  if (label) label.textContent = isExpanded ? 'Compact' : 'Expand';
}

function toggleAllPatchDetails() {
  const container = document.getElementById('patchNotesTimelineContainer');
  if (!container) return;
  areAllPatchDetailsCollapsed = !areAllPatchDetailsCollapsed;

  const lists = container.querySelectorAll('.patch-features-list');
  const btns = container.querySelectorAll('.patch-card-toggle-btn');
  lists.forEach(el => el.classList.toggle('collapsed', areAllPatchDetailsCollapsed));
  btns.forEach(btn => btn.textContent = areAllPatchDetailsCollapsed ? '▼' : '▲');

  const iconEl = document.getElementById('toggleAllPatchDetailsIcon');
  const labelEl = document.getElementById('toggleAllPatchDetailsLabel');
  if (iconEl) iconEl.textContent = areAllPatchDetailsCollapsed ? '▲' : '▼';
  if (labelEl) labelEl.textContent = areAllPatchDetailsCollapsed ? 'Expand All' : 'Collapse All';
}

function togglePatchCardDetails(btn) {
  if (!btn) return;
  const card = btn.closest('.patch-release-card');
  if (!card) return;
  const list = card.querySelector('.patch-features-list');
  if (!list) return;
  const isNowCollapsed = !list.classList.contains('collapsed');
  list.classList.toggle('collapsed', isNowCollapsed);
  btn.textContent = isNowCollapsed ? '▼' : '▲';
}

function checkAndShowPatchNotesOnLogin(user, force = false) {
  try {
    const autoShowSetting = localStorage.getItem('nirvtrack_auto_show_patch_on_login') !== 'false';
    if (!autoShowSetting && !force) return;

    const sessionKey = 'nirvtrack_patch_shown_session';
    const alreadyShownSession = sessionStorage.getItem(sessionKey);
    const lastSeenVersion = localStorage.getItem('nirvtrack_seen_patch_version');
    const currentVersion = getAppVersion();

    // If new version OR first login this session OR force requested:
    if (force || lastSeenVersion !== currentVersion || !alreadyShownSession) {
      sessionStorage.setItem(sessionKey, 'true');
      setTimeout(() => {
        openPatchNotesModal('all', '', true); // true = open in expanded wide view!
      }, 500);
    }
  } catch (err) {
    console.warn('Error in checkAndShowPatchNotesOnLogin:', err);
  }
}

