window.testPatchFeature = function(tag, actionCode) {
  try {
    if (navigator.vibrate) navigator.vibrate([15, 30, 20]);
    if (typeof showToast === 'function') {
      showToast(`Testing ${tag || 'feature'}... 🚀`, 'info');
    }
    
    if (actionCode === 'openCoverOverspendModal()') {
      const pModal = document.getElementById('patchNotesModal');
      if (pModal) pModal.classList.remove('active');
      if (typeof openCoverOverspendModal === 'function') {
        openCoverOverspendModal();
      } else {
        if (typeof showToast === 'function') showToast('Cover Overspend modal ready on Dashboard category cards!', 'success');
      }
    } else if (actionCode === 'openIncomeLedgerModal()') {
      const pModal = document.getElementById('patchNotesModal');
      if (pModal) pModal.classList.remove('active');
      if (typeof switchTab === 'function') switchTab('budget');
      if (typeof openIncomeLedgerModal === 'function') {
        openIncomeLedgerModal();
      } else {
        if (typeof showToast === 'function') showToast('Income Ledger ready on Monthly Income Schedule card!', 'success');
      }
    } else if (actionCode === 'openReconcileWalletModal()') {
      const pModal = document.getElementById('patchNotesModal');
      if (pModal) pModal.classList.remove('active');
      if (typeof openReconcileWalletModal === 'function') {
        openReconcileWalletModal();
      } else {
        if (typeof showToast === 'function') showToast('Reconcile Wallets ready on Accounts strip!', 'success');
      }
    } else if (actionCode === 'testPaydayHorizonToggle()') {
      const pModal = document.getElementById('patchNotesModal');
      if (pModal) pModal.classList.remove('active');
      if (typeof switchTab === 'function') switchTab('dashboard');
      const pill = document.querySelector('.payday-horizon-toggle') || document.getElementById('paydayHorizonToggleContainer');
      if (pill) {
        pill.classList.add('nirv-spotlight-active');
        pill.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => pill.classList.remove('nirv-spotlight-active'), 3600);
      }
      if (typeof showToast === 'function') showToast('Switched to Dashboard: Payday Horizon highlighted! 📅', 'success');
    } else if (actionCode === 'testTactileSpring()') {
      if (typeof showToast === 'function') showToast('Spring tactile press verified (:active scaling)! 🎯', 'success');
    } else if (actionCode === 'triggerTestHaptic()') {
      if (navigator.vibrate) {
        navigator.vibrate([25, 40, 30]);
        if (typeof showToast === 'function') showToast('📲 Native haptic pulse emitted!', 'success');
      } else {
        if (typeof showToast === 'function') showToast('Haptic supported on mobile devices! Simulated pulse 📲', 'info');
      }
    } else if (actionCode === 'focusQuickAddBar()') {
      const pModal = document.getElementById('patchNotesModal');
      if (pModal) pModal.classList.remove('active');
      if (typeof switchTab === 'function') switchTab('dashboard');
      const input = document.getElementById('dashboardQuickAddInput') || document.getElementById('quickAddInput');
      if (input) {
        input.classList.add('nirv-spotlight-active');
        input.focus();
        setTimeout(() => input.classList.remove('nirv-spotlight-active'), 3600);
        if (typeof showToast === 'function') showToast('Quick-Add input focused and ready! ⚡', 'success');
      }
    } else if (actionCode === 'testCreditCardPayoffMode()') {
      const pModal = document.getElementById('patchNotesModal');
      if (pModal) pModal.classList.remove('active');
      if (typeof openAddExpenseModal === 'function') {
        openAddExpenseModal();
        setTimeout(() => {
          const toggle = document.getElementById('expenseExcludeBudgetGroup') || document.getElementById('expenseExcludeBudget');
          if (toggle) {
            toggle.classList.add('nirv-spotlight-active');
            setTimeout(() => toggle.classList.remove('nirv-spotlight-active'), 3600);
          }
        }, 200);
      }
      if (typeof showToast === 'function') showToast('Add Expense opened: CC Statement Payoff toggle highlighted! 💳', 'success');
    } else if (actionCode === 'testCashflowCushion()') {
      const pModal = document.getElementById('patchNotesModal');
      if (pModal) pModal.classList.remove('active');
      if (typeof switchTab === 'function') switchTab('dashboard');
      const widget = document.getElementById('cashflowCushionWidget') || document.querySelector('[data-widget-id="widget-cashflow-cushion"]');
      if (widget) {
        widget.classList.add('nirv-spotlight-active');
        widget.scrollIntoView({ behavior: 'smooth', block: 'center' });
        setTimeout(() => widget.classList.remove('nirv-spotlight-active'), 3600);
      }
      if (typeof showToast === 'function') showToast('Switched to Dashboard: Cashflow Cushion highlighted! 📊', 'success');
    } else if (actionCode === 'testPatchFeatureEngine()') {
      if (typeof showToast === 'function') showToast('🎮 Patch Notes Interactive GUI Engine is fully operational!', 'success');
    } else {
      const fnName = actionCode.replace(/\(\)$/, '');
      if (typeof window[fnName] === 'function') {
        window[fnName]();
      } else {
        try {
          new Function(actionCode)();
        } catch (e) {
          console.warn('[PatchGUI] Test action fallback:', e);
        }
      }
    }
  } catch (err) {
    console.error('[PatchGUI] Error executing test action:', err);
  }
};

function renderPatchNotes(query = '', filter = 'all') {
  const container = document.getElementById('patchNotesTimelineContainer');
  if (!container) return;

  const q = String(query || '').toLowerCase().trim();
  const f = String(filter || 'all').toLowerCase().trim();

  const filtered = APP_PATCH_NOTES.filter(rel => {
    if (f !== 'all') {
      const hasMatchingFeature = (rel.features || []).some(feat => feat.type === f);
      if (!hasMatchingFeature) return false;
    }
    if (!q) return true;
    const inVersion = String(rel.version || '').toLowerCase().includes(q);
    const inTitle = String(rel.title || '').toLowerCase().includes(q);
    const inSummary = String(rel.summary || '').toLowerCase().includes(q);
    const inFeatures = (rel.features || []).some(feat =>
      String(feat.title || '').toLowerCase().includes(q) ||
      String(feat.desc || '').toLowerCase().includes(q) ||
      String(feat.tag || '').toLowerCase().includes(q)
    );
    return inVersion || inTitle || inSummary || inFeatures;
  });

  const countEl = document.getElementById('patchNotesReleaseCount');
  if (countEl) {
    countEl.textContent = `${filtered.length} release${filtered.length === 1 ? '' : 's'} found`;
  }

  if (filtered.length === 0) {
    container.innerHTML = `
      <div style="text-align: center; padding: 40px 20px; color: #94a3b8;">
        <div style="font-size: 2.2rem; margin-bottom: 10px;">🔍</div>
        <h4 style="margin: 0 0 6px 0; color: #f1f5f9; font-size: 1rem;">No matching patch notes</h4>
        <p style="margin: 0; font-size: 0.8rem;">Try clearing your search or switching filter categories.</p>
      </div>
    `;
    return;
  }

  const safeEscape = (str) => {
    if (typeof escapeHtml === 'function') return escapeHtml(str);
    if (typeof escapeHTML === 'function') return escapeHTML(str);
    return String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  };

  const tagLabelMap = {
    feature: { label: '🚀 Feature', class: 'patch-tag-feature' },
    security: { label: '🔒 Security', class: 'patch-tag-security' },
    improvement: { label: '⚡ Enhanced', class: 'patch-tag-improvement' },
    fix: { label: '🐛 Bug Fix', class: 'patch-tag-fix' }
  };

  const html = filtered.map((rel, idx) => {
    const isLatest = idx === 0 && !q && f === 'all';
    const badgeCls = rel.badgeType || (isLatest ? 'latest' : 'major');

    const visibleFeatures = (rel.features || []).filter(feat => {
      if (f !== 'all' && feat.type !== f) return false;
      if (q) {
        const inFeat = String(feat.title || '').toLowerCase().includes(q) ||
                       String(feat.desc || '').toLowerCase().includes(q) ||
                       String(feat.tag || '').toLowerCase().includes(q);
        const inHeader = String(rel.version || '').toLowerCase().includes(q) ||
                         String(rel.title || '').toLowerCase().includes(q) ||
                         String(rel.summary || '').toLowerCase().includes(q);
        return inFeat || inHeader;
      }
      return true;
    });

    const featuresHtml = visibleFeatures.map(feat => {
      const meta = tagLabelMap[feat.type] || tagLabelMap.feature;
      const tagPill = feat.tag ? `<span class="patch-feature-tag-id">${safeEscape(feat.tag)}</span>` : '';
      
      const guiDescriptor = feat.gui || (typeof getFeatureGuiPreview === 'function' ? getFeatureGuiPreview(feat) : null);
      let guiHtml = '';
      if (guiDescriptor && guiDescriptor.previewHtml) {
        const actionBtn = guiDescriptor.actionCode ? `
          <button type="button" class="btn-patch-test-action" onclick="testPatchFeature('${safeEscape(feat.tag || '')}', '${safeEscape(guiDescriptor.actionCode || '')}')">
            ${safeEscape(guiDescriptor.actionLabel || 'Try It Live 🚀')}
          </button>
        ` : '';
        guiHtml = `
          <div class="patch-feature-gui-preview">
            <div class="patch-gui-header">
              <span class="patch-gui-pill">🎮 Live Component Preview</span>
              <span style="font-size: 0.65rem; color: #94a3b8;">Interactive Sandbox</span>
            </div>
            <div class="patch-gui-content">
              ${guiDescriptor.previewHtml}
            </div>
            ${actionBtn ? `<div class="patch-gui-footer">${actionBtn}</div>` : ''}
          </div>
        `;
      }

      return `
        <div class="patch-feature-item">
          <span class="patch-feature-tag ${meta.class}">${meta.label}</span>
          <div class="patch-feature-text">
            <strong>${safeEscape(feat.title)}</strong>${tagPill}: ${safeEscape(feat.desc)}
            ${guiHtml}
          </div>
        </div>
      `;
    }).join('');

    return `
      <div class="patch-release-card ${isLatest ? 'is-latest' : ''}">
        <div class="patch-release-header">
          <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
            <span class="patch-release-vpill">${safeEscape(rel.version)}</span>
            ${rel.badge ? `<span class="patch-release-badge ${badgeCls}">${safeEscape(rel.badge)}</span>` : ''}
            <span class="patch-release-date" style="margin-left: 4px;">📅 ${safeEscape(rel.date)}</span>
          </div>
          <div style="display: flex; align-items: center; gap: 6px;">
            <button type="button" class="patch-card-toggle-btn" title="Toggle feature details" onclick="togglePatchCardDetails(this)">▲</button>
          </div>
        </div>
        <h4 class="patch-release-title">${safeEscape(rel.title)}</h4>
        <p class="patch-release-summary">${safeEscape(rel.summary)}</p>
        <div class="patch-features-list">
          ${featuresHtml}
        </div>
      </div>
    `;
  }).join('');

  container.innerHTML = html;
}

function setupPatchNotesEventListeners() {
  const searchInput = document.getElementById('patchNotesSearchInput');
  const clearBtn = document.getElementById('btnClearPatchNotesSearch');
  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      currentPatchQuery = e.target.value;
      if (clearBtn) clearBtn.style.display = currentPatchQuery ? 'block' : 'none';
      renderPatchNotes(currentPatchQuery, currentPatchFilter);
    });
  }
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      if (searchInput) {
        searchInput.value = '';
        searchInput.focus();
      }
      currentPatchQuery = '';
      clearBtn.style.display = 'none';
      renderPatchNotes('', currentPatchFilter);
    });
  }

  const filterContainer = document.getElementById('patchNotesFilterPills');
  if (filterContainer) {
    filterContainer.addEventListener('click', (e) => {
      const btn = e.target.closest('.btn-patch-filter');
      if (!btn) return;
      filterContainer.querySelectorAll('.btn-patch-filter').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentPatchFilter = btn.getAttribute('data-filter') || 'all';
      renderPatchNotes(currentPatchQuery, currentPatchFilter);
    });
  }

  const btnExpand = document.getElementById('btnPatchExpandToggle');
  if (btnExpand) {
    btnExpand.addEventListener('click', togglePatchNotesExpand);
  }

  const btnToggleAll = document.getElementById('btnToggleAllPatchDetails');
  if (btnToggleAll) {
    btnToggleAll.addEventListener('click', toggleAllPatchDetails);
  }

  const chkAutoShow = document.getElementById('chkAutoShowPatchNotesOnLogin');
  if (chkAutoShow) {
    chkAutoShow.addEventListener('change', (e) => {
      localStorage.setItem('nirvtrack_auto_show_patch_on_login', e.target.checked ? 'true' : 'false');
    });
  }

  const modal = document.getElementById('patchNotesModal');
  if (modal) {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        closePatchNotesModal();
      }
    });
  }
}

