/**
 * Returns 'needs' or 'wants' for a category ID with robust backward-compatible fallback.
 */
function getCategoryBudgetType(categoryId) {
  if (!categoryId) return 'needs';
  const cat = (appState.categories || []).find(c => c.id === categoryId);
  if (cat && cat.budgetType) return cat.budgetType;
  const wantsList = ['entertainment', 'shopping', 'miscellaneous', 'dining', 'lifestyle', 'travel', 'hobby', 'hobbies'];
  if (wantsList.includes(String(categoryId).toLowerCase())) return 'wants';
  return 'needs';
}

