/**
 * [FEAT-36] Detects whether the current client is a mobile phone or tablet.
 * Evaluates mobile user agents, iPadOS touch signatures, and viewport/touch geometry.
 * When true, Mobile Pocket UI is permanently enforced for the device.
 */
function isMobileOrTabletDevice() {
  try {
    const ua = navigator.userAgent || navigator.vendor || window.opera || '';
    const isMobileUA = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini|Mobile|mobile|Silk|Kindle|Tablet/i.test(ua);
    const isIPadOS = (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
    const isNarrowViewport = (window.innerWidth <= 1024);
    
    return isMobileUA || isIPadOS || isNarrowViewport;
  } catch (e) {
    return window.innerWidth <= 1024;
  }
}
window.isMobileOrTabletDevice = isMobileOrTabletDevice;

