  if (btnOpenFAQ) btnOpenFAQ.addEventListener('click', openFAQModal);

  const btnSidebarFAQ = document.getElementById('btnSidebarFAQ');
  if (btnSidebarFAQ) btnSidebarFAQ.addEventListener('click', openFAQModal);

