function getRandomCategoryColor(excludeColor = null) {
  const options = excludeColor 
    ? CATEGORY_COLOR_PALETTE.filter(c => c.toLowerCase() !== String(excludeColor).toLowerCase())
    : CATEGORY_COLOR_PALETTE;
  const list = options.length > 0 ? options : CATEGORY_COLOR_PALETTE;
  const randomIndex = Math.floor(Math.random() * list.length);
  return list[randomIndex];
}

