function detectCategoryIcon(name) {
  if (!name) return '🏷️';
  const clean = name.toLowerCase().trim();

  for (const entry of CATEGORY_ICON_KEYWORDS) {
    for (const word of entry.words) {
      if (clean === word || clean.includes(word)) {
        return entry.icon;
      }
    }
  }
  return '🏷️';
}

