// [FEAT-03 & FEAT-23] Open Edit Category modal (supports focusField = 'budget' to focus and select budget amount on click)
function openEditCategoryModal(categoryId, focusField = 'name') {
  const cat = appState.categories.find(c => c.id === categoryId);
  if (!cat) return;

  const modal = document.getElementById('categoryModal');
  const form = document.getElementById('categoryForm');
  form.reset();

  // Hide bulk banner when editing an existing category
  const bulkBanner = document.getElementById('catModalBulkBanner');
  if (bulkBanner) bulkBanner.style.display = 'none';

  const editIdInput = document.getElementById('editCategoryId');
  if (editIdInput) editIdInput.value = cat.id;

  const modalTitle = document.getElementById('categoryModalTitle');
  if (modalTitle) modalTitle.textContent = `Edit Category: ${cat.name}`;

  const submitBtn = document.getElementById('btnSubmitCategory');
  if (submitBtn) submitBtn.textContent = 'Save Changes';

  document.getElementById('categoryName').value = cat.name;
  document.getElementById('categoryIcon').value = cat.icon || '🏷️';
  document.getElementById('categoryColor').value = cat.color || '#06b6d4';
  document.getElementById('categoryColorHex').textContent = cat.color || '#06b6d4';

  const currentBudget = (appState.budgets[appState.activeMonth] && appState.budgets[appState.activeMonth][cat.id] !== undefined)
    ? appState.budgets[appState.activeMonth][cat.id]
    : (cat.defaultBudget || 0);
  document.getElementById('categoryDefaultBudget').value = currentBudget;
  document.getElementById('categoryCurrencyLabel').textContent = appState.currency;
  setCategoryBudgetType(cat.budgetType || getCategoryBudgetType(cat.id));

  // Hide scope selector when editing an existing category
  const scopeGroup = document.getElementById('categoryScopeGroup');
  if (scopeGroup) scopeGroup.style.display = 'none';
  const monthLabel = (typeof formatMonthLabel === 'function' && appState.activeMonth)
    ? formatMonthLabel(appState.activeMonth)
    : 'Current Month';
  const lblBudget = document.getElementById('lblCategoryDefaultBudget');
  if (lblBudget) lblBudget.textContent = `Budget Allocation for ${monthLabel}`;

  modal.classList.add('active');
  setTimeout(() => {
    if (focusField === 'budget') {
      const budgetInput = document.getElementById('categoryDefaultBudget');
      if (budgetInput) {
        budgetInput.focus();
        budgetInput.select();
      }
    } else {
      const nameInput = document.getElementById('categoryName');
      if (nameInput) {
        nameInput.focus();
        nameInput.select();
      }
    }
  }, 100);
}

