function setupPlannedExpensesListeners() {
  // Subtabs switching
  const btnActual = document.getElementById('btnSubtabActualExpenses');
  if (btnActual) btnActual.addEventListener('click', () => switchExpenseSubtab('actual'));

  const btnPlanned = document.getElementById('btnSubtabPlannedExpenses');
  if (btnPlanned) btnPlanned.addEventListener('click', () => switchExpenseSubtab('planned'));

  // Projection Toggle
  const chkProjection = document.getElementById('chkIncludePlannedInProjections');
  if (chkProjection) {
    chkProjection.addEventListener('change', (e) => {
      setIncludePlannedInProjections(e.target.checked);
    });
  }

  // Open Planned Modal
  const btnOpen = document.getElementById('btnOpenPlannedModal');
  if (btnOpen) btnOpen.addEventListener('click', () => openPlannedExpenseModal());

  const btnEmpty = document.getElementById('btnEmptyAddPlanned');
  if (btnEmpty) btnEmpty.addEventListener('click', () => openPlannedExpenseModal());

  // [FEAT-CSV-PLANNED] Planned Expenses CSV Upload & Template Download Listeners
  const btnUploadPlannedCSV = document.getElementById('btnUploadPlannedCSV');
  const fileInputPlannedCSV = document.getElementById('plannedCSVFileInput');
  if (btnUploadPlannedCSV && fileInputPlannedCSV) {
    btnUploadPlannedCSV.addEventListener('click', (e) => {
      if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-FUTURE-EXPENSES]')) {
        e.preventDefault();
        if (typeof showUpgradePrompt === 'function') {
          showUpgradePrompt('[FEAT-FUTURE-EXPENSES]', 'CSV Importer for Planned & Future Expenses', 'expenses');
        }
        return;
      }
      fileInputPlannedCSV.value = '';
      fileInputPlannedCSV.click();
    });
    fileInputPlannedCSV.addEventListener('change', handlePlannedCSVUpload);
  }

  const btnEmptyUploadPlanned = document.getElementById('btnEmptyUploadPlannedCSV');
  if (btnEmptyUploadPlanned && fileInputPlannedCSV) {
    btnEmptyUploadPlanned.addEventListener('click', (e) => {
      if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-FUTURE-EXPENSES]')) {
        e.preventDefault();
        if (typeof showUpgradePrompt === 'function') {
          showUpgradePrompt('[FEAT-FUTURE-EXPENSES]', 'CSV Importer for Planned & Future Expenses', 'expenses');
        }
        return;
      }
      fileInputPlannedCSV.value = '';
      fileInputPlannedCSV.click();
    });
  }

  const btnPlannedTemplate = document.getElementById('btnDownloadPlannedCSVTemplate');
  if (btnPlannedTemplate) {
    btnPlannedTemplate.addEventListener('click', downloadPlannedExpenseCSVTemplate);
  }

  // Form submit and cancel
  const form = document.getElementById('plannedExpenseForm');
  if (form) form.addEventListener('submit', handlePlannedExpenseSubmit);

  const btnClose = document.getElementById('btnClosePlannedExpenseModal');
  if (btnClose) btnClose.addEventListener('click', closePlannedExpenseModal);

  const btnCancel = document.getElementById('btnCancelPlannedModal');
  if (btnCancel) btnCancel.addEventListener('click', closePlannedExpenseModal);

  // In-modal switcher to Normal / Recurring from Planned Modal
  const btnPlannedOneTime = document.getElementById('btnPlannedTypeOneTime');
  if (btnPlannedOneTime) {
    btnPlannedOneTime.addEventListener('click', () => {
      const amount = document.getElementById('plannedExpenseAmount')?.value || '';
      const cat = document.getElementById('plannedExpenseCategory')?.value || '';
      const desc = document.getElementById('plannedExpenseDescription')?.value || '';
      const method = document.getElementById('plannedExpensePaymentMethod')?.value || '';

      closePlannedExpenseModal();
      openExpenseModal();

      if (amount) {
        const expAmt = document.getElementById('expenseAmount');
        if (expAmt) expAmt.value = amount;
      }
      if (desc) {
        const expDesc = document.getElementById('expenseDescription');
        if (expDesc) expDesc.value = desc;
      }
      if (cat) {
        const expCat = document.getElementById('expenseCategory');
        if (expCat) expCat.value = cat;
      }
      if (method) {
        const expMethod = document.getElementById('expensePaymentMethod');
        if (expMethod) expMethod.value = method;
      }
    });
  }

  const btnPlannedRecurring = document.getElementById('btnPlannedTypeRecurring');
  if (btnPlannedRecurring) {
    btnPlannedRecurring.addEventListener('click', () => {
      if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-32]')) {
        if (typeof showUpgradePrompt === 'function') {
          showUpgradePrompt('[FEAT-32]', 'Recurring Bills & Subscriptions Calendar', 'bills');
        }
        return;
      }
      const amount = document.getElementById('plannedExpenseAmount')?.value || '';
      const cat = document.getElementById('plannedExpenseCategory')?.value || '';
      const desc = document.getElementById('plannedExpenseDescription')?.value || '';
      const method = document.getElementById('plannedExpensePaymentMethod')?.value || '';

      closePlannedExpenseModal();
      openBillModal();

      if (amount) {
        const billAmt = document.getElementById('billAmount');
        if (billAmt) billAmt.value = amount;
      }
      if (desc) {
        const billName = document.getElementById('billName');
        if (billName) billName.value = desc;
      }
      if (cat) {
        const billCat = document.getElementById('billCategory');
        if (billCat) billCat.value = cat;
      }
      if (method) {
        const billMethod = document.getElementById('billPaymentMethod');
        if (billMethod) billMethod.value = method;
      }
    });
  }

  // Banner Actions
  const btnDpbApproveAll = document.getElementById('btnDpbApproveAll');
  if (btnDpbApproveAll) btnDpbApproveAll.addEventListener('click', approveAllDuePlannedExpenses);

  const btnDpbReview = document.getElementById('btnDpbReviewModal');
  if (btnDpbReview) btnDpbReview.addEventListener('click', openDuePlannedExpenseModal);

  const btnDpbDismiss = document.getElementById('btnDpbDismiss');
  if (btnDpbDismiss) {
    btnDpbDismiss.addEventListener('click', () => {
      const today = (typeof billTodayStr === 'function') ? billTodayStr() : new Date().toISOString().split('T')[0];
      sessionStorage.setItem('nirvtrack_due_planned_banner_dismissed', today);
      const banner = document.getElementById('duePlannedExpenseBanner');
      if (banner) banner.style.display = 'none';
      showToast('Due planned expenses banner dismissed for this session.', 'info');
    });
  }

  // Due Review Modal Actions
  const btnCloseDue = document.getElementById('btnCloseDuePlannedModal');
  if (btnCloseDue) btnCloseDue.addEventListener('click', closeDuePlannedExpenseModal);

  const btnDismissDue = document.getElementById('btnDismissDuePlannedModal');
  if (btnDismissDue) btnDismissDue.addEventListener('click', closeDuePlannedExpenseModal);

  const btnApproveAllModal = document.getElementById('btnApproveAllDueModal');
  if (btnApproveAllModal) btnApproveAllModal.addEventListener('click', approveAllDuePlannedExpenses);

  // Reschedule Modal Actions
  const btnCloseReschedule = document.getElementById('btnCloseRescheduleModal');
  if (btnCloseReschedule) btnCloseReschedule.addEventListener('click', closeReschedulePlannedModal);

  const btnCancelReschedule = document.getElementById('btnCancelRescheduleModal');
  if (btnCancelReschedule) btnCancelReschedule.addEventListener('click', closeReschedulePlannedModal);

  const btnP1d = document.getElementById('btnPostpone1d');
  if (btnP1d) btnP1d.addEventListener('click', () => postponePlannedExpense(currentReschedulePlannedId, 1));

  const btnP3d = document.getElementById('btnPostpone3d');
  if (btnP3d) btnP3d.addEventListener('click', () => postponePlannedExpense(currentReschedulePlannedId, 3));

  const btnP7d = document.getElementById('btnPostpone7d');
  if (btnP7d) btnP7d.addEventListener('click', () => postponePlannedExpense(currentReschedulePlannedId, 7));

  const btnConfirmReschedule = document.getElementById('btnConfirmReschedule');
  if (btnConfirmReschedule) {
    btnConfirmReschedule.addEventListener('click', () => {
      const dateVal = document.getElementById('rescheduleCustomDate')?.value;
      if (!dateVal) {
        showToast('Please select a valid date.', 'warning');
        return;
      }
      postponePlannedExpense(currentReschedulePlannedId, dateVal);
    });
  }

  // Search & Filter controls for planned table
  const searchInput = document.getElementById('plannedSearchInput');
  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      plannedExpensesFilterState.search = e.target.value;
      renderPlannedExpensesTable();
    });
  }

  const catFilter = document.getElementById('plannedFilterCategory');
  if (catFilter) {
    catFilter.addEventListener('change', (e) => {
      plannedExpensesFilterState.category = e.target.value;
      renderPlannedExpensesTable();
    });
  }

  const statusFilter = document.getElementById('plannedFilterStatus');
  if (statusFilter) {
    statusFilter.addEventListener('change', (e) => {
      plannedExpensesFilterState.status = e.target.value;
      renderPlannedExpensesTable();
    });
  }

  // [FEAT-SORT-PLANNED] Sortable headers click listeners for planned expenses table
  document.querySelectorAll('#plannedExpensesTable thead th.sortable-th').forEach(th => {
    th.addEventListener('click', () => {
      const field = th.getAttribute('data-sort');
      if (!field) return;
      if (plannedExpensesSortState.field === field) {
        plannedExpensesSortState.order = plannedExpensesSortState.order === 'asc' ? 'desc' : 'asc';
      } else {
        plannedExpensesSortState.field = field;
        plannedExpensesSortState.order = (field === 'amount') ? 'desc' : 'asc';
      }
      renderPlannedExpensesTable();
    });
  });
}

// ==========================================
// 12. CORE METRICS & KPI COMPUTATIONS
// ==========================================
function calculateMetrics() {
  const months = getSortedActiveMonths();

  // 1. Total Income & breakdown aggregated across all active months
  let totalIncome = 0;
  let totalPaycheck15 = 0;
  let totalPaycheck30 = 0;
  let totalAdditional = 0;
  let totalCarryoverSurplus = 0;

  months.forEach(m => {
    const inc = getMonthlyIncome(m);
    totalIncome += inc.total;
    totalPaycheck15 += inc.paycheck15;
    totalPaycheck30 += inc.paycheck30;
    totalAdditional += inc.additional;
    totalCarryoverSurplus += (inc.carryoverSurplus || 0);
  });

  // 2. Total Budget aggregated across all active months
  let totalBudget = 0;
  const categoryBudgets = {};
  appState.categories.forEach(cat => { categoryBudgets[cat.id] = 0; });

  months.forEach(m => {
    const b = appState.budgets[m] || {};
    const excludedList = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[m]) || [];
    appState.categories.forEach(cat => {
      if (excludedList.includes(cat.id)) return;
      const amt = b[cat.id] !== undefined ? b[cat.id] : (cat.defaultBudget || 0);
      categoryBudgets[cat.id] += amt;
      totalBudget += amt;
    });
  });

  // 3. Expenses aggregated across all active months (handling Refunds/Offsets and CC Payoff Exclusions)
  const activeExpenses = getActiveExpenses();
  let totalExpenses = 0;
  activeExpenses.forEach(item => {
    if (item.excludeFromBudget === true || item.isCreditCardPayoff === true) return;
    if (item.isRefund === true || item.type === 'refund') {
      totalExpenses -= (item.amount || 0);
    } else {
      totalExpenses += (item.amount || 0);
    }
  });

  const remainingBudget = totalBudget - totalExpenses;
  const netSavings = totalIncome - totalExpenses;
  const plannedSavings = totalIncome - totalBudget;

  const savingsRate = totalIncome > 0 ? (netSavings / totalIncome) * 100 : 0;
  const budgetUtilization = totalBudget > 0 ? (totalExpenses / totalBudget) * 100 : 0;
  const budgetToIncomeRatio = totalIncome > 0 ? (totalBudget / totalIncome) * 100 : 0;

  // 4. Category spending breakdown
  const categorySpending = {};
  appState.categories.forEach(c => { categorySpending[c.id] = 0; });
  activeExpenses.forEach(e => {
    if (e.excludeFromBudget === true || e.isCreditCardPayoff === true) return;
    const delta = (e.isRefund === true || e.type === 'refund') ? -(e.amount || 0) : (e.amount || 0);
    if (categorySpending[e.categoryId] !== undefined) {
      categorySpending[e.categoryId] += delta;
    } else {
      categorySpending[e.categoryId] = (categorySpending[e.categoryId] || 0) + delta;
    }
  });

  // 5. [FEAT-38] Savings Analyst Breakdown: Recorded vs. Recurring vs. Projected Savings
  const recordedItems = activeExpenses.filter(item => !item.billId && !item.excludeFromBudget && !item.isCreditCardPayoff);
  const recordedExpenses = recordedItems.reduce((sum, item) => {
    const amt = (item.isRefund || item.type === 'refund') ? -(item.amount || 0) : (item.amount || 0);
    return sum + amt;
  }, 0);
  const recordedTxCount = recordedItems.length;

  const postedRecurringItems = activeExpenses.filter(item => Boolean(item.billId));
  const postedRecurringExpenses = postedRecurringItems.reduce((sum, item) => sum + (item.amount || 0), 0);
  const postedRecurringCount = postedRecurringItems.length;

  // Unposted active recurring bill occurrences scheduled in active months + Not Started Yet bills
  const todayStrForBills = typeof billTodayStr === 'function' ? billTodayStr() : new Date().toISOString().split('T')[0];
  let unpostedRecurringExpenses = 0;
  let unpostedRecurringCount = 0;
  let notStartedRecurringExpenses = 0;
  let notStartedRecurringCount = 0;
  const activeBillsList = (appState.recurringBills || []).filter(b => b.active !== false);

  months.forEach(m => {
    const excluded = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[m]) || [];
    activeBillsList.forEach(bill => {
      if (bill.categoryId && excluded.includes(bill.categoryId)) return;
      const isNotStarted = Boolean(bill.startDate && bill.startDate > todayStrForBills);
      const dues = getBillDueDatesForMonth(bill, m);

      if (isNotStarted) {
        // [FIX-NOT-STARTED-RECURRING] Bill has status "Not Started Yet" (startDate > today).
        // Do not skip due < startDate here so that all Not Started bills are computed into the forecast.
        const duesAfterStart = dues.filter(d => d >= bill.startDate);
        const effectiveDues = duesAfterStart.length > 0 ? duesAfterStart : (dues.length > 0 ? dues : [bill.startDate]);
        effectiveDues.forEach(due => {
          if (!isBillDateSettled(bill, due)) {
            const amt = Number(bill.amount) || 0;
            unpostedRecurringExpenses += amt;
            unpostedRecurringCount++;
            notStartedRecurringExpenses += amt;
            notStartedRecurringCount++;
          }
        });
      } else {
        dues.forEach(due => {
          if (bill.startDate && due < bill.startDate) return;
          if (!isBillDateSettled(bill, due)) {
            const amt = Number(bill.amount) || 0;
            unpostedRecurringExpenses += amt;
            unpostedRecurringCount++;
          }
        });
      }
    });
  });

  const recurringExpenses = postedRecurringExpenses + unpostedRecurringExpenses;
  const recurringCount = postedRecurringCount + unpostedRecurringCount;
  // [FEAT-38] Total Actual Expenses is the actual logged expenses only (recurring removed from formula)
  const totalActualExpenses = totalExpenses;

  // [FEAT-PLANNED-EXPENSES] Planned / Future Commitments for active months
  const currentYm = todayStrForBills.substring(0, 7);
  const activePlannedExpenses = (appState.plannedExpenses || []).filter(item => {
    if (!item.date) return true;
    const m = item.date.substring(0, 7);
    if (months.includes(m)) return true;
    if (months.includes(currentYm) && m > currentYm) return true;
    return false;
  });
  const totalPlannedExpenses = activePlannedExpenses.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
  const plannedTxCount = activePlannedExpenses.length;

  const includePlannedInProjections = (appState.includePlannedInProjections === true) &&
    (typeof canAccessFeature === 'function' ? canAccessFeature('[FEAT-FUTURE-EXPENSES]') : true);
  // [FEAT-RECURRING-FORECAST] When forecast toggle is active, deduct both scheduled planned expenses AND unposted / not-started recurring bills
  const totalForecastDeductions = includePlannedInProjections ? ((totalPlannedExpenses || 0) + (unpostedRecurringExpenses || 0)) : 0;
  const projectedEffectiveExpenses = totalExpenses + totalForecastDeductions;

  // Dual Savings Analyst Projections:
  // 1) Total Projected Savings = Total Income - Total Budget
  const projectedSavings = totalIncome - totalBudget;
  const projectedSavingsRate = totalIncome > 0 ? (projectedSavings / totalIncome) * 100 : 0;

  // 2) Projected Actual Savings = Total Income - Effective Outflows
  const projectedActualSavings = totalIncome - projectedEffectiveExpenses;
  const projectedActualSavingsRate = totalIncome > 0 ? (projectedActualSavings / totalIncome) * 100 : 0;

  // 6. [FEAT-39] Needs vs. Wants breakdown for 50/30/20 Rule
  let actualNeeds = 0;
  let actualWants = 0;
  activeExpenses.forEach(e => {
    if (e.excludeFromBudget === true || e.isCreditCardPayoff === true) return;
    const bType = e.budgetType || getCategoryBudgetType(e.categoryId) || 'needs';
    const delta = (e.isRefund === true || e.type === 'refund') ? -(e.amount || 0) : (e.amount || 0);
    if (bType === 'wants') {
      actualWants += delta;
    } else {
      actualNeeds += delta;
    }
  });

  // 7. [FEAT-CC-FLOAT-PROTECT] Credit Card Float & Statement Payoff calculation
  let ccTotalSwiped = 0;
  let ccTotalPaid = 0;
  activeExpenses.forEach(e => {
    const isCC = (e.paymentMethod === 'Credit Card' || e.paymentMethod === 'credit');
    const isCCPayoff = Boolean(e.isCreditCardPayoff || (e.excludeFromBudget && isCC) || e.paymentMethod === 'Credit Card Payoff');
    if (isCC && !isCCPayoff) {
      if (e.isRefund || e.type === 'refund') {
        ccTotalSwiped -= (e.amount || 0);
      } else {
        ccTotalSwiped += (e.amount || 0);
      }
    } else if (isCCPayoff) {
      ccTotalPaid += (e.amount || 0);
    }
  });
  const creditCardFloat = Math.max(0, ccTotalSwiped - ccTotalPaid);

  return {
    months,
    totalIncome,
    paycheck15: totalPaycheck15,
    paycheck30: totalPaycheck30,
    additionalIncome: totalAdditional,
    carryoverSurplus: totalCarryoverSurplus,
    totalBudget,
    categoryBudgets,
    totalExpenses,
    remainingBudget,
    netSavings,
    plannedSavings,
    savingsRate,
    creditCardFloat,
    ccTotalSwiped,
    ccTotalPaid,
    budgetUtilization,
    budgetToIncomeRatio,
    txCount: activeExpenses.length,
    categorySpending,
    // [FEAT-38] Savings Analyst metrics
    recordedExpenses,
    recordedTxCount,
    postedRecurringExpenses,
    postedRecurringCount,
    unpostedRecurringExpenses,
    unpostedRecurringCount,
    notStartedRecurringExpenses,
    notStartedRecurringCount,
    recurringExpenses,
    recurringCount,
    totalActualExpenses,
    projectedSavings,
    projectedSavingsRate,
    projectedActualSavings,
    projectedActualSavingsRate,
    totalPlannedExpenses,
    plannedTxCount,
    totalForecastDeductions,
    projectedEffectiveExpenses,
    includePlannedInProjections,
    // [FEAT-39] 50/30/20 actual tagged amounts
    actualNeeds,
    actualWants
  };
}

// ==========================================
// 13. UPDATE ALL VIEWS
// ==========================================
function updateAllViews() {
  // [FEAT-34] Auto-add due recurring bills to the expense tracker before computing totals
  autoPostRecurringBills();

  const metrics = calculateMetrics();
  const periodLabel = formatActivePeriodLabel();
  const months = getSortedActiveMonths();
  const isMultiMonth = months.length > 1;

  // Period headers
  document.getElementById('currentPeriodDisplay').textContent = isMultiMonth
    ? `Viewing aggregated data for ${periodLabel}`
    : `Viewing data for ${periodLabel}`;
  document.getElementById('budgetPeriodLabel').textContent = periodLabel;
  document.getElementById('expensesPeriodLabel').textContent = periodLabel;
  const pillPeriodLabel = document.getElementById('pillPeriodLabel');
  if (pillPeriodLabel) pillPeriodLabel.textContent = periodLabel;

  // Multi-month badge in sidebar
  const multiMonthBadge = document.getElementById('multiMonthBadge');
  const multiMonthBadgeText = document.getElementById('multiMonthBadgeText');
  if (multiMonthBadge && multiMonthBadgeText) {
    if (isMultiMonth) {
      multiMonthBadge.style.display = 'flex';
      multiMonthBadgeText.textContent = `${months.length} Months Active`;
    } else {
      multiMonthBadge.style.display = 'none';
    }
  }

  updatePresetPillsActive();

  // 1. Dashboard KPI Card 1: TOTAL MONTHLY INCOME
  const kpiIncomeEl = document.getElementById('kpiTotalIncome');
  if (kpiIncomeEl) {
    kpiIncomeEl.textContent = formatCurrency(metrics.totalIncome);
    document.getElementById('kpiIncome15Tag').textContent = isMultiMonth
      ? `Total 15th: ${formatCurrency(metrics.paycheck15)}`
      : `15th: ${formatCurrency(metrics.paycheck15)}`;
    document.getElementById('kpiIncome30Tag').textContent = isMultiMonth
      ? `Total 30th: ${formatCurrency(metrics.paycheck30)}`
      : `30th: ${formatCurrency(metrics.paycheck30)}`;

    const kpiSurplusRow = document.getElementById('kpiIncomeSurplusRow');
    const kpiSurplusTag = document.getElementById('kpiIncomeSurplusTag');
    if (kpiSurplusRow && kpiSurplusTag) {
      if (metrics.carryoverSurplus > 0) {
        const pct = metrics.totalIncome > 0
          ? ((metrics.carryoverSurplus / metrics.totalIncome) * 100).toFixed(0)
          : 0;
        kpiSurplusTag.textContent = isMultiMonth
          ? `🛡️ Swept Surplus: +${formatCurrency(metrics.carryoverSurplus)} (${pct}%)`
          : `🛡️ Swept Surplus: +${formatCurrency(metrics.carryoverSurplus)} (${pct}% of total)`;
        kpiSurplusTag.title = `Includes ${formatCurrency(metrics.carryoverSurplus)} unspent surplus swept from previous month into your General Savings Reserve`;
        kpiSurplusRow.style.display = 'flex';
      } else {
        kpiSurplusRow.style.display = 'none';
      }
    }
  }

  // 2. Dashboard KPI Card 2: TOTAL MONTHLY BUDGET
  document.getElementById('kpiTotalBudget').textContent = formatCurrency(metrics.totalBudget);
  document.getElementById('kpiBudgetCount').textContent = isMultiMonth
    ? `${appState.categories.length} Categories × ${months.length} Mo`
    : `${appState.categories.length} Categories`;
  const kpiBudgetVsIncome = document.getElementById('kpiBudgetVsIncome');
  if (kpiBudgetVsIncome) {
    kpiBudgetVsIncome.textContent = `${metrics.budgetToIncomeRatio.toFixed(1)}% of Income`;
  }
  const kpiBudgetIncomeBar = document.getElementById('kpiBudgetIncomeBar');
  if (kpiBudgetIncomeBar) {
    kpiBudgetIncomeBar.style.width = `${Math.min(100, metrics.budgetToIncomeRatio)}%`;
  }

  // 3. Dashboard KPI Card 3: TOTAL EXPENSES
  document.getElementById('kpiTotalExpenses').textContent = formatCurrency(metrics.totalExpenses);
  document.getElementById('kpiExpenseTxCount').textContent = `${metrics.txCount} Transactions`;

  // Expense Pace calculation across active period
  let totalDays = 0;
  let daysPassed = 0;
  const now = new Date();

  months.forEach(m => {
    const [yearStr, monthStr] = m.split('-');
    const y = parseInt(yearStr, 10);
    const mo = parseInt(monthStr, 10);
    const daysInM = new Date(y, mo, 0).getDate();
    totalDays += daysInM;

    if (now.getFullYear() === y && (now.getMonth() + 1) === mo) {
      daysPassed += Math.max(1, now.getDate());
    } else if (new Date(y, mo - 1, 1) < now) {
      daysPassed += daysInM;
    }
  });
  daysPassed = Math.max(1, daysPassed);
  const avgDaily = metrics.totalExpenses / daysPassed;
  document.getElementById('kpiExpensesPace').textContent = `Avg ${formatCurrency(avgDaily)}/day`;

  // 4. Dashboard KPI Card 4: REMAINING BUDGET
  const remainingEl = document.getElementById('kpiRemainingBudget');
  remainingEl.textContent = formatCurrency(metrics.remainingBudget);
  if (metrics.remainingBudget >= 0) {
    remainingEl.className = 'kpi-value text-emerald';
    document.getElementById('kpiRemainingStatus').textContent = 'Healthy Surplus';
    document.getElementById('kpiRemainingStatus').className = 'kpi-trend positive';
  } else {
    remainingEl.className = 'kpi-value text-rose';
    document.getElementById('kpiRemainingStatus').textContent = 'Deficit Overrun';
    document.getElementById('kpiRemainingStatus').className = 'kpi-trend negative';
  }
  const remainingPct = metrics.totalBudget > 0 ? Math.max(0, Math.min(100, (metrics.remainingBudget / metrics.totalBudget) * 100)) : 0;
  document.getElementById('kpiRemainingBar').style.width = `${remainingPct}%`;

  // 5. Dashboard KPI Card 5: NET PROJECTED SAVINGS
  const savingsEl = document.getElementById('kpiSavingsAmount');
  if (savingsEl) {
    const totalForecastDeductions = (metrics.totalPlannedExpenses || 0) + (metrics.unpostedRecurringExpenses || 0);
    const isForecastActive = metrics.includePlannedInProjections && totalForecastDeductions > 0;
    const displaySavings = isForecastActive ? metrics.projectedActualSavings : metrics.netSavings;
    savingsEl.textContent = formatCurrency(displaySavings);
    if (displaySavings >= 0) {
      savingsEl.className = 'kpi-value text-emerald';
    } else {
      savingsEl.className = 'kpi-value text-rose';
    }

    // [FEAT-SAVINGS-BASELINE] Header Forecast Badge
    const forecastBadge = document.getElementById('kpiSavingsForecastBadge');
    if (forecastBadge) {
      forecastBadge.style.display = isForecastActive ? 'inline-block' : 'none';
      if (isForecastActive) {
        if (metrics.totalPlannedExpenses > 0 && metrics.unpostedRecurringExpenses > 0) {
          forecastBadge.textContent = 'INCL. PLANNED & REC';
        } else if (metrics.unpostedRecurringExpenses > 0) {
          forecastBadge.textContent = 'INCL. RECURRING';
        } else {
          forecastBadge.textContent = 'INCL. PLANNED';
        }
      }
    }

    // [FEAT-SAVINGS-BASELINE] Dynamic Baseline Callout: Income - Actual Expenses + Deductions
    const baselineWrap = document.getElementById('kpiSavingsBaselineWrap');
    const baselineAmtEl = document.getElementById('kpiSavingsBaselineAmount');
    const baselineRateEl = document.getElementById('kpiSavingsBaselineRate');
    const plannedRow = document.getElementById('kpiSavingsPlannedRow');
    const plannedDeductEl = document.getElementById('kpiSavingsPlannedDeduct');
    const recurringRow = document.getElementById('kpiSavingsRecurringRow');
    const recurringLabelEl = document.getElementById('kpiSavingsRecurringLabel');
    const recurringDeductEl = document.getElementById('kpiSavingsRecurringDeduct');

    if (baselineWrap && baselineAmtEl) {
      if (isForecastActive) {
        baselineWrap.style.display = 'flex';
        baselineWrap.style.setProperty('margin-bottom', 'auto', 'important');
        savingsEl.style.setProperty('margin-top', 'auto', 'important');
        savingsEl.style.setProperty('margin-bottom', '4px', 'important');
        savingsEl.style.setProperty('text-align', 'center', 'important');
        baselineAmtEl.textContent = formatCurrency(metrics.netSavings);
        if (baselineRateEl) {
          baselineRateEl.textContent = `(${metrics.savingsRate.toFixed(1)}%)`;
        }
        if (plannedRow && plannedDeductEl) {
          if (metrics.totalPlannedExpenses > 0) {
            plannedRow.style.display = 'flex';
            plannedDeductEl.textContent = `-${formatCurrency(metrics.totalPlannedExpenses)}`;
          } else {
            plannedRow.style.display = 'none';
          }
        }
        if (recurringRow && recurringDeductEl) {
          if (metrics.unpostedRecurringExpenses > 0) {
            recurringRow.style.display = 'flex';
            recurringDeductEl.textContent = `-${formatCurrency(metrics.unpostedRecurringExpenses)}`;
            if (recurringLabelEl) {
              recurringLabelEl.textContent = (metrics.notStartedRecurringExpenses > 0 && metrics.notStartedRecurringExpenses === metrics.unpostedRecurringExpenses)
                ? 'Recurring (Not Started):'
                : 'Recurring (Not Started/Unposted):';
            }
          } else {
            recurringRow.style.display = 'none';
          }
        }
        baselineWrap.title = `Baseline Savings: Total Income (${formatCurrency(metrics.totalIncome)}) − Actual Expenses (${formatCurrency(metrics.totalActualExpenses)}) = ${formatCurrency(metrics.netSavings)} (${metrics.savingsRate.toFixed(1)}% of income) | Planned: -${formatCurrency(metrics.totalPlannedExpenses || 0)} | Recurring (Not Started/Unposted): -${formatCurrency(metrics.unpostedRecurringExpenses || 0)}`;
      } else {
        baselineWrap.style.display = 'none';
        savingsEl.style.setProperty('margin-top', 'auto', 'important');
        savingsEl.style.setProperty('margin-bottom', 'auto', 'important');
        savingsEl.style.setProperty('text-align', 'center', 'important');
      }
    }

    const savingsTag = document.getElementById('kpiSavingsTag');
    if (savingsTag) {
      if (isForecastActive) {
        savingsTag.textContent = `Target: ${formatCurrency(metrics.plannedSavings)}`;
        savingsTag.title = `Target Savings (Income − Budget): ${formatCurrency(metrics.plannedSavings)} | Forecast deducts ${formatCurrency(totalForecastDeductions)} (${formatCurrency(metrics.totalPlannedExpenses || 0)} planned + ${formatCurrency(metrics.unpostedRecurringExpenses || 0)} recurring not started)`;
      } else if (totalForecastDeductions > 0) {
        savingsTag.textContent = `Target: ${formatCurrency(metrics.plannedSavings)}`;
        savingsTag.title = `Scheduled commitments (${formatCurrency(totalForecastDeductions)}) are currently excluded from projected savings. Toggle ON in Planned Expenses to include.`;
      } else {
        savingsTag.textContent = `Target: ${formatCurrency(metrics.plannedSavings)}`;
        savingsTag.title = 'Target monthly savings calculated as Total Income minus Total Budget';
      }
    }

    const savingsRateEl = document.getElementById('kpiSavingsRate');
    if (savingsRateEl) {
      const displayRate = isForecastActive ? metrics.projectedActualSavingsRate : metrics.savingsRate;
      savingsRateEl.textContent = `${displayRate.toFixed(1)}% of Income`;
      savingsRateEl.className = `kpi-trend ${displayRate >= 20 ? 'positive' : (displayRate >= 0 ? 'warning' : 'negative')}`;
    }
    const displayRate = isForecastActive ? metrics.projectedActualSavingsRate : metrics.savingsRate;
    document.getElementById('kpiSavingsBar').style.width = `${Math.max(0, Math.min(100, displayRate))}%`;

    // Multi-line detailed calculation tooltip on entire KPI Card
    const cardEl = document.getElementById('kpiCardProjectedSavings');
    if (cardEl) {
      if (isForecastActive) {
        const breakdownLines = [];
        if (metrics.totalPlannedExpenses > 0) {
          breakdownLines.push(`• Planned Commitments: -${formatCurrency(metrics.totalPlannedExpenses)} (${metrics.plannedTxCount} items)`);
        }
        if (metrics.unpostedRecurringExpenses > 0) {
          breakdownLines.push(`• Unposted / Not-Started Recurring: -${formatCurrency(metrics.unpostedRecurringExpenses)} (${metrics.unpostedRecurringCount} bills)`);
        }
        cardEl.title = `Projected Savings Calculation:\n• Total Income: ${formatCurrency(metrics.totalIncome)}\n• Actual Expenses: -${formatCurrency(metrics.totalActualExpenses)}\n= Baseline Savings (Income − Actual): ${formatCurrency(metrics.netSavings)} (${metrics.savingsRate.toFixed(1)}%)\n${breakdownLines.join('\n')}\n= Net Projected Savings: ${formatCurrency(metrics.projectedActualSavings)} (${metrics.projectedActualSavingsRate.toFixed(1)}%)`;
      } else {
        cardEl.title = `Projected Savings Calculation:\n• Total Income: ${formatCurrency(metrics.totalIncome)}\n• Actual Expenses: -${formatCurrency(metrics.totalActualExpenses)}\n= Unspent Savings: ${formatCurrency(metrics.netSavings)} (${metrics.savingsRate.toFixed(1)}%)`;
      }
    }
  }

  // 6. Dashboard KPI Card 6: BUDGET UTILIZATION GAUGE CARD
  const utilBadge = document.getElementById('kpiUtilizationBadge');
  const utilPct = metrics.budgetUtilization.toFixed(1);
  document.getElementById('kpiUtilizationPercent').textContent = `${utilPct}%`;
  document.getElementById('kpiGaugeFill').style.width = `${Math.min(100, metrics.budgetUtilization)}%`;

  if (metrics.budgetUtilization <= 75) {
    utilBadge.textContent = 'ON TRACK';
    utilBadge.className = 'kpi-status-badge badge-success';
  } else if (metrics.budgetUtilization <= 100) {
    utilBadge.textContent = 'WARNING';
    utilBadge.className = 'kpi-status-badge badge-warning';
  } else {
    utilBadge.textContent = 'OVER BUDGET';
    utilBadge.className = 'kpi-status-badge badge-danger';
  }

  // 7. Sidebar Health Widget (Optional / Null-Safe)
  const sideHealth = document.getElementById('sidebarHealthPill');
  const sideBar = document.getElementById('sidebarProgressBar');
  const sideUtil = document.getElementById('sidebarUtilizationText');
  if (sideBar) sideBar.style.width = `${Math.min(100, metrics.budgetUtilization)}%`;
  if (sideUtil) sideUtil.textContent = `${utilPct}% of budget spent`;

  if (sideHealth) {
    if (metrics.budgetUtilization <= 75) {
      sideHealth.textContent = '● Excellent';
      sideHealth.style.backgroundColor = 'rgba(16, 185, 129, 0.2)';
      sideHealth.style.color = '#34d399';
      if (sideBar) sideBar.style.backgroundColor = '#10b981';
    } else if (metrics.budgetUtilization <= 100) {
      sideHealth.textContent = '● Caution';
      sideHealth.style.backgroundColor = 'rgba(245, 158, 11, 0.2)';
      sideHealth.style.color = '#fbbf24';
      if (sideBar) sideBar.style.backgroundColor = '#f59e0b';
    } else {
      sideHealth.textContent = '● Overrun';
      sideHealth.style.backgroundColor = 'rgba(239, 68, 68, 0.2)';
      sideHealth.style.color = '#f87171';
      if (sideBar) sideBar.style.backgroundColor = '#ef4444';
    }
  }

  // 8. Populate Income Panel Inputs in Budget tab
  populateIncomeInputs();

  // 8b. Update budget grid summary banner (Total Monthly Income, Planned Savings, Savings Rate)
  calculateBudgetGridSummary();

  // 9. Render Charts
  renderTrendChart();
  renderCategoryPieChart(metrics.categorySpending);
  renderBudgetVsActualChart(metrics.categorySpending, metrics.categoryBudgets);
  if (typeof renderForecasterHistoryChart === 'function' && document.getElementById('forecasterHistoryChartCanvas')) {
    renderForecasterHistoryChart();
  }

  // 10. Render Lists
  renderDashboardLists(metrics.categorySpending, metrics.categoryBudgets);

  // 11. Render Tables
  renderExpensesTable();
  renderVarianceTable(metrics);

  // 12. [FEAT-30] Safe-to-Spend widget
  renderSafeToSpend(metrics);

  // 13. [FEAT-38] Savings Analyst widget
  renderSavingsAnalyst(metrics);
  if (typeof renderForecasterViews === 'function') renderForecasterViews();

  // 14. [FEAT-32] Recurring bills tab, dashboard strip and nav badge
  updateBillsUI();

  // 15. [FEAT-50] Update Unswept Previous Month Surplus Prompt Banner
  updateSurplusRolloverBanner();

  // 16. [FEAT-51] Sinking Funds & Savings Goals UI
  if (typeof renderSavingsGoalsUI === 'function') renderSavingsGoalsUI();
  if (typeof renderDashboardGoalsStrip === 'function') renderDashboardGoalsStrip();

  // 17. [FEAT-52] Workspace Custom Layouts (All Pages)
  if (typeof applyAllPageLayouts === 'function') {
    applyAllPageLayouts();
  } else if (typeof applyDashboardLayout === 'function') {
    applyDashboardLayout();
  }

  // 18. [FEAT-64] One-Time Planned / Future Expenses & Projections
  if (typeof checkDuePlannedExpenses === 'function') checkDuePlannedExpenses();
  if (typeof renderPlannedExpensesTable === 'function') renderPlannedExpensesTable();
  if (typeof updatePlannedProjectionsToggleUI === 'function') updatePlannedProjectionsToggleUI();

  // 19. [FEAT-CASHFLOW-CUSHION] 15th vs. 30th Paycheck Cashflow Cushion Matcher
  if (typeof renderCashflowCushionMatcher === 'function') renderCashflowCushionMatcher(metrics);

  // 20. [FEAT-DAY1-ONBOARDING] 60-Second Fast-Track Setup Cockpit
  if (typeof checkDayOneOnboarding === 'function') checkDayOneOnboarding();

  // 21. [FEAT-WALLETS-ACCOUNTS] Liquid Accounts & Wallets Strip
  if (typeof renderWalletsGrid === 'function') renderWalletsGrid();

  // 22. [FEAT-CC-FLOAT-PROTECT] Credit Card Float & Statement Payoff Tracker
  if (typeof renderCreditCardFloatWidget === 'function') renderCreditCardFloatWidget(metrics);

  // 23. [FEAT-3SEC-MOBILE-FLOW] Populate Home Dashboard Quick-Add dropdowns
  if (typeof syncDashQuickAddDropdowns === 'function') syncDashQuickAddDropdowns();
}

// ==========================================
// [FEAT-CASHFLOW-CUSHION] 15TH VS. 30TH PAYCHECK CASHFLOW CUSHION MATCHER
// ==========================================
function calculateCashflowCushionMetrics(baseMetrics = null) {
  const m = baseMetrics || calculateMetrics();
  const months = getSortedActiveMonths();
  const todayStr = typeof billTodayStr === 'function' ? billTodayStr() : new Date().toISOString().split('T')[0];
  const currentYm = todayStr.substring(0, 7);

  const isFirstHalfDate = (dateStr) => {
    if (!dateStr) return true;
    const parts = String(dateStr).split('-');
    const day = parts.length === 3 ? parseInt(parts[2], 10) : 1;
    return (isNaN(day) || day <= 15);
  };

  // 1. Inflows per cutoff
  const firstHalfInflow = (m.paycheck15 || 0) + (m.carryoverSurplus || 0) + (m.additionalIncome || 0);
  const secondHalfStandaloneInflow = (m.paycheck30 || 0);

  // 2. Actual Logged Expenses split by Days 1-15 vs Days 16-End
  const activeExpenses = getActiveExpenses();
  let firstHalfActual = 0;
  let secondHalfActual = 0;
  activeExpenses.forEach(tx => {
    const amt = Number(tx.amount) || 0;
    if (isFirstHalfDate(tx.date)) {
      firstHalfActual += amt;
    } else {
      secondHalfActual += amt;
    }
  });

  // 3. Recurring Bills split by Days 1-15 vs Days 16-End (both unposted & total monthly bill load)
  let firstHalfUnpostedBills = 0;
  let secondHalfUnpostedBills = 0;
  let firstHalfAllBills = 0;
  let secondHalfAllBills = 0;
  let firstHalfBillsCount = 0;
  let secondHalfBillsCount = 0;

  const activeBillsList = (appState.recurringBills || []).filter(b => b.active !== false);
  months.forEach(monthKey => {
    const excluded = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[monthKey]) || [];
    activeBillsList.forEach(bill => {
      if (bill.categoryId && excluded.includes(bill.categoryId)) return;
      const isNotStarted = Boolean(bill.startDate && bill.startDate > todayStr);
      const dues = getBillDueDatesForMonth(bill, monthKey);
      let effectiveDues = dues;
      if (isNotStarted) {
        const duesAfterStart = dues.filter(d => d >= bill.startDate);
        effectiveDues = duesAfterStart.length > 0 ? duesAfterStart : (dues.length > 0 ? dues : [bill.startDate]);
      } else {
        effectiveDues = dues.filter(d => !(bill.startDate && d < bill.startDate));
      }

      effectiveDues.forEach(due => {
        const amt = Number(bill.amount) || 0;
        const is1H = isFirstHalfDate(due);
        if (is1H) {
          firstHalfAllBills += amt;
          firstHalfBillsCount++;
        } else {
          secondHalfAllBills += amt;
          secondHalfBillsCount++;
        }
        if (!isBillDateSettled(bill, due)) {
          if (is1H) firstHalfUnpostedBills += amt;
          else secondHalfUnpostedBills += amt;
        }
      });
    });
  });

  // 4. Scheduled Planned Expenses split by Days 1-15 vs Days 16-End
  let firstHalfPlanned = 0;
  let secondHalfPlanned = 0;
  (appState.plannedExpenses || []).forEach(item => {
    if (!item.date) return;
    const itemYm = item.date.substring(0, 7);
    const inScope = months.includes(itemYm) || (months.includes(currentYm) && itemYm > currentYm);
    if (!inScope) return;
    const amt = Number(item.amount) || 0;
    if (isFirstHalfDate(item.date)) {
      firstHalfPlanned += amt;
    } else {
      secondHalfPlanned += amt;
    }
  });

  // Total Outflows per cutoff (always includes Actual + Unposted Recurring Bills in that half + Planned)
  const firstHalfOutflow = firstHalfActual + firstHalfUnpostedBills + firstHalfPlanned;
  const secondHalfOutflow = secondHalfActual + secondHalfUnpostedBills + secondHalfPlanned;

  // Cushion Math:
  // 1st-Half Cushion = 1st-Half Inflow - 1st-Half Outflow
  const firstHalfCushion = firstHalfInflow - firstHalfOutflow;
  // Positive rollover from 1st-Half buffers the 2nd-Half
  const rolloverFromFirstHalf = Math.max(0, firstHalfCushion);
  const secondHalfEffectiveInflow = secondHalfStandaloneInflow + rolloverFromFirstHalf;
  const secondHalfCushion = secondHalfEffectiveInflow - secondHalfOutflow;

  return {
    firstHalfInflow,
    secondHalfStandaloneInflow,
    rolloverFromFirstHalf,
    secondHalfEffectiveInflow,
    firstHalfActual,
    secondHalfActual,
    firstHalfUnpostedBills,
    secondHalfUnpostedBills,
    firstHalfAllBills,
    secondHalfAllBills,
    firstHalfBillsCount,
    secondHalfBillsCount,
    firstHalfPlanned,
    secondHalfPlanned,
    firstHalfOutflow,
    secondHalfOutflow,
    firstHalfCushion,
    secondHalfCushion
  };
}

function renderCashflowCushionMatcher(baseMetrics = null) {
  const m = baseMetrics || calculateMetrics();
  const cfc = calculateCashflowCushionMetrics(m);
  const setTxt = (id, txt) => {
    const el = document.getElementById(id);
    if (el) el.textContent = txt;
  };

  const evaluateHalfStatus = (inflow, outflow, cushion, labelPrefix) => {
    if (inflow <= 0 && outflow <= 0) {
      return { state: 'ok', badgeText: '⚪ Setup Needed', cls: '', fillPct: 0 };
    }
    const ratio = inflow > 0 ? (outflow / inflow) * 100 : (outflow > 0 ? 100 : 0);
    if (cushion < 0) {
      return {
        state: 'danger',
        badgeText: `🔴 ${labelPrefix} Crunch (${formatCurrency(cushion)})`,
        cls: 'danger',
        cardCls: 'crunch-risk',
        fillPct: 100
      };
    }
    if (ratio >= 85) {
      return {
        state: 'warn',
        badgeText: `🟡 Tight Buffer (${(100 - ratio).toFixed(0)}% left)`,
        cls: 'warn',
        cardCls: 'tight-buffer',
        fillPct: Math.min(100, ratio)
      };
    }
    return {
      state: 'ok',
      badgeText: `🟢 Safe Cushion (${formatCurrency(cushion)})`,
      cls: '',
      cardCls: '',
      fillPct: Math.min(100, Math.max(0, ratio))
    };
  };

  const st1H = evaluateHalfStatus(cfc.firstHalfInflow, cfc.firstHalfOutflow, cfc.firstHalfCushion, 'Mid-Month');
  const st2H = evaluateHalfStatus(cfc.secondHalfEffectiveInflow, cfc.secondHalfOutflow, cfc.secondHalfCushion, 'Month-End');

  // 1. Update Dashboard Cashflow Cushion Widget
  const dashWidget = document.getElementById('dashboardCashflowCushionWidget');
  if (dashWidget) {
    const extra1H = (m.carryoverSurplus || 0) + (m.additionalIncome || 0);
    setTxt(
      'cfcFirstHalfInflowLabel',
      extra1H > 0
        ? `15th Pay (${formatCurrency(m.paycheck15)}) + Extra/Surplus (${formatCurrency(extra1H)})`
        : `15th Paycheck: ${formatCurrency(m.paycheck15)}`
    );
    setTxt(
      'cfcSecondHalfInflowLabel',
      cfc.rolloverFromFirstHalf > 0
        ? `30th Pay (${formatCurrency(m.paycheck30)}) + 1st-Half Rollover (+${formatCurrency(cfc.rolloverFromFirstHalf)})`
        : `30th Paycheck: ${formatCurrency(m.paycheck30)}`
    );

    setTxt('cfcFirstHalfInflow', formatCurrency(cfc.firstHalfInflow));
    setTxt('cfcFirstHalfOutflow', formatCurrency(cfc.firstHalfOutflow));
    setTxt('cfcFirstHalfCushion', `${cfc.firstHalfCushion >= 0 ? '+' : ''}${formatCurrency(cfc.firstHalfCushion)}`);

    setTxt('cfcSecondHalfInflow', formatCurrency(cfc.secondHalfEffectiveInflow));
    setTxt('cfcSecondHalfOutflow', formatCurrency(cfc.secondHalfOutflow));
    setTxt('cfcSecondHalfCushion', `${cfc.secondHalfCushion >= 0 ? '+' : ''}${formatCurrency(cfc.secondHalfCushion)}`);

    const c1El = document.getElementById('cfcFirstHalfCushion');
    if (c1El) c1El.className = `cfc-metric-val ${cfc.firstHalfCushion >= 0 ? 'text-emerald' : 'text-rose'}`;
    const c2El = document.getElementById('cfcSecondHalfCushion');
    if (c2El) c2El.className = `cfc-metric-val ${cfc.secondHalfCushion >= 0 ? 'text-emerald' : 'text-rose'}`;

    const b1El = document.getElementById('cfcFirstHalfBadge');
    if (b1El) {
      b1El.textContent = st1H.badgeText;
      b1El.className = `cfc-cycle-badge ${st1H.cls || ''}`;
    }
    const b2El = document.getElementById('cfcSecondHalfBadge');
    if (b2El) {
      b2El.textContent = st2H.badgeText;
      b2El.className = `cfc-cycle-badge ${st2H.cls || ''}`;
    }

    const card1H = document.getElementById('cfcCardFirstHalf');
    if (card1H) card1H.className = `cfc-cycle-card ${st1H.cardCls || ''}`;
    const card2H = document.getElementById('cfcCardSecondHalf');
    if (card2H) card2H.className = `cfc-cycle-card ${st2H.cardCls || ''}`;

    const bar1H = document.getElementById('cfcFirstHalfBar');
    if (bar1H) {
      bar1H.style.width = `${st1H.fillPct}%`;
      bar1H.className = `cfc-progress-fill ${st1H.cls || ''}`;
    }
    const bar2H = document.getElementById('cfcSecondHalfBar');
    if (bar2H) {
      bar2H.style.width = `${st2H.fillPct}%`;
      bar2H.className = `cfc-progress-fill ${st2H.cls || ''}`;
    }

    setTxt(
      'cfcFirstHalfFoot',
      `Actual (1–15): ${formatCurrency(cfc.firstHalfActual)} · Unposted Bills: ${formatCurrency(cfc.firstHalfUnpostedBills)} · Planned: ${formatCurrency(cfc.firstHalfPlanned)}`
    );
    setTxt(
      'cfcSecondHalfFoot',
      `Actual (16–End): ${formatCurrency(cfc.secondHalfActual)} · Unposted Bills: ${formatCurrency(cfc.secondHalfUnpostedBills)} · Planned: ${formatCurrency(cfc.secondHalfPlanned)}`
    );

    const overallBadge = document.getElementById('cfcDashboardOverallBadge');
    const overallSub = document.getElementById('cfcDashboardSub');
    if (overallBadge && overallSub) {
      if (cfc.firstHalfCushion < 0 && cfc.secondHalfCushion >= 0) {
        overallBadge.textContent = '⚠️ Mid-Month Crunch Risk (Days 1–15)';
        overallBadge.className = 'cfc-overall-badge danger';
        overallSub.textContent = `Your Days 1–15 commitments exceed your 15th paycheck by ${formatCurrency(Math.abs(cfc.firstHalfCushion))} before your 30th paycheck arrives. Consider shifting a recurring bill to after the 15th.`;
      } else if (cfc.firstHalfCushion < 0 && cfc.secondHalfCushion < 0) {
        overallBadge.textContent = '🔴 Both Cutoffs in Deficit';
        overallBadge.className = 'cfc-overall-badge danger';
        overallSub.textContent = `Both 1st-Half (${formatCurrency(cfc.firstHalfCushion)}) and 2nd-Half (${formatCurrency(cfc.secondHalfCushion)}) outflows exceed paycheck inflows.`;
      } else if (cfc.secondHalfCushion < 0) {
        overallBadge.textContent = '⚠️ 2nd-Half Deficit Risk (Days 16–End)';
        overallBadge.className = 'cfc-overall-badge warn';
        overallSub.textContent = `1st-Half has a +${formatCurrency(cfc.firstHalfCushion)} cushion, but Days 16–End commitments still exceed your 30th paycheck + rollover by ${formatCurrency(Math.abs(cfc.secondHalfCushion))}.`;
      } else if (st1H.state === 'warn' || st2H.state === 'warn') {
        overallBadge.textContent = '🟡 Tight Cutoff Buffer';
        overallBadge.className = 'cfc-overall-badge warn';
        overallSub.textContent = `Both paychecks cover their cutoffs, but over 85% of one cutoff is committed. Keep discretionary spending light.`;
      } else {
        overallBadge.textContent = '● Balanced Semi-Monthly Liquidity';
        overallBadge.className = 'cfc-overall-badge';
        overallSub.textContent = `1st-Half Cushion: +${formatCurrency(cfc.firstHalfCushion)} (Days 1–15) · Month-End Cushion: +${formatCurrency(cfc.secondHalfCushion)} (Days 16–End).`;
      }
    }
  }

  // 2. Also enrich KPI Card 1 (15th & 30th tags) with live cushion tooltips
  const tag15 = document.getElementById('kpiIncome15Tag');
  const tag30 = document.getElementById('kpiIncome30Tag');
  if (tag15) {
    tag15.title = `1st-Half Inflow: ${formatCurrency(cfc.firstHalfInflow)} | Days 1–15 Outflows: ${formatCurrency(cfc.firstHalfOutflow)} | Mid-Month Cushion: ${cfc.firstHalfCushion >= 0 ? '+' : ''}${formatCurrency(cfc.firstHalfCushion)}`;
  }
  if (tag30) {
    tag30.title = `30th Paycheck: ${formatCurrency(m.paycheck30)} (+${formatCurrency(cfc.rolloverFromFirstHalf)} 1st-Half Rollover) | Days 16–End Outflows: ${formatCurrency(cfc.secondHalfOutflow)} | Month-End Cushion: ${cfc.secondHalfCushion >= 0 ? '+' : ''}${formatCurrency(cfc.secondHalfCushion)}`;
  }

  // 3. Update Recurring Bills Tab Cashflow Cushion & Bill Load Card
  const billsCard = document.getElementById('billsCashflowCushionCard');
  if (billsCard) {
    setTxt('cfcBills1HInflow', formatCurrency(cfc.firstHalfInflow));
    setTxt('cfcBills1HBills', `${formatCurrency(cfc.firstHalfAllBills)} (${cfc.firstHalfBillsCount})`);
    setTxt('cfcBills1HOutflow', formatCurrency(cfc.firstHalfOutflow));
    setTxt('cfcBills1HCushion', `${cfc.firstHalfCushion >= 0 ? '+' : ''}${formatCurrency(cfc.firstHalfCushion)}`);

    setTxt('cfcBills2HInflow', formatCurrency(cfc.secondHalfEffectiveInflow));
    setTxt('cfcBills2HBills', `${formatCurrency(cfc.secondHalfAllBills)} (${cfc.secondHalfBillsCount})`);
    setTxt('cfcBills2HOutflow', formatCurrency(cfc.secondHalfOutflow));
    setTxt('cfcBills2HCushion', `${cfc.secondHalfCushion >= 0 ? '+' : ''}${formatCurrency(cfc.secondHalfCushion)}`);

    const b1Badge = document.getElementById('cfcBills1HBadge');
    if (b1Badge) {
      b1Badge.textContent = st1H.badgeText;
      b1Badge.className = `cfc-cycle-badge ${st1H.cls || ''}`;
    }
    const b2Badge = document.getElementById('cfcBills2HBadge');
    if (b2Badge) {
      b2Badge.textContent = st2H.badgeText;
      b2Badge.className = `cfc-cycle-badge ${st2H.cls || ''}`;
    }

    const billsOverall = document.getElementById('cfcBillsOverallBadge');
    const billsAdv = document.getElementById('cfcBillsAdvisoryText');
    if (billsOverall && billsAdv) {
      if (cfc.firstHalfCushion < 0) {
        billsOverall.textContent = '⚠️ 1st-Half Overloaded (Mid-Month Crunch)';
        billsOverall.className = 'cfc-overall-badge danger';
        billsAdv.textContent = `Days 1–15 commitments exceed your 15th paycheck by ${formatCurrency(Math.abs(cfc.firstHalfCushion))} (${cfc.firstHalfBillsCount} bills totaling ${formatCurrency(cfc.firstHalfAllBills)} due Days 1–15). Click "1st-Half (Days 1–15)" to inspect bills you can reschedule.`;
      } else if (cfc.secondHalfCushion < 0) {
        billsOverall.textContent = '⚠️ 2nd-Half Overloaded (Days 16–End)';
        billsOverall.className = 'cfc-overall-badge warn';
        billsAdv.textContent = `Days 16–End commitments exceed your 30th paycheck + rollover by ${formatCurrency(Math.abs(cfc.secondHalfCushion))} (${cfc.secondHalfBillsCount} bills totaling ${formatCurrency(cfc.secondHalfAllBills)} due Days 16–End).`;
      } else {
        billsOverall.textContent = '● Balanced Cutoff Load';
        billsOverall.className = 'cfc-overall-badge';
        billsAdv.textContent = `1st-Half Bills (Days 1–15): ${formatCurrency(cfc.firstHalfAllBills)} (${cfc.firstHalfBillsCount} bills) · 2nd-Half Bills (Days 16–End): ${formatCurrency(cfc.secondHalfAllBills)} (${cfc.secondHalfBillsCount} bills).`;
      }
    }
  }
}

// ==========================================
// [FEAT-30] SAFE-TO-SPEND DAILY ALLOWANCE
// ==========================================
function renderSafeToSpend(metrics) {
  const widget = document.getElementById('safeSpendWidget');
  if (!widget) return;

  const m = metrics || calculateMetrics();
  const months = getSortedActiveMonths();
  if (!months.length) return;

  const pad = n => String(n).padStart(2, '0');
  const now = new Date();
  const todayStr = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;

  // Active period boundaries (first day of first month -> last day of last month)
  const [fy, fm] = months[0].split('-').map(Number);
  const [ly, lm] = months[months.length - 1].split('-').map(Number);
  const startDate = new Date(fy, fm - 1, 1);
  const endDate = new Date(ly, lm, 0);
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const MS_DAY = 86400000;

  const spentToday = getActiveExpenses()
    .filter(e => e.date === todayStr)
    .reduce((s, e) => s + (e.amount || 0), 0);

  const isPaydayHorizon = (appState.safeSpendHorizonMode === 'payday');
  const btnHzMonth = document.getElementById('btnHorizonMonth');
  const btnHzPayday = document.getElementById('btnHorizonPayday');
  if (btnHzMonth && btnHzPayday) {
    btnHzMonth.classList.toggle('active', !isPaydayHorizon);
    btnHzPayday.classList.toggle('active', isPaydayHorizon);
  }

  // [FEAT-PAYDAY-HORIZON]: "Until Next Payday (15th or 30th)" mode with unpaid recurring bill reservations
  if (isPaydayHorizon) {
    const curDay = now.getDate();
    let targetCutoffLabel = '15th Payday';
    let pDaysLeft = 1;
    let periodInflow = 0;
    let periodExpenses = 0;
    let periodUnpaidBills = 0;

    if (curDay <= 15) {
      targetCutoffLabel = '15th Payday';
      pDaysLeft = Math.max(1, 15 - curDay + 1);
      periodInflow = (m.paycheck15 || 0) + (m.carryoverSurplus || 0) + (m.additionalIncome || 0);

      getActiveExpenses().forEach(e => {
        if (!e.date || !e.date.startsWith(appState.activeMonth)) return;
        const d = parseInt(e.date.split('-')[2], 10);
        if (d <= 15) {
          if (e.excludeFromBudget || e.isCreditCardPayoff) return;
          periodExpenses += (e.isRefund || e.type === 'refund') ? -Number(e.amount) : Number(e.amount);
        }
      });

      (appState.recurringBills || []).filter(b => b.active !== false).forEach(bill => {
        const dues = getBillDueDatesForMonth(bill, appState.activeMonth);
        dues.forEach(due => {
          const dueDay = parseInt(due.split('-')[2], 10);
          if (dueDay >= curDay && dueDay <= 15 && !isBillDateSettled(bill, due)) {
            periodUnpaidBills += Number(bill.amount) || 0;
          }
        });
      });
    } else {
      const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
      targetCutoffLabel = 'Month-End Payday';
      pDaysLeft = Math.max(1, daysInMonth - curDay + 1);
      periodInflow = (m.paycheck30 || 0);

      getActiveExpenses().forEach(e => {
        if (!e.date || !e.date.startsWith(appState.activeMonth)) return;
        const d = parseInt(e.date.split('-')[2], 10);
        if (d > 15) {
          if (e.excludeFromBudget || e.isCreditCardPayoff) return;
          periodExpenses += (e.isRefund || e.type === 'refund') ? -Number(e.amount) : Number(e.amount);
        }
      });

      (appState.recurringBills || []).filter(b => b.active !== false).forEach(bill => {
        const dues = getBillDueDatesForMonth(bill, appState.activeMonth);
        dues.forEach(due => {
          const dueDay = parseInt(due.split('-')[2], 10);
          if (dueDay >= curDay && dueDay <= daysInMonth && !isBillDateSettled(bill, due)) {
            periodUnpaidBills += Number(bill.amount) || 0;
          }
        });
      });
    }

    const effectiveRemaining = Math.max(0, periodInflow - periodExpenses - periodUnpaidBills);
    const paydayAllowance = pDaysLeft > 0 ? (effectiveRemaining + spentToday) / pDaysLeft : 0;
    const leftToday = paydayAllowance - spentToday;
    const payPct = paydayAllowance > 0 ? (spentToday / paydayAllowance) * 100 : 0;

    const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
    set('safeSpendRemaining', formatCurrency(effectiveRemaining));
    set('safeSpendDays', `${pDaysLeft}d to ${targetCutoffLabel}`);
    set('safeSpendToday', formatCurrency(spentToday));
    set('safeSpendAmount', formatCurrency(paydayAllowance));

    let pState = 'ok';
    let pCaption = `Reserved ${formatCurrency(periodUnpaidBills)} for unpaid bills due before ${targetCutoffLabel}.`;
    if (periodInflow - periodExpenses - periodUnpaidBills < 0) {
      pState = 'over';
      pCaption = `Commitments exceed cutoff inflow by ${formatCurrency(Math.abs(periodInflow - periodExpenses - periodUnpaidBills))}. Hold off on non-essentials until payday!`;
    } else if (leftToday >= 0) {
      pCaption += ` Safe to spend ${formatCurrency(leftToday)} today.`;
    } else {
      pState = 'warn';
      pCaption = `Over daily pace by ${formatCurrency(Math.abs(leftToday))} — tomorrow adjusts.`;
    }

    widget.setAttribute('data-state', pState);
    set('safeSpendCaption', pCaption);

    const fill = document.getElementById('safeSpendBarFill');
    if (fill) {
      fill.style.width = `${Math.min(100, payPct)}%`;
      fill.style.backgroundColor = pState === 'over' ? '#ef4444' : (payPct >= 80 ? '#f59e0b' : '#10b981');
    }
    set('safeSpendBarText', `Today: ${payPct.toFixed(0)}% of Payday Pace`);
    return;
  }

  let daysLeft;
  let phase; // 'running' | 'ended' | 'upcoming'
  if (today > endDate) {
    phase = 'ended';
    daysLeft = 0;
  } else if (today < startDate) {
    phase = 'upcoming';
    daysLeft = Math.round((endDate - startDate) / MS_DAY) + 1;
  } else {
    phase = 'running';
    daysLeft = Math.round((endDate - today) / MS_DAY) + 1; // includes today
  }

  const remaining = m.remainingBudget;
  // Allowance at the start of today = what's left plus what today already consumed
  const allowance = daysLeft > 0 ? Math.max(0, remaining + (phase === 'running' ? spentToday : 0)) / daysLeft : 0;

  const set = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
  set('safeSpendRemaining', formatCurrency(remaining));
  set('safeSpendDays', phase === 'ended' ? '—' : String(daysLeft));
  set('safeSpendToday', formatCurrency(spentToday));

  let state = 'ok';
  let caption = '';
  let pct = 0;

  if (m.totalBudget <= 0) {
    state = 'idle';
    set('safeSpendAmount', formatCurrency(0));
    caption = 'Set budget allocations to see your daily allowance.';
  } else if (phase === 'ended') {
    state = remaining < 0 ? 'over' : 'idle';
    set('safeSpendAmount', formatCurrency(0));
    caption = remaining < 0
      ? `Period ended ${formatCurrency(Math.abs(remaining))} over budget.`
      : `Period ended with ${formatCurrency(remaining)} left unspent. 🎉`;
  } else if (remaining <= 0) {
    state = 'over';
    set('safeSpendAmount', formatCurrency(0));
    caption = remaining < 0
      ? `Budget exceeded by ${formatCurrency(Math.abs(remaining))} — hold off on non-essentials.`
      : 'Budget fully used — nothing left to spend.';
  } else {
    set('safeSpendAmount', formatCurrency(allowance));
    if (phase === 'upcoming') {
      caption = `Planned daily allowance across ${daysLeft} days.`;
    } else {
      const leftToday = allowance - spentToday;
      pct = allowance > 0 ? (spentToday / allowance) * 100 : 0;
      if (leftToday >= 0) {
        caption = `You can still spend ${formatCurrency(leftToday)} today and stay on track.`;
      } else {
        state = 'warn';
        caption = `Over today's allowance by ${formatCurrency(Math.abs(leftToday))} — tomorrow's allowance adjusts.`;
      }
      if (pct >= 80 && state === 'ok') state = 'warn';
    }
  }

  widget.setAttribute('data-state', state);
  set('safeSpendCaption', caption);

  const fill = document.getElementById('safeSpendBarFill');
  if (fill) {
    fill.style.width = `${Math.min(100, pct)}%`;
    fill.style.backgroundColor = state === 'over' ? '#ef4444' : (pct >= 100 ? '#ef4444' : (pct >= 80 ? '#f59e0b' : '#10b981'));
  }
  set('safeSpendBarText', phase === 'running' && m.totalBudget > 0 && remaining > 0
    ? `Today: ${pct.toFixed(0)}% of allowance used`
    : 'Today: n/a');
}

// ==========================================
// [FEAT-38] SAVINGS ANALYST EXECUTIVE & DEEP DIVE INTELLIGENCE
// ==========================================
function renderSavingsAnalyst(metrics) {
  const m = metrics || calculateMetrics();
  const set = (id, txt) => {
    const el = document.getElementById(id);
    if (el) el.textContent = txt;
  };

  // 1. Update Dashboard Savings Analyst Card (Matches Safe-to-Spend Widget Size & Structure)
  const savingsAmtEl = document.getElementById('saDbActualSavings');
  if (savingsAmtEl) {
    savingsAmtEl.textContent = formatCurrency(m.projectedActualSavings);
    savingsAmtEl.className = `safe-spend-amount sa-db-amount ${m.projectedActualSavings >= 0 ? 'text-emerald' : 'text-rose'}`;
  }
  set('saDbSavingsRate', `${m.projectedActualSavingsRate.toFixed(1)}%`);
  set('saDb503020Benchmark', '20.0%');

  const pacingStatusEl = document.getElementById('saDbPacingStatus');
  if (pacingStatusEl) {
    if (m.projectedActualSavingsRate >= 20) {
      pacingStatusEl.textContent = 'Target Met ✨';
      pacingStatusEl.className = 'text-emerald';
    } else if (m.projectedActualSavingsRate > 0) {
      pacingStatusEl.textContent = 'Building 📈';
      pacingStatusEl.className = 'text-amber';
    } else {
      pacingStatusEl.textContent = 'Deficit ⚠️';
      pacingStatusEl.className = 'text-rose';
    }
  }

  const saBar = document.getElementById('saDbBarFill');
  const saBarTxt = document.getElementById('saDbBarText');
  if (saBar) {
    const ratePct = Math.min(100, Math.max(0, (m.projectedActualSavingsRate / 20) * 100));
    saBar.style.width = `${ratePct}%`;
    if (m.projectedActualSavingsRate >= 20) {
      saBar.style.background = 'linear-gradient(90deg, #10b981, #06b6d4)';
    } else if (m.projectedActualSavingsRate >= 10) {
      saBar.style.background = 'linear-gradient(90deg, #f59e0b, #fbbf24)';
    } else {
      saBar.style.background = 'linear-gradient(90deg, #ef4444, #f87171)';
    }
  }
  if (saBarTxt) {
    const rate = m.projectedActualSavingsRate.toFixed(1);
    saBarTxt.textContent = `Savings Rate: ${rate}% (${rate >= 20 ? 'Target achieved! ✨' : 'Target: 20%'})`;
  }

  const dbEl = document.getElementById('saDashboardBanner');
  if (dbEl) {
    let dbState = 'healthy';
    let dbPill = '● Healthy Surplus';
    let dbSub = `Projected monthly cashflow surplus · Click to view deep dive`;
    if (m.totalIncome <= 0 && m.totalBudget <= 0 && m.totalActualExpenses <= 0) {
      dbState = 'neutral';
      dbPill = '● Setup Needed';
      dbSub = 'Add monthly income and budget allocations to view savings analytics.';
    } else if (m.projectedActualSavings < 0) {
      dbState = 'deficit';
      dbPill = `● Deficit: -${formatCurrency(Math.abs(m.projectedActualSavings))}`;
      dbSub = `Spending exceeds income by ${formatCurrency(Math.abs(m.projectedActualSavings))}. Review discretionary costs.`;
    } else if (m.totalBudget > 0 && m.totalActualExpenses > m.totalBudget) {
      dbState = 'warning';
      dbPill = `● Over Budget (${formatCurrency(m.totalActualExpenses - m.totalBudget)})`;
      dbSub = `Actual spending is ${formatCurrency(m.totalActualExpenses - m.totalBudget)} over budget targets.`;
    }
    dbEl.setAttribute('data-state', dbState);
    set('saDbStatusPill', dbPill);
    set('saDbSummaryText', dbSub);
  }

  // Guard for main savings analyst widget on dedicated tab
  const widget = document.getElementById('savingsAnalystWidget');
  if (!widget) return;

  const activePeriodText = typeof formatActivePeriodLabel === 'function' ? formatActivePeriodLabel() : 'Current Period';
  set('saPeriodLabel', activePeriodText);
  set('saPeriodLabelWidget', activePeriodText);
  set('saHeaderBadge', `${m.projectedActualSavingsRate.toFixed(1)}% Realized Savings Rate`);

  // 2. Card 1: Total Income
  set('saTotalIncome', formatCurrency(m.totalIncome));
  const incParts = [`15th: ${formatCurrency(m.paycheck15)}`, `30th: ${formatCurrency(m.paycheck30)}`];
  if (m.additionalIncome > 0) incParts.push(`Extra: ${formatCurrency(m.additionalIncome)}`);
  set('saIncomeBreakdown', incParts.join(' · '));

  // 3. Card 2: Total Budget
  set('saTotalBudget', formatCurrency(m.totalBudget));
  set('saBudgetBreakdown', m.totalIncome > 0 ? `${m.budgetToIncomeRatio.toFixed(1)}% of Total Income` : '0% of Total Income');

  // 4. Card 3: Recorded Expenses (Manual entries)
  set('saRecordedExpenses', formatCurrency(m.recordedExpenses));
  set('saRecordedSub', `${m.recordedTxCount} manual transaction${m.recordedTxCount === 1 ? '' : 's'}`);

  // 5. Card 4: Recurring Expenses (Posted + Not Started / Scheduled Recurring Bills)
  set('saRecurringExpenses', formatCurrency(m.recurringExpenses));
  if (m.recurringCount === 0) {
    set('saRecurringSub', 'No recurring bills logged');
    set('saRecurringTag', 'Logged Bills');
  } else {
    const parts = [];
    if (m.postedRecurringCount > 0) parts.push(`${m.postedRecurringCount} posted`);
    if (m.notStartedRecurringCount > 0) parts.push(`${m.notStartedRecurringCount} not started`);
    const otherUnposted = Math.max(0, (m.unpostedRecurringCount || 0) - (m.notStartedRecurringCount || 0));
    if (otherUnposted > 0) parts.push(`${otherUnposted} scheduled`);
    set('saRecurringSub', parts.join(' · ') + ` (${m.recurringCount} total)`);
    set('saRecurringTag', `${m.recurringCount} Active Bill${m.recurringCount === 1 ? '' : 's'}`);
  }

  // 6. Card 5: Total Actual Expenses (Actual Logged Expenses only)
  set('saTotalActualExpenses', formatCurrency(m.totalActualExpenses));
  if (m.totalBudget > 0) {
    const expVsBudPct = (m.totalActualExpenses / m.totalBudget) * 100;
    set('saActualExpSub', `${expVsBudPct.toFixed(1)}% of Total Budget`);
  } else {
    set('saActualExpSub', `${m.txCount} logged transaction${m.txCount === 1 ? '' : 's'}`);
  }

  // 7. Card 6: Total Projected Savings (Income - Budget)
  const elProjSav = document.getElementById('saProjectedSavings');
  if (elProjSav) {
    elProjSav.textContent = formatCurrency(m.projectedSavings);
    elProjSav.classList.remove('text-emerald', 'text-amber', 'text-rose');
    elProjSav.classList.add(m.projectedSavings >= 0 ? 'text-amber' : 'text-rose');
  }
  set('saProjectedSavingsSub', `${m.projectedSavingsRate.toFixed(1)}% Planned Savings Rate`);

  // 8. Card 7: Projected Actual Savings (Income - Actual Expenses)
  const elActSav = document.getElementById('saProjectedActualSavings');
  if (elActSav) {
    elActSav.textContent = formatCurrency(m.projectedActualSavings);
    elActSav.classList.remove('text-emerald', 'text-amber', 'text-rose');
    elActSav.classList.add(m.projectedActualSavings >= 0 ? 'text-emerald' : 'text-rose');
  }
  const totalForecastDed = (m.totalPlannedExpenses || 0) + (m.unpostedRecurringExpenses || 0);
  const isForecastActive = m.includePlannedInProjections && totalForecastDed > 0;
  if (isForecastActive) {
    const parts = [];
    if (m.totalPlannedExpenses > 0) parts.push(`${formatCurrency(m.totalPlannedExpenses)} planned`);
    if (m.unpostedRecurringExpenses > 0) {
      const recTag = (m.notStartedRecurringCount > 0 && m.notStartedRecurringCount === m.unpostedRecurringCount)
        ? 'not started recurring'
        : 'recurring';
      parts.push(`${formatCurrency(m.unpostedRecurringExpenses)} ${recTag}`);
    }
    set('saProjectedActualSavingsSub', `${m.projectedActualSavingsRate.toFixed(1)}% Net Rate (-${parts.join(' - ')}) • Baseline (Income − Actual): ${formatCurrency(m.netSavings)} (${m.savingsRate.toFixed(1)}%)`);
  } else {
    set('saProjectedActualSavingsSub', `${m.projectedActualSavingsRate.toFixed(1)}% Actual Savings Rate`);
  }

  // 9. Status Pill & Health State
  let state = 'healthy';
  let pillText = '● Healthy Surplus';
  if (m.totalIncome <= 0 && m.totalBudget <= 0 && m.totalActualExpenses <= 0) {
    state = 'neutral';
    pillText = '● Setup Needed';
  } else if (m.projectedActualSavings < 0) {
    state = 'deficit';
    pillText = `● Deficit: -${formatCurrency(Math.abs(m.projectedActualSavings))}`;
  } else if (m.totalBudget > 0 && m.totalActualExpenses > m.totalBudget) {
    state = 'warning';
    pillText = `● Over Budget (${formatCurrency(m.totalActualExpenses - m.totalBudget)})`;
  } else {
    state = 'healthy';
    pillText = `● Healthy Surplus (${m.projectedActualSavingsRate.toFixed(1)}%)`;
  }
  widget.setAttribute('data-state', state);
  set('saStatusPill', pillText);

  // 10. Dual Proportion Bar
  const expPct = m.totalIncome > 0 ? (m.totalActualExpenses / m.totalIncome) * 100 : 0;
  const savPct = m.totalIncome > 0 ? (m.projectedActualSavings / m.totalIncome) * 100 : 0;
  const displayExpPct = Math.min(100, Math.max(0, expPct));
  const displaySavPct = Math.min(100 - displayExpPct, Math.max(0, savPct));

  const barFillExp = document.getElementById('saBarFillExp');
  const barFillSav = document.getElementById('saBarFillSav');
  if (barFillExp) barFillExp.style.width = `${displayExpPct}%`;
  if (barFillSav) barFillSav.style.width = `${displaySavPct}%`;

  set('saBarExpLabel', `Actual Expenses: ${expPct.toFixed(1)}% of Income`);
  set('saBarSavLabel', `Actual Savings: ${m.projectedActualSavingsRate.toFixed(1)}% of Income`);

  // 11. Plain-English Dynamic Insight Box
  const insightEl = document.getElementById('saInsightText');
  if (insightEl) {
    let insightHtml = '';
    if (m.totalIncome <= 0) {
      insightHtml = '💡 <span>Add your monthly income schedule in Monthly Budget to unlock complete cashflow analytics.</span>';
    } else if (m.projectedActualSavings < 0) {
      insightHtml = `⚠️ <span><strong>Cashflow Deficit Alert:</strong> Actual spending (${formatCurrency(m.totalActualExpenses)}) exceeds income by <strong>${formatCurrency(Math.abs(m.projectedActualSavings))}</strong>. Pause discretionary spending.</span>`;
    } else if (m.totalBudget > 0 && m.projectedActualSavings > m.projectedSavings) {
      const bonusSavings = m.projectedActualSavings - m.projectedSavings;
      insightHtml = `🚀 <span><strong>Under Budget:</strong> You are on track to save <strong>${formatCurrency(bonusSavings)} more</strong> than planned (${formatCurrency(m.projectedActualSavings)} actual vs ${formatCurrency(m.projectedSavings)} planned).</span>`;
    } else if (m.totalBudget > 0 && m.totalActualExpenses > m.totalBudget) {
      const overBudget = m.totalActualExpenses - m.totalBudget;
      insightHtml = `⚡ <span><strong>Caution:</strong> Actual expenses exceed budget by <strong>${formatCurrency(overBudget)}</strong>, pulling your projected savings down to ${formatCurrency(m.projectedActualSavings)}.</span>`;
    } else {
      insightHtml = `✨ <span><strong>Optimal Trajectory:</strong> Projected actual savings of <strong>${formatCurrency(m.projectedActualSavings)}</strong> (${m.projectedActualSavingsRate.toFixed(1)}% savings rate) aligns with your targets.</span>`;
    }
    insightEl.innerHTML = insightHtml;
  }

  // ============================================================
  // DEEP-DIVE ENHANCEMENTS: HEALTH GRADE, 50/30/20, RUNWAY, WEALTH
  // ============================================================

  // A. Savings Health Grade & Scorecard
  const billsPct = m.totalIncome > 0 ? (m.recurringExpenses / m.totalIncome) * 100 : 0;
  let savingsRateScore = 0;
  if (m.projectedActualSavingsRate >= 20) savingsRateScore = 40;
  else if (m.projectedActualSavingsRate > 0) savingsRateScore = (m.projectedActualSavingsRate / 20) * 40;

  let budgetScore = 0;
  if (m.budgetUtilization <= 90) budgetScore = 40;
  else if (m.budgetUtilization <= 100) budgetScore = 32;
  else budgetScore = Math.max(0, 32 - (m.budgetUtilization - 100) * 1.5);

  let billsScore = 0;
  if (billsPct <= 30) billsScore = 20;
  else billsScore = Math.max(0, 20 - (billsPct - 30) * 0.7);

  const totalHealthScore = Math.min(100, Math.max(0, Math.round(savingsRateScore + budgetScore + billsScore)));
  set('saHealthScoreNum', String(totalHealthScore));

  const gradeBadge = document.getElementById('saGradeBadge');
  let gradeLetter = 'Grade A';
  let gradeTitle = 'Strong Wealth Builder';
  let gradeDesc = 'You are retaining a healthy share of your income with responsible spending.';

  if (m.totalIncome <= 0) {
    gradeLetter = 'Grade —';
    gradeTitle = 'Setup Needed';
    gradeDesc = 'Add your income and budgets to generate your customized financial health score.';
  } else if (m.projectedActualSavings < 0) {
    gradeLetter = 'Grade D / Deficit';
    gradeTitle = 'Immediate Action Needed';
    gradeDesc = `Actual expenses exceed income by ${formatCurrency(Math.abs(m.projectedActualSavings))}. Review high-spend categories.`;
  } else if (totalHealthScore >= 90) {
    gradeLetter = 'Grade A+';
    gradeTitle = 'Outstanding Wealth Builder';
    gradeDesc = 'Exceptional savings pace! Your cash retention puts you in prime position for financial independence.';
  } else if (totalHealthScore >= 80) {
    gradeLetter = 'Grade A';
    gradeTitle = 'Strong Wealth Builder';
    gradeDesc = 'You are retaining a solid portion of income and keeping expenses well within planned limits.';
  } else if (totalHealthScore >= 70) {
    gradeLetter = 'Grade B';
    gradeTitle = 'Steady Financial Progress';
    gradeDesc = 'Solid foundation, but trimming recurring subscriptions or dining out could accelerate savings.';
  } else if (totalHealthScore >= 55) {
    gradeLetter = 'Grade C';
    gradeTitle = 'Moderate Cashflow Pressure';
    gradeDesc = 'Spending is close to total income. Re-evaluating non-essential spending will rebuild breathing room.';
  } else {
    gradeLetter = 'Grade D';
    gradeTitle = 'Budget Under Strain';
    gradeDesc = 'Very low savings buffer. Prioritize reducing top outflow categories to restore savings.';
  }

  if (gradeBadge) {
    gradeBadge.textContent = gradeLetter;
    gradeBadge.className = `sa-grade-badge ${totalHealthScore >= 80 ? 'grade-a' : (totalHealthScore >= 65 ? 'grade-b' : 'grade-c')}`;
  }
  set('saHealthSummaryTitle', gradeTitle);
  set('saHealthSummaryDesc', gradeDesc);

  set('saScoreSavingsRate', `${m.projectedActualSavingsRate.toFixed(1)}%`);
  set('saScoreBudgetAdherence', `${m.budgetUtilization.toFixed(1)}%`);
  set('saScoreBillsDrag', `${billsPct.toFixed(1)}%`);

  // B. 50 / 30 / 20 Rule Analysis (Powered by [FEAT-39] Smart Needs vs Wants Tags)
  const needsSpent = (m.actualNeeds !== undefined) ? m.actualNeeds : 0;
  const wantsSpent = (m.actualWants !== undefined) ? m.actualWants : 0;

  const needsPct = m.totalIncome > 0 ? (needsSpent / m.totalIncome) * 100 : 0;
  const wantsPct = m.totalIncome > 0 ? (wantsSpent / m.totalIncome) * 100 : 0;
  const savingsRulePct = Math.max(0, m.projectedActualSavingsRate);

  set('saRuleNeedsText', `${formatCurrency(needsSpent)} (${needsPct.toFixed(1)}% of Income · Benchmark: ≤50%)`);
  set('saRuleWantsText', `${formatCurrency(wantsSpent)} (${wantsPct.toFixed(1)}% of Income · Benchmark: ≤30%)`);
  set('saRuleSavingsText', `${formatCurrency(m.projectedActualSavings)} (${savingsRulePct.toFixed(1)}% of Income · Benchmark: ≥20%)`);

  const fillNeeds = document.getElementById('saRuleNeedsFill');
  const fillWants = document.getElementById('saRuleWantsFill');
  const fillSav = document.getElementById('saRuleSavingsFill');
  if (fillNeeds) {
    fillNeeds.style.width = `${Math.min(100, needsPct)}%`;
    fillNeeds.setAttribute('title', `Needs: ${formatCurrency(needsSpent)} (${needsPct.toFixed(1)}% of income · Benchmark: ≤50%). ${needsPct <= 50 ? 'Essentials within safe limit.' : 'High essentials burden.'}`);
  }
  if (fillWants) {
    fillWants.style.width = `${Math.min(100, wantsPct)}%`;
    fillWants.setAttribute('title', `Wants: ${formatCurrency(wantsSpent)} (${wantsPct.toFixed(1)}% of income · Benchmark: ≤30%). ${wantsPct <= 30 ? 'Discretionary spending is well-controlled.' : 'High discretionary spending.'}`);
  }
  if (fillSav) {
    fillSav.style.width = `${Math.min(100, savingsRulePct)}%`;
    fillSav.setAttribute('title', `Savings: ${formatCurrency(m.projectedActualSavings)} (${savingsRulePct.toFixed(1)}% of income · Benchmark: ≥20%). ${savingsRulePct >= 20 ? 'Strong wealth-building velocity!' : 'Below recommended 20% pace.'}`);
  }

  let ruleFeedback = '💡 Needs and Wants are within sustainable limits.';
  if (m.totalIncome <= 0) {
    ruleFeedback = '💡 Add income to see your 50/30/20 benchmark adherence.';
  } else if (needsPct > 50) {
    ruleFeedback = `⚠️ <strong>High Essentials:</strong> Needs absorb <strong>${needsPct.toFixed(1)}%</strong> of income (target ≤50%). Look for savings on utilities or grocery subscriptions.`;
  } else if (wantsPct > 30) {
    ruleFeedback = `⚠️ <strong>High Discretionary:</strong> Wants consume <strong>${wantsPct.toFixed(1)}%</strong> of income (target ≤30%). Trimming shopping or dining can quickly elevate your savings.`;
  } else if (savingsRulePct >= 20) {
    ruleFeedback = `🎉 <strong>50/30/20 Master:</strong> Your savings rate of <strong>${savingsRulePct.toFixed(1)}%</strong> exceeds the 20% benchmark while keeping essentials under control!`;
  } else {
    ruleFeedback = `💡 Balanced spending! Boosting your realized savings from ${savingsRulePct.toFixed(1)}% to 20% will unlock faster financial peace of mind.`;
  }
  const feedbackEl = document.getElementById('saRuleFeedbackText');
  if (feedbackEl) feedbackEl.innerHTML = ruleFeedback;

  // C. Emergency Runway & Safety Net Targets
  const monthlyLivingCost = m.totalActualExpenses > 0 ? m.totalActualExpenses : (m.totalBudget > 0 ? m.totalBudget : 0);
  const target3Mo = monthlyLivingCost * 3;
  const target6Mo = monthlyLivingCost * 6;

  set('saTarget3Mo', formatCurrency(target3Mo));
  set('saTarget6Mo', formatCurrency(target6Mo));

  let runwayMonths = '0.0';
  if (monthlyLivingCost > 0 && m.projectedActualSavings > 0) {
    runwayMonths = (m.projectedActualSavings / monthlyLivingCost).toFixed(1);
  } else if (m.projectedActualSavings <= 0) {
    runwayMonths = '0.0';
  } else {
    runwayMonths = '—';
  }
  set('saRunwayVal', runwayMonths);
  set('saRunwayLabel', 'Months of Living Expenses Covered Per Period');
  set('saRunwaySub', monthlyLivingCost > 0 ? `Based on ${formatCurrency(monthlyLivingCost)} monthly logged expenses` : 'Set budgets or log expenses to calculate');

  // D. Wealth Accumulation Simulator
  const monthlySavingsPace = Math.max(0, m.projectedActualSavings);
  const wealth3Mo = monthlySavingsPace * 3;
  const wealth6Mo = monthlySavingsPace * 6;
  const wealth9Mo = monthlySavingsPace * 9;
  const wealth1Yr = monthlySavingsPace * 12;

  // Compound interest at 4.5% annual rate compounded monthly
  const rMonth = 0.045 / 12;
  const fv3Yr = rMonth > 0 ? monthlySavingsPace * ((Math.pow(1 + rMonth, 36) - 1) / rMonth) : monthlySavingsPace * 36;
  const fv5Yr = rMonth > 0 ? monthlySavingsPace * ((Math.pow(1 + rMonth, 60) - 1) / rMonth) : monthlySavingsPace * 60;

  set('saWealth3Mo', formatCurrency(wealth3Mo));
  set('saWealth6Mo', formatCurrency(wealth6Mo));
  set('saWealth9Mo', formatCurrency(wealth9Mo));
  set('saWealth1Yr', formatCurrency(wealth1Yr));
  set('saWealth3Yr', formatCurrency(fv3Yr));
  set('saWealth5Yr', formatCurrency(fv5Yr));

  // Initialize/refresh wealth horizon display
  try {
    const savedHorizon = localStorage.getItem('budget_app_wealth_horizon') || 'all';
    setWealthForecastHorizon(savedHorizon);
  } catch (e) {
    setWealthForecastHorizon('all');
  }

  // E. Top Expense Drag on Savings
  const dragContainer = document.getElementById('saTopExpenseDragList');
  if (dragContainer) {
    const activeCats = (appState.categories || [])
      .map(c => ({
        id: c.id,
        name: c.name,
        icon: c.icon || '🏷️',
        color: c.color || '#06b6d4',
        amount: (m.categorySpending && m.categorySpending[c.id]) || 0
      }))
      .filter(c => c.amount > 0)
      .sort((a, b) => b.amount - a.amount);

    if (activeCats.length === 0) {
      dragContainer.innerHTML = '<div class="sa-drag-empty">No expenses logged yet in active period.</div>';
    } else {
      const top3 = activeCats.slice(0, 3);
      let html = '';
      top3.forEach((c, idx) => {
        const catIncomePct = m.totalIncome > 0 ? ((c.amount / m.totalIncome) * 100).toFixed(1) : '0.0';
        const tenPctSaving = c.amount * 0.1;
        html += `
          <div class="sa-drag-item">
            <div class="sa-drag-item-left">
              <span class="sa-drag-rank">#${idx + 1}</span>
              <span class="sa-drag-icon">${c.icon}</span>
              <div>
                <strong>${c.name}</strong>
                <span class="sa-drag-meta">${catIncomePct}% of Total Income</span>
              </div>
            </div>
            <div class="sa-drag-item-right">
              <strong>${formatCurrency(c.amount)}</strong>
              <span class="sa-trim-badge" title="Cutting 10% from this category">+${formatCurrency(tenPctSaving)}/mo</span>
            </div>
          </div>
        `;
      });
      dragContainer.innerHTML = html;

      // Update opportunity tip
      const tipEl = document.getElementById('saSavingsOpportunityTip');
      if (tipEl && top3.length > 0) {
        const topCat = top3[0];
        const boostAmt = topCat.amount * 0.1;
        tipEl.innerHTML = `💡 <strong>Top Savings Opportunity:</strong> Trimming just 10% from <strong>${topCat.name}</strong> will retain an extra <strong>${formatCurrency(boostAmt)}/month</strong> (${formatCurrency(boostAmt * 12)}/year) directly in your savings!`;
      }
    }
  }

  // F. Render Cashflow Allocation Donut Chart
  renderSavingsAllocationChart(m, needsSpent, wantsSpent);
}

// ==========================================
// [FEAT-38] WEALTH FORECAST HORIZON SWITCHER
// ==========================================
function setWealthForecastHorizon(horizon) {
  const normHorizon = ['months', 'years', 'all'].includes(horizon) ? horizon : 'all';
  try {
    localStorage.setItem('budget_app_wealth_horizon', normHorizon);
  } catch (e) {}

  const pills = document.querySelectorAll('.btn-wealth-pill');
  pills.forEach(p => {
    p.classList.toggle('active', p.getAttribute('data-horizon') === normHorizon);
  });

  const monthsSection = document.getElementById('saWealthMonthsSection');
  const yearsSection = document.getElementById('saWealthYearsSection');

  if (monthsSection && yearsSection) {
    if (normHorizon === 'months') {
      monthsSection.style.display = 'block';
      yearsSection.style.display = 'none';
    } else if (normHorizon === 'years') {
      monthsSection.style.display = 'none';
      yearsSection.style.display = 'block';
    } else {
      monthsSection.style.display = 'block';
      yearsSection.style.display = 'block';
    }
  }
}

// ==========================================
// [FEAT-38] SAVINGS CASHFLOW ALLOCATION CHART
// ==========================================
function renderSavingsAllocationChart(m, needsSpent, wantsSpent) {
  const canvas = document.getElementById('savingsAllocationChart');
  const storyEl = document.getElementById('saChartStoryText');
  if (!canvas || !window.Chart) return;

  if (savingsChartInstance) {
    savingsChartInstance.destroy();
  }

  const themeColors = getChartThemeColors();
  const savingsAmt = Math.max(0, m.projectedActualSavings);
  const total = needsSpent + wantsSpent + savingsAmt;

  if (total <= 0) {
    if (storyEl) {
      storyEl.innerHTML = `💡 <strong>Financial Story:</strong> Record income and expenses for this period to reveal your personalized cashflow narrative and benchmark breakdown.`;
    }
    const ctx = canvas.getContext('2d');
    savingsChartInstance = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: ['No Data Available'],
        datasets: [{
          data: [1],
          backgroundColor: ['rgba(255, 255, 255, 0.08)'],
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: { enabled: false }
        }
      }
    });
    return;
  }

  const needsPct = total > 0 ? ((needsSpent / total) * 100).toFixed(1) : '0.0';
  const wantsPct = total > 0 ? ((wantsSpent / total) * 100).toFixed(1) : '0.0';
  const savingsPct = total > 0 ? ((savingsAmt / total) * 100).toFixed(1) : '0.0';

  if (storyEl) {
    if (m.projectedActualSavings > 0) {
      if (parseFloat(savingsPct) >= 20) {
        storyEl.innerHTML = `💡 <strong>Financial Story:</strong> <strong>Outstanding financial discipline!</strong> You are retaining <strong>${savingsPct}%</strong> (${formatCurrency(savingsAmt)}) of your total income as pure savings, surpassing the 20% benchmark. Living essentials consume <strong>${needsPct}%</strong> while discretionary lifestyle accounts for <strong>${wantsPct}%</strong>.`;
      } else {
        storyEl.innerHTML = `💡 <strong>Financial Story:</strong> <strong>Positive cashflow maintained.</strong> You are saving <strong>${savingsPct}%</strong> (${formatCurrency(savingsAmt)}) this month. Living essentials take <strong>${needsPct}%</strong> and discretionary wants take <strong>${wantsPct}%</strong>. Trimming non-essential wants can accelerate your path to the 20% savings gold standard.`;
      }
    } else {
      const deficit = Math.abs(m.projectedActualSavings);
      storyEl.innerHTML = `⚠️ <strong>Financial Story:</strong> <strong>Cashflow Deficit!</strong> Your actual expenses exceed income by <strong>${formatCurrency(deficit)}</strong>. Living essentials consume <strong>${needsPct}%</strong> and discretionary wants consume <strong>${wantsPct}%</strong>. Review discretionary wants or optimize fixed bills to protect your savings cushion.`;
    }
  }

  const ctx = canvas.getContext('2d');
  savingsChartInstance = new Chart(ctx, {
    type: 'doughnut',
    data: {
      labels: ['Needs (Essentials)', 'Wants (Discretionary)', 'Realized Savings'],
      datasets: [{
        data: [needsSpent, wantsSpent, savingsAmt],
        backgroundColor: ['#06b6d4', '#8b5cf6', '#10b981'],
        borderColor: themeColors.grid,
        borderWidth: 2,
        hoverOffset: 6
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: 'bottom',
          labels: {
            color: themeColors.text,
            boxWidth: 12,
            font: { size: 11, family: 'Inter, sans-serif' },
            padding: 12
          }
        },
        tooltip: {
          backgroundColor: 'rgba(15, 23, 42, 0.95)',
          titleColor: '#f8fafc',
          bodyColor: '#cbd5e1',
          borderColor: 'rgba(255, 255, 255, 0.12)',
          borderWidth: 1,
          padding: 12,
          boxPadding: 6,
          usePointStyle: true,
          cornerRadius: 8,
          callbacks: {
            title: function(items) {
              if (!items || !items.length) return '';
              const idx = items[0].dataIndex;
              if (idx === 0) return 'Needs (Essential Living Costs)';
              if (idx === 1) return 'Wants (Discretionary Spending)';
              return 'Realized Savings (Retained Wealth)';
            },
            label: function(context) {
              const val = context.parsed || 0;
              const pct = total > 0 ? ((val / total) * 100).toFixed(1) : '0.0';
              return ` Amount: ${formatCurrency(val)} (${pct}% of cashflow)`;
            },
            afterLabel: function(context) {
              const idx = context.dataIndex;
              const pct = total > 0 ? ((context.parsed || 0) / total) * 100 : 0;
              const lines = [];
              if (idx === 0) {
                lines.push('');
                lines.push('📖 What this tells you:');
                lines.push('• Recommended Target: ≤ 50% of income');
                lines.push('• Covers groceries, housing, utilities, bills & debt service');
                if (pct <= 50) {
                  lines.push('✅ Healthy: Your essential living costs are well-contained.');
                } else {
                  lines.push(`⚠️ Above Benchmark: Essentials take ${pct.toFixed(1)}% (> 50%). Look to optimize fixed recurring bills.`);
                }
              } else if (idx === 1) {
                lines.push('');
                lines.push('📖 What this tells you:');
                lines.push('• Recommended Target: ≤ 30% of income');
                lines.push('• Covers dining out, entertainment, shopping & hobbies');
                if (pct <= 30) {
                  lines.push('✅ Balanced: Discretionary lifestyle spending is safely disciplined.');
                } else {
                  lines.push(`⚠️ Above Benchmark: Wants consume ${pct.toFixed(1)}% (> 30%). Trimming here directly increases your savings.`);
                }
              } else if (idx === 2) {
                lines.push('');
                lines.push('📖 What this tells you:');
                lines.push('• Recommended Target: ≥ 20% of income');
                lines.push('• Builds emergency runway, investment growth & long-term wealth');
                if (pct >= 20) {
                  lines.push(`🌟 Excellent: Retaining ${pct.toFixed(1)}% keeps you in the top tier of wealth builders!`);
                } else if (pct > 0) {
                  lines.push(`💡 Room to Grow: Currently at ${pct.toFixed(1)}%. Rebalance from Wants to reach the 20% milestone.`);
                } else {
                  lines.push('⚠️ Deficit: No cash retained this month. Expenses currently outpace income.');
                }
              }
              return lines;
            }
          }
        }
      },
      cutout: '68%'
    }
  });
}

// ==========================================
// 14. POWER BI CHARTS RENDERING (THEME-AWARE)
// ==========================================
/**
 * [FEAT-TREND-FORECAST] Dated forecast items (not yet in Actual Expenses) for the active months.
 * Mirrors calculateMetrics() so the chart's month-end running total equals
 * Actual + Planned + Unposted / Not Started Recurring shown on the KPI cards.
 */
function getTrendForecastItems(months) {
  const items = [];
  const today = typeof billTodayStr === 'function' ? billTodayStr() : new Date().toISOString().split('T')[0];

  // 1. Unposted + Not Started recurring bill occurrences
  (appState.recurringBills || []).filter(b => b.active !== false).forEach(bill => {
    months.forEach(m => {
      const excluded = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[m]) || [];
      if (bill.categoryId && excluded.includes(bill.categoryId)) return;
      const dues = getBillDueDatesForMonth(bill, m);
      const isNotStarted = Boolean(bill.startDate && bill.startDate > today);
      let effectiveDues;
      if (isNotStarted) {
        const after = dues.filter(d => d >= bill.startDate);
        effectiveDues = after.length > 0 ? after : (dues.length > 0 ? dues : [bill.startDate]);
      } else {
        effectiveDues = dues.filter(d => !(bill.startDate && d < bill.startDate));
      }
      effectiveDues.forEach(due => {
        if (!isBillDateSettled(bill, due)) {
          items.push({ date: due, amount: Number(bill.amount) || 0, kind: 'recurring' });
        }
      });
    });
  });

  // 2. Planned / future one-time commitments (same scope rule as calculateMetrics)
  const currentYm = today.substring(0, 7);
  (appState.plannedExpenses || []).forEach(item => {
    const m = item.date ? item.date.substring(0, 7) : null;
    const inScope = !m || months.includes(m) || (months.includes(currentYm) && m > currentYm);
    if (inScope) {
      items.push({ date: item.date || today, amount: Number(item.amount) || 0, kind: 'planned' });
    }
  });

  return items;
}

/** Least-squares linear fit over the first `fitCount` points, projected across `length` points. */
function computeLinearTrend(values, fitCount, length) {
  const n = Math.min(fitCount, values.length);
  if (n < 2) return new Array(length).fill(null);
  let sx = 0, sy = 0, sxy = 0, sxx = 0;
  for (let i = 0; i < n; i++) {
    sx += i; sy += values[i]; sxy += i * values[i]; sxx += i * i;
  }
  const denom = n * sxx - sx * sx;
  const slope = denom !== 0 ? (n * sxy - sx * sy) / denom : 0;
  const intercept = (sy - slope * sx) / n;
  return Array.from({ length }, (_, i) => Math.max(0, intercept + slope * i));
}

function renderTrendChart() {
  const canvas = document.getElementById('expenseTrendChart');
  if (!canvas || !window.Chart) return;

  const months = getSortedActiveMonths();
  const themeColors = getChartThemeColors();
  const allActiveExpenses = getActiveExpenses();
  const todayStr = typeof billTodayStr === 'function' ? billTodayStr() : new Date().toISOString().split('T')[0];
  const isSingleMonth = months.length === 1;

  let labels = [];
  let periodSpend = [];
  let barLabel = 'Daily Spent';
  let bucketCount = 0;
  let bucketIndexForDate; // (YYYY-MM-DD) => bucket index (clamped)
  let fitCount = 0;       // number of elapsed buckets used to fit the trend line

  if (isSingleMonth) {
    // Single month: Daily breakdown Day 1..daysInMonth
    barLabel = 'Daily Spent';
    const monthKey = months[0];
    const [yearStr, monthStr] = monthKey.split('-');
    const daysInMonth = new Date(parseInt(yearStr, 10), parseInt(monthStr, 10), 0).getDate();
    bucketCount = daysInMonth;
    labels = Array.from({ length: daysInMonth }, (_, i) => `Day ${i + 1}`);
    bucketIndexForDate = (d) => {
      if (!d) return daysInMonth - 1;
      const ym = d.substring(0, 7);
      if (ym < monthKey) return 0;
      if (ym > monthKey) return daysInMonth - 1;
      const day = parseInt(d.split('-')[2], 10) || 1;
      return Math.min(Math.max(day, 1), daysInMonth) - 1;
    };
    const currentYm = todayStr.substring(0, 7);
    if (monthKey < currentYm) fitCount = daysInMonth;
    else if (monthKey === currentYm) fitCount = parseInt(todayStr.split('-')[2], 10) || 1;
    else fitCount = 0;
  } else {
    // Multi-month active period: Monthly breakdown with cumulative line
    barLabel = 'Monthly Spent';
    bucketCount = months.length;
    labels = months.map(m => {
      const [y, mo] = m.split('-');
      const d = new Date(parseInt(y, 10), parseInt(mo, 10) - 1, 1);
      return d.toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
    });
    bucketIndexForDate = (d) => {
      if (!d) return months.length - 1;
      const ym = d.substring(0, 7);
      const idx = months.indexOf(ym);
      if (idx >= 0) return idx;
      return ym < months[0] ? 0 : months.length - 1;
    };
    const currentYm = todayStr.substring(0, 7);
    fitCount = months.filter(m => m <= currentYm).length;
  }

  // Actual spend per bucket
  periodSpend = new Array(bucketCount).fill(0);
  allActiveExpenses.forEach(e => {
    if (!e.date) return;
    periodSpend[bucketIndexForDate(e.date)] += Number(e.amount) || 0;
  });

  // Forecast spend per bucket (planned + unposted / not-started recurring)
  const forecastPlanned = new Array(bucketCount).fill(0);
  const forecastRecurring = new Array(bucketCount).fill(0);
  getTrendForecastItems(months).forEach(item => {
    const idx = bucketIndexForDate(item.date);
    if (item.kind === 'planned') forecastPlanned[idx] += item.amount;
    else forecastRecurring[idx] += item.amount;
  });

  // Running totals
  const cumulativeSpend = [];
  const runningTotalWithForecast = [];
  let cumActual = 0;
  let cumAll = 0;
  for (let i = 0; i < bucketCount; i++) {
    cumActual += periodSpend[i];
    cumAll += periodSpend[i] + forecastPlanned[i] + forecastRecurring[i];
    cumulativeSpend.push(cumActual);
    runningTotalWithForecast.push(cumAll);
  }
  const totalPlannedFc = forecastPlanned.reduce((a, b) => a + b, 0);
  const totalRecurringFc = forecastRecurring.reduce((a, b) => a + b, 0);
  const totalForecast = totalPlannedFc + totalRecurringFc;
  const hasForecast = totalForecast > 0;

  // Trend line fitted on actual spend for elapsed buckets, projected over the full period
  const trendLine = computeLinearTrend(periodSpend, fitCount, bucketCount);
  const hasTrend = trendLine.some(v => v !== null);

  // Header summary pill
  const summaryEl = document.getElementById('trendChartForecastSummary');
  if (summaryEl) {
    if (hasForecast) {
      summaryEl.style.display = 'inline-flex';
      summaryEl.textContent = `Actual ${formatCurrency(cumActual)} + Forecast ${formatCurrency(totalForecast)} = ${formatCurrency(cumAll)}`;
      summaryEl.title = `Running total at end of period: Actual Expenses (${formatCurrency(cumActual)}) + Planned (${formatCurrency(totalPlannedFc)}) + Recurring not yet posted (${formatCurrency(totalRecurringFc)})`;
    } else {
      summaryEl.style.display = 'none';
    }
  }

  if (trendChartInstance) {
    trendChartInstance.destroy();
  }

  const ctx = canvas.getContext('2d');
  const gradientPurple = ctx.createLinearGradient(0, 0, 0, 300);
  gradientPurple.addColorStop(0, 'rgba(139, 92, 246, 0.4)');
  gradientPurple.addColorStop(1, 'rgba(139, 92, 246, 0.0)');

  const datasets = [
    {
      label: 'Cumulative Spent (Actual)',
      data: cumulativeSpend,
      stack: 'line-actual',
      borderColor: '#8b5cf6',
      backgroundColor: gradientPurple,
      fill: true,
      tension: 0.35,
      borderWidth: 2.5,
      pointRadius: isSingleMonth ? 2 : 4,
      pointHoverRadius: 6,
      order: 3
    }
  ];

  if (hasForecast) {
    datasets.push({
      label: 'Running Total (Actual + Forecast)',
      data: runningTotalWithForecast,
      stack: 'line-forecast',
      borderColor: '#f59e0b',
      backgroundColor: 'transparent',
      borderDash: [6, 4],
      fill: false,
      tension: 0.35,
      borderWidth: 2.25,
      pointRadius: isSingleMonth ? 0 : 3,
      pointHoverRadius: 5,
      order: 2
    });
  }

  if (hasTrend) {
    datasets.push({
      label: `Trend (${barLabel})`,
      data: trendLine,
      stack: 'line-trend',
      borderColor: '#f43f5e',
      backgroundColor: 'transparent',
      borderDash: [3, 3],
      fill: false,
      tension: 0,
      borderWidth: 1.75,
      pointRadius: 0,
      pointHoverRadius: 3,
      order: 1
    });
  }

  datasets.push({
    label: barLabel,
    data: periodSpend,
    type: 'bar',
    stack: 'bars',
    backgroundColor: 'rgba(6, 182, 212, 0.75)',
    borderRadius: 4,
    borderSkipped: false,
    order: 4
  });

  if (hasForecast) {
    datasets.push({
      label: 'Forecast: Recurring Bills',
      data: forecastRecurring,
      type: 'bar',
      stack: 'bars',
      backgroundColor: 'rgba(56, 189, 248, 0.28)',
      borderColor: 'rgba(56, 189, 248, 0.85)',
      borderWidth: 1,
      borderRadius: 4,
      borderSkipped: false,
      order: 4
    });
    datasets.push({
      label: 'Forecast: Planned Expenses',
      data: forecastPlanned,
      type: 'bar',
      stack: 'bars',
      backgroundColor: 'rgba(245, 158, 11, 0.28)',
      borderColor: 'rgba(245, 158, 11, 0.85)',
      borderWidth: 1,
      borderRadius: 4,
      borderSkipped: false,
      order: 4
    });
  }

  trendChartInstance = new Chart(ctx, {
    type: 'line',
    data: {
      labels: labels,
      datasets: datasets
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: {
        mode: 'index',
        intersect: false
      },
      plugins: {
        legend: {
          display: true,
          position: 'bottom',
          labels: {
            color: themeColors.axisTicks,
            usePointStyle: true,
            boxWidth: 8,
            boxHeight: 8,
            padding: 10,
            font: { family: 'Plus Jakarta Sans', size: 10 }
          }
        },
        tooltip: {
          backgroundColor: themeColors.tooltipBg,
          titleColor: themeColors.tooltipTitle,
          bodyColor: themeColors.tooltipBody,
          borderColor: themeColors.tooltipBorder,
          borderWidth: 1,
          padding: 12,
          filter: (item) => item.raw !== null && !(item.dataset.label.startsWith('Forecast') && !item.raw),
          callbacks: {
            label: function(context) {
              return ` ${context.dataset.label}: ${formatCurrency(context.raw || 0)}`;
            }
          }
        }
      },
      scales: {
        x: {
          stacked: true,
          grid: {
            color: themeColors.gridLine,
            tickLength: 0
          },
          ticks: {
            color: themeColors.axisTicks,
            maxTicksLimit: 12,
            font: { family: 'Plus Jakarta Sans', size: 11 }
          }
        },
        y: {
          stacked: true,
          grid: {
            color: themeColors.gridLine
          },
          ticks: {
            color: themeColors.axisTicks,
            font: { family: 'Plus Jakarta Sans', size: 11 },
            callback: (v) => appState.currency + v
          }
        }
      }
    }
  });
}

function renderCategoryPieChart(categorySpending) {
  const canvas = document.getElementById('categoryBreakdownChart');
  if (!canvas || !window.Chart) return;

  const activeCategories = appState.categories.filter(c => (categorySpending[c.id] || 0) > 0);
  const activeCountBadge = document.getElementById('activeCategoryCountBadge');
  if (activeCountBadge) {
    activeCountBadge.textContent = `${activeCategories.length} Active`;
  }

  const themeColors = getChartThemeColors();

  if (pieChartInstance) {
    pieChartInstance.destroy();
  }

  if (activeCategories.length === 0) {
    const ctx = canvas.getContext('2d');
    pieChartInstance = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: ['No Expenses Logged'],
        datasets: [{
          data: [1],
          backgroundColor: [themeColors.gridLine],
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          tooltip: { enabled: false },
          legend: { display: false }
        },
        cutout: '72%'
      }
    });
    return;
  }

  const labels = activeCategories.map(c => `${c.icon} ${c.name}`);
  const data = activeCategories.map(c => categorySpending[c.id]);
  const colors = activeCategories.map(c => c.color);

  const ctx = canvas.getContext('2d');
  pieChartInstance = new Chart(ctx, {
    type: 'doughnut',
    data: {
      labels: labels,
      datasets: [{
        data: data,
        backgroundColor: colors,
        borderColor: themeColors.donutBorder,
        borderWidth: 3,
        hoverOffset: 6
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          position: 'right',
          labels: {
            color: themeColors.axisTicks,
            font: { family: 'Plus Jakarta Sans', size: 11, weight: '500' },
            boxWidth: 12,
            padding: 12
          }
        },
        tooltip: {
          backgroundColor: themeColors.tooltipBg,
          borderColor: themeColors.tooltipBorder,
          titleColor: themeColors.tooltipTitle,
          bodyColor: themeColors.tooltipBody,
          borderWidth: 1,
          padding: 12,
          callbacks: {
            label: function(context) {
              const val = context.raw;
              const total = context.dataset.data.reduce((a, b) => a + b, 0);
              const pct = ((val / total) * 100).toFixed(1);
              return ` ${formatCurrency(val)} (${pct}%)`;
            }
          }
        }
      },
      cutout: '68%'
    }
  });
}

