// ==========================================
// 15. [FEAT-26] DASHBOARD LISTS & DETAILS (HIGHEST SPENDING CATEGORIES DEFAULT VIEW SORTING)
// ==========================================
function renderDashboardLists(categorySpending, categoryBudgets = null) {
  // [FEAT-26] Top Categories (Highest Spending Categories)
  // When spending is $0.00 (default view), automatically sorts by highest budgeted amount descending
  const topList = document.getElementById('topCategoriesList');
  if (topList) {
    const sorted = [...appState.categories]
      .map(c => {
        const spent = categorySpending ? (categorySpending[c.id] || 0) : 0;
        const budgeted = (categoryBudgets && categoryBudgets[c.id] !== undefined)
          ? categoryBudgets[c.id]
          : (appState.budgets[appState.activeMonth]?.[c.id] || c.defaultBudget || 0);
        return { ...c, spent, budgeted };
      })
      .sort((a, b) => {
        // 1. Primary: sort by highest actual spending
        if (b.spent !== a.spent) {
          return b.spent - a.spent;
        }
        // 2. [FEAT-26] Default view / zero-spend tie-breaker: sort by highest budgeted amount
        if (b.budgeted !== a.budgeted) {
          return b.budgeted - a.budgeted;
        }
        // 3. Fallback: alphabetical by name
        return a.name.localeCompare(b.name);
      })
      .slice(0, 5);

    const maxSpend = sorted[0]?.spent || 1;

    topList.innerHTML = '';
    sorted.forEach(c => {
      const pct = maxSpend > 0 ? (c.spent / maxSpend) * 100 : 0;
      const row = document.createElement('div');
      row.className = 'cat-item-row';
      row.innerHTML = `
        <div class="cat-info">
          <div class="cat-icon-box" style="background: rgba(255,255,255,0.05); color: ${c.color}">
            ${c.icon}
          </div>
          <div>
            <div class="cat-name">${escapeHTML(c.name)}</div>
            <div class="cat-meta">Budgeted: ${formatCurrency(c.budgeted)}</div>
          </div>
        </div>
        <div class="cat-amount-wrap">
          <div class="cat-amount">${formatCurrency(c.spent)}</div>
          <div class="cat-percent-bar">
            <div class="cat-percent-fill" style="width: ${pct}%; background-color: ${c.color};"></div>
          </div>
        </div>
      `;
      topList.appendChild(row);
    });
  }

  // Recent 5 Transactions
  const recentList = document.getElementById('recentExpensesList');
  if (recentList) {
    const sorted = getMonthlyExpenses().sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 5);
    recentList.innerHTML = '';

    if (sorted.length === 0) {
      recentList.innerHTML = `<div style="text-align: center; color: var(--text-secondary); padding: 24px;">No transactions recorded this month yet.</div>`;
      return;
    }

    sorted.forEach(item => {
      const cat = appState.categories.find(c => c.id === item.categoryId) || { icon: '🏷️' };
      const row = document.createElement('div');
      row.className = 'tx-item-row';
      row.innerHTML = `
        <div class="tx-main">
          <div class="cat-icon-box" style="background: rgba(255,255,255,0.05);">${cat.icon}</div>
          <div>
            <div class="tx-desc">${escapeHTML(item.description)}</div>
            <div class="tx-details">
              <span>${formatShortDate(item.date)}</span>
              ${item.paymentMethod ? `<span>•</span><span>${escapeHTML(item.paymentMethod)}</span>` : ''}
            </div>
          </div>
        </div>
        <div class="tx-amount">-${formatCurrency(item.amount)}</div>
      `;
      recentList.appendChild(row);
    });
  }
}

// ==========================================
// 16. [FEAT-25] DETAILED CATEGORY VARIANCE SCORECARD TABLE & INTERACTIVE SORTING
//     [FEAT-29] EXPANDABLE CATEGORY EXPENSE ACCORDION DRILLDOWN
// ==========================================
const expandedVarianceCategoryIds = new Set();

let varianceSortState = {
  field: 'budgeted',
  order: 'desc'
};

function updateVarianceSortHeaders() {
  document.querySelectorAll('#varianceTable thead th.sortable-th').forEach(th => {
    const field = th.getAttribute('data-sort');
    const icon = th.querySelector('.sort-icon');
    th.classList.remove('sorted-asc', 'sorted-desc');
    if (field === varianceSortState.field) {
      th.classList.add(varianceSortState.order === 'asc' ? 'sorted-asc' : 'sorted-desc');
      if (icon) icon.textContent = varianceSortState.order === 'asc' ? '▲' : '▼';
    } else {
      if (icon) icon.textContent = '↕';
    }
  });
}

function toggleVarianceCategoryDrilldown(catId) {
  if (expandedVarianceCategoryIds.has(catId)) {
    expandedVarianceCategoryIds.delete(catId);
  } else {
    expandedVarianceCategoryIds.add(catId);
  }
  renderVarianceTable();
}

function toggleAllVarianceDrilldowns() {
  const visibleCategories = appState.categories || [];
  if (visibleCategories.length === 0) return;

  const allExpanded = visibleCategories.every(c => expandedVarianceCategoryIds.has(c.id));
  if (allExpanded) {
    expandedVarianceCategoryIds.clear();
  } else {
    visibleCategories.forEach(c => expandedVarianceCategoryIds.add(c.id));
  }
  renderVarianceTable();
}

function jumpToCategoryExpenses(catId) {
  switchTab('expenses');
  const filterCatSelect = document.getElementById('expenseFilterCategory');
  if (filterCatSelect) {
    filterCatSelect.value = catId;
  }
  const searchInput = document.getElementById('expenseSearchInput');
  if (searchInput) {
    searchInput.value = '';
  }
  renderExpensesTable();

  const cat = (appState.categories || []).find(c => c.id === catId);
  const catName = cat ? cat.name : catId;
  const filtered = typeof getFilteredExpensesList === 'function' ? getFilteredExpensesList() : [];
  if (typeof showToast === 'function') {
    showToast(`Filtered Expense Tracker: ${catName} (${filtered.length} ${filtered.length === 1 ? 'transaction' : 'transactions'})`, 'info', 3000);
  }
}

function jumpToCategoryBudget(catId) {
  switchTab('budget');
  if (typeof activeCategoryClassificationFilter !== 'undefined') {
    activeCategoryClassificationFilter = 'all';
    document.querySelectorAll('.btn-cat-filter').forEach(btn => {
      btn.classList.toggle('active', btn.getAttribute('data-filter') === 'all');
    });
    renderBudgetGrid();
  }
  setTimeout(() => {
    const card = document.querySelector(`.budget-cat-card[data-cat-id="${catId}"]`);
    if (card) {
      card.scrollIntoView({ behavior: 'smooth', block: 'center' });
      card.classList.add('flash-highlight');
      setTimeout(() => card.classList.remove('flash-highlight'), 1800);
    }
    const cat = (appState.categories || []).find(c => c.id === catId);
    const catName = cat ? cat.name : catId;
    if (typeof showToast === 'function') {
      showToast(`Jumped to ${catName} in Budget Allocations`, 'info', 2500);
    }
  }, 120);
}

function openExpenseModalWithCategory(catId) {
  openExpenseModal(null, catId);
}

function renderVarianceTable(metrics) {
  const tbody = document.getElementById('varianceTableBody');
  if (!tbody) return;

  const m = metrics || calculateMetrics();
  const currentBudgetObj = appState.budgets[appState.activeMonth] || {};
  tbody.innerHTML = '';

  const activePeriodExpenses = getActiveExpenses();
  const periodLabel = formatActivePeriodLabel();
  const sortedMonths = getSortedActiveMonths();
  const primaryMonth = sortedMonths.length === 1 ? sortedMonths[0] : appState.activeMonth;
  const monthProg = getMonthProgress(primaryMonth);

  const excludedInPeriod = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[primaryMonth]) || [];
  const visibleCategories = appState.categories.filter(c => !excludedInPeriod.includes(c.id));

  const rows = visibleCategories.map(cat => {
    const budgeted = (m.categoryBudgets && m.categoryBudgets[cat.id] !== undefined)
      ? m.categoryBudgets[cat.id]
      : (currentBudgetObj[cat.id] || 0);
    const spent = m.categorySpending[cat.id] || 0;
    const variance = budgeted - spent;
    const utilization = budgeted > 0 ? (spent / budgeted) * 100 : (spent > 0 ? 100 : 0);

    let statusText = 'Unused';
    let statusRank = 0;
    let statusBadge = '';
    let barColor = '#10b981';

    if (spent === 0 && budgeted === 0) {
      statusText = 'Unused';
      statusRank = 0;
      statusBadge = '<span class="kpi-status-badge" style="background: rgba(255,255,255,0.05); color: var(--text-muted)">Unused</span>';
    } else if (budgeted > 0 && spent > budgeted) {
      statusText = 'Over Budget';
      statusRank = 4;
      statusBadge = '<span class="kpi-status-badge badge-danger">🔴 Over Cap</span>';
      barColor = '#ef4444';
    } else if (sortedMonths.length === 1 && monthProg.isCurrent) {
      const pace = calculatePacingStatus(budgeted, spent, monthProg);
      if (pace.badgeClass === 'pace-warning') {
        statusText = 'Fast Burn';
        statusRank = 3;
        statusBadge = `<span class="kpi-status-badge badge-warning" title="${pace.badgeText}">⚠️ Fast Burn</span>`;
        barColor = '#f59e0b';
      } else if (pace.badgeClass === 'pace-frugal') {
        statusText = 'Frugal Pace';
        statusRank = 1;
        statusBadge = `<span class="kpi-status-badge badge-success" title="${pace.badgeText}">🟢 Frugal Pace</span>`;
        barColor = '#10b981';
      } else {
        statusText = 'On Track';
        statusRank = 2;
        statusBadge = `<span class="kpi-status-badge badge-success" style="background: rgba(6, 182, 212, 0.15); color: #38bdf8;" title="${pace.badgeText}">🟡 On Track</span>`;
        barColor = '#06b6d4';
      }
    } else if (utilization <= 75) {
      statusText = 'Under Budget';
      statusRank = 1;
      statusBadge = '<span class="kpi-status-badge badge-success">Under Budget</span>';
      barColor = '#10b981';
    } else if (utilization <= 100) {
      statusText = 'Near Limit';
      statusRank = 2;
      statusBadge = '<span class="kpi-status-badge badge-warning">Near Limit</span>';
      barColor = '#f59e0b';
    } else {
      statusText = 'Over Budget';
      statusRank = 3;
      statusBadge = '<span class="kpi-status-badge badge-danger">Over Budget</span>';
      barColor = '#ef4444';
    }

    return {
      cat,
      name: cat.name,
      budgeted,
      spent,
      variance,
      utilization,
      statusText,
      statusRank,
      statusBadge,
      barColor
    };
  });

  // Sort rows based on varianceSortState
  rows.sort((a, b) => {
    let comp = 0;
    switch (varianceSortState.field) {
      case 'name':
        comp = a.name.localeCompare(b.name);
        break;
      case 'budgeted':
        comp = a.budgeted - b.budgeted;
        break;
      case 'spent':
        comp = a.spent - b.spent;
        break;
      case 'variance':
        comp = a.variance - b.variance;
        break;
      case 'utilization':
        comp = a.utilization - b.utilization;
        break;
      case 'status':
        comp = (a.statusRank - b.statusRank) || a.statusText.localeCompare(b.statusText);
        break;
      default:
        comp = a.budgeted - b.budgeted;
    }
    return varianceSortState.order === 'asc' ? comp : -comp;
  });

  rows.forEach(item => {
    const isExpanded = expandedVarianceCategoryIds.has(item.cat.id);
    const catExpenses = activePeriodExpenses
      .filter(e => e.categoryId === item.cat.id)
      .sort((a, b) => new Date(b.date) - new Date(a.date));

    // Category parent row
    const tr = document.createElement('tr');
    tr.className = `variance-cat-row ${isExpanded ? 'expanded' : ''}`;
    tr.setAttribute('data-cat-id', item.cat.id);
    tr.title = `Click to ${isExpanded ? 'collapse' : 'expand'} expense transactions for ${escapeHTML(item.cat.name)}`;

    tr.innerHTML = `
      <td>
        <div class="variance-cat-cell">
          <button type="button" class="btn-variance-expand ${isExpanded ? 'is-expanded' : ''}" data-cat-id="${item.cat.id}" title="${isExpanded ? 'Collapse' : 'Expand'} transactions" aria-label="Toggle drilldown">
            <span class="chevron-icon">${isExpanded ? '▼' : '▶'}</span>
          </button>
          <button type="button" class="btn-variance-cat-edit" data-cat-id="${item.cat.id}" title="Click to edit category: ${escapeHTML(item.cat.name)} (Name, Icon, Color, Budget Allocation)">
            <span class="variance-cat-icon">${item.cat.icon}</span>
            <strong class="variance-cat-name-text">${escapeHTML(item.cat.name)}</strong>
            <span class="edit-pencil-cue" title="Edit Category" aria-hidden="true">✏️</span>
          </button>
          <span class="variance-tx-count-pill" title="${catExpenses.length} transactions recorded in ${escapeHTML(periodLabel)}">${catExpenses.length} txns</span>
        </div>
      </td>
      <td class="text-right">${formatCurrency(item.budgeted)}</td>
      <td class="text-right" style="color: var(--text-secondary); font-weight: 600;">${formatCurrency(item.spent)}</td>
      <td class="text-right ${item.variance >= 0 ? 'text-emerald' : 'text-rose'}" style="font-weight: 700;">
        ${item.variance >= 0 ? '+' : ''}${formatCurrency(item.variance)}
      </td>
      <td>
        <div class="progress-pill-wrap">
          <div class="progress-track">
            <div class="progress-bar-val" style="width: ${Math.min(100, item.utilization)}%; background-color: ${item.barColor};"></div>
          </div>
          <span class="progress-label" style="color: ${item.barColor};">${item.utilization.toFixed(0)}%</span>
        </div>
      </td>
      <td class="text-center">${item.statusBadge}</td>
    `;

    // Category click opens edit modal
    const catEditBtn = tr.querySelector('.btn-variance-cat-edit');
    if (catEditBtn) {
      catEditBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openEditCategoryModal(item.cat.id);
      });
    }

    // Clicking row toggles accordion
    tr.addEventListener('click', () => {
      toggleVarianceCategoryDrilldown(item.cat.id);
    });

    tbody.appendChild(tr);

    // If expanded, render detail drilldown sub-row
    if (isExpanded) {
      const detailTr = document.createElement('tr');
      detailTr.className = 'variance-detail-row';
      const detailTd = document.createElement('td');
      detailTd.className = 'variance-detail-td';
      detailTd.colSpan = 6;

      let subtableContent = '';
      if (catExpenses.length === 0) {
        subtableContent = `
          <div class="drilldown-empty-box">
            <span>No expense transactions recorded for <strong>${escapeHTML(item.cat.name)}</strong> in the selected period (<em>${escapeHTML(periodLabel)}</em>).</span>
            <button type="button" class="btn btn-primary btn-xs btn-add-cat-expense" data-cat-id="${item.cat.id}">+ Add Transaction</button>
          </div>
        `;
      } else {
        const txRows = catExpenses.map(tx => {
          const pctOfCat = item.spent > 0 ? ((tx.amount / item.spent) * 100).toFixed(1) + '%' : '0.0%';
          return `
            <tr>
              <td class="drilldown-date">${formatShortDate(tx.date)}</td>
              <td>
                <div class="drilldown-desc">
                  <span class="drilldown-desc-main">${escapeHTML(tx.description || 'Expense')}</span>
                </div>
              </td>
              <td>
                <span class="kpi-tag">${escapeHTML(tx.paymentMethod || 'Credit Card')}</span>
              </td>
              <td class="text-right drilldown-amount" style="font-weight: 600; color: #f87171;">
                -${formatCurrency(tx.amount)}
              </td>
              <td class="text-right drilldown-pct">
                ${pctOfCat}
              </td>
              <td class="text-center">
                <div style="display: inline-flex; gap: 4px;">
                  <button type="button" class="btn-icon btn-edit-drilldown-tx" data-tx-id="${tx.id}" title="Edit Transaction" style="display:inline-flex; width:26px; height:26px; padding:0; align-items:center; justify-content:center;">
                    <svg viewBox="0 0 24 24" width="12" height="12" stroke="currentColor" fill="none" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
                  </button>
                  <button type="button" class="btn-icon btn-dup-drilldown-tx" data-tx-id="${tx.id}" title="Duplicate Transaction" style="display:inline-flex; width:26px; height:26px; padding:0; align-items:center; justify-content:center;">
                    <svg viewBox="0 0 24 24" width="12" height="12" stroke="currentColor" fill="none" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>
                  </button>
                  <button type="button" class="btn-icon btn-del-drilldown-tx" data-tx-id="${tx.id}" title="Delete Transaction" style="display:inline-flex; width:26px; height:26px; padding:0; align-items:center; justify-content:center; color: #f87171;">
                    <svg viewBox="0 0 24 24" width="12" height="12" stroke="currentColor" fill="none" stroke-width="2"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>
                  </button>
                </div>
              </td>
            </tr>
          `;
        }).join('');

        subtableContent = `
          <div class="drilldown-table-responsive">
            <table class="drilldown-subtable">
              <thead>
                <tr>
                  <th style="width: 105px;">Date</th>
                  <th>Description</th>
                  <th style="width: 140px;">Payment Method</th>
                  <th style="width: 115px;" class="text-right">Amount</th>
                  <th style="width: 90px;" class="text-right">% of Cat</th>
                  <th style="width: 105px;" class="text-center">Actions</th>
                </tr>
              </thead>
              <tbody>
                ${txRows}
              </tbody>
            </table>
          </div>
        `;
      }

      detailTd.innerHTML = `
        <div class="variance-drilldown-card">
          <div class="variance-drilldown-header">
            <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
              <span class="drilldown-badge">EXPENSE BREAKDOWN</span>
              <span style="font-size: 0.82rem; color: var(--text-secondary);">
                <strong>${escapeHTML(item.cat.name)}</strong>: ${catExpenses.length} ${catExpenses.length === 1 ? 'transaction' : 'transactions'} totaling <strong style="color: #fff;">${formatCurrency(item.spent)}</strong> in ${escapeHTML(periodLabel)}
              </span>
            </div>
            <div style="display: flex; align-items: center; gap: 8px;">
              <button type="button" class="btn btn-secondary btn-xs btn-add-cat-expense" data-cat-id="${item.cat.id}">+ Add Expense</button>
              <button type="button" class="btn-drilldown-tracker" data-cat-id="${item.cat.id}">🔍 View in Expense Tracker</button>
            </div>
          </div>
          ${subtableContent}
        </div>
      `;

      // Prevent clicks inside detailTd from triggering parent row toggle
      detailTr.addEventListener('click', (e) => {
        e.stopPropagation();
      });

      // Wire subtable action buttons
      detailTd.querySelectorAll('.btn-add-cat-expense').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          openExpenseModalWithCategory(btn.getAttribute('data-cat-id'));
        });
      });

      detailTd.querySelectorAll('.btn-drilldown-tracker').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          jumpToCategoryExpenses(btn.getAttribute('data-cat-id'));
        });
      });

      detailTd.querySelectorAll('.btn-edit-drilldown-tx').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          openExpenseModal(btn.getAttribute('data-tx-id'));
        });
      });

      detailTd.querySelectorAll('.btn-dup-drilldown-tx').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          openExpenseModal(null, null, btn.getAttribute('data-tx-id'));
        });
      });

      detailTd.querySelectorAll('.btn-del-drilldown-tx').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          deleteExpense(btn.getAttribute('data-tx-id'));
        });
      });

      detailTr.appendChild(detailTd);
      tbody.appendChild(detailTr);
    }
  });

  updateVarianceSortHeaders();

  // [FEAT-29] Update Toggle All Drilldowns button text
  const toggleAllText = document.getElementById('toggleAllDrilldownsText');
  if (toggleAllText) {
    const visibleCategories = appState.categories || [];
    const isAllExpanded = visibleCategories.length > 0 && visibleCategories.every(c => expandedVarianceCategoryIds.has(c.id));
    toggleAllText.textContent = isAllExpanded ? '▲ Collapse All' : '▾ Expand All';
  }

  // Footer Totals
  document.getElementById('varianceFooterBudget').textContent = formatCurrency(m.totalBudget);
  document.getElementById('varianceFooterActual').textContent = formatCurrency(m.totalExpenses);
  
  const diffEl = document.getElementById('varianceFooterDiff');
  diffEl.textContent = `${m.remainingBudget >= 0 ? '+' : ''}${formatCurrency(m.remainingBudget)}`;
  diffEl.className = `text-right ${m.remainingBudget >= 0 ? 'text-emerald' : 'text-rose'}`;

  document.getElementById('varianceFooterPct').textContent = `${m.budgetUtilization.toFixed(1)}%`;

  const footerStatus = document.getElementById('varianceFooterStatus');
  if (m.budgetUtilization <= 75) {
    footerStatus.textContent = 'ON TRACK';
    footerStatus.className = 'kpi-status-badge badge-success';
  } else if (m.budgetUtilization <= 100) {
    footerStatus.textContent = 'WARNING';
    footerStatus.className = 'kpi-status-badge badge-warning';
  } else {
    footerStatus.textContent = 'OVER BUDGET';
    footerStatus.className = 'kpi-status-badge badge-danger';
  }
}

