// 17. EXPORT & BACKUP UTILITIES
// ==========================================
function exportCSVReport() {
  const metrics = calculateMetrics();
  const currentBudgetObj = appState.budgets[appState.activeMonth] || {};
  const periodLabel = formatActivePeriodLabel();

  let csvContent = `NirvTrack - Financial & Variance Report (${periodLabel})\n\n`;
  csvContent += `INCOME SUMMARY (${appState.currency})\n`;
  csvContent += `15th Paycheck,${metrics.paycheck15}\n`;
  csvContent += `30th Paycheck,${metrics.paycheck30}\n`;
  csvContent += `Additional / Bonus Income,${metrics.additionalIncome}\n`;
  csvContent += `Total Income,${metrics.totalIncome}\n\n`;

  csvContent += `SAVINGS ANALYSIS (${appState.currency})\n`;
  csvContent += `Total Budget Allocated,${metrics.totalBudget}\n`;
  csvContent += `Total Expenses Spent,${metrics.totalExpenses}\n`;
  csvContent += `Planned Savings (Income - Budget),${metrics.plannedSavings}\n`;
  csvContent += `Actual Net Savings (Income - Expenses),${metrics.netSavings}\n`;
  csvContent += `Savings Rate,${metrics.savingsRate.toFixed(1)}%\n\n`;

  csvContent += `CATEGORY BREAKDOWN\n`;
  csvContent += `Category,Budget Allocated (${appState.currency}),Actual Spent (${appState.currency}),Variance (${appState.currency}),Utilization %\n`;

  const excludedInPeriod = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[appState.activeMonth]) || [];
  const exportCategories = appState.categories.filter(c => !excludedInPeriod.includes(c.id));

  exportCategories.forEach(cat => {
    const budgeted = (metrics.categoryBudgets && metrics.categoryBudgets[cat.id] !== undefined)
      ? metrics.categoryBudgets[cat.id]
      : (currentBudgetObj[cat.id] || 0);
    const spent = metrics.categorySpending[cat.id] || 0;
    const variance = budgeted - spent;
    const util = budgeted > 0 ? ((spent / budgeted) * 100).toFixed(1) : 0;
    csvContent += `"${cat.name}",${budgeted},${spent},${variance},${util}%\n`;
  });

  csvContent += `\n"Grand Total Budget",${metrics.totalBudget},${metrics.totalExpenses},${metrics.remainingBudget},${metrics.budgetUtilization.toFixed(1)}%\n`;

  const fileNameSafe = periodLabel.replace(/[^a-zA-Z0-9_-]/g, '_');
  downloadFile(csvContent, `Financial_Report_${fileNameSafe}.csv`, 'text/csv;charset=utf-8;');
  showToast('Comprehensive Financial CSV Report downloaded!');
}

// ==========================================
// [CSV UPLOAD & IMPORT ENGINE] EXPENSE TRANSACTIONS
// ==========================================
function parseCSV(text) {
  if (!text) return [];
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1); // Strip UTF-8 BOM

  const rows = [];
  let currentRow = [];
  let currentVal = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const nextChar = text[i + 1];

    if (inQuotes) {
      if (char === '"' && nextChar === '"') {
        currentVal += '"';
        i++;
      } else if (char === '"') {
        inQuotes = false;
      } else {
        currentVal += char;
      }
    } else {
      if (char === '"') {
        inQuotes = true;
      } else if (char === ',') {
        currentRow.push(currentVal.trim());
        currentVal = '';
      } else if (char === '\r') {
        if (nextChar === '\n') i++;
        currentRow.push(currentVal.trim());
        if (currentRow.length > 1 || (currentRow.length === 1 && currentRow[0] !== '')) {
          rows.push(currentRow);
        }
        currentRow = [];
        currentVal = '';
      } else if (char === '\n') {
        currentRow.push(currentVal.trim());
        if (currentRow.length > 1 || (currentRow.length === 1 && currentRow[0] !== '')) {
          rows.push(currentRow);
        }
        currentRow = [];
        currentVal = '';
      } else {
        currentVal += char;
      }
    }
  }

  if (currentVal !== '' || currentRow.length > 0) {
    currentRow.push(currentVal.trim());
    if (currentRow.length > 1 || (currentRow.length === 1 && currentRow[0] !== '')) {
      rows.push(currentRow);
    }
  }

  return rows;
}

function parseCSVDate(dateStr) {
  if (!dateStr) return null;
  const clean = String(dateStr).trim();

  // YYYY-MM-DD or YYYY/MM/DD or YYYY.MM.DD
  const ymdMatch = clean.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
  if (ymdMatch) {
    const y = ymdMatch[1];
    const m = String(ymdMatch[2]).padStart(2, '0');
    const d = String(ymdMatch[3]).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  // MM/DD/YYYY or M/D/YYYY
  const mdyMatch = clean.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
  if (mdyMatch) {
    let m = parseInt(mdyMatch[1], 10);
    let d = parseInt(mdyMatch[2], 10);
    const y = mdyMatch[3];
    if (m > 12 && d <= 12) {
      const t = m;
      m = d;
      d = t;
    }
    return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
  }

  // Fallback to Date parser
  const parsed = new Date(clean);
  if (!isNaN(parsed.getTime())) {
    const y = parsed.getFullYear();
    const m = String(parsed.getMonth() + 1).padStart(2, '0');
    const d = String(parsed.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  return null;
}

function parseCSVAmount(amtStr) {
  if (amtStr === undefined || amtStr === null) return null;
  let clean = String(amtStr).replace(/[$₱£\s]/g, '').trim();
  if (clean.startsWith('(') && clean.endsWith(')')) {
    clean = clean.slice(1, -1);
  }
  clean = clean.replace(/,/g, '');
  const num = parseFloat(clean);
  if (isNaN(num)) return null;
  return Math.abs(num);
}

function findCSVColumnIndex(headers, aliases) {
  for (let i = 0; i < headers.length; i++) {
    const h = (headers[i] || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    for (const alias of aliases) {
      const a = alias.toLowerCase().replace(/[^a-z0-9]/g, '');
      if (h === a || h.includes(a)) {
        return i;
      }
    }
  }
  return -1;
}

// ==========================================
// [FEAT-41] EXPENSE TRACKER CSV BATCH UPLOAD & INTELLIGENT IMPORTER
// ==========================================
function handleExpenseCSVUpload(e) {
  const file = e.target.files && e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(evt) {
    try {
      const text = evt.target.result;
      processExpenseCSVContent(text, file.name);
    } catch (err) {
      console.error('CSV import error:', err);
      showToast('Failed to process CSV: ' + err.message, 'error');
    }
  };
  reader.onerror = function() {
    showToast('Failed to read CSV file. Please try again.', 'error');
  };
  reader.readAsText(file);
}

function processExpenseCSVContent(text, fileName = '') {
  const rows = parseCSV(text);
  if (!rows || rows.length < 2) {
    showToast('The CSV file is empty or contains no data rows.', 'warning');
    return;
  }

  const headers = rows[0].map(h => (h || '').trim());

  // Required columns
  const dateIdx = findCSVColumnIndex(headers, ['date', 'txdate', 'transdate', 'transactiondate', 'postingdate', 'time']);
  const descIdx = findCSVColumnIndex(headers, ['description', 'desc', 'vendor', 'payee', 'merchant', 'details', 'memo', 'name', 'narrative', 'title', 'item']);
  const amtIdx = findCSVColumnIndex(headers, ['amount', 'cost', 'total', 'debit', 'price', 'charge', 'spent', 'expense', 'value']);

  if (dateIdx === -1 || descIdx === -1 || amtIdx === -1) {
    const missing = [];
    if (dateIdx === -1) missing.push('Date');
    if (descIdx === -1) missing.push('Description');
    if (amtIdx === -1) missing.push('Amount');
    showToast(`CSV missing required column(s): ${missing.join(', ')}. Required fields are Date, Description, and Amount.`, 'error', 6500);
    return;
  }

  // Optional columns (any not included will simply be left blank "")
  const catIdx = findCSVColumnIndex(headers, ['category', 'cat', 'categoryname']);
  const payIdx = findCSVColumnIndex(headers, ['paymentmethod', 'payment', 'method', 'account']);
  const typeIdx = findCSVColumnIndex(headers, ['budgettype', 'tag', 'type', 'classification', 'needswants']);

  const importedExpenses = [];
  let skippedCount = 0;

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || row.length === 0 || (row.length === 1 && !row[0])) {
      continue;
    }

    const rawDate = row[dateIdx] || '';
    const rawDesc = row[descIdx] || '';
    const rawAmt = row[amtIdx] || '';

    const parsedDate = parseCSVDate(rawDate);
    const parsedDesc = rawDesc.trim();
    const parsedAmt = parseCSVAmount(rawAmt);

    // Validation: Date, Description, Amount are required
    if (!parsedDate || !parsedDesc || parsedAmt === null || parsedAmt <= 0) {
      skippedCount++;
      continue;
    }

    // Optional columns: leave blank if not included or not matched
    let matchedCatId = '';
    if (catIdx !== -1 && row[catIdx]) {
      const rawCat = row[catIdx].trim().toLowerCase();
      if (rawCat) {
        const found = appState.categories.find(c =>
          c.id.toLowerCase() === rawCat ||
          c.name.toLowerCase() === rawCat ||
          c.name.toLowerCase().includes(rawCat)
        );
        if (found) {
          matchedCatId = found.id;
        }
      }
    }

    let matchedPayMethod = '';
    if (payIdx !== -1 && row[payIdx]) {
      const rawPm = row[payIdx].trim();
      if (rawPm) {
        const knownMethods = ['Cash', 'Credit Card', 'Debit Card', 'Bank Transfer', 'GCash', 'Maya', 'PayPal', 'Digital Wallet'];
        const found = knownMethods.find(m => m.toLowerCase() === rawPm.toLowerCase());
        matchedPayMethod = found || rawPm;
      }
    }

    let matchedBudgetType = '';
    if (typeIdx !== -1 && row[typeIdx]) {
      const rawType = row[typeIdx].trim().toLowerCase();
      if (rawType.includes('want')) matchedBudgetType = 'wants';
      else if (rawType.includes('need')) matchedBudgetType = 'needs';
    }
    if (!matchedBudgetType && matchedCatId) {
      matchedBudgetType = getCategoryBudgetType(matchedCatId) || '';
    }

    const newTx = {
      id: 'tx_csv_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 6) + '_' + i,
      date: parsedDate,
      description: parsedDesc,
      amount: parsedAmt,
      categoryId: matchedCatId,       // Blank if not included in CSV
      paymentMethod: matchedPayMethod, // Blank if not included in CSV
      budgetType: matchedBudgetType    // Blank if not included in CSV
    };

    importedExpenses.push(newTx);
  }

  if (importedExpenses.length === 0) {
    showToast(`No valid transactions imported. Please check that Date, Description, and positive Amount are provided.`, 'error', 6000);
    return;
  }

  // Append new transactions to current workspace expenses
  appState.expenses.push(...importedExpenses);

  // If none of the imported expenses fall in the currently selected month, switch activeMonth so user sees them immediately
  const importedMonths = [...new Set(importedExpenses.map(e => e.date.slice(0, 7)))].filter(Boolean);
  if (importedMonths.length > 0 && !importedMonths.includes(appState.activeMonth)) {
    appState.activeMonth = importedMonths[0];
    if (!appState.activeMonths.includes(importedMonths[0])) {
      appState.activeMonths = [importedMonths[0]];
    }
    const monthInput = document.getElementById('sidebarMonthYear');
    if (monthInput) monthInput.value = appState.activeMonth;
  }

  // Ensure active months have income & budget structures
  importedMonths.forEach(m => {
    if (!appState.budgets[m]) applyDefaultBudgetsForMonth(m);
    ensureIncomeForMonth(m);
  });

  saveData();
  saveActiveWorkspaceContainer();
  updateAllViews();

  let successMsg = `Successfully imported ${importedExpenses.length} transaction${importedExpenses.length === 1 ? '' : 's'}!`;
  if (skippedCount > 0) {
    successMsg += ` (${skippedCount} row${skippedCount === 1 ? '' : 's'} skipped due to missing Date, Description, or Amount)`;
  }
  showToast(successMsg, 'success', 5000);
}

