// ==========================================
// [FEAT-CSV-PLANNED] PLANNED / FUTURE EXPENSES CSV BATCH IMPORTER & TEMPLATE
// ==========================================
function handlePlannedCSVUpload(e) {
  if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-FUTURE-EXPENSES]')) {
    if (typeof showUpgradePrompt === 'function') {
      showUpgradePrompt('[FEAT-FUTURE-EXPENSES]', 'CSV Importer for Planned & Future Expenses', 'expenses');
    }
    if (e.target) e.target.value = '';
    return;
  }

  const file = e.target.files && e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(evt) {
    try {
      const text = evt.target.result;
      processPlannedCSVContent(text, file.name);
    } catch (err) {
      console.error('Planned CSV import error:', err);
      showToast('Failed to process Planned CSV: ' + err.message, 'error');
    }
  };
  reader.onerror = function() {
    showToast('Failed to read CSV file. Please try again.', 'error');
  };
  reader.readAsText(file);
}

function processPlannedCSVContent(text, fileName = '') {
  const rows = parseCSV(text);
  if (!rows || rows.length < 2) {
    showToast('The CSV file is empty or contains no data rows.', 'warning');
    return;
  }

  const headers = rows[0].map(h => (h || '').trim());

  // Required columns
  const dateIdx = findCSVColumnIndex(headers, ['date', 'duedate', 'targetdate', 'planneddate', 'scheduledate', 'txdate', 'time']);
  const descIdx = findCSVColumnIndex(headers, ['description', 'desc', 'vendor', 'payee', 'merchant', 'details', 'memo', 'name', 'title', 'item', 'purpose']);
  const amtIdx = findCSVColumnIndex(headers, ['amount', 'cost', 'total', 'price', 'charge', 'value', 'spent']);

  if (dateIdx === -1 || descIdx === -1 || amtIdx === -1) {
    const missing = [];
    if (dateIdx === -1) missing.push('Target Date');
    if (descIdx === -1) missing.push('Description / Vendor');
    if (amtIdx === -1) missing.push('Amount');
    showToast(`CSV missing required column(s): ${missing.join(', ')}. Required fields are Target Date, Description, and Amount.`, 'error', 6500);
    return;
  }

  // Optional columns
  const catIdx = findCSVColumnIndex(headers, ['category', 'cat', 'categoryname', 'envelope']);
  const payIdx = findCSVColumnIndex(headers, ['paymentmethod', 'payment', 'method', 'channel', 'account']);
  const notesIdx = findCSVColumnIndex(headers, ['notes', 'note', 'reminders', 'comment', 'memo']);
  const typeIdx = findCSVColumnIndex(headers, ['budgettype', 'tag', 'type', 'classification', 'needswants']);

  const importedPlanned = [];
  let skippedCount = 0;

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || row.length === 0 || (row.length === 1 && !row[0])) {
      continue;
    }

    const rawDate = row[dateIdx] || '';
    const rawDesc = row[descIdx] || '';
    const rawAmt = row[amtIdx] || '';

    const parsedDate = parseCSVDate(rawDate);
    const parsedDesc = rawDesc.trim();
    const parsedAmt = parseCSVAmount(rawAmt);

    // Validation: Date, Description, Amount are required
    if (!parsedDate || !parsedDesc || parsedAmt === null || parsedAmt <= 0) {
      skippedCount++;
      continue;
    }

    // Optional Category Match
    let matchedCatId = '';
    if (catIdx !== -1 && row[catIdx]) {
      const rawCat = row[catIdx].trim().toLowerCase();
      if (rawCat) {
        const found = appState.categories.find(c =>
          c.id.toLowerCase() === rawCat ||
          c.name.toLowerCase() === rawCat ||
          c.name.toLowerCase().includes(rawCat)
        );
        if (found) {
          matchedCatId = found.id;
        }
      }
    }

    // Optional Payment Method
    let matchedPayMethod = '';
    if (payIdx !== -1 && row[payIdx]) {
      const rawPm = row[payIdx].trim();
      if (rawPm) {
        const knownMethods = ['Cash', 'Credit Card', 'Debit Card', 'Bank Transfer', 'GCash', 'Maya', 'PayPal', 'Digital Wallet'];
        const found = knownMethods.find(m => m.toLowerCase() === rawPm.toLowerCase());
        matchedPayMethod = found || rawPm;
      }
    }

    // Optional Notes
    const rawNotes = (notesIdx !== -1 && row[notesIdx]) ? row[notesIdx].trim() : '';

    // Optional Budget Classification (Needs / Wants)
    let matchedBudgetType = '';
    if (typeIdx !== -1 && row[typeIdx]) {
      const rawType = row[typeIdx].trim().toLowerCase();
      if (rawType.includes('want')) matchedBudgetType = 'wants';
      else if (rawType.includes('need')) matchedBudgetType = 'needs';
    }
    if (!matchedBudgetType && matchedCatId) {
      matchedBudgetType = getCategoryBudgetType(matchedCatId) || 'needs';
    } else if (!matchedBudgetType) {
      matchedBudgetType = 'needs';
    }

    const newPlannedItem = {
      id: 'pexp_csv_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 6) + '_' + i,
      date: parsedDate,
      description: parsedDesc,
      amount: parsedAmt,
      categoryId: matchedCatId,
      paymentMethod: matchedPayMethod,
      notes: rawNotes,
      budgetType: matchedBudgetType,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    importedPlanned.push(newPlannedItem);
  }

  if (importedPlanned.length === 0) {
    showToast(`No valid planned commitments imported. Please ensure Target Date, Description, and positive Amount are provided.`, 'error', 6000);
    return;
  }

  if (!Array.isArray(appState.plannedExpenses)) {
    appState.plannedExpenses = [];
  }

  // Append new planned expenses
  appState.plannedExpenses.push(...importedPlanned);

  saveData();
  saveActiveWorkspaceContainer();
  updateAllViews();
  renderPlannedExpensesTable();
  checkDuePlannedExpenses();

  // If user was on actual subtab, switch to planned subtab so they immediately see the imported future expenses!
  if (typeof switchExpenseSubtab === 'function' && activeExpenseSubtab !== 'planned') {
    switchExpenseSubtab('planned');
  }

  const cur = appState.currency || '$';
  const totalImportedAmt = importedPlanned.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
  let successMsg = `✓ Successfully imported ${importedPlanned.length} planned expense${importedPlanned.length === 1 ? '' : 's'} (${cur}${totalImportedAmt.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}) into Future Expenses!`;
  if (skippedCount > 0) {
    successMsg += ` (${skippedCount} row${skippedCount === 1 ? '' : 's'} skipped due to missing date, description, or amount)`;
  }
  showToast(successMsg, 'success', 5500);
}

