// ==========================================
// [FEAT-59] BULK CATEGORY CSV IMPORTER & TEMPLATE ENGINE
// [FEAT-60] CATEGORY CSV TARGET SCOPE ENGINE (CURRENT MONTH VS. GLOBAL)
// ==========================================
let pendingCategoryCSV = null;

function handleCategoryCSVUpload(e) {
  const file = e.target.files && e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(evt) {
    try {
      const text = evt.target.result;
      openCategoryCSVImportModal(text, file.name);
    } catch (err) {
      console.error('Category CSV import error:', err);
      showToast('Failed to process Category CSV: ' + err.message, 'error');
    }
  };
  reader.onerror = function() {
    showToast('Failed to read CSV file. Please try again.', 'error');
  };
  reader.readAsText(file);
}

function openCategoryCSVImportModal(text, fileName = '') {
  const rows = parseCSV(text);
  if (!rows || rows.length < 2) {
    showToast('The CSV file is empty or contains no data rows.', 'warning');
    return;
  }

  const headers = rows[0].map(h => (h || '').trim());
  const catIdx = findCSVColumnIndex(headers, ['category', 'categoryname', 'cat', 'name', 'envelope', 'title']);
  const amtIdx = findCSVColumnIndex(headers, ['amount', 'budget', 'budgetamount', 'allocated', 'allocation', 'target', 'defaultbudget', 'limit', 'cost']);

  if (catIdx === -1 || amtIdx === -1) {
    const missing = [];
    if (catIdx === -1) missing.push('Category');
    if (amtIdx === -1) missing.push('Amount');
    showToast(`CSV missing required column(s): ${missing.join(', ')}. Required fields are Category and Amount.`, 'error', 6500);
    return;
  }

  const typeIdx = findCSVColumnIndex(headers, ['budgettype', 'type', 'tag', 'classification', 'needswants', 'group']);
  const iconIdx = findCSVColumnIndex(headers, ['icon', 'emoji', 'symbol']);

  let newEnvelopesCount = 0;
  let existingEnvelopesCount = 0;
  const previewItems = [];

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || row.length === 0 || (row.length === 1 && !row[0])) continue;

    const rawName = (row[catIdx] || '').trim();
    const rawAmt = row[amtIdx];
    const parsedAmt = parseCSVAmount(rawAmt);

    if (!rawName || parsedAmt === null || isNaN(parsedAmt) || parsedAmt < 0) continue;

    const exists = (appState.categories || []).some(c =>
      c.name.trim().toLowerCase() === rawName.toLowerCase() ||
      c.id.toLowerCase() === rawName.toLowerCase()
    );

    if (exists) existingEnvelopesCount++;
    else newEnvelopesCount++;

    let budgetType = 'needs';
    if (typeIdx !== -1 && row[typeIdx]) {
      const rawType = row[typeIdx].trim().toLowerCase();
      if (rawType.includes('want')) budgetType = 'wants';
    } else {
      budgetType = getCategoryBudgetType(rawName) || 'needs';
    }

    let icon = (iconIdx !== -1 && row[iconIdx]) ? row[iconIdx].trim() : '';
    if (!icon) icon = detectCategoryIcon(rawName);

    if (previewItems.length < 50) {
      previewItems.push({
        name: rawName,
        amount: parsedAmt,
        budgetType,
        icon,
        isNew: !exists
      });
    }
  }

  const totalValid = newEnvelopesCount + existingEnvelopesCount;
  if (totalValid === 0) {
    showToast('No valid category rows found in the CSV file. Please provide Category and Amount.', 'warning', 6000);
    return;
  }

  pendingCategoryCSV = { text, fileName, totalValid };

  // Set file metadata
  const fileNameEl = document.getElementById('catImportFileName');
  if (fileNameEl) fileNameEl.textContent = fileName || 'Uploaded Categories.csv';

  const fileMetaEl = document.getElementById('catImportFileMeta');
  if (fileMetaEl) fileMetaEl.textContent = `${totalValid} categor${totalValid === 1 ? 'y' : 'ies'} detected (${newEnvelopesCount} new, ${existingEnvelopesCount} existing)`;

  const statsBadge = document.getElementById('catImportStatsBadge');
  if (statsBadge) statsBadge.textContent = `${totalValid} Ready`;

  const previewCount = document.getElementById('catImportPreviewCount');
  if (previewCount) previewCount.textContent = totalValid;

  // Set Month Label
  const currentMonth = appState.activeMonth;
  const monthLabel = (typeof formatMonthLabel === 'function' && currentMonth) ? formatMonthLabel(currentMonth) : currentMonth;
  const monthLabelEl = document.getElementById('catImportCurrentMonthLabel');
  if (monthLabelEl) monthLabelEl.textContent = monthLabel;

  // Reset radio cards to DEFAULT: Current Month
  const radioMonth = document.getElementById('catImportScopeMonth');
  const radioAll = document.getElementById('catImportScopeAll');
  const cardMonth = document.getElementById('labelCatImportScopeMonth');
  const cardAll = document.getElementById('labelCatImportScopeAll');

  if (radioMonth) radioMonth.checked = true;
  if (radioAll) radioAll.checked = false;
  if (cardMonth) cardMonth.classList.add('selected');
  if (cardAll) cardAll.classList.remove('selected');

  // Render preview table rows
  const tbody = document.getElementById('catImportPreviewBody');
  if (tbody) {
    const esc = (typeof escapeHtml === 'function') ? escapeHtml : (s => String(s).replace(/[&<>"']/g, ''));
    tbody.innerHTML = previewItems.map(item => `
      <tr style="border-bottom: 1px solid rgba(255, 255, 255, 0.05);">
        <td style="padding: 6px 10px; display: flex; align-items: center; gap: 6px;">
          <span>${item.icon || '🏷️'}</span>
          <strong>${esc(item.name)}</strong>
        </td>
        <td style="padding: 6px 10px; text-align: right; font-family: var(--font-mono, monospace);">
          ${formatCurrency(item.amount)}
        </td>
        <td style="padding: 6px 10px; text-align: center;">
          <span style="font-size: 0.7rem; padding: 2px 6px; border-radius: 4px; ${item.budgetType === 'wants' ? 'background: rgba(236, 72, 153, 0.15); color: #f472b6;' : 'background: rgba(16, 185, 129, 0.15); color: #34d399;'}">
            ${item.budgetType === 'wants' ? '✨ Wants' : '🛡️ Needs'}
          </span>
        </td>
        <td style="padding: 6px 10px; text-align: center;">
          <span style="font-size: 0.68rem; padding: 2px 6px; border-radius: 4px; ${item.isNew ? 'background: rgba(59, 130, 246, 0.15); color: #60a5fa;' : 'background: rgba(234, 179, 8, 0.15); color: #facc15;'}">
            ${item.isNew ? '+ New' : 'Update'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // Confirm button text
  const confirmBtn = document.getElementById('btnConfirmCatCSVImport');
  if (confirmBtn) confirmBtn.textContent = `Import ${totalValid} Categor${totalValid === 1 ? 'y' : 'ies'}`;

  // Open modal
  const modal = document.getElementById('categoryCSVImportModal');
  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
  }
}

function closeCategoryCSVImportModal() {
  const modal = document.getElementById('categoryCSVImportModal');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
  const fileInput = document.getElementById('categoryCSVFileInput');
  if (fileInput) fileInput.value = '';
  pendingCategoryCSV = null;
}

function processCategoryCSVContent(text, fileName = '', targetScope = 'month') {
  const rows = parseCSV(text);
  if (!rows || rows.length < 2) {
    showToast('The CSV file is empty or contains no data rows.', 'warning');
    return;
  }

  const headers = rows[0].map(h => (h || '').trim());

  // Required columns: Category, Amount
  const catIdx = findCSVColumnIndex(headers, ['category', 'categoryname', 'cat', 'name', 'envelope', 'title']);
  const amtIdx = findCSVColumnIndex(headers, ['amount', 'budget', 'budgetamount', 'allocated', 'allocation', 'target', 'defaultbudget', 'limit', 'cost']);

  if (catIdx === -1 || amtIdx === -1) {
    const missing = [];
    if (catIdx === -1) missing.push('Category');
    if (amtIdx === -1) missing.push('Amount');
    showToast(`CSV missing required column(s): ${missing.join(', ')}. Required fields are Category and Amount.`, 'error', 6500);
    return;
  }

  // Optional columns
  const typeIdx = findCSVColumnIndex(headers, ['budgettype', 'type', 'tag', 'classification', 'needswants', 'group']);
  const iconIdx = findCSVColumnIndex(headers, ['icon', 'emoji', 'symbol']);
  const colorIdx = findCSVColumnIndex(headers, ['color', 'theme', 'hex', 'colour']);
  const scopeIdx = findCSVColumnIndex(headers, ['scope', 'period']);

  const currentMonth = appState.activeMonth;
  const activeMonths = (typeof getSortedActiveMonths === 'function') ? getSortedActiveMonths() : [currentMonth];

  // All known months across appState
  const allKnownMonths = new Set([
    ...Object.keys(appState.budgets || {}),
    ...Object.keys(appState.incomes || {}),
    ...Object.keys(appState.excludedCategoriesByMonth || {}),
    ...(appState.expenses || []).map(e => e.date ? e.date.slice(0, 7) : null).filter(Boolean),
    currentMonth
  ]);

  const isGlobalImport = (targetScope === 'all');

  let createdCount = 0;
  let updatedCount = 0;
  let skippedCount = 0;

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || row.length === 0 || (row.length === 1 && !row[0])) {
      continue;
    }

    const rawCatName = (row[catIdx] || '').trim();
    const rawAmt = row[amtIdx];
    const parsedAmt = parseCSVAmount(rawAmt);

    // Validation: Category name is required, and Amount must be a valid non-negative number
    if (!rawCatName || parsedAmt === null || isNaN(parsedAmt) || parsedAmt < 0) {
      if (row.some(cell => cell && cell.trim())) {
        skippedCount++;
      }
      continue;
    }

    // Optional fields
    let budgetType = 'needs';
    if (typeIdx !== -1 && row[typeIdx]) {
      const rawType = row[typeIdx].trim().toLowerCase();
      if (rawType.includes('want')) budgetType = 'wants';
      else if (rawType.includes('need')) budgetType = 'needs';
    } else {
      budgetType = getCategoryBudgetType(rawCatName) || 'needs';
    }

    let icon = '';
    if (iconIdx !== -1 && row[iconIdx]) {
      icon = row[iconIdx].trim();
    }
    if (!icon) {
      icon = detectCategoryIcon(rawCatName);
    }

    let color = '';
    if (colorIdx !== -1 && row[colorIdx]) {
      const rawColor = row[colorIdx].trim();
      if (/^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(rawColor)) {
        color = rawColor;
      }
    }
    if (!color) {
      color = getRandomCategoryColor();
    }

    // Row-level scope override if explicitly specified in CSV, otherwise uses targetScope
    let rowScope = targetScope;
    if (scopeIdx !== -1 && row[scopeIdx]) {
      const rawScope = row[scopeIdx].trim().toLowerCase();
      if (rawScope.includes('all') || rawScope.includes('global')) rowScope = 'all';
      else if (rawScope.includes('month')) rowScope = 'month';
    }

    // Check if category already exists in appState.categories
    const existingCat = (appState.categories || []).find(c =>
      c.name.trim().toLowerCase() === rawCatName.toLowerCase() ||
      c.id.toLowerCase() === rawCatName.toLowerCase()
    );

    if (existingCat) {
      // Update existing category
      existingCat.defaultBudget = parsedAmt;
      if (typeIdx !== -1 && row[typeIdx]) existingCat.budgetType = budgetType;
      if (iconIdx !== -1 && row[iconIdx] && icon) existingCat.icon = icon;
      if (colorIdx !== -1 && row[colorIdx] && color) existingCat.color = color;

      if (rowScope === 'all') {
        // Global: apply to all known months and remove from any exclusion lists
        allKnownMonths.forEach(m => {
          if (!appState.budgets[m]) appState.budgets[m] = {};
          appState.budgets[m][existingCat.id] = parsedAmt;
          if (appState.excludedCategoriesByMonth && Array.isArray(appState.excludedCategoriesByMonth[m])) {
            appState.excludedCategoriesByMonth[m] = appState.excludedCategoriesByMonth[m].filter(id => id !== existingCat.id);
          }
        });
      } else {
        // Current Month Only: apply strictly to active months and un-exclude from active months
        activeMonths.forEach(m => {
          if (!appState.budgets[m]) appState.budgets[m] = {};
          appState.budgets[m][existingCat.id] = parsedAmt;
          if (appState.excludedCategoriesByMonth && Array.isArray(appState.excludedCategoriesByMonth[m])) {
            appState.excludedCategoriesByMonth[m] = appState.excludedCategoriesByMonth[m].filter(id => id !== existingCat.id);
          }
        });
      }

      updatedCount++;
    } else {
      // Create new category
      const safeSlug = rawCatName.toLowerCase().replace(/[^a-z0-9]/g, '_').slice(0, 18);
      const id = 'cat_' + safeSlug + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 4);

      const newCategory = {
        id,
        name: rawCatName,
        icon,
        color,
        defaultBudget: parsedAmt,
        budgetType,
        scope: rowScope,
        createdInMonth: currentMonth,
        createdInMonths: (rowScope === 'month') ? [...activeMonths] : []
      };

      if (!Array.isArray(appState.categories)) {
        appState.categories = [];
      }
      appState.categories.push(newCategory);

      if (rowScope === 'all') {
        // Global: allocate across all known months
        allKnownMonths.forEach(m => {
          if (!appState.budgets[m]) appState.budgets[m] = {};
          appState.budgets[m][id] = parsedAmt;
        });
      } else {
        // Current Month Only: allocate in active month, exclude from all other known months
        activeMonths.forEach(m => {
          if (!appState.budgets[m]) appState.budgets[m] = {};
          appState.budgets[m][id] = parsedAmt;
        });

        if (!appState.excludedCategoriesByMonth || typeof appState.excludedCategoriesByMonth !== 'object') {
          appState.excludedCategoriesByMonth = {};
        }

        allKnownMonths.forEach(m => {
          if (!activeMonths.includes(m)) {
            if (!Array.isArray(appState.excludedCategoriesByMonth[m])) {
              appState.excludedCategoriesByMonth[m] = [];
            }
            if (!appState.excludedCategoriesByMonth[m].includes(id)) {
              appState.excludedCategoriesByMonth[m].push(id);
            }
          }
        });
      }

      createdCount++;
    }
  }

  const totalProcessed = createdCount + updatedCount;
  if (totalProcessed === 0) {
    showToast('No valid categories could be imported. Please verify that Category and Amount columns are present with valid values.', 'error', 6000);
    return;
  }

  saveData();
  if (typeof saveActiveWorkspaceContainer === 'function') saveActiveWorkspaceContainer();
  if (typeof populateCategorySelects === 'function') populateCategorySelects();
  if (typeof renderBudgetGrid === 'function') renderBudgetGrid();
  if (typeof updateAllViews === 'function') updateAllViews();

  const monthLabel = (typeof formatMonthLabel === 'function' && currentMonth) ? formatMonthLabel(currentMonth) : currentMonth;
  const scopeDescription = isGlobalImport ? 'globally across all months' : `for ${monthLabel} only`;
  let msg = `Successfully imported ${totalProcessed} categories ${scopeDescription} (${createdCount} new created, ${updatedCount} existing budget targets updated)!`;
  if (skippedCount > 0) {
    msg += ` (${skippedCount} row${skippedCount === 1 ? '' : 's'} skipped due to missing Category or invalid Amount)`;
  }
  showToast(msg, 'success', 5000);
}

