// ==========================================
// [FEAT-16] RESET ALL AMOUNTS TO ZERO
// ==========================================
// Sets every amount to 0 (also used for first-run defaults). Categories are kept.
function applyZeroState() {
  // [FEAT-34] A reset must not be refilled by auto-posted bills
  if (typeof skipAllCurrentBillOccurrences === 'function') skipAllCurrentBillOccurrences();
  appState.expenses = [];
  appState.incomes = {};
  appState.budgets = {};
  appState.surplusSweeps = {};
  appState.categories.forEach(c => { c.defaultBudget = 0; });
  if (appState.savingsGoals) {
    appState.savingsGoals.forEach(g => {
      g.currentAmount = 0;
      g.history = [];
    });
  }

  // Clear any surplus banner session dismissals
  try {
    sessionStorage.removeItem('dismissedSurplusBanner');
    Object.keys(sessionStorage).forEach(k => {
      if (k.startsWith('dismissedSurplusBanner')) sessionStorage.removeItem(k);
    });
  } catch (e) {}

  getSortedActiveMonths().forEach(m => {
    applyDefaultBudgetsForMonth(m);
    ensureIncomeForMonth(m);
  });
}

// Yes/No dialog. Resolves true only on "Yes"; "No", Esc, or clicking outside = false.
function askYesNo(title, message, yesLabel = 'Yes', isDanger = true) {
  return new Promise(resolve => {
    const modal = document.getElementById('confirmModal');
    const yesBtn = document.getElementById('btnConfirmYes');
    const noBtn = document.getElementById('btnConfirmNo');
    document.getElementById('confirmTitle').textContent = title;
    document.getElementById('confirmMessage').textContent = message;
    yesBtn.textContent = yesLabel;

    const activeTier = (typeof appState !== 'undefined' && appState.userTier ? appState.userTier : (document.body.getAttribute('data-tier') || 'free')).toLowerCase();
    modal.setAttribute('data-tier', activeTier);

    if (isDanger) {
      yesBtn.className = 'btn btn-primary btn-confirm-danger';
      yesBtn.style.background = '#dc2626';
      yesBtn.style.borderColor = '#dc2626';
      yesBtn.style.color = '#ffffff';
      yesBtn.style.boxShadow = '0 0 16px rgba(220, 38, 38, 0.4)';
    } else {
      yesBtn.className = 'btn btn-primary btn-confirm-tier';
      if (activeTier === 'executive') {
        yesBtn.style.background = 'linear-gradient(135deg, #fbbf24 0%, #d97706 100%)';
        yesBtn.style.borderColor = '#fbbf24';
        yesBtn.style.color = '#0f172a';
        yesBtn.style.fontWeight = '700';
        yesBtn.style.boxShadow = '0 0 16px rgba(251, 191, 36, 0.4)';
      } else if (activeTier === 'pro') {
        yesBtn.style.background = 'linear-gradient(135deg, #06b6d4 0%, #2563eb 100%)';
        yesBtn.style.borderColor = '#38bdf8';
        yesBtn.style.color = '#ffffff';
        yesBtn.style.fontWeight = '700';
        yesBtn.style.boxShadow = '0 0 16px rgba(56, 189, 248, 0.4)';
      } else {
        yesBtn.style.background = 'linear-gradient(135deg, #10b981 0%, #059669 100%)';
        yesBtn.style.borderColor = '#34d399';
        yesBtn.style.color = '#ffffff';
        yesBtn.style.fontWeight = '700';
        yesBtn.style.boxShadow = '0 0 16px rgba(52, 211, 153, 0.4)';
      }
    }

    const finish = (answer) => {
      modal.classList.remove('active');
      yesBtn.removeEventListener('click', onYes);
      noBtn.removeEventListener('click', onNo);
      modal.removeEventListener('click', onOverlay);
      document.removeEventListener('keydown', onKey);
      resolve(answer);
    };
    const onYes = () => finish(true);
    const onNo = () => finish(false);
    const onOverlay = (e) => { if (e.target === modal) finish(false); };
    const onKey = (e) => { if (e.key === 'Escape') finish(false); };

    yesBtn.addEventListener('click', onYes);
    noBtn.addEventListener('click', onNo);
    modal.addEventListener('click', onOverlay);
    document.addEventListener('keydown', onKey);

    modal.classList.add('active');
    noBtn.focus(); // safe default: pressing Enter means "No"
  });
}

async function resetAllToZero() {
  const message =
    'This will delete ALL transactions and set all income and budget amounts to 0. ' +
    'Your categories are kept.\n\n' +
    'This will also sync the reset state to your Cloud Firestore account.\n\n' +
    'This cannot be undone. Are you sure?';

  const confirmed = await askYesNo(
    'Reset all amounts to 0?',
    message,
    'Yes, reset'
  );
  if (!confirmed) {
    showToast('Reset cancelled. Nothing was changed.');
    return;
  }

  applyZeroState();
  saveData();
  populateCategorySelects();
  renderBudgetGrid();
  updateAllViews();
  if (typeof closeSurplusSweeperModal === 'function') {
    closeSurplusSweeperModal();
  }
  if (typeof closeSystemToolsDrawer === 'function') {
    closeSystemToolsDrawer();
  }
  showToast('All amounts have been reset to 0.');
}


