// [FEAT-19 / FEAT-61] USER GUIDE, FAQ & AI COPILOT MODAL FUNCTIONS
// ==========================================
function openFAQModal(initialMode) {
  const modal = document.getElementById('faqModal');
  if (modal) {
    modal.classList.add('active');
    if (typeof userFaqDockPreference === 'undefined' || userFaqDockPreference !== false) {
      modal.classList.add('faq-docked-right');
    }
  }
  if (typeof initFaqAiCopilot === 'function') {
    initFaqAiCopilot();
  }
  const targetMode = (typeof initialMode === 'string' && initialMode) ? initialMode : null;
  if (targetMode && typeof switchFaqMode === 'function') {
    switchFaqMode(targetMode);
  } else if (typeof updateFaqWindowControlsUI === 'function') {
    updateFaqWindowControlsUI();
  }
  const searchInput = document.getElementById('faqSearchInput');
  if (searchInput && (!targetMode || targetMode === 'browse')) {
    searchInput.value = '';
    filterFAQItems();
    setTimeout(() => searchInput.focus(), 150);
  }
}

function closeFAQModal() {
  const modal = document.getElementById('faqModal');
  if (modal) modal.classList.remove('active');
}

function filterFAQItems() {
  const input = document.getElementById('faqSearchInput');
  const query = (input ? input.value : '').toLowerCase().trim();
  const activeChip = document.querySelector('.faq-chip.active');
  const activeCategory = activeChip ? activeChip.getAttribute('data-filter') : 'all';

  let matchedCount = 0;
  const items = document.querySelectorAll('.faq-item');
  items.forEach(item => {
    const category = item.getAttribute('data-category');
    const keywords = (item.getAttribute('data-keywords') || '').toLowerCase();
    const qEl = item.querySelector('.faq-q-text');
    const aEl = item.querySelector('.faq-answer');
    const questionText = (qEl ? qEl.textContent : '').toLowerCase();
    const answerText = (aEl ? aEl.textContent : '').toLowerCase();

    const matchesCategory = (activeCategory === 'all' || category === activeCategory);
    const matchesQuery = !query || questionText.includes(query) || answerText.includes(query) || keywords.includes(query);

    if (matchesCategory && matchesQuery) {
      item.style.display = 'block';
      matchedCount++;
      if (query) {
        item.classList.add('open'); // auto-expand matching items when searching
      }
    } else {
      item.style.display = 'none';
    }
  });

  // [FEAT-61] Show prompt to ask AI Copilot if static search returns 0 matches
  const noMatchPrompt = document.getElementById('faqNoMatchAiPrompt');
  if (noMatchPrompt) {
    noMatchPrompt.style.display = (query && matchedCount === 0) ? 'block' : 'none';
  }
}

function exportJSONBackup() {
  saveActiveWorkspaceContainer();
  const allWorkspacesData = {};
  if (workspaceRegistry && Array.isArray(workspaceRegistry.workspaces)) {
    const prefix = getWorkspaceDataPrefix();
    workspaceRegistry.workspaces.forEach(ws => {
      try {
        const raw = localStorage.getItem(prefix + ws.id);
        if (raw) allWorkspacesData[ws.id] = JSON.parse(raw);
      } catch (err) {
        console.warn('Could not read workspace container for export:', ws.id, err);
      }
    });
  }

  const data = {
    appName: 'NirvTrack',
    exportDate: new Date().toISOString(),
    theme: appState.theme,
    currency: appState.currency,
    uiMode: appState.uiMode,
    activeWorkspaceId: workspaceRegistry.activeWorkspaceId,
    workspaces: workspaceRegistry.workspaces,
    workspaceContainers: allWorkspacesData,
    categories: appState.categories,
    incomes: appState.incomes,
    budgets: appState.budgets,
    expenses: appState.expenses,
    excludedCategoriesByMonth: appState.excludedCategoriesByMonth,
    recurringBills: appState.recurringBills
  };
  const json = JSON.stringify(data, null, 2);
  downloadFile(json, `NirvTrack_Backup_${appState.activeMonth}.json`, 'application/json');
  showToast('JSON Backup downloaded!');
}

function downloadFile(content, fileName, mimeType) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

