// ==========================================
// 19. FORMATTING & HELPER FUNCTIONS
// ==========================================
function formatCurrency(amount) {
  const val = Number(amount) || 0;
  return appState.currency + val.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function formatMonthLabel(monthKey) {
  if (!monthKey) return '';
  const [year, month] = monthKey.split('-');
  const date = new Date(parseInt(year, 10), parseInt(month, 10) - 1, 1);
  return date.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
}

function formatShortDate(dateStr) {
  if (!dateStr) return '';
  const parts = dateStr.split('-');
  if (parts.length === 3) {
    const date = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  }
  return dateStr;
}

function escapeHTML(str) {
  if (str === undefined || str === null) return '';
  return String(str).replace(/[&<>'"]/g, 
    tag => ({
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      "'": '&#39;',
      '"': '&quot;'
    }[tag] || tag)
  );
}

function showToast(message, type = 'success', duration = 3200, action = null) {
  const container = document.getElementById('toastContainer');
  if (!container) return;

  const normAction = action ? {
    label: action.label || action.actionLabel || 'Undo',
    callback: action.callback || action.onAction || null
  } : null;

  const toast = document.createElement('div');
  toast.className = 'toast' + (normAction ? ' toast-with-action' : '');
  
  const icon = type === 'error' ? '❌' : (type === 'warning' ? '⚠️' : (type === 'info' ? 'ℹ️' : '✅'));
  
  let actionHtml = '';
  if (normAction && normAction.label && typeof normAction.callback === 'function') {
    actionHtml = `<button type="button" class="btn-toast-undo">${escapeHTML(normAction.label)}</button>`;
  }

  toast.innerHTML = `<span class="toast-icon">${icon}</span> <span class="toast-msg">${escapeHTML(message)}</span> ${actionHtml}`;
  
  let autoDismissTimer = null;
  if (normAction && normAction.callback) {
    const btn = toast.querySelector('.btn-toast-undo');
    if (btn) {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        clearTimeout(autoDismissTimer);
        try {
          normAction.callback();
        } catch (err) {
          console.error('Toast action callback error:', err);
        }
        toast.style.opacity = '0';
        toast.style.transform = 'translateY(10px)';
        toast.style.transition = 'all 0.25s ease';
        setTimeout(() => {
          if (toast.parentElement) toast.parentElement.removeChild(toast);
        }, 250);
      });
    }
  }

  container.appendChild(toast);

  autoDismissTimer = setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    toast.style.transition = 'all 0.3s ease';
    setTimeout(() => {
      if (toast.parentElement) toast.parentElement.removeChild(toast);
    }, 300);
  }, Math.max(duration, 1500));
}

// ==========================================
// 19B. [FEAT-27 v2] ISOLATED WORKSPACE / DATASET ENGINE
// ==========================================
// Zero-proxy container architecture: appState stays 100% flat while each
// workspace's data is snapshotted into its own localStorage container.
const GLOBAL_UI_KEYS = new Set(['theme', 'uiMode', 'activeTab', 'activeMonth', 'activeMonths', 'userTier']);
let activeInlineEditWorkspaceId = null;

function getWorkspaceTagIcon(tag) {
  const map = {
    'Personal': '📁',
    'Business': '💼',
    'Freelance': '💻',
    'Savings': '🏦',
    'Investments': '📈',
    'Travel': '✈️',
    'Family': '🏠',
    'Project': '🎯',
    'Other': '🏷️'
  };
  return map[tag] || '📁';
}

function getActiveWorkspaceMeta() {
  if (!workspaceRegistry || !Array.isArray(workspaceRegistry.workspaces) || workspaceRegistry.workspaces.length === 0) {
    return { id: 'ws_default', name: 'Personal Budget', tag: 'Personal' };
  }
  return workspaceRegistry.workspaces.find(w => w.id === workspaceRegistry.activeWorkspaceId) || workspaceRegistry.workspaces[0];
}

// Dynamically extracts all financial data keys from appState (excluding global UI keys)
// so any future feature added to appState is automatically isolated per workspace.
function extractWorkspaceSnapshot() {
  const snap = {};
  Object.keys(appState).forEach(key => {
    if (!GLOBAL_UI_KEYS.has(key)) {
      snap[key] = JSON.parse(JSON.stringify(appState[key]));
    }
  });
  return snap;
}

// Applies a workspace container snapshot directly onto flat appState
function applyWorkspaceSnapshot(snapshot) {
  const src = snapshot && typeof snapshot === 'object' ? snapshot : {};
  const clone = (val, fallback) => {
    if (val === undefined || val === null) return JSON.parse(JSON.stringify(fallback));
    return JSON.parse(JSON.stringify(val));
  };

  if (src.currency) {
    appState.currency = src.currency;
  }
  appState.categories = (Array.isArray(src.categories)
    ? clone(src.categories, DEFAULT_CATEGORIES)
    : clone(DEFAULT_CATEGORIES, [])).map(c => ({
      ...c,
      budgetType: c.budgetType || getCategoryBudgetType(c.id)
    }));
  appState.incomes = (src.incomes && typeof src.incomes === 'object') ? clone(src.incomes, {}) : {};
  appState.budgets = (src.budgets && typeof src.budgets === 'object') ? clone(src.budgets, {}) : {};
  appState.expenses = Array.isArray(src.expenses) ? clone(src.expenses, []) : [];
  appState.excludedCategoriesByMonth = (src.excludedCategoriesByMonth && typeof src.excludedCategoriesByMonth === 'object')
    ? clone(src.excludedCategoriesByMonth, {})
    : {};
  appState.recurringBills = Array.isArray(src.recurringBills) ? clone(src.recurringBills, []) : [];
  appState.plannedExpenses = Array.isArray(src.plannedExpenses) ? clone(src.plannedExpenses, []) : [];
  appState.includePlannedInProjections = src.includePlannedInProjections === true;
  appState.workspaceDashboardLayout = src.workspaceDashboardLayout ? clone(src.workspaceDashboardLayout, null) : null;
  appState.workspaceLayouts = (src.workspaceLayouts && typeof src.workspaceLayouts === 'object') ? clone(src.workspaceLayouts, {}) : {};

  // Copy any future data keys stored in the container
  Object.keys(src).forEach(key => {
    if (!GLOBAL_UI_KEYS.has(key) && !(key in {
      currency: 1,
      categories: 1,
      incomes: 1,
      budgets: 1,
      expenses: 1,
      excludedCategoriesByMonth: 1,
      recurringBills: 1,
      plannedExpenses: 1,
      includePlannedInProjections: 1
    })) {
      appState[key] = clone(src[key], null);
    }
  });
}

function saveWorkspaceIndex() {
  try {
    localStorage.setItem(getWorkspacesIndexKey(), JSON.stringify(workspaceRegistry));
  } catch (e) {
    console.error('Failed to save workspace index:', e);
  }
}

function saveActiveWorkspaceContainer() {
  if (!workspaceRegistry || !workspaceRegistry.activeWorkspaceId) return;
  try {
    const wsId = workspaceRegistry.activeWorkspaceId;
    const snapshot = extractWorkspaceSnapshot();
    localStorage.setItem(getWorkspaceDataPrefix() + wsId, JSON.stringify(snapshot));

    const meta = workspaceRegistry.workspaces.find(w => w.id === wsId);
    if (meta) {
      meta.updatedAt = new Date().toISOString();
    }
    saveWorkspaceIndex();
  } catch (e) {
    console.error('Failed to save active workspace container:', e);
  }
}

function loadWorkspaceContainer(wsId) {
  try {
    let raw = localStorage.getItem(getWorkspaceDataPrefix() + wsId);
    if (!raw && getCurrentUserUid()) {
      const guestRaw = localStorage.getItem(WORKSPACE_DATA_PREFIX + wsId);
      if (guestRaw) {
        raw = guestRaw;
        try { localStorage.setItem(getWorkspaceDataPrefix() + wsId, guestRaw); } catch (e) {}
      }
    }
    if (!raw) return null;
    return JSON.parse(raw);
  } catch (e) {
    console.error('Failed to load workspace container:', wsId, e);
    return null;
  }
}

function initWorkspacesEngine() {
  try {
    let rawIndex = localStorage.getItem(getWorkspacesIndexKey());
    if (!rawIndex && getCurrentUserUid()) {
      const guestIndex = localStorage.getItem(WORKSPACES_INDEX_KEY);
      if (guestIndex) {
        rawIndex = guestIndex;
        try { localStorage.setItem(getWorkspacesIndexKey(), guestIndex); } catch (e) {}
      }
    }
    if (rawIndex) {
      const parsedIndex = JSON.parse(rawIndex);
      if (parsedIndex && Array.isArray(parsedIndex.workspaces) && parsedIndex.workspaces.length > 0) {
        workspaceRegistry.workspaces = parsedIndex.workspaces;
        const exists = workspaceRegistry.workspaces.some(w => w.id === parsedIndex.activeWorkspaceId);
        workspaceRegistry.activeWorkspaceId = exists
          ? parsedIndex.activeWorkspaceId
          : workspaceRegistry.workspaces[0].id;
      }
    } else {
      const now = new Date();
      workspaceRegistry = {
        activeWorkspaceId: 'ws_default',
        workspaces: [
          {
            id: 'ws_default',
            name: 'Personal Finances',
            tag: 'Personal',
            isDefault: true,
            createdAt: now.toISOString(),
            updatedAt: now.toISOString()
          }
        ]
      };
    }

    // Ensure every registered workspace has a valid data container in localStorage
    const activeId = workspaceRegistry.activeWorkspaceId || 'ws_default';
    const existingContainer = loadWorkspaceContainer(activeId);
    if (existingContainer) {
      applyWorkspaceSnapshot(existingContainer);
    } else {
      // First-time initialization: seed active container from current flat appState
      saveActiveWorkspaceContainer();
    }
    saveWorkspaceIndex();
  } catch (e) {
    console.error('Error initializing workspaces engine:', e);
  }
}

function switchWorkspace(wsId) {
  if (!wsId || wsId === workspaceRegistry.activeWorkspaceId) return;
  const targetMeta = workspaceRegistry.workspaces.find(w => w.id === wsId);
  if (!targetMeta) return;

  // 1. Save outgoing workspace snapshot
  saveActiveWorkspaceContainer();

  // 2. Switch active workspace pointer
  workspaceRegistry.activeWorkspaceId = wsId;
  activeInlineEditWorkspaceId = null;

  // 3. Load incoming workspace container
  const targetContainer = loadWorkspaceContainer(wsId);
  if (targetContainer) {
    applyWorkspaceSnapshot(targetContainer);
  } else {
    const zeroCats = JSON.parse(JSON.stringify(DEFAULT_CATEGORIES)).map(c => ({ ...c, defaultBudget: 0 }));
    applyWorkspaceSnapshot({
      currency: appState.currency || '$',
      categories: zeroCats,
      incomes: {},
      budgets: {},
      expenses: [],
      excludedCategoriesByMonth: {},
      recurringBills: []
    });
    saveActiveWorkspaceContainer();
  }

  // Ensure active months have initialized budget & income structures for this workspace
  const months = getSortedActiveMonths();
  months.forEach(m => {
    if (!appState.budgets[m]) {
      applyDefaultBudgetsForMonth(m);
    }
    ensureIncomeForMonth(m);
  });

  // Sync currency dropdown
  const currSelect = document.getElementById('currencySelect');
  if (currSelect && appState.currency) currSelect.value = appState.currency;

  // 4. Persist state & refresh entire UI
  saveData();
  populateCategorySelects();
  populateIncomeInputs();
  renderBudgetGrid();
  updateAllViews();
  renderWorkspaceUI();

  showToast(`Switched to "${targetMeta.name}" (${targetMeta.tag})`);
}

function handleSidebarWorkspaceSelectChange(val) {
  if (!val) return;
  if (val === '__new__') {
    // Restore select to current active workspace and open create panel
    const sel = document.getElementById('sidebarWorkspaceSelect');
    if (sel) sel.value = workspaceRegistry.activeWorkspaceId;
    openWorkspaceDrawerForCreate();
    return;
  }
  switchWorkspace(val);
}

function refreshAllUI() {
  if (typeof updateAllViews === 'function') updateAllViews();
}

function createWorkspace(name, tag = 'Personal', template = 'standard') {
  // [TIER-GATING] Multi-workspace is an Executive Wealth feature
  if (workspaceRegistry.workspaces && workspaceRegistry.workspaces.length >= 1 &&
      typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-27 v2]')) {
    if (typeof showUpgradePrompt === 'function') {
      showUpgradePrompt('[FEAT-27 v2]', 'Isolated Multi-Workspaces & Separate Books');
    }
    return null;
  }

  const cleanName = (name || '').trim();
  if (!cleanName) {
    showToast('Please enter a workspace name.', 'warning');
    return null;
  }

  // Save current workspace before creating the new one
  saveActiveWorkspaceContainer();

  const newId = 'ws_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 5);
  const now = new Date().toISOString();

  let initialSnapshot;
  if (template === 'clone_active') {
    initialSnapshot = extractWorkspaceSnapshot();
  } else {
    let baseCategories = [];
    if (template === 'blank') {
      baseCategories = [];
    } else if (template === 'default_categories' || template === 'standard') {
      baseCategories = JSON.parse(JSON.stringify(DEFAULT_CATEGORIES)).map(c => ({ ...c, defaultBudget: 0 }));
    } else {
      // 'categories_only' or 'clone': keep current custom categories, but reset defaultBudget to 0 for a clean $0 ledger
      baseCategories = JSON.parse(JSON.stringify(appState.categories || DEFAULT_CATEGORIES)).map(c => ({ ...c, defaultBudget: 0 }));
    }

    const zeroBudgets = {};
    const zeroIncomes = {};
    const activeMonthsList = getSortedActiveMonths();
    activeMonthsList.forEach(m => {
      zeroIncomes[m] = { paycheck15: 0, paycheck30: 0, additional: 0 };
      zeroBudgets[m] = {};
      baseCategories.forEach(c => {
        zeroBudgets[m][c.id] = 0;
      });
    });

    initialSnapshot = {
      currency: appState.currency || '$',
      categories: baseCategories,
      incomes: zeroIncomes,
      budgets: zeroBudgets,
      expenses: [],
      excludedCategoriesByMonth: {},
      recurringBills: [],
      workspaceLayouts: (typeof DEFAULT_WORKSPACE_LAYOUTS !== 'undefined') ? JSON.parse(JSON.stringify(DEFAULT_WORKSPACE_LAYOUTS)) : {}
    };
  }

  const newMeta = {
    id: newId,
    name: cleanName,
    tag: tag || 'Personal',
    createdAt: now,
    updatedAt: now
  };

  // Store new container and update registry
  try {
    localStorage.setItem(getWorkspaceDataPrefix() + newId, JSON.stringify(initialSnapshot));
  } catch (e) {
    console.error('Failed to write new workspace container:', e);
  }

  workspaceRegistry.workspaces.push(newMeta);
  workspaceRegistry.activeWorkspaceId = newId;
  activeInlineEditWorkspaceId = null;

  applyWorkspaceSnapshot(initialSnapshot);
  saveData();

  // Reset and collapse inline creation form
  const form = document.getElementById('newWorkspaceForm');
  if (form) form.reset();
  toggleNewWorkspaceForm(false);

  populateCategorySelects();
  populateIncomeInputs();
  renderBudgetGrid();
  updateAllViews();
  renderWorkspaceUI();

  showToast(`Created workspace "${cleanName}"!`);
  return newMeta;
}

function renameWorkspace(wsId, newName, newTag) {
  const meta = workspaceRegistry.workspaces.find(w => w.id === wsId);
  if (!meta) return;

  const cleanName = (newName || '').trim();
  if (!cleanName) {
    showToast('Workspace name cannot be empty.', 'warning');
    return;
  }

  meta.name = cleanName;
  if (newTag) meta.tag = newTag;
  meta.updatedAt = new Date().toISOString();
  activeInlineEditWorkspaceId = null;

  saveWorkspaceIndex();
  saveData();
  renderWorkspaceUI();
  showToast(`Workspace updated to "${cleanName}"`);
}

function duplicateWorkspace(wsId) {
  const sourceMeta = workspaceRegistry.workspaces.find(w => w.id === wsId);
  if (!sourceMeta) return;

  // Ensure latest changes on active workspace are flushed first
  saveActiveWorkspaceContainer();

  const sourceSnapshot = (wsId === workspaceRegistry.activeWorkspaceId)
    ? extractWorkspaceSnapshot()
    : (loadWorkspaceContainer(wsId) || extractWorkspaceSnapshot());

  const newId = 'ws_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 5);
  const now = new Date().toISOString();
  const copyMeta = {
    id: newId,
    name: `${sourceMeta.name} (Copy)`,
    tag: sourceMeta.tag || 'Personal',
    createdAt: now,
    updatedAt: now
  };

  try {
    localStorage.setItem(getWorkspaceDataPrefix() + newId, JSON.stringify(sourceSnapshot));
  } catch (e) {
    console.error('Failed to duplicate workspace container:', e);
  }

  workspaceRegistry.workspaces.push(copyMeta);
  saveWorkspaceIndex();
  saveData();
  renderWorkspaceUI();
  showToast(`Cloned "${sourceMeta.name}"!`);
}

function deleteWorkspace(wsId) {
  if (!workspaceRegistry || workspaceRegistry.workspaces.length <= 1) {
    showToast('Cannot delete the only remaining workspace.', 'warning');
    return;
  }

  const targetMeta = workspaceRegistry.workspaces.find(w => w.id === wsId);
  if (!targetMeta) return;

  const idx = workspaceRegistry.workspaces.findIndex(w => w.id === wsId);
  if (idx === -1) return;

  workspaceRegistry.workspaces.splice(idx, 1);
  try {
    localStorage.removeItem(getWorkspaceDataPrefix() + wsId);
  } catch (e) {
    console.warn('Could not remove workspace container from localStorage:', e);
  }

  if (typeof deleteWorkspaceFromFirestore === 'function') {
    deleteWorkspaceFromFirestore(wsId);
  }

  // If we deleted the active workspace, immediately load the first available workspace
  if (workspaceRegistry.activeWorkspaceId === wsId) {
    const nextWs = workspaceRegistry.workspaces[0];
    workspaceRegistry.activeWorkspaceId = nextWs.id;
    const nextSnapshot = loadWorkspaceContainer(nextWs.id);
    if (nextSnapshot) {
      applyWorkspaceSnapshot(nextSnapshot);
    }
    const months = getSortedActiveMonths();
    months.forEach(m => {
      if (!appState.budgets[m]) applyDefaultBudgetsForMonth(m);
      ensureIncomeForMonth(m);
    });
    populateCategorySelects();
    populateIncomeInputs();
    renderBudgetGrid();
    updateAllViews();
  }

  activeInlineEditWorkspaceId = null;
  saveWorkspaceIndex();
  saveData();
  renderWorkspaceUI();
  showToast(`Deleted workspace "${targetMeta.name}"`);
}

function ensureWorkspaceDrawerInBody() {
  const modal = document.getElementById('workspaceDrawerModal');
  if (modal && modal.parentElement !== document.body) {
    document.body.appendChild(modal);
  }
  return modal;
}

function openWorkspaceDrawer(e) {
  if (e && typeof e.stopPropagation === 'function') e.stopPropagation();
  const modal = ensureWorkspaceDrawerInBody();
  if (!modal) return;
  activeInlineEditWorkspaceId = null;
  toggleNewWorkspaceForm(false);
  renderWorkspaceUI();
  modal.classList.add('active');
  modal.setAttribute('aria-hidden', 'false');
}

function openWorkspaceDrawerForCreate(e) {
  if (e && typeof e.stopPropagation === 'function') e.stopPropagation();
  // [TIER-GATING] Multi-workspace is an Executive Wealth feature
  if (workspaceRegistry.workspaces && workspaceRegistry.workspaces.length >= 1 &&
      typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-27 v2]')) {
    if (typeof showUpgradePrompt === 'function') {
      showUpgradePrompt('[FEAT-27 v2]', 'Isolated Multi-Workspaces & Separate Books');
    }
    return;
  }
  const modal = ensureWorkspaceDrawerInBody();
  if (!modal) return;
  activeInlineEditWorkspaceId = null;
  renderWorkspaceUI();
  modal.classList.add('active');
  modal.setAttribute('aria-hidden', 'false');
  toggleNewWorkspaceForm(true);
}

function openWorkspaceDrawerForRenameActive(e) {
  if (e && typeof e.stopPropagation === 'function') e.stopPropagation();
  const modal = ensureWorkspaceDrawerInBody();
  if (!modal) return;
  const activeId = workspaceRegistry.activeWorkspaceId || 'ws_default';
  activeInlineEditWorkspaceId = activeId;
  toggleNewWorkspaceForm(false);
  renderWorkspaceUI();
  modal.classList.add('active');
  modal.setAttribute('aria-hidden', 'false');
  setTimeout(() => {
    const inp = document.getElementById(`wsInlineName_${activeId}`);
    if (inp) {
      inp.focus();
      inp.select();
    }
  }, 40);
}

function closeWorkspaceDrawer() {
  const modal = document.getElementById('workspaceDrawerModal');
  if (!modal) return;
  modal.classList.remove('active');
  modal.setAttribute('aria-hidden', 'true');
  activeInlineEditWorkspaceId = null;
}

// [FEAT-53] Slide-Over System & Data Tools Drawer
function openSystemToolsDrawer() {
  const modal = document.getElementById('systemToolsDrawerModal');
  if (!modal) return;
  if (modal.parentElement !== document.body) {
    document.body.appendChild(modal);
  }
  modal.classList.add('active');
  modal.setAttribute('aria-hidden', 'false');
}

function closeSystemToolsDrawer() {
  const modal = document.getElementById('systemToolsDrawerModal');
  if (!modal) return;
  modal.classList.remove('active');
  modal.setAttribute('aria-hidden', 'true');
}

window.openSystemToolsDrawer = openSystemToolsDrawer;
window.closeSystemToolsDrawer = closeSystemToolsDrawer;

function toggleNewWorkspaceForm(forceShow) {
  const panel = document.getElementById('newWorkspaceCollapsePanel');
  const btn = document.getElementById('btnToggleNewWorkspaceForm');
  if (!panel) return;

  const isCurrentlyHidden = panel.style.display === 'none' || panel.hasAttribute('hidden');
  const shouldShow = typeof forceShow === 'boolean' ? forceShow : isCurrentlyHidden;

  if (shouldShow) {
    panel.style.display = 'block';
    panel.removeAttribute('hidden');
    if (btn) btn.classList.add('active');
    const nameInput = document.getElementById('newWorkspaceName') || document.getElementById('newWorkspaceNameInput');
    if (nameInput) setTimeout(() => nameInput.focus(), 40);
  } else {
    panel.style.display = 'none';
    panel.setAttribute('hidden', '');
    if (btn) btn.classList.remove('active');
  }
}

function getWorkspaceSummaryStats(wsId) {
  const snap = (wsId === workspaceRegistry.activeWorkspaceId)
    ? appState
    : (loadWorkspaceContainer(wsId) || {});
  const catCount = Array.isArray(snap.categories) ? snap.categories.length : 0;
  const txCount = Array.isArray(snap.expenses) ? snap.expenses.length : 0;
  const billCount = Array.isArray(snap.recurringBills) ? snap.recurringBills.length : 0;
  return { catCount, txCount, billCount };
}

function updateWorkspaceHeaderBadges() {
  const meta = getActiveWorkspaceMeta();
  const workspaces = workspaceRegistry.workspaces || [];
  const totalCount = workspaces.length || 1;
  const icon = getWorkspaceTagIcon(meta.tag);

  // Sidebar Active Workspace Card
  const sidebarIcon = document.getElementById('sidebarWorkspaceIcon');
  const sidebarName = document.getElementById('sidebarWorkspaceName');
  const sidebarTag = document.getElementById('sidebarWorkspaceTag') || document.getElementById('sidebarWorkspaceTagBadge');
  const sidebarCard = document.getElementById('sidebarWorkspaceCard');
  const sidebarSelect = document.getElementById('sidebarWorkspaceSelect');
  if (sidebarIcon) sidebarIcon.textContent = icon;
  if (sidebarName) sidebarName.textContent = meta.name;
  if (sidebarTag) sidebarTag.textContent = meta.tag || 'Personal';

  // Sidebar Unified Filter Pill
  const pillIcon = document.getElementById('pillWorkspaceIcon');
  const pillName = document.getElementById('pillWorkspaceName');
  if (pillIcon) pillIcon.textContent = icon;
  if (pillName) pillName.textContent = meta.name;
  if (sidebarCard) {
    sidebarCard.title = `Active Workspace: ${meta.name} (${meta.tag || 'Personal'}) — Click or press W to manage`;
  }
  if (sidebarSelect) {
    sidebarSelect.innerHTML = workspaces.map(ws => {
      const wsIcon = getWorkspaceTagIcon(ws.tag);
      const selected = ws.id === workspaceRegistry.activeWorkspaceId ? 'selected' : '';
      return `<option value="${escapeHTML(ws.id)}" ${selected}>${wsIcon} ${escapeHTML(ws.name)} (${escapeHTML(ws.tag || 'Personal')})</option>`;
    }).join('') + `<option value="__new__">➕ Create New Workspace...</option>`;
    sidebarSelect.value = workspaceRegistry.activeWorkspaceId;
  }

  // Topbar Workspace Pill
  const topbarIcon = document.getElementById('topbarWorkspaceIcon');
  const topbarName = document.getElementById('topbarWorkspaceName');
  const topbarTag = document.getElementById('topbarWorkspaceTag');
  const topbarCount = document.getElementById('topbarWorkspaceCountBadge');
  if (topbarIcon) topbarIcon.textContent = icon;
  if (topbarName) topbarName.textContent = meta.name;
  if (topbarTag) topbarTag.textContent = meta.tag || 'Personal';
  if (topbarCount) topbarCount.textContent = String(totalCount);

  // Drawer Subtitle Count
  const drawerCount = document.getElementById('workspaceDrawerCount');
  if (drawerCount) drawerCount.textContent = String(totalCount);
  const drawerCountText = document.getElementById('workspaceDrawerCountText');
  if (drawerCountText) {
    drawerCountText.textContent = `${totalCount} Isolated Container${totalCount === 1 ? '' : 's'}`;
  }
}

