function renderWorkspaceUI() {
  updateWorkspaceHeaderBadges();

  const listEl = document.getElementById('workspaceDrawerList');
  if (!listEl) return;

  const workspaces = workspaceRegistry.workspaces || [];
  const activeId = workspaceRegistry.activeWorkspaceId;
  const canDelete = workspaces.length > 1;
  const tagChoices = ['Personal', 'Business', 'Freelance', 'Project', 'Travel', 'Investments', 'Family', 'Savings', 'Other'];

  listEl.innerHTML = workspaces.map(ws => {
    const isActive = ws.id === activeId;
    const isEditing = activeInlineEditWorkspaceId === ws.id;
    const stats = getWorkspaceSummaryStats(ws.id);
    const icon = getWorkspaceTagIcon(ws.tag);

    return `
      <div class="ws-card ${isActive ? 'active is-active' : ''}" data-ws-id="${escapeHTML(ws.id)}">
        <div class="ws-card-main">
          <div class="ws-card-select-area" data-action="switch" data-ws-id="${escapeHTML(ws.id)}" title="${isActive ? 'Currently Active Workspace' : 'Click to switch to ' + escapeHTML(ws.name)}">
            <div class="ws-card-icon">${icon}</div>
            <div class="ws-card-info">
              <div class="ws-card-title-row">
                <span class="ws-card-name">${escapeHTML(ws.name)}</span>
                <span class="ws-card-tag-pill">${escapeHTML(ws.tag || 'Personal')}</span>
                ${isActive ? '<span class="ws-card-active-badge"><span class="ws-card-active-dot"></span>Active</span>' : ''}
              </div>
              <div class="ws-card-stats-row">
                <span class="ws-card-stat"><strong>${stats.catCount}</strong> Categories</span>
                <span>•</span>
                <span class="ws-card-stat"><strong>${stats.txCount}</strong> Expenses</span>
                <span>•</span>
                <span class="ws-card-stat"><strong>${stats.billCount}</strong> Bills</span>
              </div>
            </div>
          </div>
          <div class="ws-card-actions">
            ${!isActive ? `
              <button type="button" class="ws-action-btn ws-switch-btn" data-action="switch" data-ws-id="${escapeHTML(ws.id)}" title="Switch to this workspace">
                Switch
              </button>
            ` : ''}
            <button type="button" class="ws-action-btn" data-action="edit" data-ws-id="${escapeHTML(ws.id)}" title="Rename workspace or change tag">
              ✏️ Rename
            </button>
            <button type="button" class="ws-action-btn" data-action="clone" data-ws-id="${escapeHTML(ws.id)}" title="Duplicate workspace">
              📋 Clone
            </button>
            <button type="button" class="ws-action-btn ws-delete-btn" data-action="delete" data-ws-id="${escapeHTML(ws.id)}" ${!canDelete ? 'disabled title="Cannot delete the only workspace"' : 'title="Delete workspace"'}>
              🗑️
            </button>
          </div>
        </div>
        ${isEditing ? `
          <div class="ws-inline-edit-row active" data-edit-row="${escapeHTML(ws.id)}">
            <input type="text" class="ws-inline-input" id="wsInlineName_${escapeHTML(ws.id)}" value="${escapeHTML(ws.name)}" maxlength="40" placeholder="Workspace Name">
            <select class="ws-inline-select" id="wsInlineTag_${escapeHTML(ws.id)}">
              ${tagChoices.map(t =>
                `<option value="${t}" ${ws.tag === t ? 'selected' : ''}>${getWorkspaceTagIcon(t)} ${t}</option>`
              ).join('')}
            </select>
            <button type="button" class="btn btn-primary btn-sm" data-action="save-edit" data-ws-id="${escapeHTML(ws.id)}">Save</button>
            <button type="button" class="btn btn-secondary btn-sm" data-action="cancel-edit" data-ws-id="${escapeHTML(ws.id)}">Cancel</button>
          </div>
        ` : ''}
      </div>
    `;
  }).join('');

  // Bind delegated events on workspace cards
  listEl.querySelectorAll('[data-action]').forEach(el => {
    el.addEventListener('click', (e) => {
      e.stopPropagation();
      const action = el.getAttribute('data-action');
      const wsId = el.getAttribute('data-ws-id');
      if (!wsId) return;

      if (action === 'switch') {
        switchWorkspace(wsId);
      } else if (action === 'edit') {
        activeInlineEditWorkspaceId = (activeInlineEditWorkspaceId === wsId) ? null : wsId;
        renderWorkspaceUI();
        if (activeInlineEditWorkspaceId) {
          const inp = document.getElementById(`wsInlineName_${wsId}`);
          if (inp) setTimeout(() => { inp.focus(); inp.select(); }, 30);
        }
      } else if (action === 'save-edit') {
        const inp = document.getElementById(`wsInlineName_${wsId}`);
        const sel = document.getElementById(`wsInlineTag_${wsId}`);
        renameWorkspace(wsId, inp ? inp.value : '', sel ? sel.value : 'Personal');
      } else if (action === 'cancel-edit') {
        activeInlineEditWorkspaceId = null;
        renderWorkspaceUI();
      } else if (action === 'clone') {
        duplicateWorkspace(wsId);
      } else if (action === 'delete') {
        deleteWorkspace(wsId);
      }
    });
  });

  // Allow Enter key inside inline rename input to save immediately
  listEl.querySelectorAll('.ws-inline-input').forEach(inp => {
    inp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        const wsId = inp.id.replace('wsInlineName_', '');
        const sel = document.getElementById(`wsInlineTag_${wsId}`);
        renameWorkspace(wsId, inp.value, sel ? sel.value : 'Personal');
      }
    });
  });
}

