// ==========================================
// 20. [FEAT-33] PROACTIVE OVERSPEND ALERTS
// ==========================================
const OVERSPEND_ALERTS_KEY = 'budgetMasterOverspendAlerts';
const OVERSPEND_WARN_PCT = 80;

function areOverspendAlertsEnabled() {
  try {
    return localStorage.getItem(OVERSPEND_ALERTS_KEY) !== '0';
  } catch (e) {
    return true;
  }
}

function setOverspendAlertsEnabled(on) {
  try {
    localStorage.setItem(OVERSPEND_ALERTS_KEY, on ? '1' : '0');
  } catch (e) { /* preference is optional */ }
  updateOverspendToggleUI();
}

function updateOverspendToggleUI() {
  const btn = document.getElementById('btnToggleOverspendAlerts');
  if (!btn) return;
  const on = areOverspendAlertsEnabled();
  btn.classList.toggle('is-off', !on);
  btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  btn.innerHTML = on ? '<span class="alert-icon">🔔</span><span class="alert-label">Alerts: On</span>' : '<span class="alert-icon">🕜</span><span class="alert-label">Alerts: Off</span>';
  btn.title = on
    ? 'Overspend alerts are ON: you get a warning when an expense reaches 80% or exceeds a category budget. Click to turn off.'
    : 'Overspend alerts are OFF. Click to turn on.';
}

/**
 * Returns { level, msg } when saving an expense of `amount` into `categoryId` on `dateStr`
 * would reach 80% of, or exceed, that category's budget for the expense's month.
 * `excludeTxId` removes an expense that is being edited so it is not counted twice.
 */
function getOverspendAlert(categoryId, dateStr, amount, excludeTxId = null) {
  if (!areOverspendAlertsEnabled()) return null;
  if (!categoryId || !dateStr || !(amount > 0)) return null;

  const cat = appState.categories.find(c => c.id === categoryId);
  if (!cat) return null;

  const month = dateStr.slice(0, 7);
  const excluded = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[month]) || [];
  if (excluded.includes(categoryId)) return null;

  const monthBudgets = appState.budgets[month] || {};
  const budget = monthBudgets[categoryId] !== undefined ? monthBudgets[categoryId] : (cat.defaultBudget || 0);

  const before = appState.expenses
    .filter(e => e.categoryId === categoryId && e.date && e.date.slice(0, 7) === month && e.id !== excludeTxId)
    .reduce((s, e) => s + (e.amount || 0), 0);
  const after = before + amount;
  const label = `${cat.icon || ''} ${cat.name}`.trim();

  if (budget <= 0) {
    return {
      level: 'warn',
      msg: `⚠️ "${label}" has no budget allocated for ${formatMonthLabel(month)} — this spending is unbudgeted.`
    };
  }

  const pctAfter = (after / budget) * 100;

  if (after > budget) {
    const over = after - budget;
    if (before > budget) {
      return {
        level: 'danger',
        msg: `🚨 "${label}" is already over budget — now ${formatCurrency(over)} over (${pctAfter.toFixed(0)}% of ${formatCurrency(budget)}).`
      };
    }
    return {
      level: 'danger',
      msg: `🚨 This puts "${label}" ${formatCurrency(over)} over budget (${pctAfter.toFixed(0)}% of ${formatCurrency(budget)}).`
    };
  }

  const pctBefore = (before / budget) * 100;
  if (pctBefore < OVERSPEND_WARN_PCT && pctAfter >= OVERSPEND_WARN_PCT) {
    return {
      level: 'warn',
      msg: `⚠️ "${label}" has reached ${pctAfter.toFixed(0)}% of its ${formatCurrency(budget)} budget — ${formatCurrency(budget - after)} left.`
    };
  }

  return null;
}

// ==========================================
// 21. [FEAT-32] RECURRING BILLS & SUBSCRIPTIONS
// ==========================================
const BILL_FREQUENCY_LABELS = {
  monthly: 'Monthly',
  semimonthly: 'Twice a month (15th & month-end)',
  yearly: 'Yearly'
};
const BILL_SOON_DAYS = 7;
const BILL_BADGE_DAYS = 3;
const BILL_HORIZON_MONTHS = 13;

function billPad(n) { return String(n).padStart(2, '0'); }

function billTodayStr() {
  const d = new Date();
  return `${d.getFullYear()}-${billPad(d.getMonth() + 1)}-${billPad(d.getDate())}`;
}

function billParseDate(str) {
  const [y, m, d] = str.split('-').map(Number);
  return new Date(y, m - 1, d);
}

function billDaysBetween(fromStr, toStr) {
  return Math.round((billParseDate(toStr) - billParseDate(fromStr)) / 86400000);
}

/** Due dates (YYYY-MM-DD) a bill generates inside a given YYYY-MM month. */
function getBillDueDatesForMonth(bill, ym) {
  const [y, m] = ym.split('-').map(Number);
  const lastDay = new Date(y, m, 0).getDate();
  const day = Math.min(Math.max(parseInt(bill.dueDay, 10) || 1, 1), lastDay);
  const fmt = d => `${ym}-${billPad(d)}`;

  if (bill.frequency === 'semimonthly') return [fmt(Math.min(15, lastDay)), fmt(lastDay)];
  if (bill.frequency === 'yearly') return m === (parseInt(bill.dueMonth, 10) || 1) ? [fmt(day)] : [];
  return [fmt(day)];
}

/** All due dates from the bill's start date through BILL_HORIZON_MONTHS ahead. */
function getBillDueDates(bill) {
  const start = bill.startDate || billTodayStr();
  let [y, m] = start.slice(0, 7).split('-').map(Number);
  const now = new Date();
  const endIdx = now.getFullYear() * 12 + now.getMonth() + BILL_HORIZON_MONTHS;
  const out = [];
  let guard = 0;
  while (y * 12 + (m - 1) <= endIdx && guard++ < 1500) {
    getBillDueDatesForMonth(bill, `${y}-${billPad(m)}`).forEach(d => {
      if (d >= start) out.push(d);
    });
    m++;
    if (m > 12) { m = 1; y++; }
  }
  return out;
}

function isBillDateSettled(bill, due) {
  if (Array.isArray(bill.skippedDates) && bill.skippedDates.includes(due)) return true;
  return appState.expenses.some(e => e.billId === bill.id && e.billDue === due);
}

function getBillStatus(bill) {
  const today = billTodayStr();
  const isFutureStart = Boolean(bill.startDate && bill.startDate > today);
  const daysUntilStart = isFutureStart ? billDaysBetween(today, bill.startDate) : 0;

  const pending = getBillDueDates(bill).filter(d => !isBillDateSettled(bill, d));
  const overdue = pending.filter(d => d < today);
  const next = pending[0] || null;
  const daysUntil = next ? billDaysBetween(today, next) : null;

  let state = 'none';
  if (bill.active === false) state = 'paused';
  else if (isFutureStart) state = 'not_started';
  else if (overdue.length > 0) state = 'overdue';
  else if (next) state = daysUntil === 0 ? 'today' : (daysUntil <= BILL_SOON_DAYS ? 'soon' : 'upcoming');

  return { state, next, daysUntil, overdueCount: overdue.length, pending, isFutureStart, daysUntilStart };
}

function getBillMonthlyEquivalent(bill) {
  const amt = bill.amount || 0;
  if (bill.frequency === 'semimonthly') return amt * 2;
  if (bill.frequency === 'yearly') return amt / 12;
  return amt;
}

function formatBillDueLabel(dateStr) {
  return dateStr ? formatShortDate(dateStr) : '—';
}

function getBillStatusBadge(st) {
  switch (st.state) {
    case 'not_started':
      return `<span class="kpi-status-badge badge-info" title="Recurring starts in ${st.daysUntilStart} day${st.daysUntilStart === 1 ? '' : 's'}">Not Started Yet</span>`;
    case 'overdue':
      return `<span class="kpi-status-badge badge-danger">Overdue${st.overdueCount > 1 ? ` ×${st.overdueCount}` : ''}</span>`;
    case 'today':
      return '<span class="kpi-status-badge badge-warning">Due today</span>';
    case 'soon':
      return `<span class="kpi-status-badge badge-warning">Due in ${st.daysUntil}d</span>`;
    case 'upcoming':
      return `<span class="kpi-status-badge badge-success">In ${st.daysUntil} days</span>`;
    case 'paused':
      return '<span class="kpi-status-badge" style="background: rgba(255,255,255,0.05); color: var(--text-muted)">Paused</span>';
    default:
      return '<span class="kpi-status-badge" style="background: rgba(255,255,255,0.05); color: var(--text-muted)">—</span>';
  }
}

// ==========================================
// [FEAT-37] RECURRING BILLS SORTING & FILTERING STATE & LOGIC
// ==========================================
let billsSortState = {
  field: 'nextDue',
  order: 'asc'
};

let billsFilterState = {
  search: '',
  status: 'ALL',
  category: 'ALL',
  frequency: 'ALL',
  autoPost: 'ALL',
  cutoff: 'ALL'
};

const BILL_STATUS_RANK = {
  overdue: 1,
  today: 2,
  soon: 3,
  upcoming: 4,
  not_started: 5,
  paused: 6,
  none: 7
};

const BILL_FREQUENCY_RANK = {
  monthly: 1,
  semimonthly: 2,
  yearly: 3
};

function updateBillsSortHeaders() {
  document.querySelectorAll('#billsTable thead th.sortable-th').forEach(th => {
    const field = th.getAttribute('data-sort');
    const icon = th.querySelector('.sort-icon');
    th.classList.remove('sorted-asc', 'sorted-desc');
    if (field === billsSortState.field) {
      th.classList.add(billsSortState.order === 'asc' ? 'sorted-asc' : 'sorted-desc');
      if (icon) icon.textContent = billsSortState.order === 'asc' ? '▲' : '▼';
    } else {
      if (icon) icon.textContent = '↕';
    }
  });
}

function filterBillRows(rows) {
  const { search, status, category, frequency, autoPost } = billsFilterState;
  const query = (search || '').toLowerCase().trim();

  return rows.filter(({ bill, st, cat }) => {
    // 1. Text search
    if (query) {
      const nameMatch = (bill.name || '').toLowerCase().includes(query);
      const payMatch = (bill.paymentMethod || '').toLowerCase().includes(query);
      const catMatch = (cat?.name || '').toLowerCase().includes(query);
      if (!nameMatch && !payMatch && !catMatch) return false;
    }

    // 2. Status filter
    if (status !== 'ALL') {
      if (status === 'attention') {
        if (st.state !== 'overdue' && st.state !== 'today') return false;
      } else if (status === 'paused') {
        if (bill.active !== false) return false;
      } else if (status === 'soon') {
        if (st.state !== 'soon' && st.state !== 'today') return false;
      } else {
        if (st.state !== status) return false;
      }
    }

    // 3. Category filter
    if (category !== 'ALL') {
      if (bill.categoryId !== category) return false;
    }

    // 4. Frequency filter
    if (frequency !== 'ALL') {
      if (bill.frequency !== frequency) return false;
    }

    // 5. AutoPost Mode filter
    if (autoPost !== 'ALL') {
      if (autoPost === 'auto' && bill.autoPost === false) return false;
      if (autoPost === 'manual' && bill.autoPost !== false) return false;
    }

    // 6. [FEAT-BILLS-CUTOFF-LOAD] 1st-Half (Days 1-15) vs 2nd-Half (Days 16-End) cutoff filter
    if (billsFilterState.cutoff && billsFilterState.cutoff !== 'ALL') {
      const freq = bill.frequency || 'monthly';
      const dueDay = parseInt(bill.dueDay, 10) || 1;
      if (freq === 'semimonthly') {
        // Semi-monthly bills occur in both 1st-Half (15th) and 2nd-Half (30th)
        return true;
      }
      if (billsFilterState.cutoff === '1H' && dueDay > 15) return false;
      if (billsFilterState.cutoff === '2H' && dueDay <= 15) return false;
    }

    return true;
  });
}

function sortBillRows(rows) {
  const { field, order } = billsSortState;
  const dir = order === 'asc' ? 1 : -1;

  rows.sort((a, b) => {
    let diff = 0;

    switch (field) {
      case 'name':
        diff = a.bill.name.localeCompare(b.bill.name, undefined, { sensitivity: 'base' });
        break;

      case 'category': {
        const catA = a.cat?.name || 'zzzz';
        const catB = b.cat?.name || 'zzzz';
        diff = catA.localeCompare(catB, undefined, { sensitivity: 'base' });
        break;
      }

      case 'amount':
        diff = (a.bill.amount || 0) - (b.bill.amount || 0);
        break;

      case 'frequency': {
        const rA = BILL_FREQUENCY_RANK[a.bill.frequency] || 99;
        const rB = BILL_FREQUENCY_RANK[b.bill.frequency] || 99;
        diff = rA - rB;
        break;
      }

      case 'startDate': {
        const dateA = a.bill.startDate || '9999-99-99';
        const dateB = b.bill.startDate || '9999-99-99';
        diff = dateA.localeCompare(dateB);
        break;
      }

      case 'nextDue': {
        const valA = a.st.next || '9999-99-99';
        const valB = b.st.next || '9999-99-99';
        diff = valA.localeCompare(valB);
        break;
      }

      case 'status': {
        const rankA = BILL_STATUS_RANK[a.st.state] || 99;
        const rankB = BILL_STATUS_RANK[b.st.state] || 99;
        diff = rankA - rankB;
        break;
      }

      default:
        diff = 0;
    }

    if (diff !== 0) {
      return diff * dir;
    }

    // Tie-breaker 1: active vs paused
    const ap = a.bill.active === false ? 1 : 0;
    const bp = b.bill.active === false ? 1 : 0;
    if (ap !== bp) return ap - bp;

    // Tie-breaker 2: next due date
    const nextA = a.st.next || '9999-99-99';
    const nextB = b.st.next || '9999-99-99';
    if (nextA !== nextB) return nextA.localeCompare(nextB);

    // Tie-breaker 3: name
    return a.bill.name.localeCompare(b.bill.name);
  });

  return rows;
}

function resetBillFilters() {
  billsFilterState = {
    search: '',
    status: 'ALL',
    category: 'ALL',
    frequency: 'ALL',
    autoPost: 'ALL',
    cutoff: 'ALL'
  };
  document.querySelectorAll('.cfc-cutoff-pill').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-cutoff') === 'ALL');
  });

  const searchInput = document.getElementById('billSearchInput');
  const statusSelect = document.getElementById('billFilterStatus');
  const categorySelect = document.getElementById('billFilterCategory');
  const freqSelect = document.getElementById('billFilterFrequency');
  const autoSelect = document.getElementById('billFilterAutoPost');

  if (searchInput) searchInput.value = '';
  if (statusSelect) statusSelect.value = 'ALL';
  if (categorySelect) categorySelect.value = 'ALL';
  if (freqSelect) freqSelect.value = 'ALL';
  if (autoSelect) autoSelect.value = 'ALL';

  renderBillsTab();
}

function getBillRows() {
  const rows = (appState.recurringBills || []).map(bill => ({
    bill,
    st: getBillStatus(bill),
    cat: appState.categories.find(c => c.id === bill.categoryId) || null
  }));
  rows.sort((a, b) => {
    const ap = a.bill.active === false ? 1 : 0;
    const bp = b.bill.active === false ? 1 : 0;
    if (ap !== bp) return ap - bp;
    if (!a.st.next && !b.st.next) return a.bill.name.localeCompare(b.bill.name);
    if (!a.st.next) return 1;
    if (!b.st.next) return -1;
    return a.st.next.localeCompare(b.st.next);
  });
  return rows;
}

function updateBillsUI() {
  renderBillsTab();
  renderUpcomingBillsStrip();
  updateBillsNavBadge();
}

function renderBillsTab() {
  const body = document.getElementById('billsTableBody');
  if (!body) return;

  const rows = getBillRows();
  const empty = document.getElementById('billsEmptyState');
  const tableWrap = document.getElementById('billsTableWrap');
  const filterBar = document.getElementById('billsFilterBar');
  const today = billTodayStr();

  // Summary cards
  const active = rows.filter(r => r.bill.active !== false);
  const commitment = active.reduce((s, r) => s + getBillMonthlyEquivalent(r.bill), 0);
  const notStarted = active.filter(r => r.st.state === 'not_started');
  const notStartedTotal = notStarted.reduce((s, r) => s + getBillMonthlyEquivalent(r.bill), 0);
  const dueSoon = active.filter(r => r.st.next && r.st.state !== 'overdue' && r.st.state !== 'not_started' && r.st.daysUntil <= BILL_SOON_DAYS);
  const overdue = active.filter(r => r.st.state === 'overdue');
  const overdueTotal = overdue.reduce((s, r) => s + (r.bill.amount || 0) * r.st.overdueCount, 0);

  const setTxt = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
  setTxt('billsCommitment', formatCurrency(commitment));
  setTxt('billsCommitmentSub', `${active.length} active ${active.length === 1 ? 'bill' : 'bills'}`);
  setTxt('billsNotStarted', formatCurrency(notStartedTotal));
  setTxt('billsNotStartedSub', `${notStarted.length} ${notStarted.length === 1 ? 'bill' : 'bills'} in forecast`);
  setTxt('billsDueSoon', formatCurrency(dueSoon.reduce((s, r) => s + (r.bill.amount || 0), 0)));
  setTxt('billsDueSoonSub', `${dueSoon.length} due in the next ${BILL_SOON_DAYS} days`);
  setTxt('billsOverdue', formatCurrency(overdueTotal));
  setTxt('billsOverdueSub', `${overdue.length} ${overdue.length === 1 ? 'bill' : 'bills'} overdue`);

  const btnPostAll = document.getElementById('btnPostAllDueBills');
  const dueNowCount = active.reduce((n, r) => n + r.st.pending.filter(d => d <= today).length, 0);
  if (btnPostAll) {
    btnPostAll.disabled = dueNowCount === 0;
    btnPostAll.textContent = dueNowCount > 0 ? `✓ Post All Due (${dueNowCount})` : '✓ Post All Due';
  }

  body.innerHTML = '';
  if (rows.length === 0) {
    if (empty) empty.style.display = 'block';
    if (tableWrap) tableWrap.style.display = 'none';
    if (filterBar) filterBar.style.display = 'none';
    return;
  }
  if (empty) empty.style.display = 'none';
  if (tableWrap) tableWrap.style.display = '';
  if (filterBar) filterBar.style.display = 'flex';

  // Apply filters and sorting
  const filteredRows = sortBillRows(filterBillRows([...rows]));

  // Update filter count & reset button
  const filterCountEl = document.getElementById('billFilteredCount');
  const resetBtn = document.getElementById('btnResetBillFilters');
  const isFiltered = Boolean(
    billsFilterState.search ||
    billsFilterState.status !== 'ALL' ||
    billsFilterState.category !== 'ALL' ||
    billsFilterState.frequency !== 'ALL' ||
    billsFilterState.autoPost !== 'ALL' ||
    (billsFilterState.cutoff && billsFilterState.cutoff !== 'ALL')
  );

  if (filterCountEl) {
    if (isFiltered) {
      filterCountEl.textContent = `Showing ${filteredRows.length} of ${rows.length} bills`;
    } else {
      filterCountEl.textContent = `Showing all ${rows.length} ${rows.length === 1 ? 'bill' : 'bills'}`;
    }
  }

  if (resetBtn) {
    resetBtn.style.display = isFiltered ? 'inline-flex' : 'none';
  }

  updateBillsSortHeaders();

  if (filteredRows.length === 0) {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td colspan="8" style="text-align: center; padding: 36px 16px; color: var(--text-secondary);">
        <div style="font-size: 1.15rem; margin-bottom: 6px;">🔍 No matching recurring bills</div>
        <div style="font-size: 0.85rem; margin-bottom: 14px; color: var(--text-muted);">No bills match your current filter settings.</div>
        <button type="button" class="btn btn-secondary btn-sm" id="btnFilterEmptyClear">Clear All Filters</button>
      </td>
    `;
    body.appendChild(tr);
    const emptyClearBtn = document.getElementById('btnFilterEmptyClear');
    if (emptyClearBtn) emptyClearBtn.addEventListener('click', resetBillFilters);
    return;
  }

  filteredRows.forEach(({ bill, st, cat }) => {
    const tr = document.createElement('tr');
    const paused = bill.active === false;
    const isNotStarted = st.state === 'not_started';
    if (paused) tr.className = 'bill-row-paused';
    const catLabel = cat ? `${cat.icon} ${escapeHTML(cat.name)}` : '<span style="color: var(--rose)">Category removed</span>';
    const moreOverdue = st.overdueCount > 1 ? `<div class="bill-sub">+${st.overdueCount - 1} more overdue</div>` : '';

    const startsFromFormatted = bill.startDate ? formatShortDate(bill.startDate) : '—';
    const startSub = isNotStarted
      ? `<div class="bill-sub" style="color: #38bdf8; font-weight: 600;">Starts in ${st.daysUntilStart}d</div>`
      : (bill.startDate ? '<div class="bill-sub" style="color: var(--text-muted);">Active</div>' : '');

    const nextDueFormatted = isNotStarted
      ? `<span style="color: var(--text-secondary);">${formatBillDueLabel(st.next)}</span><div class="bill-sub">1st cycle</div>`
      : `${formatBillDueLabel(st.next)}${moreOverdue}`;

    const bType = bill.budgetType || (cat && cat.budgetType) || getCategoryBudgetType(bill.categoryId) || 'needs';
    const bTypeBadge = bType === 'wants'
      ? `<span class="badge-budget-tag badge-tag-wants" title="Wants (Discretionary)">✨ Wants</span>`
      : `<span class="badge-budget-tag badge-tag-needs" title="Needs (Essential)">🛡️ Needs</span>`;

    tr.innerHTML = `
      <td>
        <strong>${escapeHTML(bill.name)}</strong>
        ${bill.isInstallment ? `<span class="badge-installment-pill" title="0% Installment: month ${bill.installmentCurrent || 1} of ${bill.installmentTotal || 12}">💳 ${bill.installmentCurrent || 1}/${bill.installmentTotal || 12} mo</span>` : ''}
        ${bill.excludeFromBudget ? `<span class="badge-ccpayoff-pill" title="CC Statement Payoff: excluded from budget spending">💳 Payoff</span>` : ''}
        <div class="bill-sub">${escapeHTML(bill.paymentMethod || 'Credit Card')}${bill.autoPost !== false ? ' · 🔄 Auto-added' : ' · Manual'}</div>
      </td>
      <td>
        <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
          <span>${catLabel}</span>
          ${bTypeBadge}
        </div>
      </td>
      <td class="text-right" style="font-weight: 700;">${formatCurrency(bill.amount)}</td>
      <td>${escapeHTML(BILL_FREQUENCY_LABELS[bill.frequency] || 'Monthly')}</td>
      <td>
        <span>${startsFromFormatted}</span>
        ${startSub}
      </td>
      <td>${nextDueFormatted}</td>
      <td class="text-center">${getBillStatusBadge(st)}</td>
      <td class="text-center">
        <div class="bill-actions">
          <button type="button" class="btn btn-primary btn-xs" data-bill-action="post" data-bill-id="${bill.id}" ${(!st.next || paused || isNotStarted) ? 'disabled' : ''} title="${isNotStarted ? `Bill has not started yet (starts ${startsFromFormatted})` : `Log this bill as an expense dated ${st.next || ''}`}">Post</button>
          <button type="button" class="btn btn-secondary btn-xs" data-bill-action="skip" data-bill-id="${bill.id}" ${(!st.next || paused || isNotStarted) ? 'disabled' : ''} title="${isNotStarted ? 'Bill has not started yet' : 'Skip this occurrence without logging an expense'}">Skip</button>
          <button type="button" class="btn-icon" data-bill-action="edit" data-bill-id="${bill.id}" title="Edit bill" style="width:26px; height:26px;">✏️</button>
          <button type="button" class="btn-icon" data-bill-action="toggle" data-bill-id="${bill.id}" title="${paused ? 'Resume' : 'Pause'} bill" style="width:26px; height:26px;">${paused ? '▶️' : '⏸️'}</button>
          <button type="button" class="btn-icon" data-bill-action="delete" data-bill-id="${bill.id}" title="Delete bill" style="width:26px; height:26px; color: #f87171;">🗑️</button>
        </div>
      </td>
    `;
    body.appendChild(tr);
  });
}

function renderUpcomingBillsStrip() {
  const strip = document.getElementById('upcomingBillsStrip');
  if (!strip) return;

  const rows = getBillRows().filter(r => r.bill.active !== false && r.st.next && r.st.state !== 'not_started');
  if (rows.length === 0) {
    strip.style.display = 'none';
    strip.innerHTML = '';
    return;
  }

  const chips = rows.slice(0, 4).map(({ bill, st }) => {
    let when;
    let cls = 'ok';
    if (st.state === 'overdue') { when = `overdue${st.overdueCount > 1 ? ` ×${st.overdueCount}` : ''}`; cls = 'danger'; }
    else if (st.state === 'today') { when = 'due today'; cls = 'warn'; }
    else if (st.state === 'soon') { when = `in ${st.daysUntil} day${st.daysUntil === 1 ? '' : 's'}`; cls = 'warn'; }
    else { when = `in ${st.daysUntil} days`; }
    return `<span class="upcoming-bill-chip ${cls}"><strong>${escapeHTML(bill.name)}</strong> ${formatCurrency(bill.amount)} · ${when}</span>`;
  }).join('');

  const extra = rows.length > 4 ? `<span class="upcoming-bill-more">+${rows.length - 4} more</span>` : '';
  strip.innerHTML = `<span class="upcoming-bills-title">🔁 UPCOMING BILLS</span><div class="upcoming-bills-chips">${chips}${extra}</div>`;
  strip.style.display = 'flex';
}

function updateBillsNavBadge() {
  const badge = document.getElementById('billsNavBadge');
  const mobBadge = document.getElementById('mobileBillsNavBadge');
  const count = (appState.recurringBills || []).filter(b => {
    if (b.active === false) return false;
    const st = getBillStatus(b);
    if (st.state === 'not_started') return false;
    return st.state === 'overdue' || (st.next && st.daysUntil <= BILL_BADGE_DAYS);
  }).length;
  if (badge) {
    badge.textContent = count;
    badge.style.display = count > 0 ? 'inline-flex' : 'none';
  }
  if (mobBadge) {
    mobBadge.textContent = count;
    mobBadge.style.display = count > 0 ? 'inline-flex' : 'none';
  }
}

// ---------- Bill modal ----------
function updateBillFormVisibility() {
  const freq = document.getElementById('billFrequency').value;
  document.getElementById('billDueDayGroup').style.display = freq === 'semimonthly' ? 'none' : '';
  document.getElementById('billDueMonthGroup').style.display = freq === 'yearly' ? '' : 'none';
}

function openBillModal(editId = null) {
  if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-32]')) {
    if (typeof showUpgradePrompt === 'function') {
      showUpgradePrompt('[FEAT-32]', 'Recurring Bills & Subscriptions Calendar', 'bills');
    }
    return;
  }

  const form = document.getElementById('billForm');
  if (!form) return;
  form.reset();

  const catSelect = document.getElementById('billCategory');
  catSelect.innerHTML = '';
  appState.categories.forEach(c => {
    const opt = document.createElement('option');
    opt.value = c.id;
    opt.textContent = `${c.icon} ${c.name}`;
    catSelect.appendChild(opt);
  });

  document.getElementById('billCurrencyLabel').textContent = appState.currency;
  document.getElementById('billId').value = '';
  // Default start = first day of the current month so this month's entry is included
  document.getElementById('billStartDate').value = billTodayStr().slice(0, 8) + '01';
  document.getElementById('billActive').checked = true;
  document.getElementById('billAutoPost').checked = true;
  document.getElementById('billModalTitle').textContent = 'Add Recurring Bill';

  const billTypeSwitcher = document.getElementById('billTypeSwitcher');
  if (billTypeSwitcher) {
    billTypeSwitcher.style.display = editId ? 'none' : 'flex';
  }
  const btnBillOneTime = document.getElementById('btnBillTypeOneTime');
  const btnBillRecurring = document.getElementById('btnBillTypeRecurring');
  const btnBillPlanned = document.getElementById('btnBillTypePlanned');
  if (btnBillOneTime) btnBillOneTime.classList.remove('active');
  if (btnBillRecurring) btnBillRecurring.classList.add('active');
  if (btnBillPlanned) btnBillPlanned.classList.remove('active');

  if (editId) {
    const bill = (appState.recurringBills || []).find(b => b.id === editId);
    if (bill) {
      document.getElementById('billModalTitle').textContent = 'Edit Recurring Bill';
      document.getElementById('billId').value = bill.id;
      document.getElementById('billName').value = bill.name;
      document.getElementById('billAmount').value = bill.amount;
      if (appState.categories.some(c => c.id === bill.categoryId)) catSelect.value = bill.categoryId;
      document.getElementById('billPaymentMethod').value = bill.paymentMethod || 'Credit Card';
      document.getElementById('billFrequency').value = bill.frequency || 'monthly';
      document.getElementById('billDueDay').value = bill.dueDay || 1;
      document.getElementById('billDueMonth').value = bill.dueMonth || 1;
      document.getElementById('billStartDate').value = bill.startDate || billTodayStr();
      document.getElementById('billActive').checked = bill.active !== false;
      document.getElementById('billAutoPost').checked = bill.autoPost !== false;
      setBillBudgetType(bill.budgetType || getCategoryBudgetType(bill.categoryId));

      const chkInstallment = document.getElementById('billIsInstallment');
      const installFields = document.getElementById('billInstallmentFields');
      const txtInstallTotal = document.getElementById('billInstallmentTotal');
      const txtInstallCurrent = document.getElementById('billInstallmentCurrent');
      const chkExclude = document.getElementById('billExcludeFromBudget');
      if (chkInstallment) chkInstallment.checked = Boolean(bill.isInstallment);
      if (installFields) installFields.style.display = bill.isInstallment ? 'grid' : 'none';
      if (txtInstallTotal) txtInstallTotal.value = bill.installmentTotal || 12;
      if (txtInstallCurrent) txtInstallCurrent.value = bill.installmentCurrent || 1;
      if (chkExclude) chkExclude.checked = Boolean(bill.excludeFromBudget);
    }
  } else {
    const defaultCat = catSelect.value || (appState.categories[0] ? appState.categories[0].id : '');
    setBillBudgetType(getCategoryBudgetType(defaultCat));

    const chkInstallment = document.getElementById('billIsInstallment');
    const installFields = document.getElementById('billInstallmentFields');
    const txtInstallTotal = document.getElementById('billInstallmentTotal');
    const txtInstallCurrent = document.getElementById('billInstallmentCurrent');
    const chkExclude = document.getElementById('billExcludeFromBudget');
    if (chkInstallment) chkInstallment.checked = false;
    if (installFields) installFields.style.display = 'none';
    if (txtInstallTotal) txtInstallTotal.value = 12;
    if (txtInstallCurrent) txtInstallCurrent.value = 1;
    if (chkExclude) chkExclude.checked = false;
  }

  updateBillFormVisibility();
  document.getElementById('billModal').classList.add('active');
}

function closeBillModal() {
  closeModalGracefully('billModal');
}

function handleBillSubmit(e) {
  e.preventDefault();

  const id = document.getElementById('billId').value;
  const name = document.getElementById('billName').value.trim();
  const amount = resolveInputMathValue(document.getElementById('billAmount'));
  const categoryId = document.getElementById('billCategory').value;
  const paymentMethod = document.getElementById('billPaymentMethod').value;
  const frequency = document.getElementById('billFrequency').value;
  const dueDay = Math.min(31, Math.max(1, parseInt(document.getElementById('billDueDay').value, 10) || 1));
  const dueMonth = Math.min(12, Math.max(1, parseInt(document.getElementById('billDueMonth').value, 10) || 1));
  const startDate = document.getElementById('billStartDate').value || billTodayStr();
  const active = document.getElementById('billActive').checked;
  const autoPost = document.getElementById('billAutoPost').checked;
  const budgetType = document.getElementById('billBudgetType')?.value || getCategoryBudgetType(categoryId) || 'needs';

  if (!name || isNaN(amount) || amount <= 0 || !categoryId) {
    showToast('Please enter a name, a valid amount and a category', 'warning');
    return;
  }

  const isInstallment = document.getElementById('billIsInstallment')?.checked || false;
  const installmentTotal = parseInt(document.getElementById('billInstallmentTotal')?.value, 10) || 12;
  const installmentCurrent = parseInt(document.getElementById('billInstallmentCurrent')?.value, 10) || 1;
  const excludeFromBudget = document.getElementById('billExcludeFromBudget')?.checked || false;

  if (id) {
    const idx = appState.recurringBills.findIndex(b => b.id === id);
    if (idx !== -1) {
      appState.recurringBills[idx] = {
        ...appState.recurringBills[idx],
        name, amount, categoryId, paymentMethod, frequency, dueDay, dueMonth, startDate, active, autoPost, budgetType,
        isInstallment, installmentTotal, installmentCurrent, excludeFromBudget
      };
      showToast('Recurring bill updated');
    }
  } else {
    appState.recurringBills.push({
      id: 'bill_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
      name, amount, categoryId, paymentMethod, frequency, dueDay, dueMonth, startDate, active, autoPost, budgetType,
      isInstallment, installmentTotal, installmentCurrent, excludeFromBudget,
      skippedDates: [],
      createdAt: new Date().toISOString()
    });
    showToast('Recurring bill added');
  }

  saveData();
  closeBillModal();
  updateAllViews();
}

// ---------- Bill actions ----------
function createExpenseFromBill(bill, due) {
  let desc = bill.name;
  if (bill.isInstallment && bill.installmentTotal) {
    const cur = bill.installmentCurrent || 1;
    desc = `${bill.name} (${cur}/${bill.installmentTotal})`;
    if (bill.installmentCurrent < bill.installmentTotal) {
      bill.installmentCurrent += 1;
    } else {
      bill.active = false; // Installment completed!
    }
  }
  return {
    // Deterministic id: the same occurrence can never be duplicated (e.g. two devices auto-posting)
    id: 'tx_bill_' + bill.id + '_' + due,
    date: due,
    amount: bill.amount,
    categoryId: bill.categoryId,
    description: desc,
    paymentMethod: bill.paymentMethod || 'Credit Card',
    billId: bill.id,
    billDue: due,
    budgetType: bill.budgetType || getCategoryBudgetType(bill.categoryId) || 'needs',
    excludeFromBudget: Boolean(bill.excludeFromBudget),
    isCreditCardPayoff: Boolean(bill.excludeFromBudget)
  };
}

function postBillOccurrence(billId) {
  const bill = (appState.recurringBills || []).find(b => b.id === billId);
  if (!bill) return;
  if (!appState.categories.some(c => c.id === bill.categoryId)) {
    showToast('This bill\'s category no longer exists. Edit the bill and pick a new category.', 'warning');
    return;
  }
  const st = getBillStatus(bill);
  if (!st.next) return;

  const alertInfo = getOverspendAlert(bill.categoryId, st.next, bill.amount);
  appState.expenses.push(createExpenseFromBill(bill, st.next));
  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();
  showToast(`Posted "${bill.name}" (${formatCurrency(bill.amount)}) dated ${formatShortDate(st.next)}`);
  if (alertInfo) showToast(alertInfo.msg, 'warning', 6500);
}

function skipBillOccurrence(billId) {
  const bill = (appState.recurringBills || []).find(b => b.id === billId);
  if (!bill) return;
  const st = getBillStatus(bill);
  if (!st.next) return;
  if (!confirm(`Skip "${bill.name}" for ${formatShortDate(st.next)}? No expense will be logged.`)) return;
  if (!Array.isArray(bill.skippedDates)) bill.skippedDates = [];
  bill.skippedDates.push(st.next);
  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();
  showToast(`Skipped "${bill.name}" for ${formatShortDate(st.next)}`);
}

function toggleBillActive(billId) {
  const bill = (appState.recurringBills || []).find(b => b.id === billId);
  if (!bill) return;
  bill.active = bill.active === false;
  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();
  showToast(bill.active ? `Resumed "${bill.name}"` : `Paused "${bill.name}"`);
}

function unskipBillOccurrence(billId, due) {
  const bill = (appState.recurringBills || []).find(b => b.id === billId);
  if (!bill || !due || !Array.isArray(bill.skippedDates)) return;
  bill.skippedDates = bill.skippedDates.filter(d => d !== due);
}

// [FEAT-44] Delete recurring bill with 5-second Undo Action Toast
function deleteBill(billId) {
  const billIndex = (appState.recurringBills || []).findIndex(b => b.id === billId);
  if (billIndex === -1) return;
  const bill = appState.recurringBills[billIndex];

  appState.recurringBills.splice(billIndex, 1);
  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();

  showToast(`Deleted recurring bill "${bill.name}"`, 'info', 5500, {
    label: '↩ Undo',
    callback: () => {
      appState.recurringBills.splice(billIndex, 0, bill);
      saveData();
      updateAllViews();
      showToast(`Restored bill "${bill.name}"! ✨`);
    }
  });
}

function postAllDueBills() {
  const today = billTodayStr();
  const toPost = [];
  (appState.recurringBills || []).forEach(bill => {
    if (bill.active === false) return;
    if (!appState.categories.some(c => c.id === bill.categoryId)) return;
    getBillStatus(bill).pending.filter(d => d <= today).forEach(due => toPost.push({ bill, due }));
  });

  if (toPost.length === 0) {
    showToast('No bills are due right now', 'warning');
    return;
  }

  const total = toPost.reduce((s, x) => s + x.bill.amount, 0);
  if (!confirm(`Post ${toPost.length} due ${toPost.length === 1 ? 'bill' : 'bills'} totaling ${formatCurrency(total)} as expenses?`)) return;

  const alerts = [];
  toPost.forEach(({ bill, due }) => {
    const info = getOverspendAlert(bill.categoryId, due, bill.amount);
    if (info) alerts.push(info);
    appState.expenses.push(createExpenseFromBill(bill, due));
  });

  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();
  showToast(`Posted ${toPost.length} ${toPost.length === 1 ? 'bill' : 'bills'} (${formatCurrency(total)})`);
  if (alerts.length > 0) {
    showToast(`⚠️ ${alerts.length} posted ${alerts.length === 1 ? 'bill' : 'bills'} pushed a category to 80%+ of its budget — check the Budget vs Actual page.`, 'warning', 6500);
  }
}

// ---------- Event wiring ----------
function setupBillsEvents() {
  const on = (id, evt, fn) => { const el = document.getElementById(id); if (el) el.addEventListener(evt, fn); };

  on('btnOpenBillModal', 'click', () => openBillModal());
  on('btnEmptyAddBill', 'click', () => openBillModal());
  on('btnCloseBillModal', 'click', closeBillModal);
  on('btnCancelBillModal', 'click', closeBillModal);
  on('billForm', 'submit', handleBillSubmit);
  on('billFrequency', 'change', updateBillFormVisibility);
  on('btnPostAllDueBills', 'click', postAllDueBills);

  // [FEAT-39] Bill Modal Budget Classification Toggle & Category Auto-Preselect
  on('btnBillTypeNeeds', 'click', () => setBillBudgetType('needs'));
  on('btnBillTypeWants', 'click', () => setBillBudgetType('wants'));
  on('billCategory', 'change', (e) => {
    setBillBudgetType(getCategoryBudgetType(e.target.value));
  });

  const modal = document.getElementById('billModal');
  if (modal) modal.addEventListener('click', e => { if (e.target === modal) closeBillModal(); });

  const body = document.getElementById('billsTableBody');
  if (body) {
    body.addEventListener('click', e => {
      const btn = e.target.closest('[data-bill-action]');
      if (!btn || btn.disabled) return;
      const id = btn.getAttribute('data-bill-id');
      switch (btn.getAttribute('data-bill-action')) {
        case 'post': postBillOccurrence(id); break;
        case 'skip': skipBillOccurrence(id); break;
        case 'edit': openBillModal(id); break;
        case 'toggle': toggleBillActive(id); break;
        case 'delete': deleteBill(id); break;
      }
    });
  }

  const strip = document.getElementById('upcomingBillsStrip');
  if (strip) strip.addEventListener('click', () => switchTab('bills'));

  // [FEAT-33] Overspend alert toggle
  on('btnToggleOverspendAlerts', 'click', () => {
    const next = !areOverspendAlertsEnabled();
    setOverspendAlertsEnabled(next);
    showToast(next ? 'Overspend alerts turned on' : 'Overspend alerts turned off');
  });
  updateOverspendToggleUI();

  // [FEAT-37] Recurring Bills Table Interactive Column Sorting
  document.querySelectorAll('#billsTable thead th.sortable-th').forEach(th => {
    th.addEventListener('click', () => {
      const field = th.getAttribute('data-sort');
      if (!field) return;

      if (billsSortState.field === field) {
        billsSortState.order = billsSortState.order === 'asc' ? 'desc' : 'asc';
      } else {
        billsSortState.field = field;
        // Default amount to descending (highest first), others to ascending
        billsSortState.order = (field === 'amount') ? 'desc' : 'asc';
      }
      updateBillsSortHeaders();
      renderBillsTab();
    });
  });

  // [FEAT-37] Recurring Bills Table Filters
  on('billSearchInput', 'input', (e) => {
    billsFilterState.search = e.target.value;
    renderBillsTab();
  });

  on('billFilterStatus', 'change', (e) => {
    billsFilterState.status = e.target.value;
    renderBillsTab();
  });

  on('billFilterCategory', 'change', (e) => {
    billsFilterState.category = e.target.value;
    renderBillsTab();
  });

  on('billFilterFrequency', 'change', (e) => {
    billsFilterState.frequency = e.target.value;
    renderBillsTab();
  });

  on('billFilterAutoPost', 'change', (e) => {
    billsFilterState.autoPost = e.target.value;
    renderBillsTab();
  });

  on('btnResetBillFilters', 'click', resetBillFilters);
}

// ==========================================
// 22. [FEAT-34] AUTO-ADD RECURRING BILLS TO THE EXPENSE TRACKER
// ==========================================
function markBillOccurrenceSkipped(billId, due) {
  const bill = (appState.recurringBills || []).find(b => b.id === billId);
  if (!bill || !due) return;
  if (!Array.isArray(bill.skippedDates)) bill.skippedDates = [];
  if (!bill.skippedDates.includes(due)) bill.skippedDates.push(due);
}

function getBillAutoPostCutoff() {
  const n = new Date();
  const last = new Date(n.getFullYear(), n.getMonth() + 1, 0).getDate();
  return `${n.getFullYear()}-${billPad(n.getMonth() + 1)}-${billPad(last)}`;
}

/** Marks every occurrence up to the end of this month as handled (used by "reset all amounts"). */
function skipAllCurrentBillOccurrences() {
  const cutoff = getBillAutoPostCutoff();
  (appState.recurringBills || []).forEach(bill => {
    getBillDueDates(bill).forEach(due => {
      if (due <= cutoff) markBillOccurrenceSkipped(bill.id, due);
    });
  });
}

/**
 * Adds every unposted occurrence due up to the end of the current month for active,
 * auto-add bills. Safe to call repeatedly: posted/skipped occurrences are never re-added.
 */
function autoPostRecurringBills() {
  const bills = appState.recurringBills;
  if (!Array.isArray(bills) || bills.length === 0) return 0;

  const today = billTodayStr();
  const cutoff = getBillAutoPostCutoff();
  let count = 0;
  let total = 0;
  let alerts = 0;
  let healed = false;

  // Self-heal: remove any prematurely auto-posted expense whose parent bill has not started yet (startDate > today)
  // or whose billDue is earlier than the bill's startDate.
  if (Array.isArray(appState.expenses) && appState.expenses.length > 0) {
    const beforeLen = appState.expenses.length;
    appState.expenses = appState.expenses.filter(exp => {
      if (!exp || !exp.billId || !String(exp.id || '').startsWith('tx_bill_')) return true;
      const parentBill = bills.find(b => b.id === exp.billId);
      if (!parentBill) return true;
      if (parentBill.startDate && parentBill.startDate > today) return false;
      if (parentBill.startDate && exp.billDue && exp.billDue < parentBill.startDate) return false;
      return true;
    });
    if (appState.expenses.length !== beforeLen) {
      healed = true;
    }
  }

  bills.forEach(bill => {
    if (bill.active === false || bill.autoPost === false) return;
    // Never auto-post a bill that is "Not Started Yet" (startDate in the future) into Actual Expenses
    if (bill.startDate && bill.startDate > today) return;
    if (!appState.categories.some(c => c.id === bill.categoryId)) return;

    const dues = getBillDueDates(bill);
    for (let i = 0; i < dues.length; i++) {
      const due = dues[i];
      if (due > cutoff) break;
      if (bill.startDate && due < bill.startDate) continue;
      if (isBillDateSettled(bill, due)) continue;

      // Respect months where the user removed this category's allocation
      const excluded = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[due.slice(0, 7)]) || [];
      if (excluded.includes(bill.categoryId)) continue;

      if (getOverspendAlert(bill.categoryId, due, bill.amount)) alerts++;
      appState.expenses.push(createExpenseFromBill(bill, due));
      count++;
      total += bill.amount;
    }
  });

  if (count > 0 || healed) {
    saveData();
    if (count > 0) {
      showToast(`🔄 Auto-added ${count} recurring ${count === 1 ? 'bill' : 'bills'} to Expense Tracker (${formatCurrency(total)})`);
      if (alerts > 0) {
        showToast(`⚠️ ${alerts} auto-added ${alerts === 1 ? 'bill' : 'bills'} pushed a category to 80%+ of its budget.`, 'warning', 6500);
      }
    }
  }
  return count;
}

// ==========================================
// [FEAT-35] MINIMALIST COLLAPSIBLE KEYBOARD SHORTCUTS GUIDE HUD
// ==========================================
function initMinimalShortcutsGuide() {
  const hud = document.getElementById('shortcutsHud');
  if (!hud) return;

  const pill = document.getElementById('btnShortcutsPill');
  const btnFloatingAiChat = document.getElementById('btnFloatingAiChat');
  const btnMin = document.getElementById('btnHudMinimize');
  const btnCollapseFooter = document.getElementById('btnHudCollapseFooter');
  const btnOpenFaq = document.getElementById('btnHudOpenFaq');

  // Load saved state: default to minimized ('true') for a clean, non-intrusive UI
  const savedState = localStorage.getItem('budgetMasterShortcutsMinimized');
  const isMinimized = savedState !== 'false';
  setShortcutsGuideState(isMinimized);

  if (btnFloatingAiChat) {
    btnFloatingAiChat.addEventListener('click', (e) => {
      e.stopPropagation();
      openFAQModal('ai');
    });
  }

  if (pill) {
    pill.addEventListener('click', (e) => {
      e.stopPropagation();
      setShortcutsGuideState(false);
    });
  }

  if (btnMin) {
    btnMin.addEventListener('click', (e) => {
      e.stopPropagation();
      setShortcutsGuideState(true);
    });
  }

  if (btnCollapseFooter) {
    btnCollapseFooter.addEventListener('click', (e) => {
      e.stopPropagation();
      setShortcutsGuideState(true);
    });
  }

  if (btnOpenFaq) {
    btnOpenFaq.addEventListener('click', (e) => {
      e.stopPropagation();
      openFAQModal();
    });
  }

  // Interactive shortcut clicks: clicking any shortcut item runs its action
  const items = hud.querySelectorAll('.shortcut-item[data-key]');
  items.forEach(item => {
    item.addEventListener('click', () => {
      const key = item.getAttribute('data-key');
      executeShortcutAction(key);
    });
  });
}

function setShortcutsGuideState(minimized) {
  const hud = document.getElementById('shortcutsHud');
  if (!hud) return;
  const pill = document.getElementById('btnShortcutsPill');

  if (minimized) {
    hud.classList.add('is-minimized');
    if (pill) pill.setAttribute('aria-expanded', 'false');
    localStorage.setItem('budgetMasterShortcutsMinimized', 'true');
  } else {
    hud.classList.remove('is-minimized');
    if (pill) pill.setAttribute('aria-expanded', 'true');
    localStorage.setItem('budgetMasterShortcutsMinimized', 'false');
  }
}

