let activeDepositGoalId = null;
let activeDepositMode = 'deposit';
let goalDeleteSnapshot = null;

function getMonthsBetween(fromYM, toYM) {
  if (!fromYM || !toYM) return 0;
  const [y1, m1] = fromYM.split('-').map(Number);
  const [y2, m2] = toYM.split('-').map(Number);
  if (isNaN(y1) || isNaN(m1) || isNaN(y2) || isNaN(m2)) return 0;
  return (y2 - y1) * 12 + (m2 - m1);
}

