  const totalAccumulated = goals.reduce((sum, g) => sum + (parseFloat(g.currentAmount) || 0), 0);
  const overallFundedPct = totalTarget > 0 ? (totalAccumulated / totalTarget) * 100 : 0;
  const activeCount = goals.length;

