function openCommandPalette() {
  if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-48]')) {
    if (typeof showUpgradePrompt === 'function') {
      showUpgradePrompt('[FEAT-48]', 'Universal Spotlight Command Palette (Ctrl+K)');
    }
    return;
  }
  const modal = document.getElementById('commandPaletteModal');
  const input = document.getElementById('commandPaletteInput');
  if (!modal || !input) return;

  commandPaletteState.isOpen = true;
  modal.classList.add('active');
  input.value = '';
  renderCommandPaletteResults('');

  requestAnimationFrame(() => {
    input.focus();
  });
}

function closeCommandPalette() {
  const modal = document.getElementById('commandPaletteModal');
  if (!modal) return;
  commandPaletteState.isOpen = false;
  modal.classList.remove('active');
}

function toggleCommandPalette() {
  if (commandPaletteState.isOpen) {
    closeCommandPalette();
  } else {
    openCommandPalette();
  }
}

