/**
 * [FEAT-ADMIN-CHECK]
 * Checks if the current authenticated user has administrative privileges.
 * Superadmin: nirvash0074@gmail.com or role === 'admin'
 */
function isCurrentUserAdmin() {
  const currentUser = (typeof fbAuth !== 'undefined' && fbAuth && fbAuth.currentUser)
    ? fbAuth.currentUser
    : (typeof currentAuthenticatedUser !== 'undefined' ? currentAuthenticatedUser : null);
  const email = (currentUser && currentUser.email) ? currentUser.email.toLowerCase().trim() : '';
  if (email === 'nirvash0074@gmail.com') return true;

  if (typeof appState !== 'undefined') {
    if (appState.userRole && String(appState.userRole).toLowerCase() === 'admin') return true;
    if (appState.isAdmin === true) return true;
    if (appState.userTier && String(appState.userTier).toLowerCase() === 'admin') return true;
  }
  const storedRole = (typeof localStorage !== 'undefined')
    ? (localStorage.getItem('budgetMaster_userRole') || localStorage.getItem('nirv_userRole') || '')
    : '';
  if (storedRole && storedRole.toLowerCase() === 'admin') return true;
  return false;
}
window.isCurrentUserAdmin = isCurrentUserAdmin;

