/**
 * [FEAT-WIDGET-TIER-GATING]
 * Checks if the current user session is entitled to view or configure a given widget.
 * Non-entitled widgets are automatically hidden from DOM layouts and the Widget Manager.
 * @param {string} widgetId
 * @param {object} [config]
 * @returns {boolean}
 */
function isWidgetEntitled(widgetId, config = null) {
  // Verified Admin always bypasses all tier gating (100% full unlocked access)
  if (typeof isCurrentUserAdmin === 'function' && isCurrentUserAdmin()) return true;

  let currentTier = 'free';
  if (typeof appState !== 'undefined' && appState.userTier) {
    currentTier = String(appState.userTier).toLowerCase().trim();
  } else if (typeof getUserTierStorageKey === 'function') {
    currentTier = (localStorage.getItem(getUserTierStorageKey()) || 'free').toLowerCase().trim();
  } else if (typeof localStorage !== 'undefined') {
    currentTier = (localStorage.getItem('budgetMaster_userTier') || 'free').toLowerCase().trim();
  }

  // Admin and Executive tiers have 100% access to all widgets
  if (currentTier === 'admin' || currentTier === 'executive') return true;

  const cfg = config || (typeof findWidgetConfigById === 'function' ? findWidgetConfigById(widgetId) : null);
  const reqTier = (cfg && (cfg.tier || cfg.requiredTier)) || WIDGET_TIER_REQUIREMENTS[widgetId] || 'free';

  if (reqTier === 'free') return true;

  // If feature tag is present, evaluate via canAccessFeature
  if (cfg && cfg.featureTag && typeof canAccessFeature === 'function') {
    return canAccessFeature(cfg.featureTag);
  }

  // Evaluate via numeric tier level
  const userLevel = (typeof TIER_LEVELS !== 'undefined' && TIER_LEVELS[currentTier]) || 1;
  const reqLevel = (typeof TIER_LEVELS !== 'undefined' && TIER_LEVELS[reqTier])
    ? TIER_LEVELS[reqTier]
    : (reqTier === 'executive' ? 3 : (reqTier === 'pro' ? 2 : 1));
  return userLevel >= reqLevel;
}
window.isWidgetEntitled = isWidgetEntitled;

function findWidgetConfigById(widgetId) {
  if (!widgetId) return null;
  for (const page of Object.keys(PAGE_WIDGET_CONFIGS)) {
    const list = PAGE_WIDGET_CONFIGS[page];
    if (Array.isArray(list)) {
      const found = list.find(w => w.id === widgetId);
      if (found) return found;
    }
  }
  return null;
}
window.findWidgetConfigById = findWidgetConfigById;

