const PAGE_DISPLAY_NAMES = {
  dashboard: 'Dashboard',
  budget: 'Budget',
  expenses: 'Expenses',
  bills: 'Bills',
  analytics: 'Analytics',
  savings: 'Savings',
  forecaster: 'Forecaster Hub'
};

let isCustomLayoutModeActive = false;
let activeModalWidgetTab = 'dashboard';
let draggedLayoutWidgetInfo = null;

/**
 * Automatic DOM Widget Discovery Engine ([FEAT-52]):
 * Scans `#tab-${pageId} [data-widget-id]` and automatically registers any DOM widget
 * that has both `id` and `data-widget-id` into `PAGE_WIDGET_CONFIGS[pageId]`.
 * Ensures any newly created widget in HTML is immediately customizable without manual wiring.
 */
function syncDynamicDomWidgetsToConfig(pageId = 'dashboard') {
  if (!PAGE_WIDGET_CONFIGS[pageId]) {
    PAGE_WIDGET_CONFIGS[pageId] = [];
  }
  const tab = document.getElementById(`tab-${pageId}`);
  if (!tab) return;

  const configs = PAGE_WIDGET_CONFIGS[pageId];
  const domWidgets = tab.querySelectorAll('[data-widget-id]');
  domWidgets.forEach(el => {
    const widgetId = el.getAttribute('data-widget-id');
    const elementId = el.id;
    if (!widgetId || !elementId) return;

    const alreadyRegistered = configs.some(c => c.id === widgetId || c.elementId === elementId);
    if (!alreadyRegistered) {
      const attrName = el.getAttribute('data-widget-name');
      const attrIcon = el.getAttribute('data-widget-icon');
      const attrDesc = el.getAttribute('data-widget-desc');
      const headingEl = el.querySelector('h2, h3, h4, strong');
      const fallbackName = headingEl
        ? headingEl.textContent.replace(/\s+/g, ' ').trim().slice(0, 60)
        : widgetId.replace(/^widget-/, '').replace(/-/g, ' ').replace(/\b\w/g, ch => ch.toUpperCase());

      const attrTier = el.getAttribute('data-widget-tier') || el.getAttribute('data-tier') || (typeof WIDGET_TIER_REQUIREMENTS !== 'undefined' ? WIDGET_TIER_REQUIREMENTS[widgetId] : 'free');
      const attrTag = el.getAttribute('data-feature-tag') || el.getAttribute('data-tag');

      configs.push({
        id: widgetId,
        elementId: elementId,
        name: attrName || fallbackName || 'Custom Workspace Widget',
        icon: attrIcon || '🧩',
        desc: attrDesc || 'Customizable workspace widget module',
        tier: attrTier || 'free',
        featureTag: attrTag || null
      });
    }
  });
}

function ensureWorkspaceLayouts() {
  if (!appState.workspaceLayouts || typeof appState.workspaceLayouts !== 'object') {
    appState.workspaceLayouts = {};
  }
  // Seamless migration from single dashboard layout
  if (appState.workspaceDashboardLayout && !appState.workspaceLayouts.dashboard) {
    appState.workspaceLayouts.dashboard = appState.workspaceDashboardLayout;
  }

  // [FEAT-ADMIN-GLOBAL-LAYOUT] Auto-apply cached or published Universal Default Layouts for users on default view
  try {
    const cachedGlobalStr = localStorage.getItem('nirv_global_default_layouts');
    const cachedMetaStr = localStorage.getItem('nirv_global_default_layouts_meta');
    if (cachedGlobalStr) {
      const cachedLayouts = JSON.parse(cachedGlobalStr);
      const cachedMeta = cachedMetaStr ? JSON.parse(cachedMetaStr) : {};
      const cachedTs = cachedMeta.updatedAt || 'cached_v1';
      const lastAppliedTs = localStorage.getItem('nirv_applied_global_layout_ts');

      if (lastAppliedTs !== cachedTs) {
        let appliedAny = false;
        Object.keys(cachedLayouts).forEach(pId => {
          const isCustomProfile = (typeof getActiveLayoutProfile === 'function') ? !!getActiveLayoutProfile(pId) : false;
          if (!isCustomProfile) {
            appState.workspaceLayouts[pId] = JSON.parse(JSON.stringify(cachedLayouts[pId]));
            if (pId === 'dashboard') {
              appState.workspaceDashboardLayout = appState.workspaceLayouts[pId];
            }
            appliedAny = true;
          }
        });
        localStorage.setItem('nirv_applied_global_layout_ts', cachedTs);
        if (appliedAny && typeof saveData === 'function') {
          saveData();
        }
      }
    }
  } catch (e) {
    console.warn('[LayoutInit] Notice checking cached global layouts:', e);
  }

  // [FEAT-WALLETS-BUDGET-MIGRATION] Seamless migration of Liquid Wallets to Budget tab
  try {
    const WALLETS_MIGRATION_KEY = 'nirv_wallets_on_budget_tab_v65';
    if (!localStorage.getItem(WALLETS_MIGRATION_KEY)) {
      if (appState.workspaceLayouts) {
        if (appState.workspaceLayouts.dashboard && Array.isArray(appState.workspaceLayouts.dashboard.order)) {
          appState.workspaceLayouts.dashboard.order = appState.workspaceLayouts.dashboard.order.filter(id => id !== 'widget-wallets-balance');
          if (appState.workspaceDashboardLayout && Array.isArray(appState.workspaceDashboardLayout.order)) {
            appState.workspaceDashboardLayout.order = appState.workspaceDashboardLayout.order.filter(id => id !== 'widget-wallets-balance');
          }
        }
        if (appState.workspaceLayouts.budget && Array.isArray(appState.workspaceLayouts.budget.order)) {
          if (!appState.workspaceLayouts.budget.order.includes('widget-wallets-balance')) {
            const incIdx = appState.workspaceLayouts.budget.order.indexOf('widget-budget-income');
            if (incIdx !== -1) {
              appState.workspaceLayouts.budget.order.splice(incIdx + 1, 0, 'widget-wallets-balance');
            } else {
              appState.workspaceLayouts.budget.order.unshift('widget-wallets-balance');
            }
            if (appState.workspaceLayouts.budget.sizes) {
              appState.workspaceLayouts.budget.sizes['widget-wallets-balance'] = 'col-12';
            }
          }
        }
        if (typeof saveData === 'function') {
          saveData();
        }
      }
      localStorage.setItem(WALLETS_MIGRATION_KEY, '1');
    }
  } catch (e) {
    console.warn('[LayoutMigration] Notice migrating wallets widget to budget tab:', e);
  }

  // [FEAT-INSIGHTS-DEFAULT-LAYOUT] Auto-upgrade existing users on the Default Layout to the Insights-First Hierarchy
  try {
    const MIGRATION_KEY = 'nirv_insights_default_layout_v62';
    if (!localStorage.getItem(MIGRATION_KEY)) {
      const activeProfId = (appState.activeLayoutProfileIds && appState.activeLayoutProfileIds.dashboard);
      const isCustomProfile = activeProfId && activeProfId !== 'default';
      // Only upgrade if user is on default layout; never overwrite explicit custom named profiles
      if (!isCustomProfile) {
        if (typeof DEFAULT_WORKSPACE_LAYOUTS !== 'undefined' && DEFAULT_WORKSPACE_LAYOUTS.dashboard) {
          appState.workspaceLayouts.dashboard = JSON.parse(JSON.stringify(DEFAULT_WORKSPACE_LAYOUTS.dashboard));
          appState.workspaceDashboardLayout = appState.workspaceLayouts.dashboard;
          if (typeof saveData === 'function') {
            saveData();
          }
        }
      }
      localStorage.setItem(MIGRATION_KEY, '1');
    }
  } catch (e) {
    console.warn('[LayoutMigration] Could not check insights default layout migration:', e);
  }
}

function getPageLayout(pageId = 'dashboard') {
  ensureWorkspaceLayouts();
  syncDynamicDomWidgetsToConfig(pageId);
  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const registeredIds = configs.map(w => w.id);

  // Retrieve factory default layout definition for this page
  const defaultDef = (typeof DEFAULT_WORKSPACE_LAYOUTS !== 'undefined' && DEFAULT_WORKSPACE_LAYOUTS[pageId])
    ? JSON.parse(JSON.stringify(DEFAULT_WORKSPACE_LAYOUTS[pageId]))
    : { order: registeredIds, hidden: [], sizes: {}, fonts: {}, stacks: {} };

  const defaultOrder = Array.isArray(defaultDef.order) ? [...defaultDef.order] : [...registeredIds];
  // Ensure any newly discovered DOM widgets not in defaultDef are appended
  registeredIds.forEach(id => {
    if (!defaultOrder.includes(id)) defaultOrder.push(id);
  });

  const pageLayout = appState.workspaceLayouts[pageId];
  if (pageLayout && Array.isArray(pageLayout.order)) {
    const currentOrder = [...pageLayout.order];
    // Ensure newly introduced widgets are appended
    defaultOrder.forEach(id => {
      if (!currentOrder.includes(id)) currentOrder.push(id);
    });
    // Filter out any stale IDs that no longer exist
    const validOrder = currentOrder.filter(id => defaultOrder.includes(id));
    const hidden = Array.isArray(pageLayout.hidden)
      ? pageLayout.hidden.filter(id => defaultOrder.includes(id))
      : [];
    const sizes = (pageLayout.sizes && typeof pageLayout.sizes === 'object') ? { ...pageLayout.sizes } : {};
    // Backfill with factory default sizes if not explicitly overridden by user
    if (defaultDef.sizes) {
      Object.keys(defaultDef.sizes).forEach(wId => {
        if (!sizes[wId] && defaultOrder.includes(wId)) {
          sizes[wId] = defaultDef.sizes[wId];
        }
      });
    }
    const fonts = (pageLayout.fonts && typeof pageLayout.fonts === 'object') ? { ...pageLayout.fonts } : {};
    const stacks = (pageLayout.stacks && typeof pageLayout.stacks === 'object') ? JSON.parse(JSON.stringify(pageLayout.stacks)) : {};
    return { order: validOrder, hidden: hidden, sizes: sizes, fonts: fonts, stacks: stacks };
  }
  return {
    order: defaultOrder,
    hidden: Array.isArray(defaultDef.hidden) ? [...defaultDef.hidden] : [],
    sizes: (defaultDef.sizes && typeof defaultDef.sizes === 'object') ? { ...defaultDef.sizes } : {},
    fonts: (defaultDef.fonts && typeof defaultDef.fonts === 'object') ? { ...defaultDef.fonts } : {},
    stacks: (defaultDef.stacks && typeof defaultDef.stacks === 'object') ? JSON.parse(JSON.stringify(defaultDef.stacks)) : {}
  };
}

function getWorkspaceDashboardLayout() {
  return getPageLayout('dashboard');
}

function getWidgetStackInfo(pageId, widgetId) {
  const layout = getPageLayout(pageId);
  const stacks = layout.stacks || {};
  for (const [anchorId, members] of Object.entries(stacks)) {
    if (Array.isArray(members) && members.includes(widgetId)) {
      return { anchorId, members, isAnchor: anchorId === widgetId };
    }
  }
  return null;
}

function applyPageLayout(pageId) {
  syncDynamicDomWidgetsToConfig(pageId);
  const configs = PAGE_WIDGET_CONFIGS[pageId];
  if (!configs) return;

  const tab = document.getElementById(`tab-${pageId}`);
  if (!tab) return;

  const layout = getPageLayout(pageId);
  const hiddenSet = new Set(layout.hidden);
  const sizes = layout.sizes || {};
  const fonts = layout.fonts || {};
  const stacks = layout.stacks || {};

  // Preserve sticky/top header panels (e.g. .section-header-panel) at top of tab
  const headerPanel = tab.querySelector('.section-header-panel');
  if (headerPanel && headerPanel.parentNode === tab) {
    tab.insertBefore(headerPanel, tab.firstChild);
  }

  // Remove existing .widget-column-stack wrappers and re-attach children cleanly to avoid nesting leaks
  tab.querySelectorAll('.widget-column-stack').forEach(wrapper => {
    while (wrapper.firstChild) {
      if (wrapper.firstChild.classList && wrapper.firstChild.classList.contains('widget-stack-drop-slot')) {
        wrapper.removeChild(wrapper.firstChild);
      } else {
        tab.appendChild(wrapper.firstChild);
      }
    }
    wrapper.remove();
  });
  tab.querySelectorAll('.widget-stack-drop-slot').forEach(s => s.remove());

  // Map stacked secondary members to anchor ID
  const memberToAnchor = {};
  Object.entries(stacks).forEach(([anchorId, members]) => {
    if (Array.isArray(members) && members.length > 1) {
      members.forEach((mId, mIdx) => {
        if (mIdx > 0) memberToAnchor[mId] = anchorId;
      });
    }
  });

  // Position each widget according to the saved layout order within its parent container
  layout.order.forEach((widgetId, index) => {
    const config = configs.find(w => w.id === widgetId);
    if (!config) return;
    const el = document.getElementById(config.elementId);
    if (!el) return;

    // Apply or remove hidden class
    if (hiddenSet.has(widgetId)) {
      el.classList.add('layout-widget-hidden');
    } else {
      el.classList.remove('layout-widget-hidden');
    }

    // [FEAT-WIDGET-TIER-GATING] Check subscription tier entitlement
    const isEntitled = (typeof isWidgetEntitled === 'function') ? isWidgetEntitled(widgetId, config) : true;
    if (!isEntitled) {
      el.classList.add('widget-tier-hidden');
    } else {
      el.classList.remove('widget-tier-hidden');
    }

    // [FEAT-MODULAR-WIDGET-SIZING] Apply modular width classes (col-4, col-6, col-8, col-12)
    el.classList.remove('widget-size-4', 'widget-size-6', 'widget-size-8', 'widget-size-12');
    const size = sizes[widgetId] || 'col-12';
    el.setAttribute('data-widget-size', size);
    if (size === 'col-4') el.classList.add('widget-size-4');
    else if (size === 'col-6') el.classList.add('widget-size-6');
    else if (size === 'col-8') el.classList.add('widget-size-8');
    else el.classList.add('widget-size-12');

    // [FEAT-MODULAR-WIDGET-SIZING] Apply per-widget font size class (sm, md, lg)
    el.classList.remove('widget-font-sm', 'widget-font-md', 'widget-font-lg');
    const font = fonts[widgetId] || 'md';
    el.setAttribute('data-widget-font', font);
    if (font === 'sm') el.classList.add('widget-font-sm');
    else if (font === 'lg') el.classList.add('widget-font-lg');
    else el.classList.add('widget-font-md');

    // [FEAT-WIDGET-COLUMN-STACK] Wrap stacked widgets inside .widget-column-stack
    const isAnchor = stacks[widgetId] && Array.isArray(stacks[widgetId]) && stacks[widgetId].length > 1;
    const isSecondaryMember = !!memberToAnchor[widgetId];
    const isInStack = isAnchor || isSecondaryMember;

    if (isAnchor) {
      let stackWrapper = tab.querySelector(`.widget-column-stack[data-stack-anchor="${widgetId}"]`);
      if (!stackWrapper) {
        stackWrapper = document.createElement('div');
        const colSize = size === 'col-4' ? 'widget-size-4' : (size === 'col-8' ? 'widget-size-8' : 'widget-size-6');
        stackWrapper.className = `widget-column-stack ${colSize}`;
        stackWrapper.setAttribute('data-stack-anchor', widgetId);
        tab.appendChild(stackWrapper);
      }
      stackWrapper.appendChild(el);
    } else if (isSecondaryMember) {
      const anchorId = memberToAnchor[widgetId];
      let stackWrapper = tab.querySelector(`.widget-column-stack[data-stack-anchor="${anchorId}"]`);
      if (!stackWrapper) {
        stackWrapper = document.createElement('div');
        const anchorSize = sizes[anchorId] || 'col-6';
        const colSize = anchorSize === 'col-4' ? 'widget-size-4' : (anchorSize === 'col-8' ? 'widget-size-8' : 'widget-size-6');
        stackWrapper.className = `widget-column-stack ${colSize}`;
        stackWrapper.setAttribute('data-stack-anchor', anchorId);
        tab.appendChild(stackWrapper);
      }
      stackWrapper.appendChild(el);
    } else {
      const parentContainer = el.parentElement || tab;
      if (parentContainer !== tab && !parentContainer.classList.contains('widget-column-stack')) {
        parentContainer.appendChild(el);
      } else {
        tab.appendChild(el);
      }
    }

    // Ensure mini-toolbar exists for layout mode
    ensureWidgetLayoutToolbar(el, pageId, widgetId, index + 1, layout.order.length, hiddenSet.has(widgetId), size, font, isInStack);
  });

  // [FEAT-WIDGET-COLUMN-STACK] Cleanup empty stack wrappers where all children are tier-hidden or layout-hidden
  tab.querySelectorAll('.widget-column-stack').forEach(wrapper => {
    const visibleChildren = Array.from(wrapper.children).filter(child => {
      if (child.classList.contains('widget-stack-drop-slot')) return false;
      if (child.classList.contains('widget-tier-hidden')) return false;
      if (child.classList.contains('layout-widget-hidden')) return false;
      return true;
    });
    if (visibleChildren.length === 0) {
      wrapper.style.display = 'none';
    } else {
      wrapper.style.display = '';
    }
  });

  // In Layout Mode: Render visual stack drop slots under half-width cards & column stacks
  if (isCustomLayoutModeActive && document.body.classList.contains('layout-mode-active')) {
    renderStackDropSlots(pageId, tab);
    renderBesideDropSlots(pageId, tab);
  } else {
    // Strictly purge all layout helper slots when not in layout mode
    tab.querySelectorAll('.widget-beside-drop-slot, .widget-stack-drop-slot').forEach(s => s.remove());
  }

  // Trigger chart reflow if needed
  if (pageId === 'dashboard' || pageId === 'forecaster' || pageId === 'analytics') {
    setTimeout(resizeAllDashboardCharts, 50);
  }

  // Keep studio dock title and workspace meta in sync
  updateLayoutStudioDockTitle(appState.activeTab || pageId);
}

/* [FEAT-WIDGET-COLUMN-STACK] Render Visual Stack Drop Slots in Layout Mode */
function renderStackDropSlots(pageId, tab) {
  tab.querySelectorAll('.widget-stack-drop-slot').forEach(s => s.remove());
  if (!isCustomLayoutModeActive || !document.body.classList.contains('layout-mode-active')) return;

  const layout = getPageLayout(pageId);
  const hiddenSet = new Set(layout.hidden);
  const sizes = layout.sizes || {};
  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];

  layout.order.forEach(widgetId => {
    if (hiddenSet.has(widgetId)) return;
    const size = sizes[widgetId] || 'col-12';
    if (size !== 'col-6' && size !== 'col-4') return;

    const cfg = configs.find(w => w.id === widgetId);
    if (typeof isWidgetEntitled === 'function' && !isWidgetEntitled(widgetId, cfg)) return;
    const widgetName = cfg ? cfg.name : widgetId;
    const el = document.getElementById(cfg ? cfg.elementId : widgetId) || tab.querySelector(`[data-widget-id="${widgetId}"]`);
    if (!el || el.offsetParent === null || el.classList.contains('layout-widget-hidden') || el.classList.contains('widget-tier-hidden') || el.style.display === 'none') return;

    const parentStack = el.closest('.widget-column-stack');
    if (parentStack) {
      if (parentStack.querySelector('.widget-stack-drop-slot')) return;
      const slot = createDropSlotElement(pageId, widgetId, `➕ Drop widget here to stack in this column`);
      parentStack.appendChild(slot);
      return;
    }

    // If standalone col-6 widget without stack below it:
    const slot = createDropSlotElement(pageId, widgetId, `➕ Drop widget here to stack under ${widgetName}`);
    el.insertAdjacentElement('afterend', slot);
  });
}

function createDropSlotElement(pageId, targetWidgetId, labelText) {
  const slot = document.createElement('div');
  slot.className = 'widget-stack-drop-slot';
  slot.setAttribute('data-stack-target', targetWidgetId);
  slot.innerHTML = `
    <span style="font-size: 1.15rem;">⬇️</span>
    <span>${labelText}</span>
  `;

  slot.addEventListener('dragover', (e) => {
    if (!isCustomLayoutModeActive || !draggedLayoutWidgetInfo || draggedLayoutWidgetInfo.pageId !== pageId) return;
    if (draggedLayoutWidgetInfo.widgetId === targetWidgetId) return;
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
    slot.classList.add('slot-hover');
  });

  slot.addEventListener('dragleave', () => {
    slot.classList.remove('slot-hover');
  });

  slot.addEventListener('drop', (e) => {
    slot.classList.remove('slot-hover');
    if (!isCustomLayoutModeActive || !draggedLayoutWidgetInfo || draggedLayoutWidgetInfo.pageId !== pageId) return;
    e.preventDefault();
    e.stopPropagation();
    const sourceWidgetId = draggedLayoutWidgetInfo.widgetId;
    draggedLayoutWidgetInfo = null;
    stackWidgetUnder(pageId, sourceWidgetId, targetWidgetId);
  });

  slot.addEventListener('click', () => {
    openWidgetPairPickerModal(pageId, targetWidgetId, 'stack');
  });

  return slot;
}

/* [FEAT-GHOST-BESIDE-SLOTS] Render Visual Companion Drop Slots Beside Unpaired 50% Cards */
function renderBesideDropSlots(pageId, tab) {
  tab.querySelectorAll('.widget-beside-drop-slot').forEach(s => s.remove());
  if (!isCustomLayoutModeActive || !document.body.classList.contains('layout-mode-active')) return;

  const layout = getPageLayout(pageId);
  const hiddenSet = new Set(layout.hidden);
  const sizes = layout.sizes || {};
  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];

  // Filter visible widgets and ensure element actually exists and is visibly rendered in DOM
  const visibleWidgets = layout.order.filter(wId => {
    if (hiddenSet.has(wId)) return false;
    const cfg = configs.find(w => w.id === wId);
    if (!cfg) return true;
    if (typeof isWidgetEntitled === 'function' && !isWidgetEntitled(wId, cfg)) return false;
    const el = document.getElementById(cfg.elementId);
    if (el && (el.offsetParent === null || el.classList.contains('layout-widget-hidden') || el.classList.contains('widget-tier-hidden') || el.style.display === 'none')) {
      return false;
    }
    return true;
  });

  // Trace column grid sum to detect incomplete rows (e.g. 6/12 columns taken)
  let rowSpan = 0;
  visibleWidgets.forEach((wId, i) => {
    const sz = sizes[wId] || 'col-12';
    const span = sz === 'col-4' ? 4 : (sz === 'col-6' ? 6 : (sz === 'col-8' ? 8 : 12));
    rowSpan += span;
    if (rowSpan % 12 === 6) {
      const nextId = visibleWidgets[i + 1];
      const nextSpan = nextId ? ((sizes[nextId] || 'col-12') === 'col-6' ? 6 : 12) : 0;
      if (nextSpan !== 6) {
        const cfg = configs.find(w => w.id === wId);
        if (cfg) {
          const el = document.getElementById(cfg.elementId);
          if (el && el.parentNode && el.offsetParent !== null && !el.classList.contains('layout-widget-hidden') && el.style.display !== 'none') {
            const besideSlot = document.createElement('div');
            besideSlot.className = 'widget-beside-drop-slot';
            besideSlot.innerHTML = `
              <div class="slot-title"><span>◨</span> + Place Widget Beside</div>
              <div class="slot-hint">Drag any card here or click to pick from list (50% / 50%)</div>
            `;
            besideSlot.addEventListener('dragover', (e) => {
              if (!isCustomLayoutModeActive || !draggedLayoutWidgetInfo || draggedLayoutWidgetInfo.pageId !== pageId) return;
              if (draggedLayoutWidgetInfo.widgetId === wId) return;
              e.preventDefault();
              if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
              besideSlot.classList.add('slot-hover');
            });
            besideSlot.addEventListener('dragleave', () => {
              besideSlot.classList.remove('slot-hover');
            });
            besideSlot.addEventListener('drop', (e) => {
              besideSlot.classList.remove('slot-hover');
              if (!isCustomLayoutModeActive || !draggedLayoutWidgetInfo || draggedLayoutWidgetInfo.pageId !== pageId) return;
              e.preventDefault();
              e.stopPropagation();
              const sourceWidgetId = draggedLayoutWidgetInfo.widgetId;
              draggedLayoutWidgetInfo = null;
              reorderPageWidgetToTarget(pageId, sourceWidgetId, wId, 'right');
            });
            besideSlot.addEventListener('click', () => {
              openWidgetPairPickerModal(pageId, wId, 'side');
            });

            const refEl = el.closest('.widget-column-stack') || el;
            if (refEl.nextSibling) {
              refEl.parentNode.insertBefore(besideSlot, refEl.nextSibling);
            } else {
              refEl.parentNode.appendChild(besideSlot);
            }
          }
        }
      }
    }
    if (rowSpan >= 12) rowSpan = 0;
  });
}

/* [FEAT-WIDGET-COLUMN-STACK] Stack Source Widget Vertically Under Target Widget */
function stackWidgetUnder(pageId, sourceWidgetId, targetWidgetId) {
  if (!sourceWidgetId || !targetWidgetId || sourceWidgetId === targetWidgetId) return;

  ensureWorkspaceLayouts();
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  const stacks = layout.stacks || {};

  // Find if targetWidgetId is an anchor or a member of an existing stack
  let anchorId = targetWidgetId;
  for (const [aId, members] of Object.entries(stacks)) {
    if (Array.isArray(members) && members.includes(targetWidgetId)) {
      anchorId = aId;
      break;
    }
  }

  // Remove sourceWidgetId from any existing stack
  for (const [aId, members] of Object.entries(stacks)) {
    if (Array.isArray(members) && members.includes(sourceWidgetId)) {
      stacks[aId] = members.filter(id => id !== sourceWidgetId);
      if (stacks[aId].length <= 1) delete stacks[aId];
    }
  }

  // Initialize stack if not present
  if (!stacks[anchorId]) {
    stacks[anchorId] = [anchorId];
  }

  // Append sourceWidgetId after targetWidgetId in stack
  const tgtIdx = stacks[anchorId].indexOf(targetWidgetId);
  if (tgtIdx !== -1) {
    stacks[anchorId].splice(tgtIdx + 1, 0, sourceWidgetId);
  } else {
    stacks[anchorId].push(sourceWidgetId);
  }

  // Position sourceWidgetId right after targetWidgetId in layout.order
  const fromOrderIdx = layout.order.indexOf(sourceWidgetId);
  if (fromOrderIdx !== -1) layout.order.splice(fromOrderIdx, 1);
  const toOrderIdx = layout.order.indexOf(targetWidgetId);
  layout.order.splice(toOrderIdx + 1, 0, sourceWidgetId);

  // Set widths
  if (!layout.sizes) layout.sizes = {};
  if (!layout.sizes[anchorId] || layout.sizes[anchorId] === 'col-12') {
    layout.sizes[anchorId] = 'col-6';
  }
  layout.sizes[sourceWidgetId] = layout.sizes[anchorId];

  appState.workspaceLayouts[pageId] = {
    order: layout.order,
    hidden: layout.hidden,
    sizes: layout.sizes,
    fonts: layout.fonts || {},
    stacks: stacks
  };

  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const srcCfg = configs.find(w => w.id === sourceWidgetId);
  const tgtCfg = configs.find(w => w.id === targetWidgetId);
  const srcName = srcCfg ? srcCfg.name : sourceWidgetId;
  const tgtName = tgtCfg ? tgtCfg.name : targetWidgetId;
  showToast(`Stacked "${srcName}" under "${tgtName}" side-by-side! ◧✨`, 'success');
}

/* [FEAT-WIDGET-COLUMN-STACK] Stack Source Widget Vertically Above Target Widget */
function stackWidgetAbove(pageId, sourceWidgetId, targetWidgetId) {
  if (!sourceWidgetId || !targetWidgetId || sourceWidgetId === targetWidgetId) return;

  ensureWorkspaceLayouts();
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  const stacks = layout.stacks || {};

  let anchorId = targetWidgetId;
  for (const [aId, members] of Object.entries(stacks)) {
    if (Array.isArray(members) && members.includes(targetWidgetId)) {
      anchorId = aId;
      break;
    }
  }

  for (const [aId, members] of Object.entries(stacks)) {
    if (Array.isArray(members) && members.includes(sourceWidgetId)) {
      stacks[aId] = members.filter(id => id !== sourceWidgetId);
      if (stacks[aId].length <= 1) delete stacks[aId];
    }
  }

  if (!stacks[anchorId]) {
    stacks[anchorId] = [anchorId];
  }

  const tgtIdx = stacks[anchorId].indexOf(targetWidgetId);
  if (tgtIdx !== -1) {
    stacks[anchorId].splice(tgtIdx, 0, sourceWidgetId);
  } else {
    stacks[anchorId].unshift(sourceWidgetId);
  }

  const fromOrderIdx = layout.order.indexOf(sourceWidgetId);
  if (fromOrderIdx !== -1) layout.order.splice(fromOrderIdx, 1);
  const toOrderIdx = layout.order.indexOf(targetWidgetId);
  layout.order.splice(toOrderIdx, 0, sourceWidgetId);

  if (!layout.sizes) layout.sizes = {};
  if (!layout.sizes[anchorId] || layout.sizes[anchorId] === 'col-12') {
    layout.sizes[anchorId] = 'col-6';
  }
  layout.sizes[sourceWidgetId] = layout.sizes[anchorId];

  appState.workspaceLayouts[pageId] = {
    order: layout.order,
    hidden: layout.hidden,
    sizes: layout.sizes,
    fonts: layout.fonts || {},
    stacks: stacks
  };

  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const srcCfg = configs.find(w => w.id === sourceWidgetId);
  const tgtCfg = configs.find(w => w.id === targetWidgetId);
  const srcName = srcCfg ? srcCfg.name : sourceWidgetId;
  const tgtName = tgtCfg ? tgtCfg.name : targetWidgetId;
  showToast(`Stacked "${srcName}" above "${tgtName}" side-by-side! ◧✨`, 'success');
}

/* [FEAT-WIDGET-COLUMN-STACK] Unstack Widget from Column Stack */
function unstackWidget(pageId, widgetId) {
  ensureWorkspaceLayouts();
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  const stacks = layout.stacks || {};

  for (const [anchorId, members] of Object.entries(stacks)) {
    if (Array.isArray(members) && members.includes(widgetId)) {
      stacks[anchorId] = members.filter(id => id !== widgetId);
      if (stacks[anchorId].length <= 1) delete stacks[anchorId];
    }
  }

  appState.workspaceLayouts[pageId] = {
    order: layout.order,
    hidden: layout.hidden,
    sizes: layout.sizes || {},
    fonts: layout.fonts || {},
    stacks: stacks
  };

  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const cfg = configs.find(w => w.id === widgetId);
  showToast(`Unstacked "${cfg ? cfg.name : widgetId}"!`, 'info');
}

/* [FEAT-WIDGET-COLUMN-STACK] 1-Click Stack Next Candidate Under this Widget */
function stackNextWidgetUnder(pageId, widgetId) {
  ensureWorkspaceLayouts();
  const layout = getPageLayout(pageId);
  const hiddenSet = new Set(layout.hidden);
  const visibleOrder = layout.order.filter(id => !hiddenSet.has(id));
  const idx = visibleOrder.indexOf(widgetId);

  const stackInfo = getWidgetStackInfo(pageId, widgetId);
  const currentMembers = stackInfo ? stackInfo.members : [widgetId];
  let candidateId = null;

  for (let i = idx + 1; i < visibleOrder.length; i++) {
    if (!currentMembers.includes(visibleOrder[i])) {
      candidateId = visibleOrder[i];
      break;
    }
  }

  if (!candidateId) {
    for (let i = idx - 1; i >= 0; i--) {
      if (!currentMembers.includes(visibleOrder[i])) {
        candidateId = visibleOrder[i];
        break;
      }
    }
  }

  if (!candidateId) {
    showToast('No other visible widgets available to stack!', 'warning');
    return;
  }

  stackWidgetUnder(pageId, candidateId, widgetId);
}

function applyAllPageLayouts() {
  Object.keys(PAGE_WIDGET_CONFIGS).forEach(pageId => {
    applyPageLayout(pageId);
  });
}

function applyDashboardLayout() {
  applyPageLayout('dashboard');
}

/* [UX-LAYOUT-UNDO] Layout Snapshot History Stack & Undo Controller */
const layoutHistoryStack = {
  dashboard: [],
  budget: [],
  expenses: [],
  bills: [],
  analytics: [],
  savings: [],
  forecaster: []
};

function pushLayoutHistory(pageId) {
  if (!layoutHistoryStack[pageId]) layoutHistoryStack[pageId] = [];
  const layout = getPageLayout(pageId);
  const snapshot = {
    order: [...layout.order],
    hidden: [...layout.hidden],
    sizes: { ...(layout.sizes || {}) },
    fonts: { ...(layout.fonts || {}) },
    stacks: JSON.parse(JSON.stringify(layout.stacks || {}))
  };
  layoutHistoryStack[pageId].push(snapshot);
  if (layoutHistoryStack[pageId].length > 20) layoutHistoryStack[pageId].shift();

  const undoBtn = document.getElementById('btnLayoutUndo');
  if (undoBtn) undoBtn.disabled = false;
}

function undoLastLayoutChange(pageId = null) {
  const targetPage = pageId || appState.activeTab || 'dashboard';
  if (!layoutHistoryStack[targetPage] || layoutHistoryStack[targetPage].length === 0) {
    showToast('Nothing to undo in layout.', 'info');
    return;
  }
  const prevSnapshot = layoutHistoryStack[targetPage].pop();
  ensureWorkspaceLayouts();
  appState.workspaceLayouts[targetPage] = prevSnapshot;
  if (targetPage === 'dashboard') {
    appState.workspaceDashboardLayout = prevSnapshot;
  }
  applyPageLayout(targetPage);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(targetPage);
  }

  const undoBtn = document.getElementById('btnLayoutUndo');
  if (undoBtn) undoBtn.disabled = layoutHistoryStack[targetPage].length === 0;

  showToast('↩️ Reverted last layout change!', 'success');
}

/* [FEAT-SIDE-BY-SIDE-DRAG] Smart Reorder & Side-by-Side Snapping Engine */
function reorderPageWidgetToTarget(pageId, draggedWidgetId, targetWidgetId, side = 'center') {
  if (!draggedWidgetId || !targetWidgetId || draggedWidgetId === targetWidgetId) return;
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  const fromIdx = layout.order.indexOf(draggedWidgetId);
  if (fromIdx === -1) return;

  // Remove dragged widget from current position
  layout.order.splice(fromIdx, 1);

  // If targetWidgetId is part of a stack, find the anchor and member list
  const stacks = layout.stacks || {};
  let targetAnchor = targetWidgetId;
  let targetStackMembers = null;
  for (const [aId, members] of Object.entries(stacks)) {
    if (Array.isArray(members) && members.includes(targetWidgetId)) {
      targetAnchor = aId;
      targetStackMembers = members;
      break;
    }
  }

  if (side === 'left') {
    // Insert immediately BEFORE target stack anchor so dragged widget is placed on the LEFT of the stack
    const anchorIdx = layout.order.indexOf(targetAnchor);
    const insertIdx = anchorIdx !== -1 ? anchorIdx : layout.order.indexOf(targetWidgetId);
    layout.order.splice(insertIdx, 0, draggedWidgetId);
  } else if (side === 'right') {
    // Insert immediately AFTER target stack's last member so dragged widget is placed on the RIGHT of the stack
    let lastMember = targetWidgetId;
    if (targetStackMembers && targetStackMembers.length > 0) {
      lastMember = targetStackMembers[targetStackMembers.length - 1];
    }
    const lastMemberIdx = layout.order.indexOf(lastMember);
    const insertIdx = lastMemberIdx !== -1 ? lastMemberIdx + 1 : layout.order.indexOf(targetWidgetId) + 1;
    layout.order.splice(insertIdx, 0, draggedWidgetId);
  } else {
    const toIdx = layout.order.indexOf(targetWidgetId);
    layout.order.splice(toIdx, 0, draggedWidgetId);
  }

  // If draggedWidgetId was in a stack, clean it up
  for (const [aId, members] of Object.entries(stacks)) {
    if (Array.isArray(members) && members.includes(draggedWidgetId)) {
      stacks[aId] = members.filter(id => id !== draggedWidgetId);
      if (stacks[aId].length <= 1) delete stacks[aId];
    }
  }

  ensureWorkspaceLayouts();
  if (!appState.workspaceLayouts[pageId]) {
    appState.workspaceLayouts[pageId] = {
      order: layout.order,
      hidden: layout.hidden,
      sizes: layout.sizes || {},
      fonts: layout.fonts || {},
      stacks: stacks
    };
  } else {
    appState.workspaceLayouts[pageId].order = layout.order;
    appState.workspaceLayouts[pageId].hidden = layout.hidden;
    if (!appState.workspaceLayouts[pageId].sizes) {
      appState.workspaceLayouts[pageId].sizes = layout.sizes || {};
    }
    if (!appState.workspaceLayouts[pageId].fonts) {
      appState.workspaceLayouts[pageId].fonts = layout.fonts || {};
    }
    appState.workspaceLayouts[pageId].stacks = stacks;
  }

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const srcCfg = configs.find(w => w.id === draggedWidgetId);
  const tgtCfg = configs.find(w => w.id === targetWidgetId);
  const srcName = srcCfg ? srcCfg.name : draggedWidgetId;
  const tgtName = tgtCfg ? tgtCfg.name : targetWidgetId;
  let toastMsg = '';

  if (side === 'left' || side === 'right') {
    appState.workspaceLayouts[pageId].sizes[draggedWidgetId] = 'col-6';
    appState.workspaceLayouts[pageId].sizes[targetWidgetId] = 'col-6';
    if (targetAnchor && targetAnchor !== targetWidgetId) {
      appState.workspaceLayouts[pageId].sizes[targetAnchor] = 'col-6';
    }
    toastMsg = side === 'left'
      ? `Snapped "${srcName}" (Left) and "${tgtName}" (Right) side-by-side (50% / 50%)! ✨`
      : `Snapped "${tgtName}" (Left) and "${srcName}" (Right) side-by-side (50% / 50%)! ✨`;
  } else {
    const finalIdx = layout.order.indexOf(draggedWidgetId);
    toastMsg = `Moved "${srcName}" to position #${finalIdx + 1}!`;
  }

  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  showToast(toastMsg, side !== 'center' ? 'success' : 'info');
}

/* [FEAT-SIDE-BY-SIDE-DRAG] 1-Click Pair Widget Side-by-Side (50% / 50%) on Left or Right */
function pairWidgetSideBySide(pageId, widgetId, side = 'right') {
  ensureWorkspaceLayouts();
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const srcCfg = configs.find(w => w.id === widgetId);
  const srcName = srcCfg ? srcCfg.name : widgetId;

  const hiddenSet = new Set(layout.hidden);
  const visibleOrder = layout.order.filter(id => !hiddenSet.has(id));
  const idx = visibleOrder.indexOf(widgetId);
  let partnerId = null;

  if (side === 'left') {
    if (idx > 0) partnerId = visibleOrder[idx - 1];
    else if (idx < visibleOrder.length - 1) partnerId = visibleOrder[idx + 1];
  } else {
    if (idx < visibleOrder.length - 1) partnerId = visibleOrder[idx + 1];
    else if (idx > 0) partnerId = visibleOrder[idx - 1];
  }

  if (!partnerId) {
    setWidgetSize(pageId, widgetId, 'col-6');
    return;
  }

  const partnerCfg = configs.find(w => w.id === partnerId);
  const partnerName = partnerCfg ? partnerCfg.name : partnerId;

  if (!appState.workspaceLayouts[pageId]) {
    appState.workspaceLayouts[pageId] = {
      order: layout.order,
      hidden: layout.hidden,
      sizes: layout.sizes || {},
      fonts: layout.fonts || {},
      stacks: layout.stacks || {}
    };
  }
  if (!appState.workspaceLayouts[pageId].sizes) {
    appState.workspaceLayouts[pageId].sizes = {};
  }

  appState.workspaceLayouts[pageId].sizes[widgetId] = 'col-6';
  appState.workspaceLayouts[pageId].sizes[partnerId] = 'col-6';

  if (side === 'left') {
    const fromIdx = layout.order.indexOf(partnerId);
    layout.order.splice(fromIdx, 1);
    const toIdx = layout.order.indexOf(widgetId);
    layout.order.splice(toIdx, 0, partnerId);
  } else {
    const fromIdx = layout.order.indexOf(partnerId);
    layout.order.splice(fromIdx, 1);
    const toIdx = layout.order.indexOf(widgetId);
    layout.order.splice(toIdx + 1, 0, partnerId);
  }
  appState.workspaceLayouts[pageId].order = layout.order;

  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const toastMsg = side === 'left'
    ? `Snapped "${partnerName}" (Left) and "${srcName}" (Right) side-by-side (50% / 50%)! ✨`
    : `Snapped "${srcName}" (Left) and "${partnerName}" (Right) side-by-side (50% / 50%)! ✨`;
  showToast(toastMsg, 'success');
}

function pairWidgetWithAdjacent(pageId, widgetId) {
  pairWidgetSideBySide(pageId, widgetId, 'right');
}

/* [UX-SWAP-SIDES-ACTION] Swap Positions of Side-by-Side Widgets */
function swapSideBySideWidgets(pageId, widgetId) {
  ensureWorkspaceLayouts();
  const layout = getPageLayout(pageId);
  const hiddenSet = new Set(layout.hidden);
  const visibleOrder = layout.order.filter(id => !hiddenSet.has(id));
  const idx = visibleOrder.indexOf(widgetId);
  if (idx === -1) return;

  const sizes = layout.sizes || {};
  let partnerId = null;

  if (idx < visibleOrder.length - 1 && (sizes[visibleOrder[idx + 1]] === 'col-6' || sizes[visibleOrder[idx + 1]] === 'col-4')) {
    partnerId = visibleOrder[idx + 1];
  } else if (idx > 0 && (sizes[visibleOrder[idx - 1]] === 'col-6' || sizes[visibleOrder[idx - 1]] === 'col-4')) {
    partnerId = visibleOrder[idx - 1];
  } else if (idx < visibleOrder.length - 1) {
    partnerId = visibleOrder[idx + 1];
  } else if (idx > 0) {
    partnerId = visibleOrder[idx - 1];
  }

  if (!partnerId) {
    showToast('No adjacent partner widget found to swap with.', 'info');
    return;
  }

  pushLayoutHistory(pageId);

  const fromIdx = layout.order.indexOf(widgetId);
  const toIdx = layout.order.indexOf(partnerId);
  layout.order[fromIdx] = partnerId;
  layout.order[toIdx] = widgetId;

  if (appState.workspaceLayouts[pageId]) {
    appState.workspaceLayouts[pageId].order = layout.order;
  }
  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const srcCfg = configs.find(w => w.id === widgetId);
  const pCfg = configs.find(w => w.id === partnerId);
  showToast(`⇄ Swapped positions of "${srcCfg ? srcCfg.name : widgetId}" and "${pCfg ? pCfg.name : partnerId}"! ✨`, 'success');
}

/* [UX-QUICK-PAIR-PICKER] 1-Click Quick Widget Pair & Stack Picker Modal */
let activePairPickerContext = null;

function openWidgetPairPickerModal(pageId, targetWidgetId, mode = 'side') {
  activePairPickerContext = { pageId, targetWidgetId, mode };
  const modal = document.getElementById('widgetPairPickerModal');
  const titleEl = document.getElementById('pairPickerTitle');
  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const targetCfg = configs.find(w => w.id === targetWidgetId);
  const targetName = targetCfg ? targetCfg.name : targetWidgetId;

  if (titleEl) {
    titleEl.innerHTML = mode === 'side'
      ? `<span>◧</span> Place Widget Beside "${targetName}"`
      : `<span>⬇️</span> Stack Widget Under "${targetName}"`;
  }

  renderWidgetPairPickerList();
  if (modal) {
    modal.classList.add('active');
    modal.setAttribute('aria-hidden', 'false');
    const searchInput = document.getElementById('pairPickerSearchInput');
    if (searchInput) {
      searchInput.value = '';
      setTimeout(() => searchInput.focus(), 50);
    }
  }
}

function closeWidgetPairPickerModal() {
  const modal = document.getElementById('widgetPairPickerModal');
  if (modal) {
    modal.classList.remove('active');
    modal.setAttribute('aria-hidden', 'true');
  }
  activePairPickerContext = null;
}

function renderWidgetPairPickerList(query = '') {
  if (!activePairPickerContext) return;
  const { pageId, targetWidgetId, mode } = activePairPickerContext;
  const listEl = document.getElementById('pairPickerList');
  if (!listEl) return;

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const layout = getPageLayout(pageId);
  const hiddenSet = new Set(layout.hidden);
  const filterQuery = (query || '').toLowerCase().trim();

  listEl.innerHTML = '';

  const candidates = configs.filter(w => {
    if (w.id === targetWidgetId) return false;
    if (hiddenSet.has(w.id)) return false;
    // [FEAT-WIDGET-TIER-GATING] Exclude widgets user is not entitled to
    if (typeof isWidgetEntitled === 'function' && !isWidgetEntitled(w.id, w)) return false;
    if (filterQuery) {
      return (w.name.toLowerCase().includes(filterQuery) || (w.desc && w.desc.toLowerCase().includes(filterQuery)));
    }
    return true;
  });

  if (candidates.length === 0) {
    listEl.innerHTML = `
      <div style="text-align: center; padding: 24px 10px; color: var(--text-muted); font-size: 0.8rem;">
        No matching widgets found.
      </div>
    `;
    return;
  }

  candidates.forEach(w => {
    const item = document.createElement('div');
    item.className = 'pair-picker-item';
    item.innerHTML = `
      <div class="pair-picker-item-info">
        <span class="pair-picker-item-icon">${w.icon || '📦'}</span>
        <div>
          <div class="pair-picker-item-title">${w.name}</div>
          <div class="pair-picker-item-desc">${w.desc || ''}</div>
        </div>
      </div>
      <div class="pair-picker-item-actions">
        <button type="button" class="btn-pair-picker-action">
          ${mode === 'side' ? '◨ Place Beside' : '⬇️ Stack Under'}
        </button>
      </div>
    `;
    item.addEventListener('click', () => {
      closeWidgetPairPickerModal();
      if (mode === 'side') {
        reorderPageWidgetToTarget(pageId, w.id, targetWidgetId, 'right');
      } else {
        stackWidgetUnder(pageId, w.id, targetWidgetId);
      }
    });
    listEl.appendChild(item);
  });
}

function filterWidgetPairPickerList(query) {
  renderWidgetPairPickerList(query);
}

/* [FEAT-LAYOUT-PRESETS] Curated Layout Presets Controller */
function applyLayoutPreset(pageId, presetKey) {
  ensureWorkspaceLayouts();
  pushLayoutHistory(pageId);

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const allIds = configs.map(w => w.id);
  const layout = getPageLayout(pageId);
  let newOrder = [...allIds];
  let newSizes = {};
  let newStacks = {};
  let newHidden = [];

  if (presetKey === 'executive' || presetKey === 'insights') {
    if (pageId === 'dashboard') {
      const execDef = DEFAULT_WORKSPACE_LAYOUTS.dashboard;
      newSizes = { ...execDef.sizes };
      newStacks = { ...execDef.stacks };
      newOrder = [...execDef.order];
    } else if (typeof DEFAULT_WORKSPACE_LAYOUTS !== 'undefined' && DEFAULT_WORKSPACE_LAYOUTS[pageId]) {
      const def = DEFAULT_WORKSPACE_LAYOUTS[pageId];
      newSizes = { ...def.sizes };
      newStacks = { ...def.stacks };
      newOrder = [...def.order];
    } else {
      allIds.forEach(id => { newSizes[id] = 'col-6'; });
    }
    showToast('Applied 💡 Executive Insights Default Layout!', 'success');
  } else if (presetKey === 'daily_focus') {
    if (pageId === 'dashboard') {
      newSizes = {
        'widget-dashboard-quickadd': 'col-12',
        'widget-kpis': 'col-12',
        'widget-safe-spend': 'col-6',
        'widget-cashflow-cushion': 'col-6',
        'widget-wallets-balance': 'col-6',
        'widget-bills': 'col-6',
        'widget-goals': 'col-6',
        'widget-bottom-grid': 'col-12'
      };
      newOrder = [
        'widget-dashboard-quickadd',
        'widget-kpis',
        'widget-safe-spend',
        'widget-cashflow-cushion',
        'widget-wallets-balance',
        'widget-bills',
        'widget-goals',
        'widget-bottom-grid',
        ...allIds.filter(id => !['widget-dashboard-quickadd', 'widget-kpis', 'widget-safe-spend', 'widget-cashflow-cushion', 'widget-wallets-balance', 'widget-bills', 'widget-goals', 'widget-bottom-grid'].includes(id))
      ];
    } else {
      allIds.forEach(id => { newSizes[id] = 'col-12'; });
    }
    showToast('Applied ⚡ Daily Driver Focus Preset!', 'success');
  } else if (presetKey === 'analytics') {
    if (pageId === 'dashboard') {
      newSizes = {
        'widget-charts': 'col-12',
        'widget-kpis': 'col-12',
        'widget-savings-banner': 'col-12',
        'widget-wallets-balance': 'col-6',
        'widget-cc-float': 'col-6',
        'widget-cashflow-cushion': 'col-6',
        'widget-safe-spend': 'col-6'
      };
      newOrder = [
        'widget-charts',
        'widget-kpis',
        'widget-savings-banner',
        'widget-wallets-balance',
        'widget-cc-float',
        'widget-cashflow-cushion',
        'widget-safe-spend',
        ...allIds.filter(id => !['widget-charts', 'widget-kpis', 'widget-savings-banner', 'widget-wallets-balance', 'widget-cc-float', 'widget-cashflow-cushion', 'widget-safe-spend'].includes(id))
      ];
    } else {
      allIds.forEach(id => { newSizes[id] = 'col-6'; });
    }
    showToast('Applied 📊 Analytics First Preset!', 'success');
  } else if (presetKey === 'stacked') {
    allIds.forEach(id => { newSizes[id] = 'col-12'; });
    newStacks = {};
    showToast('Applied 📱 Full-Width Stack Preset!', 'success');
  }

  appState.workspaceLayouts[pageId] = {
    order: newOrder,
    hidden: newHidden,
    sizes: newSizes,
    fonts: layout.fonts || {},
    stacks: newStacks
  };
  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  const menu = document.getElementById('lsdPresetsMenu');
  if (menu) menu.classList.remove('active');

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(pageId);
  }
}

function toggleLayoutPresetsMenu(e) {
  if (e) e.stopPropagation();
  const profMenu = document.getElementById('lsdProfilesMenu');
  if (profMenu) profMenu.classList.remove('active');
  const menu = document.getElementById('lsdPresetsMenu');
  if (menu) menu.classList.toggle('active');
}

/* ==========================================================================
   [FEAT-SAVED-LAYOUT-PROFILES] SAVED WIDGET LAYOUTS & PROFILE MANAGER
   ========================================================================== */

function ensureSavedLayoutProfiles() {
  if (!appState.savedLayoutProfiles || !Array.isArray(appState.savedLayoutProfiles)) {
    appState.savedLayoutProfiles = [];
  }
  if (!appState.activeLayoutProfileIds || typeof appState.activeLayoutProfileIds !== 'object') {
    appState.activeLayoutProfileIds = {};
  }
}

function getSavedLayoutProfiles(pageId = 'dashboard') {
  ensureSavedLayoutProfiles();
  return appState.savedLayoutProfiles.filter(p => p.pageId === pageId);
}

function getActiveLayoutProfile(pageId = 'dashboard') {
  ensureSavedLayoutProfiles();
  const activeId = appState.activeLayoutProfileIds[pageId];
  if (!activeId || activeId === 'default') return null;
  return appState.savedLayoutProfiles.find(p => p.id === activeId && p.pageId === pageId) || null;
}

function updateLayoutProfileUI(pageId = null) {
  const targetPage = pageId || appState.activeTab || 'dashboard';
  const activeProfile = getActiveLayoutProfile(targetPage);
  const iconEl = document.getElementById('lsdActiveProfileIcon');
  const nameEl = document.getElementById('lsdActiveProfileName');
  if (iconEl && nameEl) {
    if (activeProfile) {
      iconEl.textContent = activeProfile.icon || '📊';
      nameEl.textContent = activeProfile.name;
    } else {
      iconEl.textContent = '📑';
      nameEl.textContent = 'Default Layout';
    }
  }

  // Also sync in widget manager modal if open
  syncModalProfileSelect(targetPage);
}

function syncModalProfileSelect(pageId) {
  const selectEl = document.getElementById('wmProfileSelect');
  if (!selectEl) return;
  const profiles = getSavedLayoutProfiles(pageId);
  const activeProfile = getActiveLayoutProfile(pageId);
  const activeId = activeProfile ? activeProfile.id : 'default';

  let html = `<option value="default" ${activeId === 'default' ? 'selected' : ''}>📑 Default System Grid</option>`;
  profiles.forEach(p => {
    html += `<option value="${p.id}" ${p.id === activeId ? 'selected' : ''}>${escapeHtml(p.icon || '📊')} ${escapeHtml(p.name)}</option>`;
  });
  selectEl.innerHTML = html;
}

function handleModalProfileSelectChange(val) {
  const pageId = activeModalWidgetTab || appState.activeTab || 'dashboard';
  applySavedLayoutProfile(pageId, val);
}

function toggleLayoutProfilesMenu(e) {
  if (e) e.stopPropagation();
  const presetsMenu = document.getElementById('lsdPresetsMenu');
  if (presetsMenu) presetsMenu.classList.remove('active');

  const menu = document.getElementById('lsdProfilesMenu');
  if (!menu) return;

  const willOpen = !menu.classList.contains('active');
  if (willOpen) {
    renderLayoutProfilesMenu(appState.activeTab || 'dashboard');
    menu.classList.add('active');
  } else {
    menu.classList.remove('active');
  }
}

function renderLayoutProfilesMenu(pageId = 'dashboard') {
  const menu = document.getElementById('lsdProfilesMenu');
  if (!menu) return;
  const pageName = PAGE_DISPLAY_NAMES[pageId] || 'Dashboard';
  const profiles = getSavedLayoutProfiles(pageId);
  const activeProfile = getActiveLayoutProfile(pageId);
  const activeId = activeProfile ? activeProfile.id : 'default';

  let html = `
    <div class="lsd-profile-menu-header">📑 Saved ${escapeHtml(pageName)} Layouts</div>
    <div class="lsd-profile-item ${activeId === 'default' ? 'active' : ''}" onclick="applySavedLayoutProfile('${pageId}', 'default')">
      <div class="lsd-profile-item-left">
        <span>📑</span>
        <strong>Default System Grid</strong>
      </div>
      ${activeId === 'default' ? '<span style="color: #38bdf8; font-weight: 800;">✓</span>' : ''}
    </div>
  `;

  if (profiles.length > 0) {
    profiles.forEach(p => {
      const isActive = (p.id === activeId);
      html += `
        <div class="lsd-profile-item ${isActive ? 'active' : ''}" onclick="applySavedLayoutProfile('${pageId}', '${p.id}')">
          <div class="lsd-profile-item-left">
            <span>${escapeHtml(p.icon || '📊')}</span>
            <strong title="${escapeHtml(p.name)}">${escapeHtml(p.name)}</strong>
          </div>
          <div class="lsd-profile-item-actions" onclick="event.stopPropagation();">
            ${isActive ? '<span style="color: #38bdf8; font-weight: 800; margin-right: 2px;">✓</span>' : ''}
            <button type="button" class="btn-profile-act" title="Duplicate Layout" onclick="duplicateSavedLayoutProfile('${pageId}', '${p.id}')">📋</button>
            <button type="button" class="btn-profile-act" title="Rename Layout" onclick="openSaveLayoutModal('${pageId}', 'rename', '${p.id}')">✏️</button>
            <button type="button" class="btn-profile-act" title="Delete Layout" onclick="deleteSavedLayoutProfile('${pageId}', '${p.id}')">🗑️</button>
          </div>
        </div>
      `;
    });
  }

  html += `<div class="lsd-profile-menu-divider"></div>`;

  if (activeProfile) {
    html += `
      <button type="button" class="lsd-profile-action-btn" onclick="quickSaveActiveLayoutProfile('${pageId}')">
        <span>💾</span>
        <span>Save Changes to "${escapeHtml(activeProfile.name)}"</span>
      </button>
    `;
  }

  html += `
    <button type="button" class="lsd-profile-action-btn" onclick="openSaveLayoutModal('${pageId}', 'save_current')">
      <span>💾</span>
      <span>Save Current as New Layout...</span>
    </button>
    <button type="button" class="lsd-profile-action-btn" onclick="openSaveLayoutModal('${pageId}', 'create_new')">
      <span>✨</span>
      <span>Create Another Layout...</span>
    </button>
  `;

  // [FEAT-ADMIN-GLOBAL-LAYOUT] 1-Click Publish to All Users in Layout Profile Menu (Admin Only)
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : false;
  if (isAdmin) {
    html += `
      <button type="button" class="lsd-profile-action-btn lsd-profile-admin-publish" onclick="openPublishGlobalLayoutModal('${pageId}')">
        <span>👑</span>
        <span>Set as Universal Default (All Users)...</span>
      </button>
    `;
  }

  menu.innerHTML = html;
}

function quickSaveActiveLayoutProfile(pageId) {
  const profile = getActiveLayoutProfile(pageId);
  if (!profile) return;
  const layout = getPageLayout(pageId);
  profile.layout = JSON.parse(JSON.stringify(layout));
  profile.updatedAt = new Date().toISOString();
  saveData();
  const menu = document.getElementById('lsdProfilesMenu');
  if (menu) menu.classList.remove('active');
  showToast(`Saved layout "${profile.name}" changes successfully! 💾`, 'success');
}

function applySavedLayoutProfile(pageId, profileId) {
  ensureSavedLayoutProfiles();
  pushLayoutHistory(pageId);

  const menu = document.getElementById('lsdProfilesMenu');
  if (menu) menu.classList.remove('active');

  if (profileId === 'default') {
    appState.activeLayoutProfileIds[pageId] = 'default';
    resetPageLayout(pageId);
    updateLayoutProfileUI(pageId);
    showToast(`Switched to Default Layout for ${PAGE_DISPLAY_NAMES[pageId] || pageId}`, 'info');
    return;
  }

  const profile = appState.savedLayoutProfiles.find(p => p.id === profileId && p.pageId === pageId);
  if (!profile) return;

  ensureWorkspaceLayouts();
  appState.workspaceLayouts[pageId] = JSON.parse(JSON.stringify(profile.layout));
  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }
  appState.activeLayoutProfileIds[pageId] = profile.id;

  applyPageLayout(pageId);
  saveData();
  updateLayoutProfileUI(pageId);

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(pageId);
  }

  showToast(`Switched to "${profile.name}" layout! 🎨`, 'success');
}

function duplicateSavedLayoutProfile(pageId, profileId) {
  const profile = appState.savedLayoutProfiles.find(p => p.id === profileId && p.pageId === pageId);
  if (!profile) return;

  const copyName = `${profile.name} (Copy)`;
  const newProfile = {
    id: 'lp_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
    pageId: pageId,
    name: copyName,
    icon: profile.icon || '📊',
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    layout: JSON.parse(JSON.stringify(profile.layout))
  };

  appState.savedLayoutProfiles.push(newProfile);
  applySavedLayoutProfile(pageId, newProfile.id);
  showToast(`Duplicated into "${copyName}"! 📋`, 'success');
}

function deleteSavedLayoutProfile(pageId, profileId) {
  const profile = appState.savedLayoutProfiles.find(p => p.id === profileId && p.pageId === pageId);
  if (!profile) return;

  if (!confirm(`Are you sure you want to delete the layout profile "${profile.name}"?`)) {
    return;
  }

  appState.savedLayoutProfiles = appState.savedLayoutProfiles.filter(p => p.id !== profileId);
  if (appState.activeLayoutProfileIds[pageId] === profileId) {
    appState.activeLayoutProfileIds[pageId] = 'default';
    resetPageLayout(pageId);
  }

  saveData();
  updateLayoutProfileUI(pageId);
  renderLayoutProfilesMenu(pageId);
  showToast(`Deleted layout profile "${profile.name}".`, 'info');
}

let activeLayoutIcon = '📊';

function toggleLayoutIconPicker() {
  const ribbon = document.getElementById('layoutIconPickerRibbon');
  if (ribbon) {
    ribbon.style.display = ribbon.style.display === 'none' ? 'flex' : 'none';
  }
}

function selectLayoutProfileIcon(icon) {
  activeLayoutIcon = icon;
  const selEl = document.getElementById('layoutProfileSelectedIcon');
  if (selEl) selEl.textContent = icon;
  const ribbon = document.getElementById('layoutIconPickerRibbon');
  if (ribbon) ribbon.style.display = 'none';
}

function openSaveLayoutModal(pageId, mode = 'save_current', profileId = null) {
  const menu = document.getElementById('lsdProfilesMenu');
  if (menu) menu.classList.remove('active');

  const modal = document.getElementById('saveLayoutProfileModal');
  if (!modal) return;

  document.getElementById('saveLayoutModalPageId').value = pageId;
  document.getElementById('saveLayoutModalMode').value = mode;
  document.getElementById('saveLayoutModalProfileId').value = profileId || '';

  const titleEl = document.getElementById('saveLayoutModalTitle');
  const subEl = document.getElementById('saveLayoutModalSubtitle');
  const headerIcon = document.getElementById('saveLayoutModalHeaderIcon');
  const nameInput = document.getElementById('layoutProfileNameInput');
  const templateGroup = document.getElementById('layoutStartingTemplateGroup');
  const submitBtn = document.getElementById('btnSubmitSaveLayoutProfile');

  if (mode === 'rename') {
    const profile = appState.savedLayoutProfiles.find(p => p.id === profileId);
    titleEl.textContent = 'Rename Layout Profile';
    subEl.textContent = 'Update the name and icon for this layout';
    headerIcon.textContent = '✏️';
    nameInput.value = profile ? profile.name : '';
    selectLayoutProfileIcon(profile && profile.icon ? profile.icon : '📊');
    if (templateGroup) templateGroup.style.display = 'none';
    if (submitBtn) submitBtn.textContent = '✓ Save Changes';
  } else if (mode === 'create_new') {
    titleEl.textContent = 'Create Another Layout';
    subEl.textContent = 'Choose a base template and customize a brand-new layout';
    headerIcon.textContent = '✨';
    nameInput.value = '';
    selectLayoutProfileIcon('⚡');
    if (templateGroup) templateGroup.style.display = 'block';
    if (submitBtn) submitBtn.textContent = '✓ Create & Switch';
  } else {
    // save_current
    const activeProfile = getActiveLayoutProfile(pageId);
    titleEl.textContent = 'Save Widget Layout';
    subEl.textContent = 'Save your current arrangement as a reusable layout profile';
    headerIcon.textContent = '💾';
    nameInput.value = activeProfile ? `${activeProfile.name} (New)` : '';
    selectLayoutProfileIcon(activeProfile && activeProfile.icon ? activeProfile.icon : '📊');
    if (templateGroup) templateGroup.style.display = 'none';
    if (submitBtn) submitBtn.textContent = '✓ Save & Switch';
  }

  modal.classList.add('active');
  setTimeout(() => nameInput.focus(), 80);
}

function closeSaveLayoutModal() {
  const modal = document.getElementById('saveLayoutProfileModal');
  if (modal) modal.classList.remove('active');
  const ribbon = document.getElementById('layoutIconPickerRibbon');
  if (ribbon) ribbon.style.display = 'none';
}

function submitSaveLayoutProfile() {
  const pageId = document.getElementById('saveLayoutModalPageId').value || 'dashboard';
  const mode = document.getElementById('saveLayoutModalMode').value || 'save_current';
  const profileId = document.getElementById('saveLayoutModalProfileId').value;
  const nameInput = document.getElementById('layoutProfileNameInput');
  const name = nameInput.value.trim();

  if (!name) {
    showToast('Please enter a name for your layout!', 'warning');
    nameInput.focus();
    return;
  }

  ensureSavedLayoutProfiles();

  if (mode === 'rename') {
    const profile = appState.savedLayoutProfiles.find(p => p.id === profileId);
    if (profile) {
      profile.name = name;
      profile.icon = activeLayoutIcon || '📊';
      profile.updatedAt = new Date().toISOString();
      saveData();
      updateLayoutProfileUI(pageId);
      closeSaveLayoutModal();
      showToast(`Renamed layout to "${name}"! ✨`, 'success');
    }
    return;
  }

  // Determine starting layout data
  let layoutData = null;
  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const allIds = configs.map(w => w.id);

  if (mode === 'create_new') {
    const selectedTemplate = document.querySelector('input[name="layoutBaseTemplate"]:checked')?.value || 'current';
    if (selectedTemplate === 'default' || selectedTemplate === 'executive') {
      const baseDef = (typeof DEFAULT_WORKSPACE_LAYOUTS !== 'undefined' && DEFAULT_WORKSPACE_LAYOUTS[pageId])
        ? JSON.parse(JSON.stringify(DEFAULT_WORKSPACE_LAYOUTS[pageId]))
        : { order: [...allIds], hidden: [], sizes: {}, fonts: {}, stacks: {} };
      layoutData = baseDef;
    } else if (selectedTemplate === 'daily_focus') {
      let newSizes = {};
      if (pageId === 'dashboard') {
        newSizes = { 'widget-dashboard-quickadd': 'col-12', 'widget-safe-spend': 'col-6', 'widget-wallets-balance': 'col-6' };
      }
      layoutData = { order: [...allIds], hidden: [], sizes: newSizes, fonts: {}, stacks: {} };
    } else {
      // 'current'
      layoutData = getPageLayout(pageId);
    }
  } else {
    // 'save_current'
    layoutData = getPageLayout(pageId);
  }

  const newProfile = {
    id: 'lp_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
    pageId: pageId,
    name: name,
    icon: activeLayoutIcon || '📊',
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    layout: JSON.parse(JSON.stringify(layoutData))
  };

  appState.savedLayoutProfiles.push(newProfile);
  appState.activeLayoutProfileIds[pageId] = newProfile.id;

  ensureWorkspaceLayouts();
  appState.workspaceLayouts[pageId] = JSON.parse(JSON.stringify(layoutData));
  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();
  updateLayoutProfileUI(pageId);
  closeSaveLayoutModal();

  showToast(`Saved and activated layout "${name}"! 🚀`, 'success');
}

window.toggleLayoutProfilesMenu = toggleLayoutProfilesMenu;
window.applySavedLayoutProfile = applySavedLayoutProfile;
window.duplicateSavedLayoutProfile = duplicateSavedLayoutProfile;
window.deleteSavedLayoutProfile = deleteSavedLayoutProfile;
window.quickSaveActiveLayoutProfile = quickSaveActiveLayoutProfile;
window.openSaveLayoutModal = openSaveLayoutModal;
window.closeSaveLayoutModal = closeSaveLayoutModal;
window.submitSaveLayoutProfile = submitSaveLayoutProfile;
window.toggleLayoutIconPicker = toggleLayoutIconPicker;
window.selectLayoutProfileIcon = selectLayoutProfileIcon;
window.handleModalProfileSelectChange = handleModalProfileSelectChange;

/* ==========================================================================
   [FEAT-ADMIN-GLOBAL-LAYOUT] ADMIN UNIVERSAL DEFAULT LAYOUT PUBLISHER & MANAGER
   ========================================================================== */
let activePublishLayoutPageId = 'dashboard';

function openPublishGlobalLayoutModal(pageId = 'dashboard') {
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : false;
  if (!isAdmin) {
    showToast('🛡️ Access Denied: Administrator privileges required to publish global default layouts.', 'error');
    return;
  }

  activePublishLayoutPageId = pageId || appState.activeTab || 'dashboard';
  const pageName = PAGE_DISPLAY_NAMES[activePublishLayoutPageId] || activePublishLayoutPageId;

  const tabNameDisplay = document.getElementById('publishActiveTabNameDisplay');
  if (tabNameDisplay) tabNameDisplay.textContent = pageName;

  const descInput = document.getElementById('publishLayoutDescription');
  if (descInput) descInput.value = '';

  // Summarize current layout
  const summaryEl = document.getElementById('publishLayoutSummaryText');
  if (summaryEl) {
    const layout = getPageLayout(activePublishLayoutPageId);
    const hiddenCount = (layout.hidden || []).length;
    const visibleCount = layout.order.length - hiddenCount;
    const sizes = layout.sizes || {};
    let col6Count = 0;
    let col12Count = 0;
    Object.values(sizes).forEach(s => {
      if (s === 'col-6') col6Count++;
      else if (s === 'col-12') col12Count++;
    });

    summaryEl.innerHTML = `
      <strong>${escapeHtml(pageName)}:</strong> ${visibleCount} visible widget${visibleCount === 1 ? '' : 's'} (${col6Count} 50/50 dual-column pairs, ${col12Count} full-width cards${hiddenCount > 0 ? `, ${hiddenCount} hidden` : ''}).<br>
      <span style="opacity: 0.85;">Selecting <strong>Entire Workstation</strong> will publish your custom blueprints across all 7 tabs (Dashboard, Budget, Expenses, Bills, Analytics, Savings, Forecaster Hub).</span>
    `;
  }

  // Update cloud metadata status
  updateAdminGlobalLayoutStatusText();

  const modal = document.getElementById('publishGlobalLayoutModal');
  if (modal) modal.classList.add('active');
}
window.openPublishGlobalLayoutModal = openPublishGlobalLayoutModal;

function closePublishGlobalLayoutModal() {
  const modal = document.getElementById('publishGlobalLayoutModal');
  if (modal) modal.classList.remove('active');
}
window.closePublishGlobalLayoutModal = closePublishGlobalLayoutModal;

function updateAdminGlobalLayoutStatusText() {
  const statusEl = document.getElementById('currentGlobalDefaultStatusText');
  const hubMetaEl = document.getElementById('adminHubGlobalStatusMeta');
  const hubTitleEl = document.getElementById('adminHubGlobalStatusTitle');

  let meta = null;
  try {
    const raw = localStorage.getItem('nirv_global_default_layouts_meta');
    if (raw) meta = JSON.parse(raw);
  } catch (e) {}

  if (meta && meta.publishedByEmail) {
    const dateStr = meta.updatedAt ? new Date(meta.updatedAt).toLocaleString() : 'Recently';
    const txt = `Published by ${meta.publishedByEmail} on ${dateStr} (${meta.version || 'Latest'})`;
    if (statusEl) statusEl.textContent = txt;
    if (hubMetaEl) hubMetaEl.textContent = txt;
    if (hubTitleEl) hubTitleEl.textContent = 'Active Cloud Universal Default (Live in Firestore)';
  } else {
    const txt = 'Using factory code defaults (no custom cloud layout published yet)';
    if (statusEl) statusEl.textContent = txt;
    if (hubMetaEl) hubMetaEl.textContent = txt;
    if (hubTitleEl) hubTitleEl.textContent = 'Factory Built-in Default Blueprint';
  }
}
window.updateAdminGlobalLayoutUI = updateAdminGlobalLayoutStatusText;

async function submitPublishGlobalDefaultLayout() {
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : false;
  if (!isAdmin) {
    showToast('🛡️ Access Denied: Administrator privileges required.', 'error');
    return;
  }

  const scopeRadio = document.querySelector('input[name="publishLayoutScope"]:checked');
  const scope = scopeRadio ? scopeRadio.value : 'all';
  const descInput = document.getElementById('publishLayoutDescription');
  const description = (descInput && descInput.value.trim()) || '';

  const confirmBtn = document.getElementById('btnConfirmPublishGlobalLayout');
  if (confirmBtn) {
    confirmBtn.disabled = true;
    confirmBtn.textContent = '⏳ Publishing to Cloud...';
  }

  try {
    let layoutsToPublish = {};
    if (scope === 'all') {
      const allPages = Object.keys(PAGE_DISPLAY_NAMES);
      allPages.forEach(pId => {
        layoutsToPublish[pId] = getPageLayout(pId);
      });
    } else {
      layoutsToPublish[activePublishLayoutPageId] = getPageLayout(activePublishLayoutPageId);
    }

    let cloudResult = null;
    if (typeof publishGlobalDefaultLayoutToCloud === 'function') {
      cloudResult = await publishGlobalDefaultLayoutToCloud(layoutsToPublish, scope, description);
    } else {
      // Local fallback
      Object.keys(layoutsToPublish).forEach(pId => {
        DEFAULT_WORKSPACE_LAYOUTS[pId] = JSON.parse(JSON.stringify(layoutsToPublish[pId]));
      });
      localStorage.setItem('nirv_global_default_layouts', JSON.stringify(layoutsToPublish));
    }

    closePublishGlobalLayoutModal();

    if (cloudResult && cloudResult._cloudSyncError) {
      showToast('⚠️ Universal Layout applied locally & cached! To broadcast to other remote devices, update rules in Firebase Console. You can also click "📋 Copy Layout JSON" to bake it directly into app.js.', 'warning', 10000);
    } else {
      showToast('👑 Universal Default Layout Published! All new users and users on the default view will now see your customized arrangement.', 'success', 6000);
    }

    if (document.getElementById('adminHubModal')?.classList.contains('active')) {
      renderAdminGlobalLayoutTab();
    }
  } catch (err) {
    console.error('Error publishing universal default layout:', err);
    showToast(`Error publishing layout: ${err.message || err}`, 'error');
  } finally {
    if (confirmBtn) {
      confirmBtn.disabled = false;
      confirmBtn.textContent = '👑 Publish to All Users Live';
    }
  }
}
window.submitPublishGlobalDefaultLayout = submitPublishGlobalDefaultLayout;

/* [FEAT-ADMIN-GLOBAL-LAYOUT] 1-Click Copy Current Layout JSON for Codebase Baseline */
function copyCurrentLayoutAsCode() {
  const scopeRadio = document.querySelector('input[name="publishLayoutScope"]:checked');
  const scope = scopeRadio ? scopeRadio.value : 'all';

  let layouts = {};
  if (scope === 'all') {
    Object.keys(PAGE_DISPLAY_NAMES).forEach(pId => {
      layouts[pId] = getPageLayout(pId);
    });
  } else {
    const targetPage = activePublishLayoutPageId || appState.activeTab || 'dashboard';
    layouts[targetPage] = getPageLayout(targetPage);
  }

  const jsonString = JSON.stringify(layouts, null, 2);

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(jsonString).then(() => {
      showToast('📋 Layout JSON copied to clipboard! Paste it to the assistant to bake directly into app.js.', 'success', 7000);
    }).catch(() => {
      prompt('Copy layout JSON manually below (Ctrl+C):', jsonString);
    });
  } else {
    prompt('Copy layout JSON manually below (Ctrl+C):', jsonString);
  }
  return jsonString;
}
window.copyCurrentLayoutAsCode = copyCurrentLayoutAsCode;

async function revertGlobalDefaultLayoutToFactory() {
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : false;
  if (!isAdmin) {
    showToast('🛡️ Access Denied: Administrator privileges required.', 'error');
    return;
  }

  if (!confirm('Are you sure you want to revert the platform Universal Default Layout back to the factory code baseline?')) {
    return;
  }

  try {
    if (typeof ORIGINAL_FACTORY_WORKSPACE_LAYOUTS !== 'undefined') {
      Object.keys(ORIGINAL_FACTORY_WORKSPACE_LAYOUTS).forEach(pId => {
        DEFAULT_WORKSPACE_LAYOUTS[pId] = JSON.parse(JSON.stringify(ORIGINAL_FACTORY_WORKSPACE_LAYOUTS[pId]));
      });
    }

    localStorage.removeItem('nirv_global_default_layouts');
    localStorage.removeItem('nirv_global_default_layouts_meta');

    // If connected to Firestore, delete cloud doc
    if (typeof fbDb !== 'undefined' && fbDb) {
      try {
        await fbDb.collection('system_config').doc('default_layout').delete();
      } catch (e) {
        console.warn('Notice removing cloud doc during factory reset:', e);
      }
    }

    applyAllPageLayouts();
    updateAdminGlobalLayoutStatusText();
    closePublishGlobalLayoutModal();

    if (document.getElementById('adminHubModal')?.classList.contains('active')) {
      renderAdminGlobalLayoutTab();
    }

    showToast('🔄 Reverted Universal Default Layout to Factory Code Baseline!', 'info');
  } catch (err) {
    console.error('Error reverting universal default layout:', err);
    showToast(`Error resetting: ${err.message || err}`, 'error');
  }
}
window.revertGlobalDefaultLayoutToFactory = revertGlobalDefaultLayoutToFactory;

function renderAdminGlobalLayoutTab() {
  updateAdminGlobalLayoutStatusText();
  const grid = document.getElementById('adminHubLayoutCardsGrid');
  if (!grid) return;

  const pages = Object.keys(PAGE_DISPLAY_NAMES);
  let html = '';

  pages.forEach(pId => {
    const pageName = PAGE_DISPLAY_NAMES[pId] || pId;
    const layout = (typeof DEFAULT_WORKSPACE_LAYOUTS !== 'undefined' && DEFAULT_WORKSPACE_LAYOUTS[pId])
      ? DEFAULT_WORKSPACE_LAYOUTS[pId]
      : getPageLayout(pId);

    const order = layout.order || [];
    const sizes = layout.sizes || {};
    const hidden = layout.hidden || [];
    const visibleCount = order.length - hidden.length;

    html += `
      <div class="admin-layout-card">
        <div class="admin-layout-card-header">
          <span class="admin-layout-card-title">${escapeHtml(pageName)} Tab</span>
          <span class="admin-layout-card-badge">${visibleCount} Widgets</span>
        </div>
        <div style="font-size: 0.72rem; color: var(--text-muted); margin-bottom: 6px;">
          Default ordering &amp; modular grid:
        </div>
        <div style="display: flex; flex-wrap: wrap; gap: 4px; max-height: 120px; overflow-y: auto;">
    `;

    order.forEach(wId => {
      const isHidden = hidden.includes(wId);
      const size = sizes[wId] || 'col-12';
      const cleanName = wId.replace(/^widget-/, '').replace(/-/g, ' ');
      html += `
        <span style="font-size: 0.68rem; padding: 2px 6px; border-radius: 4px; background: ${isHidden ? 'rgba(239,68,68,0.15)' : 'rgba(255,255,255,0.06)'}; color: ${isHidden ? '#f87171' : 'var(--text-secondary)'}; border: 1px solid ${isHidden ? 'rgba(239,68,68,0.3)' : 'var(--border-subtle)'};">
          ${cleanName} <code style="opacity: 0.7; font-size: 0.62rem;">(${size})</code>
        </span>
      `;
    });

    html += `
        </div>
        <div style="margin-top: 8px; border-top: 1px solid var(--border-subtle); padding-top: 6px; display: flex; justify-content: space-between; align-items: center;">
          <button type="button" class="btn btn-outline-cyan btn-xs" onclick="openPublishGlobalLayoutModal('${pId}')" title="Publish only this tab to all users">
            👑 Publish ${escapeHtml(pageName)}
          </button>
          <button type="button" class="btn btn-secondary btn-xs" onclick="closeAdminHubModal(); switchTab('${pId}'); toggleCustomLayoutMode(true);" title="Edit in Layout Studio">
            🎨 Edit Layout
          </button>
        </div>
      </div>
    `;
  });

  grid.innerHTML = html;
}
window.renderAdminGlobalLayoutTab = renderAdminGlobalLayoutTab;

function pairWidgetWithAdjacent(pageId, widgetId) {
  pairWidgetSideBySide(pageId, widgetId, 'right');
}

/* [FEAT-EDGE-DRAG-RESIZE] Interactive Horizontal Edge Drag-Resize Controller */
function bindWidgetEdgeDragResize(handle, widgetEl, pageId, widgetId) {
  let isDragging = false;
  let startX = 0;
  let initialWidth = 0;
  let parentWidth = 1;
  let hasMoved = false;

  const onMouseDown = (e) => {
    e.preventDefault();
    e.stopPropagation();
    isDragging = true;
    hasMoved = false;
    startX = e.clientX;
    initialWidth = widgetEl.offsetWidth;
    parentWidth = widgetEl.parentElement ? widgetEl.parentElement.offsetWidth : window.innerWidth;
    handle.classList.add('active');
    document.body.style.cursor = 'ew-resize';

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  };

  const onMouseMove = (e) => {
    if (!isDragging) return;
    const deltaX = e.clientX - startX;
    if (Math.abs(deltaX) > 6) hasMoved = true;
  };

  const onMouseUp = (e) => {
    if (!isDragging) return;
    isDragging = false;
    handle.classList.remove('active');
    document.body.style.cursor = '';
    window.removeEventListener('mousemove', onMouseMove);
    window.removeEventListener('mouseup', onMouseUp);

    const deltaX = e.clientX - startX;

    if (!hasMoved) {
      const layout = getPageLayout(pageId);
      const currentSize = (layout.sizes && layout.sizes[widgetId]) || 'col-12';
      const target = currentSize === 'col-6' ? 'col-12' : 'col-6';
      setWidgetSize(pageId, widgetId, target);
      return;
    }

    const projectedWidth = initialWidth + deltaX;
    const ratio = projectedWidth / Math.max(parentWidth, 1);
    let targetSize = 'col-12';
    if (ratio <= 0.42) targetSize = 'col-4';
    else if (ratio <= 0.60) targetSize = 'col-6';
    else if (ratio <= 0.85) targetSize = 'col-8';
    else targetSize = 'col-12';

    setWidgetSize(pageId, widgetId, targetSize);
  };

  handle.addEventListener('mousedown', onMouseDown);
}

function ensureWidgetLayoutToolbar(widgetEl, pageId, widgetId, position, totalWidgets, isHidden, currentSize = 'col-12', currentFont = 'md', isInStack = false) {
  if (!widgetEl) return;
  let toolbar = widgetEl.querySelector('.widget-layout-toolbar');
  if (!toolbar) {
    toolbar = document.createElement('div');
    toolbar.className = 'widget-layout-toolbar';
    widgetEl.insertBefore(toolbar, widgetEl.firstChild);
  }

  // Render edge resize handle for interactive horizontal dragging
  let resizeHandle = widgetEl.querySelector('.wlt-edge-resize-handle');
  if (!resizeHandle) {
    resizeHandle = document.createElement('div');
    resizeHandle.className = 'wlt-edge-resize-handle';
    resizeHandle.title = 'Drag left/right to resize width, or click to toggle 50/50 side-by-side';
    widgetEl.appendChild(resizeHandle);
    bindWidgetEdgeDragResize(resizeHandle, widgetEl, pageId, widgetId);
  }

  toolbar.innerHTML = `
    <span class="wlt-pill-pos" title="Drag to reorder, or drag left/right over another widget to place side-by-side (Position #${position})" style="cursor: grab;">⠿ #${position}</span>
    <button type="button" class="wlt-btn btn-wlt-up" title="Move Up" onclick="event.stopPropagation(); movePageWidget('${pageId}', '${widgetId}', -1);" ${position <= 1 ? 'disabled style="opacity: 0.3;"' : ''}>▲</button>
    <button type="button" class="wlt-btn btn-wlt-down" title="Move Down" onclick="event.stopPropagation(); movePageWidget('${pageId}', '${widgetId}', 1);" ${position >= totalWidgets ? 'disabled style="opacity: 0.3;"' : ''}>▼</button>
    <div class="wlt-size-selector" title="Modular Column Span">
      <button type="button" class="wlt-btn-size ${currentSize === 'col-4' ? 'active' : ''}" title="Compact Width (⅓)" onclick="event.stopPropagation(); setWidgetSize('${pageId}', '${widgetId}', 'col-4');">⅓</button>
      <button type="button" class="wlt-btn-size ${currentSize === 'col-6' ? 'active' : ''}" title="Balanced Width (½)" onclick="event.stopPropagation(); setWidgetSize('${pageId}', '${widgetId}', 'col-6');">½</button>
      <button type="button" class="wlt-btn-size ${currentSize === 'col-8' ? 'active' : ''}" title="Focus Width (⅔)" onclick="event.stopPropagation(); setWidgetSize('${pageId}', '${widgetId}', 'col-8');">⅔</button>
      <button type="button" class="wlt-btn-size ${currentSize === 'col-12' || !currentSize ? 'active' : ''}" title="Full Width" onclick="event.stopPropagation(); setWidgetSize('${pageId}', '${widgetId}', 'col-12');">Full</button>
    </div>
    <div class="wlt-pair-group" title="Side-by-Side Dual Column Pairing">
      <button type="button" class="wlt-btn wlt-btn-pair-left ${currentSize === 'col-6' ? 'active' : ''}" title="Snap Side-by-Side on LEFT (50% / 50%)" onclick="event.stopPropagation(); pairWidgetSideBySide('${pageId}', '${widgetId}', 'left');">
        <span>◫</span> <span class="wlt-pair-label">Left</span>
      </button>
      <button type="button" class="wlt-btn wlt-btn-pair-right ${currentSize === 'col-6' ? 'active' : ''}" title="Snap Side-by-Side on RIGHT (50% / 50%)" onclick="event.stopPropagation(); pairWidgetSideBySide('${pageId}', '${widgetId}', 'right');">
        <span>◨</span> <span class="wlt-pair-label">Right</span>
      </button>
    </div>
    ${currentSize === 'col-6' ? `
      <button type="button" class="wlt-btn wlt-btn-swap" title="Swap sides with adjacent widget (⇄ Swap)" onclick="event.stopPropagation(); swapSideBySideWidgets('${pageId}', '${widgetId}');">
        ⇄ Swap
      </button>
    ` : ''}
    <button type="button" class="wlt-btn wlt-btn-pair-picker" title="Pick a widget to place side-by-side or stack (1-Click)" onclick="event.stopPropagation(); openWidgetPairPickerModal('${pageId}', '${widgetId}', 'side');">
      ◧ Pair With...
    </button>
    ${(currentSize === 'col-6' || currentSize === 'col-4' || isInStack) ? `
      <button type="button" class="wlt-btn wlt-btn-stack" title="Stack next widget under this in column" onclick="event.stopPropagation(); stackNextWidgetUnder('${pageId}', '${widgetId}');">
        ⬇️ Stack
      </button>
    ` : ''}
    ${isInStack ? `
      <button type="button" class="wlt-btn wlt-btn-unstack" title="Unstack this widget from column" onclick="event.stopPropagation(); unstackWidget('${pageId}', '${widgetId}');">
        ⏏ Unstack
      </button>
    ` : ''}
    <button type="button" class="wlt-btn wlt-btn-font" title="Font Scale: ${currentFont.toUpperCase()} (Click to cycle S / M / L)" onclick="event.stopPropagation(); cycleWidgetFontSize('${pageId}', '${widgetId}');">
      <span>Aa</span> <span class="wlt-font-badge">${currentFont.toUpperCase()}</span>
    </button>
    <button type="button" class="wlt-btn btn-wlt-hide" title="${isHidden ? 'Unhide Widget' : 'Hide Widget'}" onclick="event.stopPropagation(); togglePageWidgetVisibility('${pageId}', '${widgetId}');">
      ${isHidden ? '🙈 Hidden' : '👁️'}
    </button>
  `;

  // Bind HTML5 Drag-and-Drop in Layout Mode once per widget element
  if (!widgetEl.dataset.layoutDndBound) {
    widgetEl.dataset.layoutDndBound = 'true';
    widgetEl.addEventListener('dragstart', (e) => {
      if (!isCustomLayoutModeActive) {
        e.preventDefault();
        return;
      }
      const wId = widgetEl.getAttribute('data-widget-id');
      draggedLayoutWidgetInfo = { pageId, widgetId: wId };
      widgetEl.style.opacity = '0.55';
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', wId);
      }
    });
    widgetEl.addEventListener('dragend', () => {
      widgetEl.style.opacity = '';
      document.querySelectorAll('.widget-drop-hover, .widget-drop-side-left, .widget-drop-side-right, .widget-drop-stack-below, .widget-drop-stack-above').forEach(el => {
        el.classList.remove('widget-drop-hover', 'widget-drop-side-left', 'widget-drop-side-right', 'widget-drop-stack-below', 'widget-drop-stack-above');
      });
      draggedLayoutWidgetInfo = null;
    });
    widgetEl.addEventListener('dragover', (e) => {
      if (!isCustomLayoutModeActive || !draggedLayoutWidgetInfo || draggedLayoutWidgetInfo.pageId !== pageId) return;
      if (draggedLayoutWidgetInfo.widgetId === widgetId) return;
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';

      const rect = widgetEl.getBoundingClientRect();
      const xRatio = (e.clientX - rect.left) / Math.max(rect.width, 1);
      const yRatio = (e.clientY - rect.top) / Math.max(rect.height, 1);

      widgetEl.classList.remove('widget-drop-hover', 'widget-drop-side-left', 'widget-drop-side-right', 'widget-drop-stack-below', 'widget-drop-stack-above');

      const isNarrowCard = (currentSize === 'col-6' || currentSize === 'col-4' || isInStack);

      if (isNarrowCard) {
        if (xRatio < 0.32) {
          widgetEl.classList.add('widget-drop-side-left');
        } else if (xRatio > 0.68) {
          widgetEl.classList.add('widget-drop-side-right');
        } else if (yRatio > 0.60) {
          widgetEl.classList.add('widget-drop-stack-below');
        } else if (yRatio < 0.40) {
          widgetEl.classList.add('widget-drop-stack-above');
        } else {
          widgetEl.classList.add('widget-drop-hover');
        }
      } else {
        if (xRatio < 0.48) {
          widgetEl.classList.add('widget-drop-side-left');
        } else if (xRatio > 0.52) {
          widgetEl.classList.add('widget-drop-side-right');
        } else {
          widgetEl.classList.add('widget-drop-hover');
        }
      }
    });
    widgetEl.addEventListener('dragleave', () => {
      widgetEl.classList.remove('widget-drop-hover', 'widget-drop-side-left', 'widget-drop-side-right', 'widget-drop-stack-below', 'widget-drop-stack-above');
    });
    widgetEl.addEventListener('drop', (e) => {
      const isStackBelow = widgetEl.classList.contains('widget-drop-stack-below');
      const isStackAbove = widgetEl.classList.contains('widget-drop-stack-above');
      const isLeft = widgetEl.classList.contains('widget-drop-side-left');
      const isRight = widgetEl.classList.contains('widget-drop-side-right');

      widgetEl.classList.remove('widget-drop-hover', 'widget-drop-side-left', 'widget-drop-side-right', 'widget-drop-stack-below', 'widget-drop-stack-above');
      if (!isCustomLayoutModeActive || !draggedLayoutWidgetInfo || draggedLayoutWidgetInfo.pageId !== pageId) return;
      e.preventDefault();
      e.stopPropagation();
      const targetWidgetId = widgetEl.getAttribute('data-widget-id');
      const sourceWidgetId = draggedLayoutWidgetInfo.widgetId;
      draggedLayoutWidgetInfo = null;

      if (isStackBelow) {
        stackWidgetUnder(pageId, sourceWidgetId, targetWidgetId);
      } else if (isStackAbove) {
        stackWidgetAbove(pageId, sourceWidgetId, targetWidgetId);
      } else if (isLeft) {
        reorderPageWidgetToTarget(pageId, sourceWidgetId, targetWidgetId, 'left');
      } else if (isRight) {
        reorderPageWidgetToTarget(pageId, sourceWidgetId, targetWidgetId, 'right');
      } else {
        reorderPageWidgetToTarget(pageId, sourceWidgetId, targetWidgetId, 'center');
      }
    });
  }
  widgetEl.setAttribute('draggable', isCustomLayoutModeActive ? 'true' : 'false');
}

/* [FEAT-MODULAR-WIDGET-SIZING] Set Modular Column Span */
function setWidgetSize(pageId, widgetId, size) {
  const allowedSizes = ['col-4', 'col-6', 'col-8', 'col-12'];
  const targetSize = allowedSizes.includes(size) ? size : 'col-12';

  ensureWorkspaceLayouts();
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  if (!appState.workspaceLayouts[pageId]) {
    appState.workspaceLayouts[pageId] = {
      order: layout.order,
      hidden: layout.hidden,
      sizes: {},
      fonts: {}
    };
  }
  if (!appState.workspaceLayouts[pageId].sizes) {
    appState.workspaceLayouts[pageId].sizes = {};
  }
  appState.workspaceLayouts[pageId].sizes[widgetId] = targetSize;
  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const sizeLabelMap = { 'col-4': '1/3 Width (Compact)', 'col-6': '1/2 Width (Balanced)', 'col-8': '2/3 Width (Focus)', 'col-12': 'Full Width' };
  showToast(`Widget width set to ${sizeLabelMap[targetSize] || targetSize}!`, 'info');
}

/* [FEAT-MODULAR-WIDGET-SIZING] Set Per-Widget Font Size */
function setWidgetFontSize(pageId, widgetId, fontSize) {
  const allowedFonts = ['sm', 'md', 'lg'];
  const targetFont = allowedFonts.includes(fontSize) ? fontSize : 'md';

  ensureWorkspaceLayouts();
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  if (!appState.workspaceLayouts[pageId]) {
    appState.workspaceLayouts[pageId] = {
      order: layout.order,
      hidden: layout.hidden,
      sizes: {},
      fonts: {}
    };
  }
  if (!appState.workspaceLayouts[pageId].fonts) {
    appState.workspaceLayouts[pageId].fonts = {};
  }
  appState.workspaceLayouts[pageId].fonts[widgetId] = targetFont;
  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  showToast(`Widget font scaled to ${targetFont.toUpperCase()}!`, 'info');
}

function cycleWidgetFontSize(pageId, widgetId) {
  const layout = getPageLayout(pageId);
  const currentFont = (layout.fonts && layout.fonts[widgetId]) || 'md';
  const fontCycle = { 'sm': 'md', 'md': 'lg', 'lg': 'sm' };
  const nextFont = fontCycle[currentFont] || 'md';
  setWidgetFontSize(pageId, widgetId, nextFont);
}

/* [FEAT-MODULAR-WIDGET-SIZING] Global Workstation Density Scaling */
function setWorkstationDensity(density, showToastNotification = true) {
  const valid = ['compact', 'default', 'comfort'];
  const targetDensity = valid.includes(density) ? density : 'default';

  if (!appState.userSettings) appState.userSettings = {};
  appState.userSettings.workstationDensity = targetDensity;
  document.body.setAttribute('data-density', targetDensity);

  updateDensityUIControls(targetDensity);
  if (showToastNotification) {
    saveData();
    setTimeout(resizeAllDashboardCharts, 60);
    const labels = { compact: 'Compact (85%)', default: 'Default (100%)', comfort: 'Comfort (115%)' };
    showToast(`Workstation density updated to ${labels[targetDensity]}!`, 'info');
  }
}

function updateDensityUIControls(density) {
  document.querySelectorAll('.btn-lsd-density, .btn-wm-density').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-density') === density);
  });
}

function resizeAllDashboardCharts() {
  try {
    if (typeof trendChartInstance !== 'undefined' && trendChartInstance) trendChartInstance.resize();
    if (typeof pieChartInstance !== 'undefined' && pieChartInstance) pieChartInstance.resize();
    if (typeof varianceChartInstance !== 'undefined' && varianceChartInstance) varianceChartInstance.resize();
    if (typeof savingsChartInstance !== 'undefined' && savingsChartInstance) savingsChartInstance.resize();
    if (typeof forecasterHistoryChartInstance !== 'undefined' && forecasterHistoryChartInstance) forecasterHistoryChartInstance.resize();
  } catch (err) {
    // Graceful ignore
  }
}

function updateLayoutStudioDockTitle(tabId) {
  const currentTab = tabId || appState.activeTab || 'dashboard';
  const pageName = PAGE_DISPLAY_NAMES[currentTab] || 'Workspace';

  const titleEl = document.getElementById('lsdTitleText');
  if (titleEl) {
    titleEl.textContent = `${pageName} Layout Studio`;
  }

  const wsMeta = (typeof workspaceRegistry !== 'undefined' && workspaceRegistry.workspaces)
    ? workspaceRegistry.workspaces.find(w => w.id === workspaceRegistry.activeWorkspaceId)
    : null;
  const wsNameEl = document.getElementById('lsdWorkspaceName');
  if (wsNameEl) {
    wsNameEl.textContent = `Workspace: ${wsMeta ? wsMeta.name : 'Active Workspace'}`;
  }

  if (typeof updateLayoutProfileUI === 'function') {
    updateLayoutProfileUI(currentTab);
  }
}

function toggleCustomLayoutMode(forceState = null) {
  if (forceState !== false && typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-52]')) {
    if (typeof showUpgradePrompt === 'function') {
      showUpgradePrompt('[FEAT-52]', 'Workspace Custom UI Layout Studio');
    }
    return;
  }
  isCustomLayoutModeActive = (forceState !== null) ? !!forceState : !isCustomLayoutModeActive;

  document.body.classList.toggle('layout-mode-active', isCustomLayoutModeActive);

  if (!isCustomLayoutModeActive) {
    document.querySelectorAll('.widget-beside-drop-slot, .widget-stack-drop-slot').forEach(s => s.remove());
  }

  const dock = document.getElementById('layoutStudioDock');
  if (dock) {
    dock.style.display = isCustomLayoutModeActive ? 'flex' : 'none';
  }

  const btnToggle = document.getElementById('btnToggleCustomLayoutMode');
  if (btnToggle) {
    btnToggle.classList.toggle('active', isCustomLayoutModeActive);
    btnToggle.setAttribute('aria-pressed', isCustomLayoutModeActive ? 'true' : 'false');
    const label = btnToggle.querySelector('.layout-label');
    if (label) {
      label.textContent = isCustomLayoutModeActive ? 'Exit Layout' : 'Customize Layout';
    }
  }

  const currentTab = appState.activeTab || 'dashboard';
  updateLayoutStudioDockTitle(currentTab);
  const currentDensity = (appState.userSettings && appState.userSettings.workstationDensity) || 'default';
  updateDensityUIControls(currentDensity);

  if (isCustomLayoutModeActive) {
    const pageName = PAGE_DISPLAY_NAMES[currentTab] || 'Dashboard';
    showToast(`${pageName} Layout Studio active: Reorder or toggle widgets freely!`);
  }

  applyAllPageLayouts();
}

function movePageWidget(pageId, widgetId, delta) {
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  const idx = layout.order.indexOf(widgetId);
  if (idx === -1) return;

  const targetIdx = idx + delta;
  if (targetIdx < 0 || targetIdx >= layout.order.length) return;

  // Swap positions
  const temp = layout.order[idx];
  layout.order[idx] = layout.order[targetIdx];
  layout.order[targetIdx] = temp;

  // Persist into active workspace
  ensureWorkspaceLayouts();
  appState.workspaceLayouts[pageId] = {
    order: layout.order,
    hidden: layout.hidden
  };
  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const cfg = configs.find(w => w.id === widgetId);
  showToast(`Moved "${cfg ? cfg.name : widgetId}" ${delta < 0 ? 'up' : 'down'}!`, 'info');
}

function togglePageWidgetVisibility(pageId, widgetId) {
  pushLayoutHistory(pageId);
  const layout = getPageLayout(pageId);
  const hiddenSet = new Set(layout.hidden);

  if (hiddenSet.has(widgetId)) {
    hiddenSet.delete(widgetId);
  } else {
    hiddenSet.add(widgetId);
  }

  const updatedHidden = Array.from(hiddenSet);
  ensureWorkspaceLayouts();
  appState.workspaceLayouts[pageId] = {
    order: layout.order,
    hidden: updatedHidden
  };
  if (pageId === 'dashboard') {
    appState.workspaceDashboardLayout = appState.workspaceLayouts[pageId];
  }

  applyPageLayout(pageId);
  saveData();

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const configs = PAGE_WIDGET_CONFIGS[pageId] || [];
  const cfg = configs.find(w => w.id === widgetId);
  const isNowHidden = hiddenSet.has(widgetId);
  showToast(`"${cfg ? cfg.name : widgetId}" is now ${isNowHidden ? 'hidden' : 'visible'} in this workspace!`, isNowHidden ? 'warning' : 'success');
}

function moveDashboardWidget(widgetId, delta) {
  movePageWidget('dashboard', widgetId, delta);
}

function toggleDashboardWidgetVisibility(widgetId) {
  togglePageWidgetVisibility('dashboard', widgetId);
}

function resetPageLayout(pageId) {
  const targetPage = pageId || appState.activeTab || 'dashboard';
  ensureWorkspaceLayouts();
  delete appState.workspaceLayouts[targetPage];
  if (targetPage === 'dashboard') {
    appState.workspaceDashboardLayout = null;
  }

  applyPageLayout(targetPage);
  saveData();

  if (typeof updateLayoutProfileUI === 'function') {
    updateLayoutProfileUI(targetPage);
  }

  if (document.getElementById('widgetManagerModal')?.classList.contains('active')) {
    renderWidgetManagerList(activeModalWidgetTab);
  }

  const wsMeta = (typeof workspaceRegistry !== 'undefined' && workspaceRegistry.workspaces)
    ? workspaceRegistry.workspaces.find(w => w.id === workspaceRegistry.activeWorkspaceId)
    : null;
  const pageName = PAGE_DISPLAY_NAMES[targetPage] || targetPage;
  showToast(`${pageName} layout reset to Insights Default Layout for ${wsMeta ? wsMeta.name : 'this workspace'}! 💡`, 'success');
}

function resetCurrentModalPageLayout() {
  resetPageLayout(activeModalWidgetTab);
}

function resetDashboardLayout() {
  resetPageLayout('dashboard');
}

function switchWidgetManagerTab(pageId) {
  if (!PAGE_WIDGET_CONFIGS[pageId]) return;
  activeModalWidgetTab = pageId;

  // Update tabs UI
  document.querySelectorAll('#wmPageTabs .btn-wm-tab').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-page') === pageId);
  });

  renderWidgetManagerList(pageId);
}

function openWidgetManagerModal(preferredTab = null) {
  const modal = document.getElementById('widgetManagerModal');
  if (!modal) return;

  const currentTab = preferredTab || appState.activeTab || 'dashboard';
  activeModalWidgetTab = PAGE_WIDGET_CONFIGS[currentTab] ? currentTab : 'dashboard';

  // Sync active tab button in modal
  document.querySelectorAll('#wmPageTabs .btn-wm-tab').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-page') === activeModalWidgetTab);
  });

  const wsMeta = (typeof workspaceRegistry !== 'undefined' && workspaceRegistry.workspaces)
    ? workspaceRegistry.workspaces.find(w => w.id === workspaceRegistry.activeWorkspaceId)
    : null;
  const subEl = document.getElementById('wmModalWorkspaceSubtitle');
  if (subEl) {
    subEl.textContent = `Customizing arrangement for: ${wsMeta ? wsMeta.name : 'Active Workspace'}`;
  }

  const currentDensity = (appState.userSettings && appState.userSettings.workstationDensity) || 'default';
  updateDensityUIControls(currentDensity);

  renderWidgetManagerList(activeModalWidgetTab);
  modal.classList.add('active');
}

function closeWidgetManagerModal() {
  const modal = document.getElementById('widgetManagerModal');
  if (modal) modal.classList.remove('active');
}

function renderWidgetManagerList(pageId = null) {
  const targetPage = pageId || activeModalWidgetTab || 'dashboard';
  const listEl = document.getElementById('widgetManagerList');
  if (!listEl) return;

  if (typeof syncModalProfileSelect === 'function') {
    syncModalProfileSelect(targetPage);
  }

  syncDynamicDomWidgetsToConfig(targetPage);
  const configs = PAGE_WIDGET_CONFIGS[targetPage] || [];
  const layout = getPageLayout(targetPage);
  const hiddenSet = new Set(layout.hidden);
  const sizes = layout.sizes || {};
  const fonts = layout.fonts || {};

  listEl.innerHTML = '';

  // [FEAT-WIDGET-TIER-GATING] Filter out widgets user is not entitled to based on tier
  const entitledItems = layout.order
    .map(widgetId => ({ widgetId, cfg: configs.find(w => w.id === widgetId) }))
    .filter(item => item.cfg && (typeof isWidgetEntitled === 'function' ? isWidgetEntitled(item.widgetId, item.cfg) : true));

  entitledItems.forEach((item, index) => {
    const { widgetId, cfg } = item;

    const isHidden = hiddenSet.has(widgetId);
    const currentSize = sizes[widgetId] || 'col-12';
    const currentFont = fonts[widgetId] || 'md';
    const stackInfo = getWidgetStackInfo(targetPage, widgetId);
    const isStacked = !!stackInfo;
    const stackIndex = isStacked ? stackInfo.members.indexOf(widgetId) : -1;
    const stackTotal = isStacked ? stackInfo.members.length : 0;

    const row = document.createElement('div');
    row.className = `wm-row ${isHidden ? 'is-hidden' : ''}`;
    row.setAttribute('data-widget-id', widgetId);
    row.setAttribute('draggable', 'true');
    row.style.cursor = 'grab';

    row.innerHTML = `
      <div class="wm-left">
        <span class="wm-order-badge" title="Drag row to reorder">⠿ #${index + 1}</span>
        <span class="wm-icon">${cfg.icon}</span>
        <div class="wm-info">
          <strong class="wm-title">
            ${cfg.name}
            ${isStacked ? `<span class="wm-stack-pill" title="Stacked in column (${stackIndex + 1} of ${stackTotal})">◧ Stacked ${stackIndex + 1}/${stackTotal}</span>` : ''}
          </strong>
          <span class="wm-desc">${cfg.desc}</span>
        </div>
      </div>
      <div class="wm-actions">
        <div class="wm-size-group" title="Modular Column Span">
          <button type="button" class="btn-wm-size-pill ${currentSize === 'col-4' ? 'active' : ''}" title="Compact Width (⅓)" onclick="event.stopPropagation(); setWidgetSize('${targetPage}', '${widgetId}', 'col-4');">⅓</button>
          <button type="button" class="btn-wm-size-pill ${currentSize === 'col-6' ? 'active' : ''}" title="Balanced Width (½)" onclick="event.stopPropagation(); setWidgetSize('${targetPage}', '${widgetId}', 'col-6');">½</button>
          <button type="button" class="btn-wm-size-pill ${currentSize === 'col-8' ? 'active' : ''}" title="Focus Width (⅔)" onclick="event.stopPropagation(); setWidgetSize('${targetPage}', '${widgetId}', 'col-8');">⅔</button>
          <button type="button" class="btn-wm-size-pill ${currentSize === 'col-12' || !currentSize ? 'active' : ''}" title="Full Width" onclick="event.stopPropagation(); setWidgetSize('${targetPage}', '${widgetId}', 'col-12');">Full</button>
        </div>
        <div class="wm-pair-group" title="Side-by-Side Dual Column Pairing">
          <button type="button" class="btn-wm-pair-left ${currentSize === 'col-6' ? 'active' : ''}" title="Snap Side-by-Side on LEFT (50% / 50%)" onclick="event.stopPropagation(); pairWidgetSideBySide('${targetPage}', '${widgetId}', 'left');">◫</button>
          <button type="button" class="btn-wm-pair-right ${currentSize === 'col-6' ? 'active' : ''}" title="Snap Side-by-Side on RIGHT (50% / 50%)" onclick="event.stopPropagation(); pairWidgetSideBySide('${targetPage}', '${widgetId}', 'right');">◨</button>
        </div>
        ${currentSize === 'col-6' ? `
        <button type="button" class="btn-wm-swap" title="Swap sides with adjacent partner" onclick="event.stopPropagation(); swapSideBySideWidgets('${targetPage}', '${widgetId}');">⇄ Swap</button>
        ` : ''}
        <button type="button" class="btn-wm-size-pill" title="Pick a companion widget from list" onclick="event.stopPropagation(); openWidgetPairPickerModal('${targetPage}', '${widgetId}', 'side');">◧ Pair</button>
        ${(currentSize === 'col-6' || currentSize === 'col-4' || isStacked) ? `
        <button type="button" class="btn-wm-size-pill" title="Stack next widget under this in column" onclick="event.stopPropagation(); stackNextWidgetUnder('${targetPage}', '${widgetId}');">⬇️ Stack</button>
        ` : ''}
        ${isStacked ? `
        <button type="button" class="btn-wm-unstack" title="Unstack this widget from column" onclick="event.stopPropagation(); unstackWidget('${targetPage}', '${widgetId}');">
          ⏏ Unstack
        </button>
        ` : ''}
        <button type="button" class="btn-wm-font-pill" title="Font Scale: ${currentFont.toUpperCase()} (Click to cycle S / M / L)" onclick="event.stopPropagation(); cycleWidgetFontSize('${targetPage}', '${widgetId}');">
          <span>Aa</span> <strong>${currentFont.toUpperCase()}</strong>
        </button>
        <button type="button" class="btn-wm-nav" title="Move Up" onclick="event.stopPropagation(); movePageWidget('${targetPage}', '${widgetId}', -1);" ${index === 0 ? 'disabled' : ''}>▲</button>
        <button type="button" class="btn-wm-nav" title="Move Down" onclick="event.stopPropagation(); movePageWidget('${targetPage}', '${widgetId}', 1);" ${index === layout.order.length - 1 ? 'disabled' : ''}>▼</button>
        <button type="button" class="btn-wm-toggle ${isHidden ? 'state-hidden' : ''}" onclick="event.stopPropagation(); togglePageWidgetVisibility('${targetPage}', '${widgetId}');">
          ${isHidden ? '🙈 Hidden' : '👁️ Visible'}
        </button>
      </div>
    `;

    row.addEventListener('dragstart', (e) => {
      draggedLayoutWidgetInfo = { pageId: targetPage, widgetId };
      row.style.opacity = '0.5';
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', widgetId);
      }
    });
    row.addEventListener('dragend', () => {
      row.style.opacity = '';
      document.querySelectorAll('.wm-row.widget-drop-hover').forEach(el => el.classList.remove('widget-drop-hover'));
      draggedLayoutWidgetInfo = null;
    });
    row.addEventListener('dragover', (e) => {
      if (!draggedLayoutWidgetInfo || draggedLayoutWidgetInfo.pageId !== targetPage) return;
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
      row.classList.add('widget-drop-hover');
    });
    row.addEventListener('dragleave', () => {
      row.classList.remove('widget-drop-hover');
    });
    row.addEventListener('drop', (e) => {
      row.classList.remove('widget-drop-hover');
      if (!draggedLayoutWidgetInfo || draggedLayoutWidgetInfo.pageId !== targetPage) return;
      e.preventDefault();
      e.stopPropagation();
      const sourceWidgetId = draggedLayoutWidgetInfo.widgetId;
      draggedLayoutWidgetInfo = null;
      reorderPageWidgetToTarget(targetPage, sourceWidgetId, widgetId);
    });

    listEl.appendChild(row);
  });
}

// ==========================================
// 44. [FEAT-54 / FEAT-55] ADMIN COMMAND CENTER & CUSTOMER DIRECTORY
