/**
 * Opens the Admin Command Center modal (#adminHubModal).
 * Restricts access to users with verified 'Admin' role.
 */
function openAdminHubModal() {
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : false;

  if (!isAdmin) {
    if (typeof showToast === 'function') {
      showToast('⚠️ Access Denied: Admin privileges required to open Command Center.', 'error');
    }
    return;
  }

  const modalEl = document.getElementById('adminHubModal');
  if (!modalEl) return;

  modalEl.classList.add('active');

  // Restore previous desktop maximize preference
  try {
    const savedMax = localStorage.getItem('budget_master_admin_maximized');
    const card = document.querySelector('.admin-hub-card');
    const icon = document.getElementById('adminHubSizeIcon');
    if (card && savedMax === 'true') {
      card.classList.add('maximized');
      if (icon) icon.textContent = '🗂️';
    }
  } catch (e) {}

  // Sync simulator cards with current appState tier
  const activeTier = (typeof appState !== 'undefined' && appState.userTier)
    ? appState.userTier
    : 'executive';
  updateSimulatorCardsUI(activeTier);

  // Switch to simulator tab by default
  switchAdminHubTab('simulator');

  // Pre-load customer list and calculate executive KPI stats
  renderAdminHubUsers();

  // [FEAT-62] Update wishlist count badge in Admin Command Center
  if (typeof updateAdminWishlistCountBadge === 'function') {
    updateAdminWishlistCountBadge();
  }
}

/**
 * Toggles widescreen maximized / restore view for desktop users.
 */
function toggleAdminHubMaximize() {
  const card = document.querySelector('.admin-hub-card');
  const icon = document.getElementById('adminHubSizeIcon');
  const btn = document.getElementById('btnToggleAdminHubMaximize');
  if (!card) return;

  const isMax = card.classList.toggle('maximized');
  if (icon) icon.textContent = isMax ? '🗂️' : '🛑';
  if (btn) btn.title = isMax ? 'Restore Standard View (M)' : 'Toggle Widescreen Desktop View (M)';

  try {
    localStorage.setItem('budget_master_admin_maximized', String(isMax));
  } catch (e) {}
}

/**
 * Dynamically displays the Admin Command Center button in the desktop sidebar
 * only when the active session is a verified Admin.
 */
function updateAdminSidebarVisibility() {
  const btn = document.getElementById('btnSidebarAdminHub');
  const isAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : false;
  if (btn) {
    btn.style.display = isAdmin ? 'flex' : 'none';
  }
  const btnDockPublish = document.getElementById('btnAdminPublishGlobalLayout');
  if (btnDockPublish) {
    btnDockPublish.style.display = isAdmin ? 'inline-flex' : 'none';
  }
  const btnModalPublish = document.getElementById('btnModalAdminPublishGlobalLayout');
  if (btnModalPublish) {
    btnModalPublish.style.display = isAdmin ? 'inline-flex' : 'none';
  }
  const btnAdminTabLayouts = document.getElementById('btnAdminTabLayouts');
  if (btnAdminTabLayouts) {
    btnAdminTabLayouts.style.display = isAdmin ? 'inline-flex' : 'none';
  }
  if (typeof updateFaqAiKeyUI === 'function') {
    updateFaqAiKeyUI();
  }
  if (typeof updateAdminGlobalLayoutUI === 'function') {
    updateAdminGlobalLayoutUI();
  }
}

/**
 * Closes the Admin Command Center modal (#adminHubModal).
 */
function closeAdminHubModal() {
  const modalEl = document.getElementById('adminHubModal');
  if (modalEl) {
    modalEl.classList.remove('active');
  }
}

/**
 * Switches between segmented tabs inside the Admin Command Center:
 * 'simulator' | 'customers' | 'billing' | 'wishlist' | 'notepad'
 */
function switchAdminHubTab(tabName) {
  // Update tab navigation buttons
  const tabBtns = document.querySelectorAll('#adminHubTabs .btn-admin-tab');
  tabBtns.forEach(btn => {
    const isTarget = btn.getAttribute('data-admin-tab') === tabName;
    btn.classList.toggle('active', isTarget);
  });

  // Toggle tab panes
  const paneSim = document.getElementById('adminTabSimulator');
  const paneCust = document.getElementById('adminTabCustomers');
  const paneBill = document.getElementById('adminTabBilling');
  const paneWish = document.getElementById('adminTabWishlist');
  const paneNote = document.getElementById('adminTabNotepad');
  const paneLayout = document.getElementById('adminTabLayouts');

  if (paneSim) paneSim.style.display = tabName === 'simulator' ? 'block' : 'none';
  if (paneCust) paneCust.style.display = tabName === 'customers' ? 'block' : 'none';
  if (paneBill) paneBill.style.display = tabName === 'billing' ? 'block' : 'none';
  if (paneWish) paneWish.style.display = tabName === 'wishlist' ? 'block' : 'none';
  if (paneNote) paneNote.style.display = tabName === 'notepad' ? 'block' : 'none';
  if (paneLayout) paneLayout.style.display = tabName === 'layouts' ? 'block' : 'none';

  // Lazy render customer directory, feature wishlist, notepad, or universal layout on demand
  if (tabName === 'customers') {
    const res = renderAdminHubUsers();
    setTimeout(() => {
      if (typeof initAdminTableColumnResizing === 'function') initAdminTableColumnResizing();
    }, 60);
    return res;
  }
  if (tabName === 'wishlist' && typeof renderAdminWishlist === 'function') {
    return renderAdminWishlist();
  }
  if (tabName === 'notepad' && typeof loadAdminNotepad === 'function') {
    return loadAdminNotepad();
  }
  if (tabName === 'layouts' && typeof renderAdminGlobalLayoutTab === 'function') {
    return renderAdminGlobalLayoutTab();
  }
}

