function openUpgradeModal(targetTier = 'pro') {
  showUpgradePrompt('[FEAT-38]', 'NirvTrack Subscription Plans', null);
  if (targetTier === 'executive') {
    handleAltTierPaymentCheckout();
  }
}

function closeUpgradeModal() {
  const modal = document.getElementById('upgradePromptModal');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('active');
  }
}

function handleTierPaymentCheckout(tier) {
  const currentTier = (typeof appState !== 'undefined' && appState.userTier)
    ? appState.userTier.toLowerCase()
    : 'free';
  const targetTier = tier || (pendingUpgradeState && pendingUpgradeState.requiredTier) || 'pro';

  const proCfg = (typeof NIRVTRACK_TIER_CONFIG !== 'undefined' && NIRVTRACK_TIER_CONFIG.pro)
    ? NIRVTRACK_TIER_CONFIG.pro
    : { pricePhp: 199, durationDays: 30 };
  const execCfg = (typeof NIRVTRACK_TIER_CONFIG !== 'undefined' && NIRVTRACK_TIER_CONFIG.executive)
    ? NIRVTRACK_TIER_CONFIG.executive
    : { pricePhp: 599, durationDays: 30 };

  const tierInfo = {
    pro: { name: 'Budget Pro', price: `₱${proCfg.pricePhp}.00 / ${proCfg.durationDays} days`, badge: '⚡ NIRVTRACK PRO' },
    executive: { name: 'Executive Wealth', price: `₱${execCfg.pricePhp}.00 / ${execCfg.durationDays} days`, badge: '👑 EXECUTIVE WEALTH' }
  }[targetTier] || { name: 'Budget Pro', price: `₱${proCfg.pricePhp}.00 / ${proCfg.durationDays} days`, badge: '⚡ NIRVTRACK PRO' };

  closeUpgradeModal();

  activePayPalTargetTier = targetTier;

  const modal = document.getElementById('paymentPlaceholderModal');
  if (modal) {
    const badge = document.getElementById('paymentModalBadge');
    const title = document.getElementById('paymentModalTitle');
    const planLabel = document.getElementById('paymentModalPlanLabel');
    const priceLabel = document.getElementById('paymentModalPriceLabel');

    if (badge) badge.textContent = tierInfo.badge;
    if (title) title.textContent = `Upgrade to ${tierInfo.name}`;
    if (planLabel) planLabel.textContent = `${tierInfo.name} Subscription`;
    if (priceLabel) priceLabel.textContent = tierInfo.price;

    modal.style.display = 'flex';
    modal.classList.add('active');

    // Route exclusively to PayMongo while PayPal is temporarily disabled
    switchPaymentGateway('paymongo');
  }
}

