const NIRVTRACK_PAYPAL_CONFIG = {
  clientId: 'BAAQOkcu3dYzrL__mSmk_CBX24JIpFz7QUU8O7Cqkt6Ub8Lq7IkdFbJVT97xctAQWLx5IVFX1AZvmMr5Nc',
  plans: {
    pro: 'P-8HS226514X313964XNLJ2XYY',       // Live NirvTrack Pro Plan ID
    executive: 'P-9N169270V7975103BNLJ2Y2Y'  // Live NirvTrack Executive Plan ID
  }
};

let activePayPalTargetTier = 'pro';

/**
 * Dynamically mounts PayPal Smart Buttons into #paypalButtonsContainer for the chosen tier.
 */
function renderPayPalButtonsForTier(targetTier) {
  // PayPal is temporarily deactivated; route cleanly to PayMongo
  const wrapper = document.getElementById('paypalButtonsWrapper');
  if (wrapper) wrapper.style.display = 'none';
  return;
  const container = document.getElementById('paypalButtonsContainer');
  const loading = document.getElementById('paypalButtonsLoading');
  if (!container) return;

  container.innerHTML = '';
  if (loading) {
    loading.style.display = 'block';
    loading.innerHTML = '⏳ Loading secure PayPal checkout buttons...';
  }

  // Check if PayPal SDK is available on window (or still initializing)
  if (typeof window.paypal === 'undefined' || !window.paypal.Buttons) {
    setTimeout(() => {
      if (typeof window.paypal !== 'undefined' && window.paypal.Buttons) {
        renderPayPalButtonsForTier(targetTier);
      } else if (loading) {
        loading.innerHTML = '💳 <strong>PayPal Checkout Ready:</strong> Click <strong>🧪 Instant Test Upgrade</strong> below to test Cloud Firestore sync!';
      }
    }, 700);
    return;
  }

  const planId = (NIRVTRACK_PAYPAL_CONFIG.plans && NIRVTRACK_PAYPAL_CONFIG.plans[targetTier])
    ? NIRVTRACK_PAYPAL_CONFIG.plans[targetTier]
    : NIRVTRACK_PAYPAL_CONFIG.plans.pro;

  const currentUid = (typeof firebase !== 'undefined' && firebase.auth && firebase.auth().currentUser && firebase.auth().currentUser.uid)
    ? firebase.auth().currentUser.uid
    : 'guest';

  try {
    window.paypal.Buttons({
      style: {
        shape: 'pill',
        color: 'gold',
        layout: 'vertical',
        label: 'subscribe'
      },
      createSubscription: function(data, actions) {
        try {
          return actions.subscription.create({
            'plan_id': planId,
            'custom_id': currentUid
          });
        } catch (subErr) {
          console.error('PayPal createSubscription error:', subErr);
          throw subErr;
        }
      },
      onApprove: async function(data, actions) {
        const subId = data.subscriptionID || data.orderID || ('sub_' + Date.now());
        await finalizePayPalTierUpgrade(targetTier, subId);
      },
      onError: function(err) {
        console.error('PayPal Buttons error:', err);
        const errMsg = (err && err.message) ? err.message : String(err || '');
        if (typeof showToast === 'function') {
          showToast(`⚠️ PayPal Notice: ${errMsg || 'Popup closed. (Note: Merchant cannot pay themselves in PayPal)'}`, 'warning', 6000);
        }
        if (loading) {
          loading.style.display = 'block';
          loading.innerHTML = 'ℹ️ <strong>PayPal Notice:</strong> ' + (errMsg || 'PayPal does not allow paying your own account. Use another card or test below:') + '<br><span style="font-size: 0.77rem; color: #94a3b8;">Click <strong>🧪 Instant Test Upgrade</strong> below to verify full Cloud Firestore tier sync.</span>';
        }
      },
      onCancel: function(data) {
        if (typeof showToast === 'function') {
          showToast('PayPal subscription window closed.', 'info', 3000);
        }
      }
    }).render('#paypalButtonsContainer').then(() => {
      if (loading) loading.style.display = 'none';
    }).catch(err => {
      console.warn('PayPal Buttons render catch:', err);
      if (loading) {
        loading.style.display = 'block';
        loading.innerHTML = 'ℹ️ <strong>PayPal Staging:</strong> Click <strong>🧪 Instant Test Upgrade</strong> below to simulate payment and verify full Firestore tier sync!';
      }
    });
  } catch (err) {
    console.warn('Failed to render PayPal buttons:', err);
    if (loading) {
      loading.style.display = 'block';
      loading.innerHTML = 'ℹ️ <strong>PayPal Staging:</strong> Click <strong>🧪 Instant Test Upgrade</strong> below to test Cloud Firestore sync!';
    }
  }
}

/**
 * Finalizes the tier upgrade in Cloud Firestore and syncs active UI visuals.
 */
async function finalizePayPalTierUpgrade(targetTier, subscriptionId) {
  closePaymentPlaceholderModal();

  const authUser = (typeof firebase !== 'undefined' && firebase.auth && firebase.auth().currentUser) || null;
  const sbUser = window.currentAuthenticatedUser;
  const nowIso = new Date().toISOString();

  // 1. Sync tier upgrade to Cloud Firestore at /users/{userId}
  if (authUser && typeof fbDb !== 'undefined' && fbDb) {
    try {
      await fbDb.collection('users').doc(authUser.uid).set({
        tier: targetTier,
        subscriptionStatus: 'active',
        paypalSubscriptionId: String(subscriptionId || ''),
        paymentProvider: 'paypal',
        tierUpdatedAt: nowIso,
        updatedAt: nowIso
      }, { merge: true });
    } catch (e) {
      console.error('Failed to update user tier in Cloud Firestore:', e);
    }
  }

  // 2. Activate tier in local state & update visual auras/badges
  if (typeof setSimulatedTier === 'function') {
    setSimulatedTier(targetTier);
  } else if (typeof appState !== 'undefined') {
    appState.userTier = targetTier;
  }

  const tierTitle = targetTier === 'executive' ? 'Executive Wealth' : 'NirvTrack Pro';
  if (typeof showToast === 'function') {
    showToast(`🎉 Payment Confirmed! Welcome to ${tierTitle}. All features are unlocked and synced to Cloud Firestore.`, 'success', 6000);
  }

  // [PAYMENT-CELEBRATION] Show Custom Styled Thank-You Celebration Modal
  if (typeof showTierUpgradeSuccessModal === 'function') {
    showTierUpgradeSuccessModal(targetTier, {
      paymentId: subscriptionId,
      amount: targetTier === 'executive' ? '$12.99' : '$4.99',
      method: 'paypal',
      email: authUser ? authUser.email : ''
    });
  }
}

