/**
 * Upgrades a user in Cloud Firestore by their email address.
 */
async function upgradeUserByEmail(email, tier = 'pro', paymentId = 'pay_live', customAmountPhp = null) {
  if (typeof fbDb === 'undefined' || !fbDb) {
    if (typeof showToast === 'function') showToast('Firestore not initialized', 'error');
    return;
  }
  try {
    const q = await fbDb.collection('users').where('email', '==', email.toLowerCase().trim()).limit(1).get();
    if (q.empty) {
      if (typeof showToast === 'function') showToast(`User ${email} not found in Firestore.`, 'warning');
      return;
    }
    const userDoc = q.docs[0];
    const existingData = userDoc.data() || {};
    const nowIso = new Date().toISOString();
    const isExec = tier === 'executive';
    const tierCfg = (typeof NIRVTRACK_TIER_CONFIG !== 'undefined' && NIRVTRACK_TIER_CONFIG[tier])
      ? NIRVTRACK_TIER_CONFIG[tier]
      : { pricePhp: (isExec ? 599 : 199), durationDays: 30 };
    const durationDays = Number(tierCfg.durationDays) || 30;
    const endIso = new Date(Date.now() + durationDays * 24 * 60 * 60 * 1000).toISOString();

    let amt = '';
    if (customAmountPhp !== null && !isNaN(Number(customAmountPhp)) && Number(customAmountPhp) > 0) {
      amt = `\u20B1${Number(customAmountPhp).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    } else if (existingData.amountPaid && existingData.tier === tier) {
      // Preserve actual logged purchase amount if already recorded for this tier
      amt = existingData.amountPaid;
    } else {
      const actualPhpNum = Number(tierCfg.pricePhp) || (isExec ? 599 : 199);
      amt = `\u20B1${actualPhpNum.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }

    await fbDb.collection('users').doc(userDoc.id).set({
      tier: tier,
      tierStatus: 'active',
      subscriptionStatus: 'active',
      paymentProvider: 'paymongo',
      paymongoPaymentId: paymentId,
      paymongoPaymentMethod: existingData.paymongoPaymentMethod || 'qrph',
      lastPaymentAmount: amt,
      amountPaid: amt,
      subscriptionStartDate: existingData.subscriptionStartDate || nowIso,
      subscriptionEndDate: existingData.subscriptionEndDate || endIso,
      upgradedAt: existingData.upgradedAt || nowIso,
      tierUpdatedAt: nowIso,
      maxWorkspaces: isExec ? 99999 : 5,
      updatedAt: nowIso
    }, { merge: true });

    if (typeof showToast === 'function') {
      showToast(`⚡ User ${email} successfully synced to ${tier.toUpperCase()} (${amt})!`, 'success', 6000);
    }
    if (typeof renderAdminHubUsers === 'function') {
      renderAdminHubUsers();
    }
  } catch (err) {
    console.error('upgradeUserByEmail error:', err);
    if (typeof showToast === 'function') showToast(`Error upgrading user: ${err.message}`, 'error');
  }
}

