/**
 * Synthesizes an elegant, uplifting major chord chime using Web Audio API.
 */
function playCelebrationChime() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const notes = [523.25, 659.25, 783.99, 1046.50]; // C5, E5, G5, C6 (Harmonic arpeggio chord)
    notes.forEach((freq, idx) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, ctx.currentTime + idx * 0.07);
      gain.gain.setValueAtTime(0, ctx.currentTime + idx * 0.07);
      gain.gain.linearRampToValueAtTime(0.18, ctx.currentTime + idx * 0.07 + 0.03);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + idx * 0.07 + 0.65);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(ctx.currentTime + idx * 0.07);
      osc.stop(ctx.currentTime + idx * 0.07 + 0.7);
    });
  } catch (e) {}
}

/**
 * Lightweight 60fps micro-particle confetti canvas engine matching tier colors.
 */
function launchCelebrationConfetti(tier) {
  const canvas = document.getElementById('celebrationConfettiCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  if (!ctx) return;

  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  const isExec = tier === 'executive';
  const colors = isExec
    ? ['#fbbf24', '#f59e0b', '#10b981', '#34d399', '#fef08a', '#ffffff']
    : ['#06b6d4', '#38bdf8', '#3b82f6', '#14b8a6', '#67e8f9', '#ffffff'];

  const particles = [];
  const particleCount = 75;

  for (let i = 0; i < particleCount; i++) {
    particles.push({
      x: canvas.width / 2 + (Math.random() - 0.5) * 80,
      y: canvas.height * 0.45 + (Math.random() - 0.5) * 50,
      w: Math.random() * 8 + 4,
      h: Math.random() * 6 + 4,
      vx: (Math.random() - 0.5) * 12,
      vy: (Math.random() - 0.9) * 12 - 2,
      rotation: Math.random() * 360,
      vRotation: (Math.random() - 0.5) * 10,
      color: colors[Math.floor(Math.random() * colors.length)],
      opacity: 1,
      gravity: 0.22,
      drag: 0.97
    });
  }

  let startTime = Date.now();

  function animate() {
    const elapsed = Date.now() - startTime;
    if (elapsed > 3500) {
      stopCelebrationConfetti();
      return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    particles.forEach(p => {
      p.vx *= p.drag;
      p.vy = p.vy * p.drag + p.gravity;
      p.x += p.vx;
      p.y += p.vy;
      p.rotation += p.vRotation;

      if (elapsed > 2000) {
        p.opacity = Math.max(0, 1 - (elapsed - 2000) / 1500);
      }

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate((p.rotation * Math.PI) / 180);
      ctx.globalAlpha = p.opacity;
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
      ctx.restore();
    });

    celebrationConfettiAnimId = requestAnimationFrame(animate);
  }

  stopCelebrationConfetti();
  animate();
}

/**
 * Halts confetti rendering.
 */
function stopCelebrationConfetti() {
  if (celebrationConfettiAnimId) {
    cancelAnimationFrame(celebrationConfettiAnimId);
    celebrationConfettiAnimId = null;
  }
  const canvas = document.getElementById('celebrationConfettiCanvas');
  if (canvas) {
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
  }
}

/**
 * Checks for return URL parameters (e.g., ?payment=success&tier=executive)
 */
async function checkUrlPaymentParams() {
  try {
    const params = new URLSearchParams(window.location.search);
    if (params.get('payment') === 'success') {
      const rawTier = (params.get('tier') || 'executive').toLowerCase();
      const targetTier = (rawTier === 'pro') ? 'pro' : 'executive';
      const sessionId = params.get('session_id') || ('pay_' + Date.now().toString(36));

      // Clean URL immediately without page refresh
      try {
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {}

      // Execute instant tier upgrade and sync
      setTimeout(async () => {
        await finalizePayMongoTierUpgrade(targetTier, sessionId, 'paymongo');
      }, 500);
    }
  } catch (e) {
    console.warn('Notice checking URL payment params:', e);
  }
}

