/**
 * Simulates receiving an incoming PayMongo webhook event (checkout_session.payment.paid).
 */
async function simulatePayMongoWebhook(tier, method) {
  const targetTier = tier || 'pro';
  const payMethod = method || 'gcash';
  const tierCfg = (typeof NIRVTRACK_TIER_CONFIG !== 'undefined' && NIRVTRACK_TIER_CONFIG[targetTier])
    ? NIRVTRACK_TIER_CONFIG[targetTier]
    : { pricePhp: (targetTier === 'executive' ? 599 : 199), durationDays: 30 };
  const activePriceNum = Number(tierCfg.pricePhp) || (targetTier === 'executive' ? 599 : 199);
  const durationDays = Number(tierCfg.durationDays) || 30;
  const priceAmount = `\u20B1${activePriceNum.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  const terminalLog = document.getElementById('adminWebhookTerminalLog');
  const currentUser = (typeof fbAuth !== 'undefined' && fbAuth && fbAuth.currentUser)
    ? fbAuth.currentUser
    : (typeof currentAuthenticatedUser !== 'undefined' ? currentAuthenticatedUser : null);

  const mockPayMongoEvent = {
    data: {
      id: `evt_pm_${Date.now()}`,
      type: 'event',
      attributes: {
        type: 'checkout_session.payment.paid',
        data: {
          id: `cs_${Date.now()}`,
          type: 'checkout_session',
          attributes: {
            payment_method_used: payMethod,
            amount: Math.round(activePriceNum * 100),
            currency: 'PHP',
            status: 'paid',
            line_items: [{ name: `NirvTrack ${targetTier.toUpperCase()} Plan` }]
          }
        }
      }
    }
  };

  if (terminalLog) {
    const timestamp = new Date().toLocaleTimeString();
    const isQrPh = payMethod.toLowerCase() === 'qrph';
    const methodDesc = isQrPh
      ? '⚡ QR Ph (National QR / InstaPay Rail Verified via Mobile Banking Biometrics/MPIN)'
      : `${payMethod.toUpperCase()} E-Wallet`;
    terminalLog.innerHTML = `
      <span style="color: #34d399;">[${timestamp}] [PayMongo Webhook Received]</span> Event: checkout_session.payment.paid<br>
      <span style="color: #38bdf8;">→ Method:</span> ${methodDesc}<br>
      <span style="color: #fbbf24;">→ Amount Logged:</span> ${priceAmount} (${durationDays}d) | <span style="color: #34d399;">Rail:</span> InstaPay / BancNet Settlement Cleared<br>
      <span style="color: #a78bfa;">→ Action:</span> Upgrading Firestore user doc to tier: <strong>${targetTier.toUpperCase()}</strong> (amountPaid: ${priceAmount})...<br>
      <span style="color: #34d399;">✓ [200 OK] Handshake verified. Tier unlocked.</span>
    `;
  }

  setSimulatedTier(targetTier);

  if (typeof fbDb !== 'undefined' && fbDb && currentUser) {
    try {
      const nowIso = new Date().toISOString();
      const endIso = new Date(Date.now() + durationDays * 24 * 60 * 60 * 1000).toISOString();
      await fbDb.collection('users').doc(currentUser.uid).set({
        tier: targetTier,
        tierStatus: 'active',
        subscriptionStatus: 'active',
        paymentProvider: 'paymongo',
        paymongoPaymentId: mockPayMongoEvent.data.attributes.data.id,
        paymongoPaymentMethod: payMethod,
        lastPaymentAmount: priceAmount,
        amountPaid: priceAmount,
        subscriptionStartDate: nowIso,
        subscriptionEndDate: endIso,
        lastPaymentDate: nowIso,
        tierUpdatedAt: nowIso,
        maxWorkspaces: targetTier === 'executive' ? 99999 : 5,
        updatedAt: nowIso
      }, { merge: true });
    } catch (e) {}
  }

  if (typeof renderAdminHubUsers === 'function') {
    renderAdminHubUsers();
  }

  if (typeof showToast === 'function') {
    const methodToast = payMethod.toLowerCase() === 'qrph' ? '⚡ QR Ph (Bank Biometrics)' : payMethod.toUpperCase();
    showToast(`🇵🇭 PayMongo Verified! Received ${methodToast} Webhook → Unlocked ${targetTier.toUpperCase()} (${priceAmount})`);
  }
}
