/**
 * Filters the customer roster table by search query and tier dropdown.
 */
function filterAdminHubUsers() {
  const searchInput = document.getElementById('adminUserSearchInput');
  const tierFilter = document.getElementById('adminUserTierFilter');
  const clearBtn = document.getElementById('btnClearAdminUserSearch');

  const query = searchInput ? searchInput.value.trim().toLowerCase() : '';
  const selectedTier = tierFilter ? tierFilter.value : 'all';

  if (clearBtn) {
    clearBtn.style.display = query.length > 0 ? 'block' : 'none';
  }

  const filtered = cachedAdminUserList.filter(u => {
    const matchesQuery = !query ||
      (u.displayName && u.displayName.toLowerCase().includes(query)) ||
      (u.email && u.email.toLowerCase().includes(query)) ||
      (u.uid && u.uid.toLowerCase().includes(query)) ||
      (u.provider && u.provider.toLowerCase().includes(query));

    const matchesTier = (selectedTier === 'all') || (u.tier === selectedTier);

    return matchesQuery && matchesTier;
  });

  renderAdminHubUsersRows(filtered);
}

/**
 * Sorts customer table columns (name, role, tier, status, provider, createdAt, lastLogin).
 */
function sortAdminHubUsers(column) {
  if (adminUserSortState.column === column) {
    adminUserSortState.dir = adminUserSortState.dir === 'asc' ? 'desc' : 'asc';
  } else {
    adminUserSortState.column = column;
    adminUserSortState.dir = 'asc';
  }

  const factor = adminUserSortState.dir === 'asc' ? 1 : -1;
  cachedAdminUserList.sort((a, b) => {
    if (column === 'name') {
      const valA = (a.displayName || a.email || '').toLowerCase();
      const valB = (b.displayName || b.email || '').toLowerCase();
      return valA.localeCompare(valB) * factor;
    } else if (column === 'createdAt') {
      const valA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
      const valB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
      return (valA - valB) * factor;
    } else if (column === 'lastLogin') {
      const valA = a.lastLogin ? new Date(a.lastLogin).getTime() : 0;
      const valB = b.lastLogin ? new Date(b.lastLogin).getTime() : 0;
      return (valA - valB) * factor;
    } else if (column === 'payment' || column === 'subscription') {
      const valA = (a.lifecycle ? `${a.lifecycle.paymentMethod} ${a.lifecycle.amountPaid}` : `${a.paymentProvider || ''}`).toLowerCase();
      const valB = (b.lifecycle ? `${b.lifecycle.paymentMethod} ${b.lifecycle.amountPaid}` : `${b.paymentProvider || ''}`).toLowerCase();
      return valA.localeCompare(valB) * factor;
    } else if (column === 'lifecycle') {
      const valA = (a.lifecycle && a.lifecycle.daysLeft !== null && typeof a.lifecycle.daysLeft === 'number') ? a.lifecycle.daysLeft : 999999;
      const valB = (b.lifecycle && b.lifecycle.daysLeft !== null && typeof b.lifecycle.daysLeft === 'number') ? b.lifecycle.daysLeft : 999999;
      return (valA - valB) * factor;
    } else {
      const valA = String(a[column] || '').toLowerCase();
      const valB = String(b[column] || '').toLowerCase();
      return valA.localeCompare(valB) * factor;
    }
  });

  filterAdminHubUsers();
}

/**
 * [FEAT-RESIZE] Column resizing configuration and persistence system.
 * Default column widths in pixels (11 Columns):
 * 0: User / Customer (200px)
 * 1: Firebase UID (115px)
 * 2: Provider (95px)
 * 3: Account Role (105px)
 * 4: Active Tier (120px)
 * 5: Payment & Amount (185px)
 * 6: Subscription Lifecycle (215px)
 * 7: Created Date (115px)
 * 8: Last Login (125px)
 * 9: Status (110px)
 * 10: Actions (180px)
 */
const DEFAULT_ADMIN_COL_WIDTHS = [200, 115, 95, 105, 120, 185, 215, 115, 125, 110, 180];
const STORAGE_KEY_ADMIN_COL_WIDTHS = 'budget_master_admin_col_widths_v3';

function getAdminTableColumnWidths() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY_ADMIN_COL_WIDTHS);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length === DEFAULT_ADMIN_COL_WIDTHS.length) {
        return parsed.map((w, i) => Math.max(65, Number(w) || DEFAULT_ADMIN_COL_WIDTHS[i]));
      }
    }
  } catch (e) {}
  return [...DEFAULT_ADMIN_COL_WIDTHS];
}

function applyAdminTableColumnWidths(widths) {
  const table = document.getElementById('adminUsersTable');
  if (!table) return;
  const ths = table.querySelectorAll('thead th');
  if (!ths || ths.length === 0) return;

  let totalWidth = 0;
  widths.forEach((w, idx) => {
    if (ths[idx]) {
      const pixelWidth = Math.max(65, Number(w) || DEFAULT_ADMIN_COL_WIDTHS[idx] || 120);
      ths[idx].style.width = `${pixelWidth}px`;
      ths[idx].style.minWidth = `${pixelWidth}px`;
      ths[idx].style.maxWidth = `${pixelWidth}px`;
      totalWidth += pixelWidth;
    }
  });

  if (totalWidth > 0) {
    table.style.minWidth = `${totalWidth}px`;
  }
}

function initAdminTableColumnResizing() {
  const table = document.getElementById('adminUsersTable');
  if (!table) return;
  const ths = table.querySelectorAll('thead th');
  if (!ths || ths.length === 0) return;

  const currentWidths = getAdminTableColumnWidths();
  applyAdminTableColumnWidths(currentWidths);

  ths.forEach((th, idx) => {
    // Only append handle once
    let handle = th.querySelector('.col-resize-handle');
    if (!handle) {
      handle = document.createElement('div');
      handle.className = 'col-resize-handle';
      handle.title = 'Drag horizontally to adjust column width. Double-click to reset.';
      th.appendChild(handle);
    }

    let startX = 0;
    let startWidth = 0;

    const onMouseMove = (e) => {
      const deltaX = e.clientX - startX;
      const newWidth = Math.max(65, startWidth + deltaX);
      th.style.width = `${newWidth}px`;
      th.style.minWidth = `${newWidth}px`;
      th.style.maxWidth = `${newWidth}px`;
      currentWidths[idx] = newWidth;

      const totalWidth = currentWidths.reduce((sum, w) => sum + (Number(w) || 100), 0);
      table.style.minWidth = `${totalWidth}px`;
    };

    const onMouseUp = () => {
      document.removeEventListener('mousemove', onMouseMove);
      document.removeEventListener('mouseup', onMouseUp);
      document.body.style.cursor = '';
      table.classList.remove('is-resizing');
      handle.classList.remove('active');

      try {
        localStorage.setItem(STORAGE_KEY_ADMIN_COL_WIDTHS, JSON.stringify(currentWidths));
      } catch (e) {}

      if (typeof showToast === 'function') {
        showToast(`↔️ Adjusted column width to ${currentWidths[idx]}px`, 'info', 1600);
      }
    };

    handle.onmousedown = (e) => {
      e.preventDefault();
      e.stopPropagation(); // Avoid triggering sortAdminHubUsers on the parent th
      startX = e.clientX;
      startWidth = th.offsetWidth;
      document.body.style.cursor = 'col-resize';
      table.classList.add('is-resizing');
      handle.classList.add('active');

      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    };

    handle.ondblclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      const defaultW = DEFAULT_ADMIN_COL_WIDTHS[idx] || 120;
      currentWidths[idx] = defaultW;
      th.style.width = `${defaultW}px`;
      th.style.minWidth = `${defaultW}px`;
      th.style.maxWidth = `${defaultW}px`;
      try {
        localStorage.setItem(STORAGE_KEY_ADMIN_COL_WIDTHS, JSON.stringify(currentWidths));
      } catch (err) {}
      applyAdminTableColumnWidths(currentWidths);
      if (typeof showToast === 'function') {
        showToast(`↔️ Reset column width to ${defaultW}px`, 'info', 1800);
      }
    };
  });
}

function resetAdminTableColumnWidths() {
  try {
    localStorage.removeItem(STORAGE_KEY_ADMIN_COL_WIDTHS);
  } catch (e) {}
  applyAdminTableColumnWidths(DEFAULT_ADMIN_COL_WIDTHS);
  if (typeof showToast === 'function') {
    showToast('↔️ All columns reset to default spacious layout!', 'success', 3000);
  }
}

/**
 * Calculates complete subscription lifecycle metrics for any user:
 * payment method, amount paid, purchase start date, subscription end date, and days remaining.
 */
function calculateSubscriptionLifecycle(u) {
  const isSuperAdminEmail = u.email && u.email.toLowerCase() === 'nirvash0074@gmail.com';
  const isSuperAdmin = isSuperAdminEmail || (u.role === 'Admin');
  const tier = (u.tier || 'free').toLowerCase();
  const isPaidTier = tier === 'pro' || tier === 'executive';

  // 1. Superadmin / Lifetime License
  if (isSuperAdmin) {
    const startIso = u.createdAt || u.tierUpdatedAt || new Date().toISOString();
    return {
      isSubscribed: true,
      tier: tier,
      paymentMethod: '👑 Superadmin (Lifetime)',
      paymentProvider: 'admin',
      amountPaid: 'Lifetime License',
      startDate: startIso,
      startDateFormatted: formatAdminDate(startIso),
      endDate: 'Perpetual',
      endDateFormatted: 'Perpetual (No Expiration)',
      daysLeft: 99999,
      daysLeftLabel: '👑 Lifetime Access',
      daysLeftBadge: `<span style="display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 700; background: rgba(168, 85, 247, 0.2); color: #c084fc; border: 1px solid rgba(168, 85, 247, 0.45); white-space: nowrap;">👑 Lifetime Access</span>`,
      statusText: 'Active Superadmin'
    };
  }

  // 2. Free Core Plan (No Subscription)
  if (!isPaidTier) {
    return {
      isSubscribed: false,
      tier: 'free',
      paymentMethod: '🌱 Free Core',
      paymentProvider: 'none',
      amountPaid: '₱0.00 (Free)',
      startDate: null,
      startDateFormatted: '—',
      endDate: null,
      endDateFormatted: 'Perpetual Free',
      daysLeft: null,
      daysLeftLabel: '🌱 Free Plan (No Expiry)',
      daysLeftBadge: `<span style="display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 600; background: rgba(148, 163, 184, 0.12); color: #94a3b8; border: 1px solid rgba(148, 163, 184, 0.25); white-space: nowrap;">🌱 Free Plan</span>`,
      statusText: 'Free Core'
    };
  }

  // 3. Paid Tier (Pro or Executive)
  let method = 'Unknown';
  let provider = String(u.paymentProvider || 'none').toLowerCase();
  if (u.paymongoPaymentId || u.paymongoPaymentMethod || provider === 'paymongo') {
    const rawMethod = (u.paymongoPaymentMethod || 'qrph').toLowerCase();
    const methodNames = {
      qrph: 'QR Ph (GCash/Maya/Bank)',
      gcash: 'GCash',
      paymaya: 'Maya',
      card: 'Credit/Debit Card',
      dob: 'Online Banking',
      billease: 'BillEase'
    };
    method = `PayMongo • ${methodNames[rawMethod] || rawMethod.toUpperCase()}`;
    provider = 'paymongo';
  } else if (u.paypalSubscriptionId || provider === 'paypal') {
    method = 'PayPal Live Subscription';
    provider = 'paypal';
  } else if (provider === 'stripe') {
    method = 'Stripe Checkout';
  } else {
    method = 'Direct Admin Grant';
  }

  // Amount Paid (with accurate currency detection)
  const proCfg = (typeof NIRVTRACK_TIER_CONFIG !== 'undefined' && NIRVTRACK_TIER_CONFIG.pro) ? NIRVTRACK_TIER_CONFIG.pro : { pricePhp: 199, durationDays: 30 };
  const execCfg = (typeof NIRVTRACK_TIER_CONFIG !== 'undefined' && NIRVTRACK_TIER_CONFIG.executive) ? NIRVTRACK_TIER_CONFIG.executive : { pricePhp: 599, durationDays: 30 };
  let amount = '';
  const rawStoredAmt = String(u.lastPaymentAmount || u.amountPaid || '').trim();
  if (rawStoredAmt) {
    if (/^[0-9]+(\.[0-9]+)?$/.test(rawStoredAmt)) {
      const numVal = parseFloat(rawStoredAmt);
      amount = (provider === 'paypal' || provider === 'stripe')
        ? ('$' + numVal.toFixed(2))
        : ('\u20B1' + numVal.toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
    } else if (/^PHP\s*/i.test(rawStoredAmt)) {
      amount = rawStoredAmt.replace(/^PHP\s*/i, '\u20B1');
    } else if (/^USD\s*/i.test(rawStoredAmt)) {
      amount = rawStoredAmt.replace(/^USD\s*/i, '$');
    } else {
      amount = rawStoredAmt;
    }
  } else if (provider === 'paymongo') {
    const defPhp = tier === 'executive' ? execCfg.pricePhp : proCfg.pricePhp;
    amount = '\u20B1' + Number(defPhp).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  } else if (provider === 'paypal' || provider === 'stripe') {
    amount = tier === 'executive' ? '$12.99 / mo' : '$4.99 / mo';
  } else {
    const defPhp = tier === 'executive' ? execCfg.pricePhp : proCfg.pricePhp;
    amount = '\u20B1' + Number(defPhp).toLocaleString('en-PH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  // Start Date
  const startIso = u.subscriptionStartDate || u.upgradedAt || u.tierUpdatedAt || u.createdAt || new Date().toISOString();
  const startDateObj = new Date(startIso);
  const isValidDate = !isNaN(startDateObj.getTime());
  const startDateFormatted = isValidDate ? formatAdminDate(startIso) : 'Recent';

  // End Date (Default 30-day monthly billing cycle from purchase date)
  let endDateObj;
  if (u.subscriptionEndDate && !isNaN(new Date(u.subscriptionEndDate).getTime())) {
    endDateObj = new Date(u.subscriptionEndDate);
  } else if (isValidDate) {
    endDateObj = new Date(startDateObj.getTime() + (30 * 24 * 60 * 60 * 1000));
  } else {
    endDateObj = new Date(Date.now() + (30 * 24 * 60 * 60 * 1000));
  }
  const endDateFormatted = formatAdminDate(endDateObj.toISOString());

  // Days Remaining calculation
  const nowMs = Date.now();
  const diffMs = endDateObj.getTime() - nowMs;
  const daysLeft = Math.ceil(diffMs / (1000 * 60 * 60 * 24));

  let daysLeftBadge = '';
  let daysLeftLabel = '';
  let isExpired = false;

  if (daysLeft > 7) {
    daysLeftLabel = `${daysLeft} days remaining`;
    daysLeftBadge = `<span style="display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 700; background: rgba(16, 185, 129, 0.18); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.4); white-space: nowrap;" title="Renews / Expires: ${endDateFormatted}">⚡ ${daysLeft} days left</span>`;
  } else if (daysLeft > 0) {
    daysLeftLabel = `${daysLeft} days remaining (Ending soon)`;
    daysLeftBadge = `<span style="display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 700; background: rgba(245, 158, 11, 0.2); color: #fbbf24; border: 1px solid rgba(245, 158, 11, 0.45); white-space: nowrap;" title="Renews / Expires: ${endDateFormatted}">⏳ ${daysLeft} day${daysLeft === 1 ? '' : 's'} left</span>`;
  } else if (daysLeft === 0) {
    daysLeftLabel = `Subscription ends today`;
    daysLeftBadge = `<span style="display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 700; background: rgba(245, 158, 11, 0.25); color: #f59e0b; border: 1px solid rgba(245, 158, 11, 0.5); white-space: nowrap;" title="Ends today: ${endDateFormatted}">⚠️ Ends Today</span>`;
  } else {
    isExpired = true;
    daysLeftLabel = `Expired (${Math.abs(daysLeft)} days ago)`;
    daysLeftBadge = `<span style="display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 700; background: rgba(239, 68, 68, 0.18); color: #f87171; border: 1px solid rgba(239, 68, 68, 0.4); white-space: nowrap;" title="Expired on ${endDateFormatted}">❌ Expired (${Math.abs(daysLeft)}d ago)</span>`;
  }

  return {
    isSubscribed: !isExpired,
    tier: tier,
    paymentMethod: method,
    paymentProvider: provider,
    amountPaid: amount,
    startDate: isValidDate ? startIso : null,
    startDateFormatted: startDateFormatted,
    endDate: endDateObj.toISOString(),
    endDateFormatted: endDateFormatted,
    daysLeft: daysLeft,
    daysLeftLabel: daysLeftLabel,
    daysLeftBadge: daysLeftBadge,
    statusText: isExpired ? 'Expired Subscription' : 'Active Subscription'
  };
}

/**
 * Renders the subscription provider & status badge for a customer directory row.
 */
function renderAdminSubscriptionBadge(u) {
  const provider = String(u.paymentProvider || 'none').toLowerCase();
  const status = String(u.subscriptionStatus || 'inactive').toLowerCase();
  const isActive = status === 'active';

  let providerLabel = 'Free Core';
  let providerIcon = '🌱';
  let customStyle = 'background: rgba(148, 163, 184, 0.12); color: #94a3b8; border: 1px solid rgba(148, 163, 184, 0.25);';

  if (provider.includes('paypal')) {
    providerLabel = 'PayPal';
    providerIcon = '🅿️';
    customStyle = 'background: rgba(0, 112, 186, 0.18); color: #38bdf8; border: 1px solid rgba(0, 112, 186, 0.4);';
  } else if (provider.includes('paymongo')) {
    const rawMethod = (u.paymongoPaymentMethod || 'qrph').toUpperCase();
    providerLabel = `PayMongo (${rawMethod})`;
    providerIcon = '🇵🇭';
    customStyle = 'background: rgba(16, 185, 129, 0.18); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.4);';
  } else if (provider.includes('stripe')) {
    providerLabel = 'Stripe';
    providerIcon = '💳';
    customStyle = 'background: rgba(99, 102, 241, 0.18); color: #818cf8; border: 1px solid rgba(99, 102, 241, 0.4);';
  } else if (provider.includes('admin')) {
    providerLabel = 'Admin License';
    providerIcon = '👑';
    customStyle = 'background: rgba(168, 85, 247, 0.18); color: #c084fc; border: 1px solid rgba(168, 85, 247, 0.4);';
  }

  const statusColor = isActive ? '#34d399' : '#94a3b8';
  const statusDot = `<span style="width: 6px; height: 6px; border-radius: 50%; background: ${statusColor}; display: inline-block;"></span>`;

  return `
    <span style="display: inline-flex; align-items: center; gap: 5px; padding: 2px 7px; border-radius: 4px; font-size: 0.72rem; font-weight: 600; white-space: nowrap; ${customStyle}" title="Payment Gateway: ${providerLabel}">
      ${providerIcon} ${providerLabel}
    </span>
    <span style="display: inline-flex; align-items: center; gap: 4px; font-size: 0.70rem; color: ${statusColor}; font-weight: 600; white-space: nowrap;" title="Subscription Status: ${status}">
      ${statusDot} ${status}
    </span>
  `;
}

/**
 * Renders an array of user objects into the table body (11 Columns).
 */
function renderAdminHubUsersRows(users) {
  const tbody = document.getElementById('adminUsersTableBody');
  if (!tbody) return;

  if (users.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="11" style="text-align: center; padding: 32px; color: var(--text-muted);">
          No matching members found.
        </td>
      </tr>
    `;
    return;
  }

  const currentUser = (typeof fbAuth !== 'undefined' && fbAuth && fbAuth.currentUser)
    ? fbAuth.currentUser
    : (typeof currentAuthenticatedUser !== 'undefined' ? currentAuthenticatedUser : null);

  tbody.innerHTML = '';
  users.forEach(u => {
    const row = document.createElement('tr');

    const roleSelect = `
      <select id="selRoleOverride_${u.uid}" class="admin-role-select ${u.role === 'Admin' ? 'role-admin' : 'role-member'}" onchange="handleUserRoleSelectChange('${u.uid}', this)" title="Click to edit Account Role" style="min-width: 95px;">
        <option value="Admin" ${u.role === 'Admin' ? 'selected' : ''}>👑 Admin</option>
        <option value="Member" ${u.role !== 'Admin' ? 'selected' : ''}>👤 Member</option>
      </select>
    `;

    const tierPills = {
      free: `<span class="tier-sim-pill pill-free" style="padding: 3px 10px; font-size: 0.74rem; display: inline-flex; align-items: center; gap: 5px; white-space: nowrap;">🌱 Free Core</span>`,
      pro: `<span class="tier-sim-pill pill-pro" style="padding: 3px 10px; font-size: 0.74rem; display: inline-flex; align-items: center; gap: 5px; white-space: nowrap;">⚡ Pro</span>`,
      executive: `<span class="tier-sim-pill pill-exec" style="padding: 3px 10px; font-size: 0.74rem; display: inline-flex; align-items: center; gap: 5px; white-space: nowrap;">👑 Executive</span>`
    };
    const currentTierPill = tierPills[u.tier] || tierPills.free;

    const providerBadge = renderAdminProviderBadge(u.provider);
    const createdStr = formatAdminDate(u.createdAt);
    const lastLoginStr = formatAdminDateTime(u.lastLogin);
    const isCurrentUser = u.isSelf || (currentUser && currentUser.uid === u.uid);

    const safeEscapedName = (u.rawDisplayName || u.displayName || 'Member').replace(/'/g, "\\'").replace(/"/g, '&quot;');
    const safeEscapedEmail = (u.email || '').replace(/'/g, "\\'").replace(/"/g, '&quot;');

    const deleteButtonHtml = isCurrentUser
      ? `<button type="button" class="btn btn-ghost btn-sm" disabled title="You cannot remove your own active administrator account" style="opacity: 0.35; cursor: not-allowed; padding: 4px 8px; font-size: 0.8rem;">🔒</button>`
      : `<button type="button" class="btn btn-danger-soft btn-sm btn-delete-user" id="btnDeleteUser_${u.uid}" onclick="removeUserFromDatabase('${u.uid}', '${safeEscapedName}', '${safeEscapedEmail}');" title="Permanently remove user from Cloud Firestore database" style="padding: 4px 8px; font-size: 0.8rem; color: #ef4444; background: rgba(239, 68, 68, 0.1); border: 1px solid rgba(239, 68, 68, 0.25); border-radius: var(--radius-sm); cursor: pointer; transition: all 0.15s ease;">🗑️</button>`;

    const lc = u.lifecycle || calculateSubscriptionLifecycle(u);
    const activePayId = u.paymongoPaymentId || u.paypalSubscriptionId || '';

    row.innerHTML = `
      <td>
        <div style="font-weight: 600; font-size: 0.85rem; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${u.displayName}</div>
        <div style="font-size: 0.76rem; color: var(--text-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${u.email}</div>
      </td>
      <td>
        <code style="font-size: 0.72rem; padding: 2px 6px; background: rgba(255, 255, 255, 0.04); border-radius: 4px; border: 1px solid var(--border-subtle); color: var(--text-secondary); white-space: nowrap;" title="${u.uid}">${u.uid.slice(0, 10)}...</code>
      </td>
      <td>${providerBadge}</td>
      <td>${roleSelect}</td>
      <td>${currentTierPill}</td>
      <td>
        <!-- COLUMN 5: Payment Method & Amount Paid -->
        <div style="display: flex; flex-direction: column; gap: 3px; min-width: 175px;">
          <div style="display: flex; align-items: center; gap: 6px; flex-wrap: nowrap;">
            ${renderAdminSubscriptionBadge(u)}
          </div>
          <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 2px;">
            <span style="font-size: 0.76rem; font-weight: 700; color: #34d399; white-space: nowrap;">${lc.amountPaid}</span>
            ${activePayId
              ? `<code style="font-size: 0.68rem; padding: 1px 5px; background: rgba(255, 255, 255, 0.05); border-radius: 4px; border: 1px solid var(--border-subtle); color: #fbbf24; font-family: monospace; max-width: 100px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${activePayId}">${activePayId.slice(0, 12)}...</code>`
              : `<span style="font-size: 0.68rem; color: var(--text-muted); white-space: nowrap;">No Billing ID</span>`}
          </div>
        </div>
      </td>
      <td>
        <!-- COLUMN 6: Subscription Lifecycle (Start Date, End Date, Days Remaining) -->
        <div style="display: flex; flex-direction: column; gap: 3px; min-width: 205px;">
          <div style="display: flex; align-items: center; justify-content: space-between; gap: 6px; flex-wrap: nowrap;">
            ${lc.daysLeftBadge}
            <button type="button" class="btn btn-secondary btn-sm" onclick="openUserSubscriptionModal('${u.uid}');" title="Inspect Cloud Firestore subscription JSON payload" style="padding: 2px 7px; font-size: 0.70rem; display: inline-flex; align-items: center; gap: 3px; border-radius: 4px; background: rgba(56, 189, 248, 0.1); border-color: rgba(56, 189, 248, 0.35); color: #38bdf8; white-space: nowrap; flex-shrink: 0;">
              🧾 View JSON
            </button>
          </div>
          <div style="font-size: 0.72rem; color: var(--text-secondary); margin-top: 2px; white-space: nowrap;">
            <span style="color: var(--text-muted);">Start:</span> <strong style="color: var(--text-primary); font-weight: 500;">${lc.startDateFormatted}</strong>
          </div>
          <div style="font-size: 0.72rem; color: var(--text-secondary); white-space: nowrap;">
            <span style="color: var(--text-muted);">Ends:</span> <strong style="color: ${lc.daysLeft !== null && lc.daysLeft < 0 ? '#f87171' : (lc.daysLeft !== null && lc.daysLeft <= 7 ? '#fbbf24' : 'var(--text-primary)')}; font-weight: 600;">${lc.endDateFormatted}</strong>
          </div>
        </div>
      </td>
      <td>
        <span style="font-size: 0.76rem; color: var(--text-secondary); white-space: nowrap;" title="${u.createdAt || ''}">${createdStr}</span>
      </td>
      <td>
        <span style="font-size: 0.76rem; color: var(--text-secondary); white-space: nowrap;" title="${u.lastLogin || ''}">${lastLoginStr}</span>
      </td>
      <td>
        <span style="display: inline-flex; align-items: center; gap: 5px; font-size: 0.76rem; color: #34d399; white-space: nowrap;">
          <span style="width: 6px; height: 6px; border-radius: 50%; background: #34d399; display: inline-block;"></span>
          ${u.status}
        </span>
      </td>
      <td>
        <div style="display: flex; align-items: center; gap: 6px; white-space: nowrap;">
          <select id="selTierOverride_${u.uid}" class="admin-tier-select" onchange="handleUserTierSelectChange('${u.uid}', this)" style="background: var(--bg-card); color: var(--text-primary); border: 1px solid var(--border-subtle); border-radius: var(--radius-sm); padding: 4px 8px; font-size: 0.76rem;">
            <option value="free" ${u.tier === 'free' ? 'selected' : ''}>🌱 Free Core</option>
            <option value="pro" ${u.tier === 'pro' ? 'selected' : ''}>⚡ NirvTrack Pro</option>
            <option value="executive" ${u.tier === 'executive' ? 'selected' : ''}>👑 Executive</option>
          </select>
          <button type="button" class="btn btn-secondary btn-sm" id="btnSaveOverride_${u.uid}" onclick="applyUserOverrides('${u.uid}');" style="padding: 4px 10px; font-size: 0.74rem;">
            Save
          </button>
          ${deleteButtonHtml}
        </div>
      </td>
    `;
    tbody.appendChild(row);
  });

  // Apply saved or default column widths and attach draggable resizer handles
  if (typeof initAdminTableColumnResizing === 'function') {
    initAdminTableColumnResizing();
  }
}

/**
 * Opens the Admin User Subscription & Payload Inspector modal dialog.
 * Pre-populates KPI tiles and the exact JSON payload from Firestore.
 */
function openUserSubscriptionModal(uid) {
  const modal = document.getElementById('adminUserSubscriptionModal');
  if (!modal) return;

  const user = (cachedAdminUserList && cachedAdminUserList.find(u => u.uid === uid)) || {
    uid: uid,
    displayName: 'Customer',
    email: 'user@budgetmaster.app',
    tier: 'free',
    subscriptionStatus: 'inactive',
    paymentProvider: 'none',
    paypalSubscriptionId: '',
    tierUpdatedAt: new Date().toISOString()
  };

  const isPayMongo = String(user.paymentProvider || '').toLowerCase() === 'paymongo';
  const lc = user.lifecycle || (typeof calculateSubscriptionLifecycle === 'function' ? calculateSubscriptionLifecycle(user) : {});

  const payload = {
    uid: user.uid,
    email: user.email,
    displayName: user.rawDisplayName || user.displayName || 'Customer',
    role: user.role || 'Member',
    tier: user.tier || 'free',
    subscriptionStatus: user.subscriptionStatus || (user.tier !== 'free' ? 'active' : 'inactive'),
    paymentProvider: user.paymentProvider || (user.paymongoPaymentId ? 'paymongo' : (user.paypalSubscriptionId ? 'paypal' : 'none')),
    paymentMethod: lc.paymentMethod || 'None',
    amountPaid: lc.amountPaid || '₱0.00',
    subscriptionStartDate: lc.startDate || null,
    subscriptionEndDate: lc.endDate || null,
    daysRemaining: lc.daysLeft,
    paypalSubscriptionId: isPayMongo ? '' : (user.paypalSubscriptionId || ''),
    paymongoPaymentId: user.paymongoPaymentId || '',
    paymongoPaymentMethod: user.paymongoPaymentMethod || '',
    tierUpdatedAt: user.tierUpdatedAt || (user.createdAt ? user.createdAt : new Date().toISOString())
  };

  const nameEl = document.getElementById('userSubModalUserName');
  const emailEl = document.getElementById('userSubModalUserEmail');
  const uidEl = document.getElementById('userSubModalUserUid');
  const tierEl = document.getElementById('userSubModalCardTier');
  const statusEl = document.getElementById('userSubModalCardStatus');
  const methodEl = document.getElementById('userSubModalCardMethod');
  const amountEl = document.getElementById('userSubModalCardAmount');
  const startEl = document.getElementById('userSubModalCardStartDate');
  const endEl = document.getElementById('userSubModalCardEndDate');
  const daysLeftEl = document.getElementById('userSubModalCardDaysLeft');
  const updatedEl = document.getElementById('userSubModalCardUpdatedAt');
  const subIdEl = document.getElementById('userSubModalCardSubId');
  const gatewayLabelEl = document.getElementById('userSubModalCardGatewayLabel');
  const codeEl = document.getElementById('userSubModalJsonCode');

  if (nameEl) nameEl.textContent = user.rawDisplayName || user.displayName || 'Customer';
  if (emailEl) emailEl.textContent = user.email || '—';
  if (uidEl) uidEl.textContent = user.uid;

  const tierNames = {
    free: '🌱 Free Core',
    pro: '⚡ NirvTrack Pro',
    executive: '👑 Executive Wealth'
  };
  if (tierEl) tierEl.textContent = tierNames[user.tier] || String(user.tier || '').toUpperCase();

  const isActive = (user.subscriptionStatus === 'active' || lc.isSubscribed);
  if (statusEl) {
    statusEl.innerHTML = `${isActive ? '🟢' : '⚪'} ${user.subscriptionStatus || (isActive ? 'active' : 'inactive')}`;
    statusEl.style.color = isActive ? '#34d399' : '#94a3b8';
  }

  if (methodEl) methodEl.textContent = lc.paymentMethod || 'None';
  if (amountEl) amountEl.textContent = lc.amountPaid || '₱0.00';
  if (startEl) startEl.textContent = lc.startDateFormatted || '—';
  if (endEl) endEl.textContent = lc.endDateFormatted || '—';

  if (daysLeftEl) {
    daysLeftEl.textContent = lc.daysLeftLabel || '—';
    if (lc.daysLeft !== null && typeof lc.daysLeft === 'number') {
      daysLeftEl.style.color = lc.daysLeft < 0 ? '#f87171' : (lc.daysLeft <= 7 ? '#fbbf24' : '#34d399');
    } else {
      daysLeftEl.style.color = '#94a3b8';
    }
  }

  if (gatewayLabelEl) {
    gatewayLabelEl.textContent = isPayMongo ? 'PayMongo Live Checkout Transaction' : 'PayPal / Live Billing ID';
  }

  if (subIdEl) {
    subIdEl.textContent = user.paymongoPaymentId || user.paypalSubscriptionId || '— (No active billing ID)';
  }

  if (updatedEl) {
    updatedEl.textContent = formatAdminDateTime(payload.tierUpdatedAt);
    updatedEl.title = payload.tierUpdatedAt;
  }

  const jsonString = JSON.stringify(payload, null, 2);
  if (codeEl) {
    codeEl.textContent = jsonString;
  }
  window._currentUserSubJsonPayload = jsonString;

  modal.classList.add('active');
}

/**
 * Closes the Admin User Subscription & Payload Inspector modal dialog.
 */
function closeUserSubscriptionModal() {
  const modal = document.getElementById('adminUserSubscriptionModal');
  if (modal) {
    modal.classList.remove('active');
  }
}

/**
 * Copies the inspected JSON payload to user clipboard with toast notification.
 */
function copyUserSubJsonToClipboard() {
  const text = window._currentUserSubJsonPayload || '';
  if (!text) {
    if (typeof showToast === 'function') showToast('⚠️ No payload available to copy.');
    return;
  }

  if (navigator && navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Copied subscription payload JSON to clipboard!', 'success');
      }
    }).catch(() => {
      fallbackCopyText(text);
    });
  } else {
    fallbackCopyText(text);
  }
}

function fallbackCopyText(text) {
  try {
    const tempInput = document.createElement('textarea');
    tempInput.value = text;
    tempInput.style.position = 'fixed';
    tempInput.style.opacity = '0';
    document.body.appendChild(tempInput);
    tempInput.select();
    document.execCommand('copy');
    document.body.removeChild(tempInput);
    if (typeof showToast === 'function') {
      showToast('📋 Copied subscription payload JSON to clipboard!', 'success');
    }
  } catch (err) {
    if (typeof showToast === 'function') {
      showToast('⚠️ Could not auto-copy. Please select and copy manually.');
    }
  }
}

/**
 * [FEAT-55] Permanently removes a user document and their subcollections from Cloud Firestore.
 */
async function removeUserFromDatabase(uid, displayName, email) {
  const currentUser = (typeof fbAuth !== 'undefined' && fbAuth && fbAuth.currentUser)
    ? fbAuth.currentUser
    : (typeof currentAuthenticatedUser !== 'undefined' ? currentAuthenticatedUser : null);

  if (currentUser && currentUser.uid === uid) {
    if (typeof showToast === 'function') {
      showToast('⚠️ You cannot remove your currently authenticated account.');
    }
    return;
  }

  // Confirmation dialog
  let confirmed = false;
  const confirmMsg = `Are you sure you want to permanently remove user "${displayName}" (${email || uid}) from Cloud Firestore?\n\nThis will delete their user document, settings, and workspace data from the database.`;
  if (typeof askYesNo === 'function') {
    confirmed = await askYesNo(
      'Remove User from Database?',
      `Are you sure you want to permanently remove "${displayName}" (${email || uid}) from Cloud Firestore? This will purge their database document and workspace data.`,
      'Yes, remove user'
    );
  } else {
    confirmed = window.confirm(confirmMsg);
  }

  if (!confirmed) return;

  const deleteBtn = document.getElementById(`btnDeleteUser_${uid}`);
  if (deleteBtn) {
    deleteBtn.disabled = true;
    deleteBtn.innerHTML = '⏳';
  }

  let deleteSuccess = false;
  try {
    const token = (currentUser && typeof currentUser.getIdToken === 'function') ? await currentUser.getIdToken() : '';
    if (token) {
      const edgeRes = await fetch('/api/admin-supabase-sync', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ action: 'delete_user', uid: uid })
      });
      if (edgeRes.ok) {
        const resJson = await edgeRes.json().catch(() => ({}));
        if (resJson.success) deleteSuccess = true;
      }
    }

    if (!deleteSuccess && window.sbClient) {
      await window.sbClient.from('expenses').delete().eq('user_id', uid);
      await window.sbClient.from('budgets').delete().eq('user_id', uid);
      await window.sbClient.from('incomes').delete().eq('user_id', uid);
      await window.sbClient.from('categories').delete().eq('user_id', uid);
      await window.sbClient.from('workspaces').delete().eq('user_id', uid);
      const { error } = await window.sbClient.from('users').delete().eq('id', uid);
      if (!error) deleteSuccess = true;
    }

    if (deleteSuccess) {
      if (typeof showToast === 'function') {
        showToast(`🗑️ User "${displayName}" successfully removed from database.`);
      }
    }
  } catch (err) {
    console.error('Failed to remove user from Supabase:', err);
    if (typeof showToast === 'function') {
      showToast(`❌ Error removing user: ${err.message || err}`);
    }
    if (deleteBtn) {
      deleteBtn.disabled = false;
      deleteBtn.innerHTML = '🗑️';
    }
    return;
  }

  // Remove from in-memory cache
  if (cachedAdminUserList && cachedAdminUserList.length > 0) {
    cachedAdminUserList = cachedAdminUserList.filter(u => u.uid !== uid);
  }

  // Clear any local overrides for this UID
  delete adminRoleOverrides[uid];
  delete adminTierOverrides[uid];
  try {
    localStorage.removeItem(`budget_master_user_role_${uid}`);
  } catch (e) {}

  // Update KPI and re-render table
  renderAdminHubKpi(cachedAdminUserList);
  filterAdminHubUsers();
}
window.removeUserFromDatabase = removeUserFromDatabase;

/**
 * [FEAT-55] Exports the current customer directory to an Excel-compatible CSV file.
 */
function exportAdminCustomersToCSV() {
  if (!cachedAdminUserList || cachedAdminUserList.length === 0) {
    if (typeof showToast === 'function') showToast('⚠️ No customer records available to export.');
    return;
  }

  const headers = [
    'Email', 'Display Name', 'Firebase UID', 'Provider', 'Account Role',
    'Active Tier', 'Subscribed Status', 'Payment Method', 'Amount Paid',
    'Subscription Start Date', 'Subscription End Date', 'Days Remaining',
    'Created Date', 'Last Login Date', 'Status'
  ];
  const rows = cachedAdminUserList.map(u => {
    const lc = u.lifecycle || (typeof calculateSubscriptionLifecycle === 'function' ? calculateSubscriptionLifecycle(u) : {});
    return [
      `"${u.email}"`,
      `"${(u.displayName || '').replace(/"/g, '""')}"`,
      `"${u.uid}"`,
      `"${u.provider || 'Email'}"`,
      `"${u.role}"`,
      `"${u.tier.toUpperCase()}"`,
      `"${lc.isSubscribed ? 'Subscribed' : 'Free'}"`,
      `"${lc.paymentMethod || 'None'}"`,
      `"${lc.amountPaid || '₱0.00'}"`,
      `"${lc.startDateFormatted || '—'}"`,
      `"${lc.endDateFormatted || '—'}"`,
      `"${lc.daysLeftLabel || '—'}"`,
      `"${formatAdminDate(u.createdAt)}"`,
      `"${formatAdminDateTime(u.lastLogin)}"`,
      `"${u.status}"`
    ].join(',');
  });

  const csvContent = [headers.join(','), ...rows].join('\r\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `budget_master_customers_${new Date().toISOString().slice(0, 10)}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);

  if (typeof showToast === 'function') {
    showToast(`📄 Exported ${cachedAdminUserList.length} customer records to CSV!`);
  }
}

/**
 * Reacts to live edits in the Account Role dropdown.
 */
function handleUserRoleSelectChange(uid, selectEl) {
  const isNowAdmin = selectEl.value === 'Admin';
  selectEl.classList.toggle('role-admin', isNowAdmin);
  selectEl.classList.toggle('role-member', !isNowAdmin);

  const saveBtn = document.getElementById(`btnSaveOverride_${uid}`);
  if (saveBtn) {
    saveBtn.classList.remove('btn-secondary');
    saveBtn.classList.add('btn-primary');
    saveBtn.innerHTML = '💾 Save *';
  }
}

/**
 * Reacts to live edits in the Active Tier dropdown.
 */
function handleUserTierSelectChange(uid, selectEl) {
  const saveBtn = document.getElementById(`btnSaveOverride_${uid}`);
  if (saveBtn) {
    saveBtn.classList.remove('btn-secondary');
    saveBtn.classList.add('btn-primary');
    saveBtn.innerHTML = '💾 Save *';
  }
}

/**
 * Manually overrides and updates a specific user's Account Role and Tier.
 * Writes changes directly to Cloud Firestore /users/{uid} document.
 */
async function applyUserOverrides(uid) {
  const selRole = document.getElementById(`selRoleOverride_${uid}`);
  const selTier = document.getElementById(`selTierOverride_${uid}`);
  if (!selTier && !selRole) return;

  const targetRole = selRole ? selRole.value : 'Member';
  const targetTier = selTier ? selTier.value : 'free';

  adminRoleOverrides[uid] = targetRole;
  adminTierOverrides[uid] = targetTier;

  const currentUser = (typeof fbAuth !== 'undefined' && fbAuth && fbAuth.currentUser)
    ? fbAuth.currentUser
    : (typeof currentAuthenticatedUser !== 'undefined' ? currentAuthenticatedUser : null);

  // If overriding currently active user session, apply locally immediately
  if (currentUser && currentUser.uid === uid) {
    if (typeof updateUserRoleFromCloud === 'function') {
      updateUserRoleFromCloud(currentUser, targetRole);
    }
    if (typeof setSimulatedTier === 'function') {
      setSimulatedTier(targetTier);
    }
    if (typeof updateAdminSidebarVisibility === 'function') {
      updateAdminSidebarVisibility();
    }
  }

  // Update in Supabase PostgreSQL
  try {
    const token = (currentUser && typeof currentUser.getIdToken === 'function') ? await currentUser.getIdToken() : '';
    if (token) {
      await fetch('/api/admin-supabase-sync', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          action: 'update_user',
          uid: uid,
          updates: {
            role: targetRole.toLowerCase(),
            tier: targetTier.toLowerCase()
          }
        })
      });
    } else if (window.sbClient) {
      await window.sbClient.from('users').update({
        role: targetRole.toLowerCase(),
        tier: targetTier.toLowerCase(),
        updated_at: new Date().toISOString()
      }).eq('id', uid);
    }
  } catch (err) {
    console.warn('Supabase user override update failed:', err);
  }

  // Cache role locally for this UID
  try {
    localStorage.setItem(`budget_master_user_role_${uid}`, targetRole);
  } catch (e) {}

  if (typeof showToast === 'function') {
    showToast(`✅ Successfully updated user (${uid.slice(0, 8)}...): Role → ${targetRole}, Tier → ${targetTier.toUpperCase()}`);
  }

  // Refresh customer table to reflect new badge & KPI
  return renderAdminHubUsers();
}

/**
 * Simulates receiving an incoming Stripe checkout.session.completed webhook.
 * Demonstrates automated instant tier unlock without external cloud function deploy.
 */
function simulateStripePaymentWebhook(planTier) {
  const targetTier = (planTier === 'pro') ? 'pro' : 'executive';
  const priceAmount = (targetTier === 'pro') ? '$4.99' : '$12.99';

  const currentUser = (typeof fbAuth !== 'undefined' && fbAuth && fbAuth.currentUser)
    ? fbAuth.currentUser
    : (typeof currentAuthenticatedUser !== 'undefined' ? currentAuthenticatedUser : null);

  const customerEmail = (currentUser && currentUser.email) ? currentUser.email : 'admin@nirvtrack.io';
  const customerUid = currentUser ? currentUser.uid : 'usr_test_sim';

  // Construct simulated Stripe webhook payload
  const mockWebhookEvent = {
    id: `evt_sim_${Date.now()}`,
    object: 'event',
    type: 'checkout.session.completed',
    created: Math.floor(Date.now() / 1000),
    data: {
      object: {
        id: `cs_test_${Math.random().toString(36).substring(2, 10)}`,
        customer_email: customerEmail,
        client_reference_id: customerUid,
        amount_total: targetTier === 'pro' ? 499 : 1299,
        currency: 'usd',
        payment_status: 'paid',
        subscription: `sub_sim_${Math.random().toString(36).substring(2, 10)}`,
        metadata: {
          tier: targetTier,
          product_name: targetTier === 'pro' ? 'NirvTrack Pro' : 'Executive'
        }
      }
    }
  };

  console.log('[Stripe Webhook Simulator] Inbound verified webhook event payload:', mockWebhookEvent);

  // Append live log entry into desktop terminal viewer
  const terminalEl = document.getElementById('adminWebhookTerminalLog');
  if (terminalEl) {
    const timeStr = new Date().toLocaleTimeString();
    const logEntry = `[${timeStr}] ⚡ INBOUND WEBHOOK: event='checkout.session.completed'\n` +
      `  • Event ID: ${mockWebhookEvent.id}\n` +
      `  • Customer: ${customerEmail} (${customerUid.slice(0, 10)}...)\n` +
      `  • Subscribed: ${targetTier.toUpperCase()} (${priceAmount})\n` +
      `  • Result: 200 OK — Cloud Firestore user profile updated successfully.\n\n`;
    terminalEl.textContent = logEntry + terminalEl.textContent;
  }

  // Apply tier to app session
  setSimulatedTier(targetTier);

  // If connected to Firestore, persist subscription metadata
  if (typeof fbDb !== 'undefined' && fbDb && currentUser) {
    try {
      fbDb.collection('users').doc(currentUser.uid).set({
        tier: targetTier,
        subscriptionStatus: 'active',
        stripeCustomerId: `cus_sim_${Date.now()}`,
        stripeSubscriptionId: mockWebhookEvent.data.object.subscription,
        lastPaymentAmount: priceAmount,
        lastPaymentDate: new Date().toISOString()
      }, { merge: true }).catch(() => {});
    } catch (e) {}
  }

  if (typeof showToast === 'function') {
    showToast(`⚡ Webhook Verified! Received 'checkout.session.completed' -> Unlocked ${targetTier.toUpperCase()} (${priceAmount})`);
  }
}

/**
 * Copies the Cloud Functions Webhook Endpoint URL to clipboard.
 */
function copyWebhookUrl() {
  const urlEl = document.getElementById('webhookEndpointUrl');
  const textToCopy = urlEl ? urlEl.textContent.trim() : 'https://us-central1-budget-master-app-cc2ff.cloudfunctions.net/api/billing/webhook';

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(textToCopy).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Webhook Endpoint copied to clipboard!');
      }
    }).catch(() => {
      prompt('Copy Webhook URL:', textToCopy);
    });
  } else {
    prompt('Copy Webhook URL:', textToCopy);
  }
}

