// ==========================================================================
// [PWA] PROGRESSIVE WEB APP & STANDALONE INSTALLATION SYSTEM
// ==========================================================================

let deferredPwaInstallPrompt = null;

/**
 * Checks whether the app is currently running in standalone display mode (PWA installed).
 */
function isRunningStandalone() {
  return (
    window.matchMedia('(display-mode: standalone)').matches ||
    window.navigator.standalone === true ||
    (typeof document !== 'undefined' && document.referrer && document.referrer.includes('android-app://'))
  );
}

/**
 * Initializes Service Worker registration and PWA install prompt listeners.
 */
function initPwaSupport() {
  // 1. Register Service Worker if supported
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('./sw.js')
        .then((registration) => {
          console.log('[PWA SW] Registered successfully with scope:', registration.scope);
        })
        .catch((error) => {
          console.warn('[PWA SW] Registration failed:', error);
        });
    });
  }

  // 2. Intercept beforeinstallprompt for YouTube-style custom in-app trigger
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPwaInstallPrompt = e;
    window.deferredInstallPrompt = e;

    const brandIcon = document.getElementById('brandIcon');
    if (brandIcon) {
      brandIcon.classList.add('has-install-prompt');
      brandIcon.setAttribute('title', 'Click to Install NirvTrack App');
    }
  });

  // 3. Listen for completed installation
  window.addEventListener('appinstalled', () => {
    deferredPwaInstallPrompt = null;
    window.deferredInstallPrompt = null;

    const brandIcon = document.getElementById('brandIcon');
    if (brandIcon) {
      brandIcon.classList.remove('has-install-prompt');
    }

    if (typeof showToast === 'function') {
      showToast('✨ NirvTrack was installed as a standalone app!', 'success');
    }
    closePwaInstallModal();
  });
}

/**
 * Opens the YouTube-style PWA installation preview dialog.
 */
function openPwaInstallModal() {
  const modal = document.getElementById('pwaInstallModal');
  if (!modal) return;

  const isStandalone = isRunningStandalone();
  const statusTag = document.getElementById('pwaAppStatusTag');
  const btnInstall = document.getElementById('btnPwaInstallAction');
  const btnLabel = document.getElementById('pwaInstallBtnLabel');
  const guideHeading = document.getElementById('pwaGuideHeading');

  if (isStandalone) {
    if (statusTag) {
      statusTag.textContent = '⚡ Running in Standalone App Mode';
      statusTag.style.background = 'rgba(56, 189, 248, 0.15)';
      statusTag.style.color = '#38bdf8';
      statusTag.style.borderColor = 'rgba(56, 189, 248, 0.35)';
    }
    if (btnLabel) {
      btnLabel.textContent = 'App Already Installed (Active)';
    }
    if (guideHeading) {
      guideHeading.textContent = 'Running in standalone desktop mode';
    }
  } else {
    if (statusTag) {
      statusTag.textContent = deferredPwaInstallPrompt ? 'Ready to Install' : 'Install via Browser';
      statusTag.style.background = 'rgba(16, 185, 129, 0.12)';
      statusTag.style.color = '#34d399';
      statusTag.style.borderColor = 'rgba(52, 211, 153, 0.3)';
    }
    if (btnLabel) {
      btnLabel.textContent = deferredPwaInstallPrompt ? 'Install NirvTrack App' : 'Install via Browser Menu';
    }
    if (guideHeading) {
      guideHeading.textContent = 'How to install in your browser';
    }
  }

  modal.style.display = 'flex';
}

/**
 * Closes the PWA installation dialog.
 */
function closePwaInstallModal() {
  const modal = document.getElementById('pwaInstallModal');
  if (modal) {
    modal.style.display = 'none';
  }
}

/**
 * Triggers the browser's native PWA installation prompt or displays instructions.
 */
async function triggerPwaInstall() {
  if (isRunningStandalone()) {
    if (typeof showToast === 'function') {
      showToast('✨ NirvTrack is already running in standalone app mode!', 'info');
    }
    closePwaInstallModal();
    return;
  }

  if (deferredPwaInstallPrompt) {
    deferredPwaInstallPrompt.prompt();
    try {
      const { outcome } = await deferredPwaInstallPrompt.userChoice;
      if (outcome === 'accepted') {
        if (typeof showToast === 'function') {
          showToast('Installing NirvTrack...', 'success');
        }
      }
    } catch (e) {}
    deferredPwaInstallPrompt = null;
    window.deferredInstallPrompt = null;
    closePwaInstallModal();
  } else {
    // If prompt is not directly available (e.g. desktop Edge/Chrome already has icon in address bar, or Safari iOS)
    const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
    if (isIOS) {
      if (typeof showToast === 'function') {
        showToast('Tap Share (⎋) in Safari, then tap "Add to Home Screen"');
      }
    } else {
      if (typeof showToast === 'function') {
        showToast('💡 Click the Install icon in your browser address bar or Menu (⋮) → "Install NirvTrack"');
      }
    }
  }
}

/**
 * Handles action hashes defined in manifest shortcuts (e.g. #action=new-expense).
 */
function handlePwaShortcutsOnLaunch() {
  const hash = window.location.hash;
  if (!hash) return;

  if (hash.includes('new-expense')) {
    setTimeout(() => {
      const addBtn = document.getElementById('btnOpenAddModal');
      if (addBtn) addBtn.click();
    }, 350);
  } else if (hash.includes('cmd')) {
    setTimeout(() => {
      if (typeof openSpotlightCommandPalette === 'function') {
        openSpotlightCommandPalette();
      }
    }, 350);
  } else if (hash.includes('workspaces')) {
    setTimeout(() => {
      if (typeof openWorkspacesModal === 'function') {
        openWorkspacesModal();
      }
    }, 350);
  }
}

