/// ==========================================================================
// [TIER-STYLE] Interactive Tier Mouse Feedback (Click Micro-Ripple)
// ==========================================================================
function initTierInteractiveCursor() {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;

  // Remove any legacy cursor aura light ball if present
  const existingAura = document.getElementById('tierCursorAura');
  if (existingAura) {
    existingAura.remove();
  }

  // Skip on touch-primary devices (coarse pointer)
  if (window.matchMedia('(pointer: coarse)').matches) return;

  // Prevent multiple ripple event listener attachments
  if (window.__tierRippleInitialized) return;
  window.__tierRippleInitialized = true;

  // Micro-click ripple with tier styling on user interaction
  window.addEventListener('mousedown', (e) => {
    const ripple = document.createElement('div');
    ripple.className = 'tier-click-ripple';
    ripple.style.left = `${e.clientX}px`;
    ripple.style.top = `${e.clientY}px`;
    document.body.appendChild(ripple);
    setTimeout(() => {
      ripple.remove();
    }, 460);
  }, { passive: true });
}

window.initTierInteractiveCursor = initTierInteractiveCursor;

