// =========================================================================
// [FEAT-NOTEPAD] ADMIN COMMAND CENTER FEATURE IDEAS NOTEPAD
// =========================================================================
const STORAGE_ADMIN_NOTEPAD = 'nirvtrack_admin_feature_ideas_notes';
let adminNotepadAutoSaveTimer = null;

/**
 * Loads saved notes into the Admin Notepad textarea.
 * Checks localStorage first, and if online and user is admin, pulls from user's Firestore doc if available.
 */
function loadAdminNotepad() {
  const textarea = document.getElementById('adminNotepadTextarea');
  if (!textarea) return;

  let localNotes = '';
  try {
    localNotes = localStorage.getItem(STORAGE_ADMIN_NOTEPAD) || '';
  } catch (e) {}

  if (textarea.value !== localNotes) {
    textarea.value = localNotes;
  }
  updateAdminNotepadCounters();

  // If user is authenticated admin, sync latest notes from Firestore if newer
  const currentUser = (typeof fbAuth !== 'undefined' && fbAuth && fbAuth.currentUser) ? fbAuth.currentUser : null;
  if (currentUser && typeof fbDb !== 'undefined' && fbDb) {
    fbDb.collection('users').doc(currentUser.uid).get().then(doc => {
      if (doc.exists) {
        const data = doc.data();
        if (data && typeof data.adminIdeasNotepad === 'string') {
          // If local was empty or cloud is different and longer/newer, update
          if (!localNotes.trim() && data.adminIdeasNotepad.trim()) {
            textarea.value = data.adminIdeasNotepad;
            localStorage.setItem(STORAGE_ADMIN_NOTEPAD, data.adminIdeasNotepad);
            updateAdminNotepadCounters();
            setAdminNotepadSaveStatus('✓ Synced from Cloud');
          }
        }
      }
    }).catch(() => {});
  }
}

/**
 * Saves Admin Notepad content to local storage and mirrors to Cloud Firestore user profile.
 */
function saveAdminNotepad(showFeedback = true) {
  const textarea = document.getElementById('adminNotepadTextarea');
  if (!textarea) return;

  const content = textarea.value;
  try {
    localStorage.setItem(STORAGE_ADMIN_NOTEPAD, content);
  } catch (e) {}

  setAdminNotepadSaveStatus('✓ Saved');
  updateAdminNotepadCounters();

  if (showFeedback && typeof showToast === 'function') {
    showToast('📝 Feature ideas saved successfully!', 'success');
  }

  // Cloud Firestore sync for authenticated admin
  const currentUser = (typeof fbAuth !== 'undefined' && fbAuth && fbAuth.currentUser) ? fbAuth.currentUser : null;
  if (currentUser && typeof fbDb !== 'undefined' && fbDb) {
    try {
      fbDb.collection('users').doc(currentUser.uid).set({
        adminIdeasNotepad: content,
        adminIdeasUpdatedAt: new Date().toISOString()
      }, { merge: true }).catch(() => {});
    } catch (e) {}
  }
}

/**
 * Updates words, characters, and lines counters below the notepad.
 */
function updateAdminNotepadCounters() {
  const textarea = document.getElementById('adminNotepadTextarea');
  const wordEl = document.getElementById('adminNotepadWordCount');
  const charEl = document.getElementById('adminNotepadCharCount');
  const lineEl = document.getElementById('adminNotepadLineCount');
  if (!textarea) return;

  const val = textarea.value || '';
  const charCount = val.length;
  const words = val.trim().split(/\s+/).filter(Boolean);
  const wordCount = val.trim() ? words.length : 0;
  const lines = val.split('\n');
  const lineCount = val ? lines.length : 0;

  if (wordEl) wordEl.textContent = `${wordCount} ${wordCount === 1 ? 'word' : 'words'}`;
  if (charEl) charEl.textContent = `${charCount} ${charCount === 1 ? 'character' : 'characters'}`;
  if (lineEl) lineEl.textContent = `${lineCount} ${lineCount === 1 ? 'line' : 'lines'}`;
}

/**
 * Updates visual auto-save status indicator.
 */
function setAdminNotepadSaveStatus(statusText, isSaving = false) {
  const statusEl = document.getElementById('adminNotepadSaveStatus');
  if (!statusEl) return;
  statusEl.textContent = statusText;
  statusEl.style.color = isSaving ? '#fbbf24' : '#34d399';
}

/**
 * Exports notepad content as a markdown / text file.
 */
function exportAdminNotepadTxt() {
  const textarea = document.getElementById('adminNotepadTextarea');
  const content = textarea ? textarea.value : '';
  if (!content.trim()) {
    if (typeof showToast === 'function') showToast('Notepad is currently empty.', 'warning');
    return;
  }

  const timestamp = new Date().toISOString().slice(0, 10);
  const blob = new Blob([
    `# NirvTrack Admin - Feature Ideas & Roadmap\nExported: ${new Date().toLocaleString()}\n\n---\n\n${content}`
  ], { type: 'text/markdown;charset=utf-8' });

  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `nirvtrack-feature-ideas-${timestamp}.md`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  if (typeof showToast === 'function') showToast('📄 Exported feature ideas file!', 'success');
}

/**
 * Clears notepad content with confirmation.
 */
function clearAdminNotepad() {
  const textarea = document.getElementById('adminNotepadTextarea');
  if (!textarea || !textarea.value.trim()) return;

  if (typeof openConfirmModal === 'function') {
    openConfirmModal(
      'Clear Feature Ideas Notepad?',
      'Are you sure you want to clear your notes? Any unsaved ideas will be deleted.',
      () => {
        textarea.value = '';
        saveAdminNotepad(false);
        if (typeof showToast === 'function') showToast('🗑️ Notepad cleared.', 'info');
      }
    );
  } else if (confirm('Are you sure you want to clear your feature ideas notepad?')) {
    textarea.value = '';
    saveAdminNotepad(false);
  }
}

/**
 * Setup all Admin Notepad event listeners.
 */
function setupAdminNotepadEventListeners() {
  const textarea = document.getElementById('adminNotepadTextarea');
  const btnSave = document.getElementById('btnAdminNotepadSave');
  const btnClear = document.getElementById('btnAdminNotepadClear');
  const btnExport = document.getElementById('btnAdminNotepadExport');

  if (textarea) {
    textarea.addEventListener('input', () => {
      setAdminNotepadSaveStatus('Saving...', true);
      updateAdminNotepadCounters();
      clearTimeout(adminNotepadAutoSaveTimer);
      adminNotepadAutoSaveTimer = setTimeout(() => {
        saveAdminNotepad(false);
      }, 700);
    });
  }

  if (btnSave) {
    btnSave.addEventListener('click', () => saveAdminNotepad(true));
  }

  if (btnClear) {
    btnClear.addEventListener('click', clearAdminNotepad);
  }

  if (btnExport) {
    btnExport.addEventListener('click', exportAdminNotepadTxt);
  }

  // Quick prompt snippet inserters
  document.querySelectorAll('.btn-notepad-snippet').forEach(btn => {
    btn.addEventListener('click', () => {
      const snippet = btn.getAttribute('data-snippet');
      if (!snippet || !textarea) return;

      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const text = textarea.value;
      const prefix = (start > 0 && text[start - 1] !== '\n') ? '\n' : '';
      const inserted = prefix + snippet;

      textarea.value = text.substring(0, start) + inserted + text.substring(end);
      textarea.focus();
      textarea.selectionStart = textarea.selectionEnd = start + inserted.length;

      setAdminNotepadSaveStatus('Saving...', true);
      updateAdminNotepadCounters();
      clearTimeout(adminNotepadAutoSaveTimer);
      adminNotepadAutoSaveTimer = setTimeout(() => {
        saveAdminNotepad(false);
      }, 700);
    });
  });
}

// Window bindings
window.loadAdminNotepad = loadAdminNotepad;
window.saveAdminNotepad = saveAdminNotepad;
window.exportAdminNotepadTxt = exportAdminNotepadTxt;
window.clearAdminNotepad = clearAdminNotepad;
window.setupAdminNotepadEventListeners = setupAdminNotepadEventListeners;

