// --- 1. [FEAT-COVER-OVERSPEND] 1-Click Roll with the Punches Envelope Re-allocation ---
let activeCoverOverspendTargetId = null;

function openCoverOverspendModal(targetCatId, deficitAmount) {
  const modal = document.getElementById('coverOverspendModal');
  if (!modal) return;

  activeCoverOverspendTargetId = targetCatId;
  const targetCat = appState.categories.find(c => c.id === targetCatId);
  const targetName = targetCat ? `${targetCat.icon} ${targetCat.name}` : targetCatId;

  const targetNameEl = document.getElementById('coverTargetCategoryName');
  if (targetNameEl) targetNameEl.textContent = targetName;

  const deficitEl = document.getElementById('coverDeficitAmount');
  if (deficitEl) deficitEl.textContent = formatCurrency(deficitAmount);

  // Find all categories in activeMonth with a SURPLUS (budget > actual spent)
  const monthKey = appState.activeMonth;
  const currentBudgets = appState.budgets[monthKey] || {};
  const monthExpenses = (appState.expenses || []).filter(e => e.date && e.date.startsWith(monthKey));
  const categorySpending = {};
  monthExpenses.forEach(e => {
    if (e.excludeFromBudget || e.isCreditCardPayoff) return;
    const delta = (e.isRefund || e.type === 'refund') ? -Number(e.amount) : Number(e.amount);
    categorySpending[e.categoryId] = (categorySpending[e.categoryId] || 0) + delta;
  });

  const select = document.getElementById('coverFromCategorySelect');
  if (select) {
    select.innerHTML = '<option value="">-- Select Source Envelope with Surplus --</option>';
    let surplusCount = 0;

    appState.categories.forEach(cat => {
      if (cat.id === targetCatId) return;
      const b = currentBudgets[cat.id] !== undefined ? currentBudgets[cat.id] : (cat.defaultBudget || 0);
      const s = categorySpending[cat.id] || 0;
      const surplus = b - s;
      if (surplus > 0) {
        surplusCount++;
        const opt = document.createElement('option');
        opt.value = cat.id;
        opt.setAttribute('data-surplus', surplus.toFixed(2));
        opt.textContent = `${cat.icon} ${cat.name} · Available Surplus: ${formatCurrency(surplus)}`;
        select.appendChild(opt);
      }
    });

    if (surplusCount === 0) {
      const opt = document.createElement('option');
      opt.disabled = true;
      opt.textContent = '⚠️ No other categories currently have surplus budget';
      select.appendChild(opt);
    }
  }

  const amtInput = document.getElementById('coverTransferAmount');
  if (amtInput) {
    amtInput.value = Number(deficitAmount).toFixed(2);
  }

  updateCoverSurplusPreview();
  modal.classList.add('active');
}

// ==========================================
// [FEAT-UIUX-MODAL-MOTION] GRACEFUL 150MS MODAL EXIT TRANSITIONS
// ==========================================
function closeModalGracefully(modalOrId) {
  const modal = typeof modalOrId === 'string' ? document.getElementById(modalOrId) : modalOrId;
  if (!modal) return;
  if (!modal.classList.contains('active')) {
    modal.style.display = 'none';
    return;
  }
  modal.classList.add('is-closing');
  setTimeout(() => {
    modal.classList.remove('active', 'is-closing');
  }, 140);
}

// ==========================================
// [FEAT-UIUX-HAPTICS] NATIVE FINTECH MICRO-HAPTIC FEEDBACK
// ==========================================
function triggerHapticFeedback(pattern = 'light') {
  if (typeof navigator === 'undefined' || !navigator.vibrate) return;
  try {
    if (pattern === 'light') {
      navigator.vibrate(8);
    } else if (pattern === 'medium') {
      navigator.vibrate(15);
    } else if (pattern === 'heavy') {
      navigator.vibrate(25);
    } else if (pattern === 'success') {
      navigator.vibrate([10, 30, 10]);
    } else if (pattern === 'warning') {
      navigator.vibrate([15, 40, 20]);
    }
  } catch (e) {}
}

function closeCoverOverspendModal() {
  closeModalGracefully('coverOverspendModal');
  activeCoverOverspendTargetId = null;
}

function updateCoverSurplusPreview() {
  const preview = document.getElementById('coverPreviewText');
  if (!preview) return;

  const select = document.getElementById('coverFromCategorySelect');
  const sourceId = select ? select.value : '';
  const amtInput = document.getElementById('coverTransferAmount');
  const transferAmt = parseFloat(amtInput ? amtInput.value : 0) || 0;

  if (!sourceId || transferAmt <= 0) {
    preview.innerHTML = 'Select a source envelope and amount to view the reallocation impact.';
    return;
  }

  const sourceCat = appState.categories.find(c => c.id === sourceId);
  const targetCat = appState.categories.find(c => c.id === activeCoverOverspendTargetId);
  const selectedOpt = select.selectedOptions[0];
  const availSurplus = parseFloat(selectedOpt?.getAttribute('data-surplus') || 0);

  if (transferAmt > availSurplus) {
    preview.innerHTML = `<span style="color: #ef4444;">⚠️ Warning: Transfer amount (${formatCurrency(transferAmt)}) exceeds available surplus in ${sourceCat?.name || 'source'} (${formatCurrency(availSurplus)}).</span>`;
  } else {
    preview.innerHTML = `✅ Reallocates <strong>${formatCurrency(transferAmt)}</strong> from <strong>${sourceCat?.name}</strong> to <strong>${targetCat?.name}</strong>. Total monthly budget remains 100% unchanged!`;
  }
}

function submitCoverOverspend() {
  const select = document.getElementById('coverFromCategorySelect');
  const sourceId = select ? select.value : '';
  const amtInput = document.getElementById('coverTransferAmount');
  const transferAmt = parseFloat(amtInput ? amtInput.value : 0) || 0;

  if (!activeCoverOverspendTargetId || !sourceId || transferAmt <= 0) {
    showToast('Please select a valid source category and transfer amount', 'warning');
    return;
  }

  const monthKey = appState.activeMonth;
  if (!appState.budgets[monthKey]) {
    appState.budgets[monthKey] = {};
  }

  const sourceCat = appState.categories.find(c => c.id === sourceId);
  const targetCat = appState.categories.find(c => c.id === activeCoverOverspendTargetId);

  const curSourceBudget = appState.budgets[monthKey][sourceId] !== undefined ? appState.budgets[monthKey][sourceId] : (sourceCat?.defaultBudget || 0);
  const curTargetBudget = appState.budgets[monthKey][activeCoverOverspendTargetId] !== undefined ? appState.budgets[monthKey][activeCoverOverspendTargetId] : (targetCat?.defaultBudget || 0);

  appState.budgets[monthKey][sourceId] = Math.max(0, curSourceBudget - transferAmt);
  appState.budgets[monthKey][activeCoverOverspendTargetId] = curTargetBudget + transferAmt;

  saveData();
  triggerHapticFeedback('success');
  closeCoverOverspendModal();
  updateAllViews();
  showToast(`🎉 Covered ${formatCurrency(transferAmt)} overspend in ${targetCat?.name} using surplus from ${sourceCat?.name}!`, 'success', 5000);
}

// --- 2. [FEAT-WALLETS-ACCOUNTS] Liquid Accounts & Wallets Strip with 1-Click Reconcile ---
let activeReconcileWalletId = null;

function ensureWallets() {
  if (!appState.wallets || !Array.isArray(appState.wallets) || appState.wallets.length === 0) {
    appState.wallets = [
      { id: 'w_gcash', name: 'GCash', icon: '📱', balance: 0, type: 'ewallet' },
      { id: 'w_maya', name: 'Maya', icon: '💳', balance: 0, type: 'ewallet' },
      { id: 'w_bank', name: 'Payroll / Savings Bank', icon: '🏦', balance: 0, type: 'bank' },
      { id: 'w_cash', name: 'Physical Cash', icon: '💵', balance: 0, type: 'cash' }
    ];
  }
}

function renderWalletsGrid() {
  const container = document.getElementById('walletsGrid') || document.getElementById('walletsListGrid');
  if (!container) return;

  ensureWallets();
  container.innerHTML = '';

  let totalLiquid = 0;
  appState.wallets.forEach(w => {
    totalLiquid += Number(w.balance || 0);
    const card = document.createElement('div');
    card.className = 'wallet-card';
    card.setAttribute('data-wallet-id', w.id);
    card.innerHTML = `
      <div class="wallet-card-head">
        <span class="wallet-icon">${w.icon || '🚪'}</span>
        <strong class="wallet-name">${escapeHTML(w.name)}</strong>
      </div>
      <div class="wallet-balance-val" data-privacy-mask>${formatCurrency(w.balance || 0)}</div>
      <div class="wallet-actions">
        <button type="button" class="btn-wallet-reconcile" onclick="openReconcileWalletModal('${w.id}')" title="Compare against actual real-life balance and reconcile discrepancy in 1 click">
          ⚖️ Reconcile
        </button>
      </div>
    `;
    container.appendChild(card);
  });

  const totalEl = document.getElementById('walletsTotalCashBadge') || document.getElementById('walletsTotalLiquidBalance');
  if (totalEl) {
    totalEl.textContent = `Total Liquid: ${formatCurrency(totalLiquid)}`;
  }
}

function openReconcileWalletModal(walletId) {
  if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-BANK-RECONCILE]')) {
    if (typeof showUpgradePrompt === 'function') {
      showUpgradePrompt('[FEAT-BANK-RECONCILE]', '1-Click Bank Account & Wallet Reconciliation', 'dashboard');
    }
    return;
  }

  const modal = document.getElementById('reconcileWalletModal');
  if (!modal) return;

  ensureWallets();
  if (!Array.isArray(appState.wallets) || appState.wallets.length === 0) {
    appState.wallets = [
      { id: 'w_gcash', name: 'GCash', icon: '📱', balance: 0 },
      { id: 'w_maya', name: 'Maya', icon: '💳', balance: 0 },
      { id: 'w_bank', name: 'Bank Account', icon: '🏛️', balance: 0 },
      { id: 'w_cash', name: 'Cash on Hand', icon: '💵', balance: 0 }
    ];
  }

  if (!walletId || !appState.wallets.some(w => w.id === walletId)) {
    walletId = appState.wallets[0].id;
  }

  activeReconcileWalletId = walletId;
  const wallet = appState.wallets.find(w => w.id === walletId);
  if (!wallet) return;

  const idInput = document.getElementById('reconcileWalletId');
  if (idInput) idInput.value = wallet.id;

  const nameEl = document.getElementById('reconcileWalletName');
  if (nameEl) nameEl.textContent = `${wallet.icon || '🚪'} ${wallet.name}`;

  const currentBalEl = document.getElementById('reconcileCalculatedBalance') || document.getElementById('reconcileCurrentTrackedBalance');
  if (currentBalEl) currentBalEl.textContent = formatCurrency(wallet.balance || 0);

  const input = document.getElementById('reconcileActualBalanceInput') || document.getElementById('reconcileActualBalance');
  if (input) {
    input.value = (wallet.balance !== undefined && wallet.balance !== null) ? wallet.balance : '';
  }

  const currLabel = document.getElementById('reconcileCurrencyLabel');
  if (currLabel) currLabel.textContent = appState.currency || '₱';

  updateReconcileDiff();
  modal.classList.add('active');
}

function closeReconcileWalletModal() {
  closeModalGracefully('reconcileWalletModal');
  activeReconcileWalletId = null;
}

function updateReconcileDiff() {
  const wallet = (appState.wallets || []).find(w => w.id === activeReconcileWalletId);
  if (!wallet) return;

  const currentBal = Number(wallet.balance || 0);
  const input = document.getElementById('reconcileActualBalanceInput') || document.getElementById('reconcileActualBalance');
  const actualVal = resolveInputMathValue(input) || 0;
  const diff = (typeof roundCurrency === 'function') ? roundCurrency(actualVal - currentBal) : Math.round((actualVal - currentBal) * 100) / 100;

  const diffEl = document.getElementById('reconcileDiffAmount');
  const diffWrap = document.getElementById('reconcileDiffWrap');

  if (diffWrap) diffWrap.style.display = 'block';

  if (diffEl) {
    if (Math.abs(diff) < 0.005) {
      diffEl.textContent = '₱0.00 (Perfect Match! 🎉)';
      diffEl.style.color = '#10b981';
      if (diffWrap) {
        diffWrap.style.background = 'rgba(16, 185, 129, 0.12)';
        diffWrap.style.border = '1px solid rgba(16, 185, 129, 0.3)';
      }
    } else if (diff > 0) {
      diffEl.textContent = `+${formatCurrency(diff)} (Actual is higher - Inflow)`;
      diffEl.style.color = '#10b981';
      if (diffWrap) {
        diffWrap.style.background = 'rgba(16, 185, 129, 0.12)';
        diffWrap.style.border = '1px solid rgba(16, 185, 129, 0.3)';
      }
    } else {
      diffEl.textContent = `-${formatCurrency(Math.abs(diff))} (Discrepancy / Unrecorded spent)`;
      diffEl.style.color = '#ef4444';
      if (diffWrap) {
        diffWrap.style.background = 'rgba(239, 68, 68, 0.12)';
        diffWrap.style.border = '1px solid rgba(239, 68, 68, 0.3)';
      }
    }
  }
}

function saveReconcileWalletBalance(autoLogAdjustment = true) {
  const wallet = (appState.wallets || []).find(w => w.id === activeReconcileWalletId);
  if (!wallet) return;

  const currentBal = Number(wallet.balance || 0);
  const input = document.getElementById('reconcileActualBalanceInput') || document.getElementById('reconcileActualBalance');
  const actualVal = resolveInputMathValue(input);

  if (isNaN(actualVal)) {
    showToast('Please enter a valid amount', 'warning');
    return;
  }

  const diff = (typeof roundCurrency === 'function') ? roundCurrency(actualVal - currentBal) : Math.round((actualVal - currentBal) * 100) / 100;
  wallet.balance = actualVal;

  const chkAuto = document.getElementById('reconcileAutoLogAdjustment');
  const shouldAutoLog = chkAuto ? chkAuto.checked : autoLogAdjustment;

  if (shouldAutoLog && Math.abs(diff) > 0.01) {
    const todayStr = new Date().toISOString().split('T')[0];
    if (diff < 0) {
      // Unrecorded expense
      const adjTx = {
        id: 'tx_recon_' + Date.now(),
        date: todayStr,
        amount: Math.abs(diff),
        categoryId: (Array.isArray(appState.categories) && appState.categories[0]?.id) || 'misc',
        description: `Reconciliation Discrepancy (${wallet.name})`,
        paymentMethod: wallet.name,
        budgetType: 'needs'
      };
      if (!Array.isArray(appState.expenses)) appState.expenses = [];
      appState.expenses.push(adjTx);
    } else if (diff > 0) {
      // Inflow discrepancy -> record refund/reimbursement offset
      const adjTx = {
        id: 'tx_recon_' + Date.now(),
        date: todayStr,
        amount: Math.abs(diff),
        isRefund: true,
        type: 'refund',
        categoryId: (Array.isArray(appState.categories) && appState.categories[0]?.id) || 'misc',
        description: `Reconciliation Inflow (${wallet.name})`,
        paymentMethod: wallet.name,
        budgetType: 'needs'
      };
      if (!Array.isArray(appState.expenses)) appState.expenses = [];
      appState.expenses.push(adjTx);
    }
  }

  saveData();
  triggerHapticFeedback('success');
  closeReconcileWalletModal();
  updateAllViews();
  showToast(`✅ ${wallet.name} reconciled to ${formatCurrency(actualVal)}!`, 'success');
}
function openWalletsSetupModal() {
  const modal = document.getElementById('walletsSetupModal');
  if (!modal) return;
  ensureWallets();
  const list = document.getElementById('walletsSetupList');
  if (list) {
    list.innerHTML = '';
    appState.wallets.forEach((w, idx) => {
      const row = document.createElement('div');
      row.className = 'wallet-setup-row';
      row.style.cssText = 'display: flex; gap: 8px; margin-bottom: 8px; align-items: center;';
      row.innerHTML = `
        <input type="text" value="${escapeHTML(w.icon || '🚪')}" style="width: 44px; text-align: center;" data-wallet-idx="${idx}" data-field="icon" class="form-input">
        <input type="text" value="${escapeHTML(w.name || '')}" style="flex: 1;" data-wallet-idx="${idx}" data-field="name" class="form-input">
        <input type="number" step="any" value="${w.balance || 0}" style="width: 110px;" data-wallet-idx="${idx}" data-field="balance" class="form-input">
      `;
      list.appendChild(row);
    });
  }
  modal.classList.add('active');
}

function closeWalletsSetupModal() {
  closeModalGracefully('walletsSetupModal');
}

function saveWalletsSetup() {
  const list = document.getElementById('walletsSetupList');
  if (!list) return;
  ensureWallets();
  const rows = list.querySelectorAll('.wallet-setup-row');
  rows.forEach((row, idx) => {
    if (appState.wallets[idx]) {
      const iconInput = row.querySelector('[data-field="icon"]');
      const nameInput = row.querySelector('[data-field="name"]');
      const balInput = row.querySelector('[data-field="balance"]');
      if (iconInput) appState.wallets[idx].icon = iconInput.value.trim() || '🚪';
      if (nameInput) appState.wallets[idx].name = nameInput.value.trim() || 'Account';
      if (balInput) appState.wallets[idx].balance = parseFloat(balInput.value) || 0;
    }
  });
  saveData();
  closeWalletsSetupModal();
  renderWalletsGrid();
  showToast('Accounts & Wallets updated!', 'success');
}

// --- 3. [FEAT-CC-FLOAT-PROTECT] Credit Card Float & Statement Payoff Tracker ---
function renderCreditCardFloatWidget(metrics) {
  const widget = document.getElementById('dashboardCreditCardFloatWidget');
  if (!widget) return;

  const m = metrics || calculateMetrics();
  const floatVal = m.creditCardFloat || 0;
  const swipedVal = m.ccTotalSwiped || 0;
  const paidVal = m.ccTotalPaid || 0;

  const floatEl = document.getElementById('ccFloatAmount');
  if (floatEl) floatEl.textContent = formatCurrency(floatVal);

  const swipedEl = document.getElementById('ccFloatSwipedTotal');
  if (swipedEl) swipedEl.textContent = formatCurrency(swipedVal);

  const paidEl = document.getElementById('ccFloatPaidTotal');
  if (paidEl) paidEl.textContent = formatCurrency(paidVal);

  const statusBadge = document.getElementById('ccFloatStatusBadge');
  const adviceEl = document.getElementById('ccFloatAdviceText');
  if (statusBadge && adviceEl) {
    if (floatVal === 0) {
      statusBadge.textContent = '● Float Fully Covered';
      statusBadge.className = 'cc-float-badge healthy';
      adviceEl.textContent = 'Zero unpaid Credit Card float this month. Statement payoff is in sync.';
    } else {
      statusBadge.textContent = '● Active Float';
      statusBadge.className = 'cc-float-badge';
      adviceEl.textContent = `You have swiped ${formatCurrency(swipedVal)} this month (${formatCurrency(paidVal)} paid off). Keep ${formatCurrency(floatVal)} in your bank to pay statement on due date without taking on interest!`;
    }
  }
}

// --- 4. [FEAT-DAY1-ONBOARDING] 60-Second Fast-Track Setup Cockpit ---
function checkDayOneOnboarding() {
  const card = document.getElementById('dayOneOnboardingCard');
  if (!card) return;

  if (appState.dismissedDayOneOnboarding) {
    card.style.display = 'none';
    return;
  }

  const m = calculateMetrics();
  if (m.totalIncome <= 0 && (!appState.expenses || appState.expenses.length === 0)) {
    card.style.display = 'block';
  } else {
    card.style.display = 'none';
  }
}

function dismissDayOneCard() {
  appState.dismissedDayOneOnboarding = true;
  saveData();
  const card = document.getElementById('dayOneOnboardingCard');
  if (card) card.style.display = 'none';
  showToast('Setup wizard dismissed. You can configure budgets anytime in the Budget tab.');
}

function setDayOneCurrency(curr) {
  if (!curr) return;
  appState.currency = curr;
  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();
  showToast(`Currency updated to ${curr}`);
}

function applyDayOnePaychecks() {
  const p15Input = document.getElementById('day1Paycheck15');
  const p30Input = document.getElementById('day1Paycheck30');
  const p15 = resolveInputMathValue(p15Input) || 0;
  const p30 = resolveInputMathValue(p30Input) || 0;

  if (p15 <= 0 && p30 <= 0) {
    showToast('Please enter at least one paycheck amount', 'warning');
    return;
  }

  const monthKey = appState.activeMonth;
  if (!appState.incomes[monthKey]) {
    appState.incomes[monthKey] = { paycheck15: 0, paycheck30: 0, additional: 0, carryoverSurplus: 0 };
  }
  appState.incomes[monthKey].paycheck15 = p15;
  appState.incomes[monthKey].paycheck30 = p30;

  const totalIncome = p15 + p30;
  const needsBudget = totalIncome * 0.50;
  const wantsBudget = totalIncome * 0.30;

  const needsCats = appState.categories.filter(c => (c.budgetType || getCategoryBudgetType(c.id)) !== 'wants');
  const wantsCats = appState.categories.filter(c => (c.budgetType || getCategoryBudgetType(c.id)) === 'wants');

  if (!appState.budgets[monthKey]) appState.budgets[monthKey] = {};

  if (needsCats.length > 0) {
    const perCat = Math.round(needsBudget / needsCats.length);
    needsCats.forEach(c => { appState.budgets[monthKey][c.id] = perCat; });
  }
  if (wantsCats.length > 0) {
    const perCat = Math.round(wantsBudget / wantsCats.length);
    wantsCats.forEach(c => { appState.budgets[monthKey][c.id] = perCat; });
  }

  appState.dismissedDayOneOnboarding = true;
  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();
  showToast(`🚀 Welcome to NirvTrack! Auto-balanced 50/30/20 budget allocated across ${appState.categories.length} envelopes.`, 'success', 6000);
}

function loadDayOneSampleData() {
  const monthKey = appState.activeMonth;
  if (!appState.incomes[monthKey]) {
    appState.incomes[monthKey] = { paycheck15: 45000, paycheck30: 45000, additional: 5000, carryoverSurplus: 0 };
  } else {
    appState.incomes[monthKey].paycheck15 = 45000;
    appState.incomes[monthKey].paycheck30 = 45000;
  }

  const todayStr = new Date().toISOString().split('T')[0];
  const sampleExpenses = [
    { id: 'tx_sample_1', date: todayStr, amount: 480, categoryId: appState.categories[0]?.id || 'food', description: 'Grocery Market', paymentMethod: 'GCash', budgetType: 'needs' },
    { id: 'tx_sample_2', date: todayStr, amount: 250, categoryId: appState.categories[1]?.id || 'trans', description: 'Commute / Gas', paymentMethod: 'Cash', budgetType: 'needs' },
    { id: 'tx_sample_3', date: todayStr, amount: 320, categoryId: appState.categories[2]?.id || 'dining', description: 'Lunch with Team', paymentMethod: 'Credit Card', budgetType: 'wants' }
  ];
  appState.expenses = [...(appState.expenses || []), ...sampleExpenses];
  appState.dismissedDayOneOnboarding = true;
  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();
  showToast('Demo data loaded successfully! Explore the Executive Dashboard.', 'success');
}

// --- 5. [FEAT-3SEC-MOBILE-FLOW] Dashboard Quick-Add Bar ---
function syncDashQuickAddDropdowns() {
  const catSel = document.getElementById('dashQuickAddCategorySelect');
  if (catSel) {
    const curVal = catSel.value;
    catSel.innerHTML = '<option value="">Auto Category</option>';
    (appState.categories || []).forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id;
      opt.textContent = `${c.icon} ${c.name}`;
      catSel.appendChild(opt);
    });
    if (curVal && appState.categories.some(c => c.id === curVal)) {
      catSel.value = curVal;
    }
  }
}

function handleDashQuickAddSubmit() {
  const input = document.getElementById('dashQuickAddInput');
  if (!input) return;

  const raw = input.value.trim();
  if (!raw) {
    showToast('Type an amount and description (e.g. "Starbucks 210 Food")', 'info');
    return;
  }

  const parsed = parseQuickAddExpenseString(raw);
  if (!parsed || !parsed.amount || parsed.amount <= 0) {
    showToast('Could not detect an amount. E.g. "Lunch 250 Food"', 'warning');
    return;
  }

  const catSel = document.getElementById('dashQuickAddCategorySelect');
  const paySel = document.getElementById('dashQuickAddPaymentSelect');
  const categoryId = (catSel && catSel.value) ? catSel.value : (parsed.category?.id || appState.categories[0]?.id || 'misc');
  const paymentMethod = (paySel && paySel.value) ? paySel.value : (parsed.paymentMethod || 'Credit Card');

  const todayStr = new Date().toISOString().split('T')[0];
  const newTx = {
    id: 'tx_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
    date: todayStr,
    amount: parsed.amount,
    categoryId: categoryId,
    description: parsed.description || 'Quick Add Expense',
    paymentMethod: paymentMethod,
    budgetType: getCategoryBudgetType(categoryId) || 'needs'
  };

  appState.expenses.push(newTx);
  saveData();
  triggerHapticFeedback('success');
  updateAllViews();
  input.value = '';

  const catName = getCategoryName(categoryId);
  showToast(`Logged ${formatCurrency(parsed.amount)} for "${newTx.description}" in ${catName}! ⚡`, 'success', 5000);
}

