// --- 7. Event Listeners Setup for Real-Life Focus Group Usability Suite ---
function setupRealLifeSuiteEventListeners() {
  // 1. Dashboard Quick-Add Bar
  const dashInput = document.getElementById('dashQuickAddInput');
  const btnDashSubmit = document.getElementById('btnDashQuickAddSubmit');
  if (dashInput) {
    dashInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleDashQuickAddSubmit();
      }
    });
  }
  if (btnDashSubmit) {
    btnDashSubmit.addEventListener('click', handleDashQuickAddSubmit);
  }

  // 2. Cover Overspend Modal
  const selCoverSource = document.getElementById('coverFromCategorySelect');
  if (selCoverSource) selCoverSource.addEventListener('change', updateCoverSurplusPreview);
  const inpCoverAmt = document.getElementById('coverTransferAmount');
  if (inpCoverAmt) inpCoverAmt.addEventListener('input', updateCoverSurplusPreview);
  const btnConfirmCover = document.getElementById('btnConfirmCoverOverspend');
  if (btnConfirmCover) btnConfirmCover.addEventListener('click', submitCoverOverspend);
  const btnCloseCover = document.getElementById('btnCloseCoverModal');
  if (btnCloseCover) btnCloseCover.addEventListener('click', closeCoverOverspendModal);
  const btnCancelCover = document.getElementById('btnCancelCoverModal');
  if (btnCancelCover) btnCancelCover.addEventListener('click', closeCoverOverspendModal);

  // 3. Reconcile Modal
  const inpReconAct = document.getElementById('reconcileActualBalance');
  if (inpReconAct) inpReconAct.addEventListener('input', updateReconcileDiff);
  const btnConfirmRecon = document.getElementById('btnConfirmReconcileBalance');
  if (btnConfirmRecon) btnConfirmRecon.addEventListener('click', () => saveReconcileWalletBalance(false));
  const btnReconAdj = document.getElementById('btnReconcileWithAdjustment');
  if (btnReconAdj) btnReconAdj.addEventListener('click', () => saveReconcileWalletBalance(true));
  const btnCloseRecon = document.getElementById('btnCloseReconcileModal');
  if (btnCloseRecon) btnCloseRecon.addEventListener('click', closeReconcileWalletModal);
  const btnCancelRecon = document.getElementById('btnCancelReconcileModal');
  if (btnCancelRecon) btnCancelRecon.addEventListener('click', closeReconcileWalletModal);

  // 4. Day 1 Cockpit
  const btnDay1Apply = document.getElementById('btnDay1ApplyBudget');
  if (btnDay1Apply) btnDay1Apply.addEventListener('click', applyDayOnePaychecks);
  const btnDismissDay1 = document.getElementById('btnDismissDayOneCard');
  if (btnDismissDay1) btnDismissDay1.addEventListener('click', dismissDayOneCard);
  const btnLoadSampleDay1 = document.getElementById('btnDay1LoadSample');
  if (btnLoadSampleDay1) btnLoadSampleDay1.addEventListener('click', loadDayOneSampleData);

  // 5. Bill Installments Toggle
  const chkInstall = document.getElementById('billIsInstallment');
  const divInstallFields = document.getElementById('billInstallmentFields');
  if (chkInstall && divInstallFields) {
    chkInstall.addEventListener('change', () => {
      divInstallFields.style.display = chkInstall.checked ? 'grid' : 'none';
    });
  }

  // 6. Safe Spend Horizon Toggle Pills
  const btnHorizonM = document.getElementById('btnHorizonMonth');
  const btnHorizonP = document.getElementById('btnHorizonPayday');
  if (btnHorizonM) {
    btnHorizonM.addEventListener('click', () => setSafeSpendHorizon('month'));
  }
  if (btnHorizonP) {
    btnHorizonP.addEventListener('click', () => setSafeSpendHorizon('payday'));
  }

  // 7. Mobile FAB Haptic Click
  const mobileFab = document.querySelector('.mobile-fab-center') || document.getElementById('mobileFabAddExpense');
  if (mobileFab) {
    mobileFab.addEventListener('click', () => {
      triggerHapticFeedback('medium');
    });
  }
}

