function quickUpdateForecasterEntry(type, id, field, newVal) {
  if (!id) return;
  let updated = false;

  if (type === 'expense') {
    const item = (appState.expenses || []).find(x => x.id === id);
    if (item) {
      if (field === 'amount') {
        const parsed = parseFloat(newVal);
        if (!isNaN(parsed) && parsed >= 0) {
          item.amount = parsed;
          updated = true;
        }
      } else if (field === 'description') {
        item.description = String(newVal).trim();
        updated = true;
      }
    }
  } else if (type === 'bill') {
    const bill = (appState.recurringBills || []).find(b => b.id === id);
    if (bill) {
      if (field === 'amount') {
        const parsed = parseFloat(newVal);
        if (!isNaN(parsed) && parsed >= 0) {
          bill.amount = parsed;
          updated = true;
        }
      } else if (field === 'name') {
        bill.name = String(newVal).trim();
        updated = true;
      }
    }
  } else if (type === 'planned') {
    const planned = (appState.plannedExpenses || []).find(p => p.id === id);
    if (planned) {
      if (field === 'amount') {
        const parsed = parseFloat(newVal);
        if (!isNaN(parsed) && parsed >= 0) {
          planned.amount = parsed;
          updated = true;
        }
      } else if (field === 'description') {
        planned.description = String(newVal).trim();
        updated = true;
      }
    }
  }

  if (updated) {
    if (typeof saveData === 'function') saveData();
    if (typeof updateAllViews === 'function') {
      try { updateAllViews(); } catch (e) { console.warn('updateAllViews error:', e); }
    }
    if (typeof renderForecasterViews === 'function') {
      try { renderForecasterViews(); } catch (e) { console.warn('renderForecasterViews error:', e); }
    }
    if (typeof showToast === 'function') showToast('Commitment updated & synced across all views!', 'success');
  }
}
window.quickUpdateForecasterEntry = quickUpdateForecasterEntry;


/**
 * [FEAT-FORECASTER-ACTUAL]
 * Calculates the total actual expenses logged for a given category in the target month.
 * Matches category ID or category name, accounts for refunds/offsets, and respects exclusions.
 */
function calculateCategorySpent(categoryId, targetMonth) {
  if (!categoryId) return 0;
  const month = targetMonth || (typeof appState !== 'undefined' ? appState.activeMonth : null);
  if (!month || typeof appState === 'undefined' || !Array.isArray(appState.expenses)) return 0;

  const targetIdStr = String(categoryId).toLowerCase().trim();
  const catObj = (appState.categories || []).find(c => 
    String(c.id).toLowerCase().trim() === targetIdStr || 
    (c.name && c.name.toLowerCase().trim() === targetIdStr)
  );
  const catName = catObj && catObj.name ? catObj.name.toLowerCase().trim() : null;
  const catId = catObj ? String(catObj.id).toLowerCase().trim() : targetIdStr;

  let total = 0;
  appState.expenses.forEach(e => {
    if (!e.date || !e.date.startsWith(month)) return;
    if (e.excludeFromBudget === true || e.isCreditCardPayoff === true) return;

    const eCatId = e.categoryId ? String(e.categoryId).toLowerCase().trim() : '';
    const eCatName = e.category ? String(e.category).toLowerCase().trim() : '';

    const matches = (eCatId === catId) ||
                    (catName && eCatName === catName) ||
                    (eCatName === catId) ||
                    (catName && eCatId === catName) ||
                    (eCatId === targetIdStr) ||
                    (eCatName === targetIdStr);

    if (!matches) return;

    const amt = parseFloat(e.amount) || 0;
    if (e.isRefund === true || e.type === 'refund') {
      total -= amt;
    } else {
      total += amt;
    }
  });

  return Math.round(total * 100) / 100;
}
window.calculateCategorySpent = calculateCategorySpent;
