function loadForecasterSettings() {
  try {
    const raw = localStorage.getItem('nirvtrack_forecaster_prefs');
    if (raw) {
      const prefs = JSON.parse(raw);
      if (prefs.horizon) forecasterHorizon = prefs.horizon;
      if (typeof prefs.anchorToBank === 'boolean') forecasterAnchorToBank = prefs.anchorToBank;
      if (prefs.chartBasis) forecasterChartBasis = prefs.chartBasis;
      forecasterViewLevel = 'months';
    }
  } catch (e) {}
}

function saveForecasterSettings() {
  try {
    localStorage.setItem('nirvtrack_forecaster_prefs', JSON.stringify({
      horizon: forecasterHorizon,
      anchorToBank: forecasterAnchorToBank,
      chartBasis: forecasterChartBasis,
      viewLevel: forecasterViewLevel
    }));
  } catch (e) {}
}
