// Live typing handler: stages the value and dynamically updates row + pillar previews
function handleForecasterBudgetLiveInput(inputEl, catId, activeMonth) {
  const excludedInMonth = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[activeMonth]) || [];
  const matrixCategories = (appState.categories || []).filter(c => !excludedInMonth.includes(c.id));
  const monthBudgets = (appState.budgets && appState.budgets[activeMonth]) || {};
  const cat = (appState.categories || []).find(c => c.id === catId);

  const rawVal = parseFloat(inputEl.value);
  const val = isNaN(rawVal) ? 0 : Math.max(0, rawVal);
  const actualBudgetVal = monthBudgets[catId] !== undefined ? (parseFloat(monthBudgets[catId]) || 0) : (parseFloat(cat?.defaultBudget) || 0);

  const isStaged = (val !== actualBudgetVal);
  if (isStaged) {
    forecasterStagedBudgets[catId] = val;
  } else {
    delete forecasterStagedBudgets[catId];
  }

  // 1. Calculate actual + recurring + planned for this category
  const actualSpent = typeof calculateCategorySpent === 'function' ? calculateCategorySpent(catId, activeMonth) : 0;

  let catRecurring = 0;
  const activeBillsList = (appState.recurringBills || []).filter(b => b.active !== false);
  activeBillsList.forEach(bill => {
    if (bill.categoryId !== catId) return;
    const dues = typeof getBillDueDatesForMonth === 'function' ? getBillDueDatesForMonth(bill, activeMonth) : [];
    catRecurring += getPendingBillAmountForMonth(bill, activeMonth, dues);
  });

  let catPlanned = 0;
  (appState.plannedExpenses || []).forEach(item => {
    if (item.categoryId !== catId || item.completed) return;
    const itemMonth = item.date ? item.date.substring(0, 7) : activeMonth;
    if (itemMonth === activeMonth) {
      catPlanned += (Number(item.amount) || 0);
    }
  });

  const totalCatSpend = actualSpent + catRecurring + catPlanned;
  const catSavingsContrib = val - totalCatSpend;

  const contribStr = catSavingsContrib >= 0
    ? `<span style="color:#10b981; font-weight:700;">+${formatCurrency(catSavingsContrib)} Saved</span>`
    : `<span style="color:#f43f5e; font-weight:700;">-${formatCurrency(Math.abs(catSavingsContrib))} Over</span>`;

  const diffVal = val - actualBudgetVal;
  const diffTag = isStaged
    ? `<span class="staged-diff text-${diffVal > 0 ? 'amber' : 'emerald'}" style="font-size:0.68rem; font-weight:700;">(${diffVal > 0 ? '+' : ''}${formatCurrency(diffVal)})</span>`
    : '';

  // Update both views in DOM
  ['forecasterA_'].forEach(pfx => {
    const elContrib = document.getElementById(`${pfx}contrib_${catId}`);
    if (elContrib) elContrib.innerHTML = contribStr;

    const elWrap = document.getElementById(`${pfx}wrap_${catId}`);
    if (elWrap) elWrap.classList.toggle('has-staged', isStaged);

    const elActions = document.getElementById(`${pfx}actions_${catId}`);
    if (elActions) {
      elActions.style.display = isStaged ? 'inline-flex' : 'none';
      if (isStaged) elActions.style.alignItems = 'center';
    }

    const elDiff = document.getElementById(`${pfx}diff_${catId}`);
    if (elDiff) elDiff.innerHTML = diffTag;

    const otherInput = document.querySelector(`.forecaster-budget-input[data-prefix="${pfx}"][data-cat-id="${catId}"]`);
    if (otherInput && otherInput !== inputEl && otherInput !== document.activeElement) {
      otherInput.value = val;
    }
  });

  // 2. Update Pillar metrics with staged values across visible month categories
  const m = typeof calculateMetrics === 'function' ? calculateMetrics() : { totalIncome: 0, totalBudget: 0, totalExpenses: 0 };
  let simulatedTotalBudget = 0;
  matrixCategories.forEach(c => {
    const act = monthBudgets[c.id] !== undefined ? (parseFloat(monthBudgets[c.id]) || 0) : (parseFloat(c.defaultBudget) || 0);
    simulatedTotalBudget += (forecasterStagedBudgets[c.id] !== undefined) ? forecasterStagedBudgets[c.id] : act;
  });

  const effectiveBudget = Object.keys(forecasterStagedBudgets).length > 0 ? simulatedTotalBudget : m.totalBudget;
  const budgetRatio = m.totalIncome > 0 ? (effectiveBudget / m.totalIncome) * 100 : 0;
  const guaranteedSavings = Math.max(0, m.totalIncome - effectiveBudget);
  const guaranteedRate = m.totalIncome > 0 ? (guaranteedSavings / m.totalIncome) * 100 : 0;

  let totalUnpaidBills = 0;
  activeBillsList.forEach(bill => {
    const dues = typeof getBillDueDatesForMonth === 'function' ? getBillDueDatesForMonth(bill, activeMonth) : [];
    totalUnpaidBills += getPendingBillAmountForMonth(bill, activeMonth, dues);
  });

  let totalPlannedSpend = 0;
  (appState.plannedExpenses || []).forEach(item => {
    if (item.completed) return;
    const itemMonth = item.date ? item.date.substring(0, 7) : activeMonth;
    if (itemMonth === activeMonth) {
      totalPlannedSpend += (Number(item.amount) || 0);
    }
  });

  const projectedSpend = m.totalExpenses + totalUnpaidBills + totalPlannedSpend;
  const projectedActualSavings = m.totalIncome - projectedSpend;
  const savingsDelta = projectedActualSavings - guaranteedSavings;
  const deltaBadge = savingsDelta >= 0
    ? `<span style="color: #34d399; font-weight: 600;">+${formatCurrency(savingsDelta)} Bonus Surplus</span>`
    : `<span style="color: #f87171; font-weight: 600;">${formatCurrency(savingsDelta)} Pacing Deficit</span>`;

  // Recalculate summary row totals dynamically across visible active month envelopes
  let dynSumBudget = 0;
  let dynSumActual = 0;
  let dynSumProjected = 0;
  let dynSumContrib = 0;

  matrixCategories.forEach(c => {
    const actBudget = monthBudgets[c.id] !== undefined ? (parseFloat(monthBudgets[c.id]) || 0) : (parseFloat(c.defaultBudget) || 0);
    const bVal = (forecasterStagedBudgets[c.id] !== undefined) ? forecasterStagedBudgets[c.id] : actBudget;
    const actSpent = calculateCategorySpent(c.id, activeMonth);

    let recBills = 0;
    activeBillsList.forEach(bill => {
      if (bill.categoryId !== c.id) return;
      const dues = typeof getBillDueDatesForMonth === 'function' ? getBillDueDatesForMonth(bill, activeMonth) : [];
      recBills += getPendingBillAmountForMonth(bill, activeMonth, dues);
    });

    let planBills = 0;
    (appState.plannedExpenses || []).forEach(item => {
      if (item.categoryId !== c.id || item.completed) return;
      const itemMonth = item.date ? item.date.substring(0, 7) : activeMonth;
      if (itemMonth === activeMonth) {
        planBills += (Number(item.amount) || 0);
      }
    });

    const totSpend = actSpent + recBills + planBills;
    const contrib = bVal - totSpend;

    dynSumBudget += bVal;
    dynSumActual += actSpent;
    dynSumProjected += totSpend;
    dynSumContrib += contrib;
  });

  ['forecasterA_'].forEach(pfx => {
    const elTotB = document.getElementById(pfx + 'TotalSumBudget');
    const elTotA = document.getElementById(pfx + 'TotalSumActual');
    const elTotP = document.getElementById(pfx + 'TotalSumProjected');
    const elTotC = document.getElementById(pfx + 'TotalSumContrib');

    if (elTotB) elTotB.textContent = formatCurrency(dynSumBudget);
    if (elTotA) elTotA.textContent = formatCurrency(dynSumActual);
    if (elTotP) elTotP.textContent = formatCurrency(dynSumProjected);
    if (elTotC) {
      elTotC.textContent = (dynSumContrib >= 0 ? '+' : '') + formatCurrency(dynSumContrib);
      elTotC.style.color = dynSumContrib >= 0 ? '#10b981' : '#f43f5e';
    }
  });

  ['forecasterA_'].forEach(pfx => {
    const elBudget = document.getElementById(`${pfx}PillarBudgetVal`);
    const elRatio = document.getElementById(`${pfx}PillarBudgetRatio`);
    const elSavVal = document.getElementById(`${pfx}PillarSavingsVal`);
    const elSavRate = document.getElementById(`${pfx}PillarSavingsRate`);
    const elSavSub = document.getElementById(`${pfx}PillarSavingsSub`);

    if (elBudget) elBudget.textContent = formatCurrency(effectiveBudget);
    if (elRatio) elRatio.textContent = `${budgetRatio.toFixed(1)}% of Total Income`;
    if (elSavVal) elSavVal.textContent = formatCurrency(Math.max(0, guaranteedSavings));
    if (elSavRate) elSavRate.textContent = `${guaranteedRate.toFixed(1)}% Cap`;
    if (elSavSub) elSavSub.innerHTML = `Guaranteed: ${formatCurrency(guaranteedSavings)} · ${deltaBadge}`;
    const elProjSav = document.getElementById(`${pfx}PillarProjSavings`);
    if (elProjSav) {
      const pRate = m.totalIncome > 0 ? (projectedActualSavings / m.totalIncome) * 100 : 0;
      elProjSav.style.color = projectedActualSavings >= 0 ? '#34d399' : '#f87171';
      elProjSav.innerHTML = `💰 Projected Savings: ${formatCurrency(projectedActualSavings)} <span style="opacity:.75;font-weight:500;">(${pRate.toFixed(1)}% · Income − Projected Spend)</span>`;
    }
    const elRunProjSav = document.getElementById(`${pfx}PillarRunningProjSavings`);
    if (elRunProjSav && typeof getForecasterMultiMonthSummary === 'function') {
      const mm = getForecasterMultiMonthSummary();
      elRunProjSav.style.color = mm.runningProjectedTotal >= 0 ? '#38bdf8' : '#f87171';
      elRunProjSav.innerHTML = `📈 Running Total Projected: ${formatCurrency(mm.runningProjectedTotal)} <span style="opacity:.75;font-weight:500;">(${mm.qualified.length} ${mm.qualified.length === 1 ? 'Month' : 'Months'})</span>`;
    }

    if (typeof updateForecasterSimulationMath === 'function') {
      updateForecasterSimulationMath(pfx);
    }
  });
}

// 1-Click push for a single category with instant sync across Budget Allocations
function promptPushSingleCategory(catId, activeMonth) {
  const stagedVal = forecasterStagedBudgets[catId];
  const cat = (appState.categories || []).find(c => c.id === catId);
  const monthBudgets = (appState.budgets && appState.budgets[activeMonth]) || {};
  const actualVal = monthBudgets[catId] !== undefined ? (parseFloat(monthBudgets[catId]) || 0) : (parseFloat(cat?.defaultBudget) || 0);

  if (stagedVal === undefined || stagedVal === actualVal) {
    if (typeof showToast === 'function') {
      showToast(`No staged changes to push for ${cat ? cat.name : 'Category'}.`, 'info');
    }
    return;
  }

  // 1. Commit this category directly into monthly budget state
  if (!appState.budgets[activeMonth]) {
    appState.budgets[activeMonth] = {};
  }
  appState.budgets[activeMonth][catId] = stagedVal;
  if (cat) cat.defaultBudget = stagedVal;
  delete forecasterStagedBudgets[catId];

  // 2. Direct DOM sync for category card on Budget Allocations tab
  const gridInput = document.querySelector(`.budget-amount-input[data-cat-id="${catId}"]`);
  if (gridInput) gridInput.value = stagedVal;
  const targetPill = document.getElementById(`target-pill-${catId}`);
  if (targetPill) targetPill.textContent = `Target: ${(appState && appState.currency) || '₱'}${stagedVal} ✎`;

  // 3. Save to persistence and completely refresh Budget Allocations grid & KPIs
  if (typeof saveData === 'function') saveData();
  if (typeof renderBudgetGrid === 'function') renderBudgetGrid();
  if (typeof calculateBudgetGridSummary === 'function') calculateBudgetGridSummary();
  if (typeof updateAllViews === 'function') updateAllViews();

  const diff = stagedVal - actualVal;
  const diffStr = diff >= 0 ? `+${formatCurrency(diff)}` : `-${formatCurrency(Math.abs(diff))}`;
  if (typeof showToast === 'function') {
    showToast(`🚀 Pushed ${cat ? cat.name : 'Category'} budget of ${formatCurrency(stagedVal)} (${diffStr}) to Budget Allocations!`, 'success', 2400);
  }
}

// Open confirmation modal for all staged changes
function openPushBudgetModal() {
  const modal = document.getElementById('pushBudgetModal');
  const listEl = document.getElementById('pushBudgetItemsList');
  const impactEl = document.getElementById('pushBudgetNetSavingsImpact');
  const subtitleEl = document.getElementById('pushBudgetModalSubtitle');
  if (!modal || !listEl) return;

  const activeMonth = (typeof appState !== 'undefined' && appState.activeMonth) || new Date().toISOString().slice(0, 7);
  const excludedInMonth = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[activeMonth]) || [];
  const stagedKeys = Object.keys(forecasterStagedBudgets).filter(k => !excludedInMonth.includes(k));
  const monthBudgets = (appState.budgets && appState.budgets[activeMonth]) || {};

  if (stagedKeys.length === 0) {
    if (typeof showToast === 'function') showToast('No staged budget adjustments to push.', 'info');
    return;
  }

  if (subtitleEl) {
    subtitleEl.textContent = `Review and push ${stagedKeys.length} adjustment(s) to ${activeMonth} budget`;
  }

  let netBudgetDelta = 0;
  const itemsHtml = stagedKeys.map(catId => {
    const cat = (appState.categories || []).find(c => c.id === catId);
    const actualVal = monthBudgets[catId] !== undefined ? (parseFloat(monthBudgets[catId]) || 0) : (parseFloat(cat?.defaultBudget) || 0);
    const newVal = forecasterStagedBudgets[catId];
    const delta = newVal - actualVal;
    netBudgetDelta += delta;

    const deltaClass = delta > 0 ? 'text-amber' : 'text-emerald';
    const deltaStr = delta > 0 ? `+${formatCurrency(delta)}` : `-${formatCurrency(Math.abs(delta))}`;

    return `
      <div class="push-budget-item-card">
        <div class="pbi-meta">
          <span>${cat ? (cat.icon || '&#x1F4C1;') : '&#x1F4C1;'}</span>
          <strong>${cat ? cat.name : 'Category'}</strong>
        </div>
        <div class="pbi-amounts">
          <span class="pbi-old">${formatCurrency(actualVal)}</span>
          <span>➔</span>
          <span class="pbi-new">${formatCurrency(newVal)}</span>
          <span class="pbi-delta ${deltaClass}">(${deltaStr})</span>
        </div>
      </div>
    `;
  }).join('');

  listEl.innerHTML = itemsHtml;

  // Impact: if budget is reduced, savings increase (+); if budget increases, savings decrease (-)
  const savingsImpact = -netBudgetDelta;
  if (impactEl) {
    impactEl.textContent = `${savingsImpact >= 0 ? '+' : ''}${formatCurrency(savingsImpact)} / month`;
    impactEl.style.color = savingsImpact >= 0 ? '#34d399' : '#f87171';
  }

  modal.classList.add('active');
}

function closePushBudgetModal() {
  const modal = document.getElementById('pushBudgetModal');
  if (modal) modal.classList.remove('active');
}

function executePushStagedBudgets() {
  const activeMonth = (typeof appState !== 'undefined' && appState.activeMonth) || new Date().toISOString().slice(0, 7);
  const excludedInMonth = (appState.excludedCategoriesByMonth && appState.excludedCategoriesByMonth[activeMonth]) || [];
  const stagedKeys = Object.keys(forecasterStagedBudgets).filter(k => !excludedInMonth.includes(k));
  const count = stagedKeys.length;

  if (count === 0) {
    closePushBudgetModal();
    return;
  }

  if (!appState.budgets[activeMonth]) {
    appState.budgets[activeMonth] = {};
  }

  stagedKeys.forEach(catId => {
    const val = forecasterStagedBudgets[catId];
    appState.budgets[activeMonth][catId] = val;
    const cat = (appState.categories || []).find(c => c.id === catId);
    if (cat) cat.defaultBudget = val;

    // Direct DOM sync for category card on Budget Allocations tab
    const gridInput = document.querySelector(`.budget-amount-input[data-cat-id="${catId}"]`);
    if (gridInput) gridInput.value = val;
    const targetPill = document.getElementById(`target-pill-${catId}`);
    if (targetPill) targetPill.textContent = `Target: ${(appState && appState.currency) || '₱'}${val} ✎`;
  });

  forecasterStagedBudgets = {};

  // Save to persistence and completely refresh Budget Allocations grid & KPIs
  if (typeof saveData === 'function') saveData();
  if (typeof renderBudgetGrid === 'function') renderBudgetGrid();
  if (typeof calculateBudgetGridSummary === 'function') calculateBudgetGridSummary();
  if (typeof updateAllViews === 'function') updateAllViews();

  closePushBudgetModal();

  if (typeof showToast === 'function') {
    showToast(`🚀 Pushed ${count} budget adjustment(s) to Budget Allocations successfully!`, 'success', 2500);
  }
}

function discardStagedBudgets() {
  forecasterStagedBudgets = {};
  if (typeof updateAllViews === 'function') updateAllViews();
  if (typeof showToast === 'function') {
    showToast('⎋ Staged budget adjustments reverted to actual saved allocations.', 'info');
  }
}

function handleForecasterWhatIfSlider(prefix) {
  const slider = document.getElementById(`${prefix}SliderTrim`);
  const manual = document.getElementById(`${prefix}ManualTrim`);
  const trimVal = document.getElementById(`${prefix}TrimVal`);
  const manualVal = document.getElementById(`${prefix}ManualTrimVal`);

  const pct = parseInt(slider?.value || 0, 10);
  const extra = Math.max(0, parseFloat(manual?.value || 0));

  forecasterSimulation.trimPercent = pct;
  forecasterSimulation.manualExtraTrim = extra;

  if (trimVal) trimVal.textContent = `${pct}% Trim`;
  if (manualVal) manualVal.textContent = formatCurrency(extra);

  updateForecasterSimulationMath(prefix);
  setTimeout(() => { if (typeof renderForecasterHistoryChart === 'function') renderForecasterHistoryChart(); }, 40);
}

function setWhatIfPreset(prefix, pct) {
  forecasterSimulation.trimPercent = pct;
  const slider = document.getElementById(`${prefix}SliderTrim`);
  const trimVal = document.getElementById(`${prefix}TrimVal`);
  if (slider) slider.value = pct;
  if (trimVal) trimVal.textContent = `${pct}% Trim`;
  updateForecasterSimulationMath(prefix);
  setTimeout(() => { if (typeof renderForecasterHistoryChart === 'function') renderForecasterHistoryChart(); }, 40);
}

function setWhatIfManual(prefix, amt) {
  forecasterSimulation.manualExtraTrim = amt;
  const manual = document.getElementById(`${prefix}ManualTrim`);
  const manualVal = document.getElementById(`${prefix}ManualTrimVal`);
  if (manual) manual.value = amt;
  if (manualVal) manualVal.textContent = formatCurrency(amt);
  updateForecasterSimulationMath(prefix);
  setTimeout(() => { if (typeof renderForecasterHistoryChart === 'function') renderForecasterHistoryChart(); }, 40);
}

function resetForecasterWhatIf(prefix) {
  forecasterSimulation.trimPercent = 0;
  forecasterSimulation.manualExtraTrim = 0;
  const slider = document.getElementById(`${prefix}SliderTrim`);
  const manual = document.getElementById(`${prefix}ManualTrim`);
  const trimVal = document.getElementById(`${prefix}TrimVal`);
  const manualVal = document.getElementById(`${prefix}ManualTrimVal`);
  if (slider) slider.value = 0;
  if (manual) manual.value = '';
  if (trimVal) trimVal.textContent = '0% Trim';
  if (manualVal) manualVal.textContent = formatCurrency(0);
  updateForecasterSimulationMath(prefix);
  setTimeout(() => { if (typeof renderForecasterHistoryChart === 'function') renderForecasterHistoryChart(); }, 40);
}

function updateForecasterSimulationMath(prefix) {
  const m = (typeof calculateMetrics === 'function') ? calculateMetrics() : { totalIncome: 0, totalBudget: 0, totalExpenses: 0 };
  const trimPct = forecasterSimulation.trimPercent || 0;
  const manualCut = forecasterSimulation.manualExtraTrim || 0;

  const baselineBudget = m.totalBudget;
  const trimmedBudget = Math.max(0, baselineBudget * (1 - trimPct / 100) - manualCut);
  const simSavings = Math.max(0, m.totalIncome - trimmedBudget);
  const simAnnual = simSavings * 12;

  const monthlyBurn = trimmedBudget > 0 ? trimmedBudget : (m.totalExpenses || 1);
  const runwayMonths = simSavings / Math.max(1, (monthlyBurn * 0.35));

  // 10-year annuity future value at 6% p.a.
  const r = 0.06 / 12;
  const n = 120;
  const compound10 = simSavings * ((Math.pow(1 + r, n) - 1) / r);

  const elMonthly = document.getElementById(`${prefix}SimMonthlySavings`);
  const elAnnual = document.getElementById(`${prefix}SimAnnualSavings`);
  const elRunway = document.getElementById(`${prefix}SimRunway`);
  const elCompound = document.getElementById(`${prefix}SimCompound`);
  const elMonthlySub = document.getElementById(`${prefix}SimMonthlySavingsSub`);

  if (elMonthly) elMonthly.textContent = formatCurrency(simSavings);
  if (elAnnual) elAnnual.textContent = formatCurrency(simAnnual);
  if (elRunway) elRunway.textContent = `+${runwayMonths.toFixed(1)} Mo`;
  if (elCompound) elCompound.textContent = formatCurrency(compound10);

  const extraSaved = simSavings - Math.max(0, m.totalIncome - baselineBudget);
  if (elMonthlySub) {
    elMonthlySub.textContent = extraSaved > 0 ? `+${formatCurrency(extraSaved)} extra monthly savings` : 'At current budget';
  }
}

