// ============================================================================
// [FEAT-SMART-PARSE] SMS & E-WALLET CLIPBOARD SMART-PARSER ENGINE (v1.20261021.82)
// Instant <10ms client-side regex extraction for GCash, Maya, BDO, BPI, Grab, etc.
// ============================================================================

let smartPasteActiveParsed = null;

const SAMPLE_ALERTS = {
  gcash_jollibee: "You have paid PHP 150.00 of Goods to JOLLIBEE on 10-21-26 13:45:20. Ref. No. 123456789.",
  maya_starbucks: "You have paid PHP 380.00 to STARBUCKS using Maya on 21-Oct-2026 08:30:00. Ref: MAYA992211.",
  bdo_supermarket: "You spent PHP 2,850.50 at SM SUPERMARKET on 10/21/2026 with your BDO Debit Card ending in 1234.",
  bpi_mcdo: "BPI: You paid PHP 420.00 to MCDONALDS via QR on 10/21/2026. Ref: BPI2026102101.",
  grab_transport: "GrabPay: You paid PHP 260.00 for order to GrabCar on 2026-10-21. Ref: GP884422."
};

function parseSmsNotificationText(raw) {
  if (!raw || typeof raw !== 'string') return null;
  const text = raw.trim();
  if (!text) return null;

  // 1. Amount Extraction
  let amount = null;
  const amountRegexes = [
    /(?:PHP|Php|₱|\$|€|£|SGD)\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?|[0-9]+(?:\.[0-9]{1,2})?)/i,
    /([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?|[0-9]+(?:\.[0-9]{1,2})?)\s*(?:PHP|Php|₱|\$|€|£|SGD)/i,
    /(?:paid|spent|sent|charged|amount of|total of|deducted)\s*(?:PHP|Php|₱|\$|€|£)?\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?|[0-9]+(?:\.[0-9]{1,2})?)/i,
    /(?:amount:?|total:?)\s*(?:PHP|Php|₱|\$|€|£)?\s*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{1,2})?|[0-9]+(?:\.[0-9]{1,2})?)/i
  ];

  for (const r of amountRegexes) {
    const m = text.match(r);
    if (m && m[1]) {
      const cleanNum = m[1].replace(/,/g, '');
      const parsed = parseFloat(cleanNum);
      if (!isNaN(parsed) && parsed > 0) {
        amount = parsed;
        break;
      }
    }
  }

  // 2. Reference Number extraction
  let refNo = null;
  const refMatch = text.match(/(?:Ref(?:\.|erence)?(?:\s+No\.?|:|\.)?)\s*([A-Za-z0-9_-]{5,})/i);
  if (refMatch && refMatch[1]) {
    refNo = refMatch[1].trim();
  }

  // 3. Payment Method detection
  let paymentMethod = 'Credit Card';
  if (/gcash/i.test(text)) paymentMethod = 'GCash';
  else if (/maya|paymaya/i.test(text)) paymentMethod = 'Maya';
  else if (/grabpay|grab\s+pay/i.test(text)) paymentMethod = 'GrabPay';
  else if (/shopeepay|shopee\s+pay/i.test(text)) paymentMethod = 'ShopeePay';
  else if (/bdo/i.test(text)) paymentMethod = /credit/i.test(text) ? 'Credit Card' : 'Debit Card';
  else if (/bpi/i.test(text)) paymentMethod = /credit/i.test(text) ? 'Credit Card' : 'Debit Card';
  else if (/unionbank|ub\s+/i.test(text)) paymentMethod = 'Bank Transfer';
  else if (/metrobank|security\s+bank|rcbc/i.test(text)) paymentMethod = 'Bank Transfer';
  else if (/debit\s*card/i.test(text)) paymentMethod = 'Debit Card';
  else if (/credit\s*card|visa|mastercard/i.test(text)) paymentMethod = 'Credit Card';
  else if (/cash/i.test(text)) paymentMethod = 'Cash';

  // 4. Merchant / Description extraction
  let description = '';
  const merchantPatterns = [
    /(?:paid\s+.*?(?:to|at)|spent\s+.*?(?:at|in)|sent\s+.*?(?:to)|charged\s+.*?(?:at)|used\s+at)\s+([A-Za-z0-9\s&'.-]{2,40}?)(?:\s+(?:on|using|with|via|Ref|ref|Ref\.|your|new\s+balance|from|\d{1,2}[/-]\d{1,2}|\.|$))/i,
    /(?:goods\s+to|order\s+to|payment\s+to)\s+([A-Za-z0-9\s&'.-]{2,40}?)(?:\s+(?:on|using|with|via|Ref|ref|\.|$))/i,
    /(?:to|at)\s+([A-Za-z0-9\s&'.-]{2,35}?)(?:\s+(?:on|using|with|via|Ref|ref|\d{1,2}[/-]\d{1,2}|\.|$))/i
  ];

  for (const p of merchantPatterns) {
    const m = text.match(p);
    if (m && m[1]) {
      let rawDesc = m[1].trim();
      rawDesc = rawDesc.replace(/^(goods\s+to|order\s+to)\s+/i, '').replace(/[\s.,]+$/, '');
      if (rawDesc.length >= 2 && !/^(php|usd|ref|account|card|balance|your)$/i.test(rawDesc)) {
        description = rawDesc;
        break;
      }
    }
  }

  if (!description) {
    if (/grabcar|grab\s+car/i.test(text)) description = 'GrabCar';
    else if (/grabfood|grab\s+food/i.test(text)) description = 'GrabFood';
    else if (/grab/i.test(text)) description = 'Grab';
    else if (/shopee/i.test(text)) description = 'Shopee';
    else if (/lazada/i.test(text)) description = 'Lazada';
    else if (/starbucks/i.test(text)) description = 'Starbucks';
    else if (/mcdonalds|mcdo/i.test(text)) description = 'McDonald\'s';
    else if (/jollibee/i.test(text)) description = 'Jollibee';
    else if (/meralco/i.test(text)) description = 'Meralco';
    else if (/pldt/i.test(text)) description = 'PLDT';
    else if (/sm\s+supermarket/i.test(text)) description = 'SM Supermarket';
    else description = 'Payment Transaction';
  }

  // 5. Date Extraction
  let dateStr = new Date().toISOString().split('T')[0];
  const dateMatches = [
    /(\d{4})[/-](\d{1,2})[/-](\d{1,2})/,
    /(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})/,
    /(\d{1,2})-(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)-(\d{2,4})/i,
    /(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{1,2})(?:st|nd|rd|th)?,?\s*(\d{2,4})?/i
  ];
  const monthMap = { jan:1, feb:2, mar:3, apr:4, may:5, jun:6, jul:7, aug:8, sep:9, oct:10, nov:11, dec:12 };

  for (const r of dateMatches) {
    const dm = text.match(r);
    if (dm) {
      try {
        if (dm[2] && monthMap[dm[2].toLowerCase()]) {
          const day = String(dm[1]).padStart(2, '0');
          const mNum = String(monthMap[dm[2].toLowerCase()]).padStart(2, '0');
          let yr = dm[3];
          if (yr.length === 2) yr = '20' + yr;
          dateStr = `${yr}-${mNum}-${day}`;
          break;
        } else if (monthMap[dm[1]?.toLowerCase()]) {
          const mNum = String(monthMap[dm[1].toLowerCase()]).padStart(2, '0');
          const day = String(dm[2]).padStart(2, '0');
          let yr = dm[3] || new Date().getFullYear();
          if (String(yr).length === 2) yr = '20' + yr;
          dateStr = `${yr}-${mNum}-${day}`;
          break;
        } else if (dm[1].length === 4) {
          dateStr = `${dm[1]}-${String(dm[2]).padStart(2, '0')}-${String(dm[3]).padStart(2, '0')}`;
          break;
        } else {
          let yr = dm[3];
          if (yr.length === 2) yr = '20' + yr;
          dateStr = `${yr}-${String(dm[1]).padStart(2, '0')}-${String(dm[2]).padStart(2, '0')}`;
          break;
        }
      } catch (e) {}
    }
  }

  // 6. Category Auto-Inference via Merchant Memory & Keyword Dictionary
  const cats = Array.isArray(appState.categories) ? appState.categories : [];
  let matchedCat = null;

  // Check past expenses for merchant memory
  const descLower = description.toLowerCase();
  const pastTx = (appState.expenses || []).slice().reverse().find(x =>
    x.description && (x.description.toLowerCase() === descLower || descLower.includes(x.description.toLowerCase()))
  );
  if (pastTx && pastTx.categoryId) {
    matchedCat = cats.find(c => c.id === pastTx.categoryId) || null;
  }

  // Keyword Dictionary fallback
  if (!matchedCat) {
    const combinedText = `${description} ${text}`.toLowerCase();
    const keywordRules = [
      { rx: /jollibee|mcdo|mcdonald|starbucks|chowking|kfc|food|restaurant|cafe|coffee|dining|pizza|burger|snack/i, catTerms: ['food', 'dining', 'restaurant'] },
      { rx: /supermarket|grocery|sm|robinsons|puregold|walmart|costco|market|deli/i, catTerms: ['grocer', 'supermarket', 'market'] },
      { rx: /grabcar|grab\s+car|taxi|uber|gas|shell|petron|caltex|fuel|parking|toll|transport|commute|mrt|lrt/i, catTerms: ['transport', 'car', 'fuel', 'gas'] },
      { rx: /meralco|maynilad|manila\s+water|pldt|globe|smart|electricity|water|wifi|internet|utility|bill/i, catTerms: ['utilit', 'electric', 'water', 'internet', 'bill'] },
      { rx: /mercury\s*drug|watsons|pharmacy|hospital|clinic|doctor|med|health/i, catTerms: ['health', 'medical', 'pharmacy'] },
      { rx: /shopee|lazada|amazon|uniqlo|zara|h&m|mall|retail|shop/i, catTerms: ['shop', 'retail', 'clothing'] },
      { rx: /netflix|spotify|disney|apple|youtube|steam|cinema|movie|game|entertainment/i, catTerms: ['entertain', 'subscript', 'stream'] }
    ];

    for (const rule of keywordRules) {
      if (rule.rx.test(combinedText)) {
        matchedCat = cats.find(c => {
          const cn = String(c.name || '').toLowerCase();
          return rule.catTerms.some(term => cn.includes(term));
        });
        if (matchedCat) break;
      }
    }
  }

  if (!matchedCat) {
    matchedCat = cats[0] || { id: 'misc', name: 'Miscellaneous', icon: '📦', budgetType: 'wants' };
  }

  return {
    amount: amount || 0,
    description: description || 'Payment Transaction',
    date: dateStr,
    categoryId: matchedCat.id,
    categoryName: matchedCat.name,
    budgetType: matchedCat.budgetType || 'wants',
    paymentMethod,
    refNo,
    rawText: text
  };
}

function populateSmartPasteCategories(selectedId) {
  const sel = document.getElementById('smartParsedCategory');
  if (!sel) return;
  sel.innerHTML = '';
  (appState.categories || []).forEach(c => {
    const opt = document.createElement('option');
    opt.value = c.id;
    opt.textContent = `${c.icon || '🏷️'} ${c.name}`;
    if (c.id === selectedId) opt.selected = true;
    sel.appendChild(opt);
  });
}

function openSmartPasteModal() {
  const modal = document.getElementById('smartPasteModal');
  if (!modal) return;
  triggerHapticFeedback('light');
  populateSmartPasteCategories();
  modal.classList.add('active');
  modal.setAttribute('aria-hidden', 'false');

  const input = document.getElementById('smartPasteInput');
  if (input) {
    input.value = '';
    setTimeout(() => input.focus(), 100);
  }

  // Reset preview
  smartPasteActiveParsed = null;
  const amtEl = document.getElementById('smartParsedAmount');
  if (amtEl) amtEl.textContent = formatCurrency(0);
  const badgeEl = document.getElementById('smartParsedBadge');
  if (badgeEl) {
    badgeEl.textContent = 'Paste text above';
    badgeEl.style.color = 'var(--text-muted)';
    badgeEl.style.background = 'var(--bg-tertiary)';
  }
}

function closeSmartPasteModal() {
  const modal = document.getElementById('smartPasteModal');
  if (!modal) return;
  modal.classList.remove('active');
  modal.setAttribute('aria-hidden', 'true');
}

function handleSmartPasteInput() {
  const input = document.getElementById('smartPasteInput');
  if (!input) return;
  const raw = input.value.trim();
  if (!raw) {
    smartPasteActiveParsed = null;
    const amtEl = document.getElementById('smartParsedAmount');
    if (amtEl) amtEl.textContent = formatCurrency(0);
    return;
  }

  const parsed = parseSmsNotificationText(raw);
  if (!parsed) return;
  smartPasteActiveParsed = parsed;

  const amtEl = document.getElementById('smartParsedAmount');
  if (amtEl) amtEl.textContent = formatCurrency(parsed.amount);

  const descEl = document.getElementById('smartParsedDesc');
  if (descEl) descEl.value = parsed.description;

  const dateEl = document.getElementById('smartParsedDate');
  if (dateEl) dateEl.value = parsed.date;

  const catSel = document.getElementById('smartParsedCategory');
  if (catSel && parsed.categoryId) {
    catSel.value = parsed.categoryId;
  }

  const paySel = document.getElementById('smartParsedPayment');
  if (paySel && parsed.paymentMethod) {
    paySel.value = parsed.paymentMethod;
  }

  const badgeEl = document.getElementById('smartParsedBadge');
  if (badgeEl) {
    if (parsed.amount > 0) {
      badgeEl.textContent = '⚡ Ready to Log';
      badgeEl.style.color = 'var(--accent-cyan)';
      badgeEl.style.background = 'rgba(6, 182, 212, 0.15)';
    } else {
      badgeEl.textContent = '⚠️ Check Amount';
      badgeEl.style.color = '#f59e0b';
      badgeEl.style.background = 'rgba(245, 158, 11, 0.15)';
    }
  }

  const refWrap = document.getElementById('smartParsedRefWrap');
  const refCode = document.getElementById('smartParsedRef');
  if (refWrap && refCode) {
    if (parsed.refNo) {
      refCode.textContent = parsed.refNo;
      refWrap.style.display = 'block';
    } else {
      refWrap.style.display = 'none';
    }
  }
}

function loadSampleAlert(sampleKey) {
  const sample = SAMPLE_ALERTS[sampleKey];
  if (!sample) return;
  const input = document.getElementById('smartPasteInput');
  if (input) {
    input.value = sample;
    handleSmartPasteInput();
    triggerHapticFeedback('light');
  }
}

async function readFromClipboardAndParse() {
  triggerHapticFeedback('light');
  try {
    if (navigator.clipboard && navigator.clipboard.readText) {
      const text = await navigator.clipboard.readText();
      if (text && text.trim()) {
        const input = document.getElementById('smartPasteInput');
        if (input) {
          input.value = text;
          handleSmartPasteInput();
          showToast('Text read from clipboard! 📋', 'success');
          return;
        }
      }
    }
    showToast('Clipboard empty or permission needed. You can paste directly (Ctrl+V) into the box.', 'info');
  } catch (err) {
    showToast('Paste directly into the text area below (Ctrl+V)', 'info');
  }
}

function executeSmartPasteSubmit() {
  const descEl = document.getElementById('smartParsedDesc');
  const dateEl = document.getElementById('smartParsedDate');
  const catSel = document.getElementById('smartParsedCategory');
  const paySel = document.getElementById('smartParsedPayment');

  const desc = (descEl && descEl.value.trim()) || (smartPasteActiveParsed && smartPasteActiveParsed.description) || 'Smart-Parsed Expense';
  const date = (dateEl && dateEl.value) || (smartPasteActiveParsed && smartPasteActiveParsed.date) || new Date().toISOString().split('T')[0];
  const categoryId = (catSel && catSel.value) || (smartPasteActiveParsed && smartPasteActiveParsed.categoryId) || (appState.categories[0] && appState.categories[0].id) || 'misc';
  const paymentMethod = (paySel && paySel.value) || (smartPasteActiveParsed && smartPasteActiveParsed.paymentMethod) || 'Credit Card';
  const amount = (smartPasteActiveParsed && smartPasteActiveParsed.amount) || 0;

  if (!amount || amount <= 0) {
    showToast('Please specify a valid transaction amount greater than 0.', 'warning');
    return;
  }

  const category = (appState.categories || []).find(c => c.id === categoryId);
  const budgetType = (category && category.budgetType) || 'wants';

  const newTx = {
    id: 'tx_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
    date: date,
    amount: amount,
    categoryId: categoryId,
    description: desc,
    paymentMethod: paymentMethod,
    budgetType: budgetType
  };

  appState.expenses = appState.expenses || [];
  appState.expenses.push(newTx);
  saveData();
  triggerHapticFeedback('success');
  updateAllViews();
  closeSmartPasteModal();

  showToast(`⚡ Logged "${newTx.description}" (${formatCurrency(newTx.amount)}) via Smart-Parser!`, 'success', 6000, {
    actionLabel: '↩ Undo',
    onAction: () => {
      appState.expenses = (appState.expenses || []).filter(x => x.id !== newTx.id);
      saveData();
      updateAllViews();
      showToast(`Undid "${newTx.description}"`, 'info');
    }
  });
}

