// [FIX-FORECASTER-DOUBLE-COUNT] Pending (unsettled / not-started) recurring bill amount for a month.
// Settled (already logged/paid) occurrences are NEVER counted again; bills with a future Starts From
// date ("Not Started Yet") are counted once so they are forecast without duplicating logged spend.
function getPendingBillAmountForMonth(bill, month, preDues) {
  if (!bill) return 0;
  if (bill.startDate && month && bill.startDate.slice(0, 7) > month) return 0;
  const amt = Number(bill.amount) || 0;
  const today = typeof billTodayStr === 'function' ? billTodayStr() : new Date().toISOString().split('T')[0];
  const dues = Array.isArray(preDues) ? preDues : (typeof getBillDueDatesForMonth === 'function' ? getBillDueDatesForMonth(bill, month) : []);
  const isSettled = (d) => (typeof isBillDateSettled === 'function') ? isBillDateSettled(bill, d) : false;
  const isNotStarted = Boolean(bill.startDate && bill.startDate > today);
  let effective;
  if (isNotStarted) {
    const after = dues.filter(d => d >= bill.startDate);
    effective = after.length > 0 ? after : (dues.length > 0 ? dues : [bill.startDate]);
  } else {
    effective = dues.filter(d => !(bill.startDate && d < bill.startDate));
  }
  let sum = 0;
  effective.forEach(d => { if (!isSettled(d)) sum += amt; });
  return sum;
}
window.getPendingBillAmountForMonth = getPendingBillAmountForMonth;


// ==========================================
// [FEAT-SIDEBAR-PIN] v1.20261021.95
// Sidebar Pin / Unpin (Collapse Left) & Auto-Peek Drawer
// ==========================================
const SIDEBAR_PIN_STORAGE_KEY = 'budgetMaster_sidebarCollapsed';
let _sidebarPeekLeaveTimer = null;

function applySidebarCollapsedState(isCollapsed, skipResize) {
  const body = document.body;
  if (!body) return;
  const pinBtn = document.getElementById('btnSidebarPinToggle');
  const expandBtn = document.getElementById('btnTopbarExpandSidebar');

  if (isCollapsed) {
    body.classList.add('sidebar-collapsed');
    body.classList.remove('sidebar-peek-open');
    if (pinBtn) {
      pinBtn.setAttribute('title', 'Pin Sidebar Open ( [ )');
      pinBtn.setAttribute('aria-pressed', 'true');
    }
    if (expandBtn) {
      expandBtn.style.display = 'inline-flex';
    }
  } else {
    body.classList.remove('sidebar-collapsed', 'sidebar-peek-open');
    if (pinBtn) {
      pinBtn.setAttribute('title', 'Unpin & Collapse Sidebar Left ( [ )');
      pinBtn.setAttribute('aria-pressed', 'false');
    }
    if (expandBtn) {
      expandBtn.style.display = 'none';
    }
  }

  if (!skipResize) {
    setTimeout(() => {
      window.dispatchEvent(new Event('resize'));
    }, 300);
  }
}

function toggleSidebarPin(e) {
  if (e && typeof e.stopPropagation === 'function') {
    e.stopPropagation();
  }
  const isCurrentlyCollapsed = document.body.classList.contains('sidebar-collapsed');
  const nextCollapsed = !isCurrentlyCollapsed;
  try {
    localStorage.setItem(SIDEBAR_PIN_STORAGE_KEY, nextCollapsed ? '1' : '0');
  } catch (err) {}
  applySidebarCollapsedState(nextCollapsed, false);
  if (typeof showToast === 'function') {
    showToast(
      nextCollapsed
        ? '📌 Sidebar unpinned & collapsed left (hover left edge or press [ to open)'
        : '📌 Sidebar pinned open'
    );
  }
}

function handleSidebarLeftEdgeEnter() {
  if (!document.body.classList.contains('sidebar-collapsed')) return;
  if (_sidebarPeekLeaveTimer) {
    clearTimeout(_sidebarPeekLeaveTimer);
    _sidebarPeekLeaveTimer = null;
  }
  document.body.classList.add('sidebar-peek-open');
}

function handleSidebarMouseLeave(e) {
  if (!document.body.classList.contains('sidebar-collapsed')) return;
  if (!document.body.classList.contains('sidebar-peek-open')) return;
  if (_sidebarPeekLeaveTimer) clearTimeout(_sidebarPeekLeaveTimer);
  _sidebarPeekLeaveTimer = setTimeout(() => {
    const pop = document.getElementById('sidebarFilterPopover');
    if (pop && pop.classList.contains('active')) return;
    document.body.classList.remove('sidebar-peek-open');
  }, 220);
}

function initSidebarPinState() {
  try {
    const saved = localStorage.getItem(SIDEBAR_PIN_STORAGE_KEY);
    if (saved === '1') {
      applySidebarCollapsedState(true, true);
    }
  } catch (err) {}
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initSidebarPinState);
} else {
  initSidebarPinState();
}

document.addEventListener('keydown', (e) => {
  if (e.key === '[' && !e.ctrlKey && !e.metaKey && !e.altKey) {
    const tag = (e.target && e.target.tagName) ? e.target.tagName.toUpperCase() : '';
    const isEditable = tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || (e.target && e.target.isContentEditable);
    if (!isEditable && !document.body.classList.contains('ui-mode-mobile')) {
      e.preventDefault();
      toggleSidebarPin();
    }
  }
});

window.toggleSidebarPin = toggleSidebarPin;
window.handleSidebarLeftEdgeEnter = handleSidebarLeftEdgeEnter;
window.handleSidebarMouseLeave = handleSidebarMouseLeave;
window.applySidebarCollapsedState = applySidebarCollapsedState;


