// [FEAT-EDIT-DUE-PLANNED] v1.20261021.97
// Edit Planned Expense Item Before Approving to Actual Expenses
// ==========================================
function checkDuePlannedExpenses() {
  const banner = document.getElementById('duePlannedExpenseBanner');
  if (!banner) return;

  if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-FUTURE-EXPENSES]')) {
    banner.style.display = 'none';
    return;
  }

  const today = (typeof billTodayStr === 'function') ? billTodayStr() : new Date().toISOString().split('T')[0];
  const dueItems = (appState.plannedExpenses || []).filter(item => item.date && item.date <= today);

  const countPill = document.getElementById('dpbCountPill');
  const itemsChips = document.getElementById('dpbItemsChips');
  const btnApproveAll = document.getElementById('btnDpbApproveAll');

  const dismissedToday = sessionStorage.getItem('nirvtrack_due_planned_banner_dismissed') === today;

  if (dueItems.length === 0 || dismissedToday) {
    banner.style.display = 'none';
    return;
  }

  banner.style.display = 'flex';
  if (countPill) countPill.textContent = `${dueItems.length} Due`;
  if (btnApproveAll) btnApproveAll.textContent = `✓ Approve & Post All Due (${dueItems.length})`;

  if (itemsChips) {
    const cur = appState.currency || '$';
    itemsChips.innerHTML = dueItems.slice(0, 4).map(item => {
      const isToday = item.date === today;
      const statusText = isToday ? 'Due Today' : 'Overdue';
      const statusClass = isToday ? 'chip-today' : 'chip-overdue';
      return `
        <div class="dpb-chip ${statusClass}" data-edit-id="${item.id}" title="Click to edit details before approving">
          <span class="dpb-chip-desc">${escapeHTML(item.description)}</span>
          <span class="dpb-chip-amt">${cur}${Number(item.amount).toFixed(2)}</span>
          <span class="dpb-chip-tag">${statusText}</span>
          <button type="button" class="btn-chip-edit" data-id="${item.id}" title="Edit amount, description, or category before approving">✏️</button>
          <button type="button" class="btn-chip-approve" data-id="${item.id}" title="Approve & Post to Actual Expenses">✓</button>
        </div>
      `;
    }).join('') + (dueItems.length > 4 ? `<span class="dpb-chip-more">+${dueItems.length - 4} more</span>` : '');

    itemsChips.querySelectorAll('.dpb-chip').forEach(chip => {
      chip.addEventListener('click', (e) => {
        if (e.target.closest('.btn-chip-approve') || e.target.closest('.btn-chip-edit')) return;
        const editId = chip.getAttribute('data-edit-id');
        if (editId) openPlannedExpenseModal(editId);
      });
    });

    itemsChips.querySelectorAll('.btn-chip-edit').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        openPlannedExpenseModal(btn.getAttribute('data-id'));
      });
    });

    itemsChips.querySelectorAll('.btn-chip-approve').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        approvePlannedExpenseToActual(btn.getAttribute('data-id'));
      });
    });
  }
}

function openPlannedExpenseModal(editId = null) {
  if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-FUTURE-EXPENSES]')) {
    if (typeof showUpgradePrompt === 'function') {
      showUpgradePrompt('[FEAT-FUTURE-EXPENSES]', 'One-Time Planned & Future Expenses Hub', 'expenses');
    }
    return;
  }
  const modal = document.getElementById('plannedExpenseModal');
  if (!modal) return;

  const titleEl = document.getElementById('plannedExpenseModalTitle');
  const idInput = document.getElementById('plannedExpenseId');
  const dateInput = document.getElementById('plannedExpenseDate');
  const descInput = document.getElementById('plannedExpenseDescription');
  const amtInput = document.getElementById('plannedExpenseAmount');
  const catSelect = document.getElementById('plannedExpenseCategory');
  const methodSelect = document.getElementById('plannedExpensePaymentMethod');
  const notesInput = document.getElementById('plannedExpenseNotes');
  const curLabel = document.getElementById('plannedExpenseCurrencyLabel');
  const btnSubmit = document.getElementById('btnSubmitPlannedExpense');
  const btnSaveAndApprove = document.getElementById('btnSaveAndApprovePlanned');

  if (curLabel) curLabel.textContent = appState.currency || '$';

  if (catSelect) {
    catSelect.innerHTML = `<option value="">— Uncategorized —</option>` +
      appState.categories.map(c => `<option value="${c.id}">${c.icon || '🏷️'} ${escapeHTML(c.name)}</option>`).join('');
  }

  const pSwitcher = document.getElementById('plannedExpenseTypeSwitcher');
  if (pSwitcher) {
    pSwitcher.style.display = editId ? 'none' : 'flex';
  }
  const btnPlannedOneTime = document.getElementById('btnPlannedTypeOneTime');
  const btnPlannedRecurring = document.getElementById('btnPlannedTypeRecurring');
  const btnPlannedSelf = document.getElementById('btnPlannedTypeSelf');
  if (btnPlannedOneTime) btnPlannedOneTime.classList.remove('active');
  if (btnPlannedRecurring) btnPlannedRecurring.classList.remove('active');
  if (btnPlannedSelf) btnPlannedSelf.classList.add('active');

  const today = (typeof billTodayStr === 'function') ? billTodayStr() : new Date().toISOString().split('T')[0];

  if (editId) {
    const item = (appState.plannedExpenses || []).find(p => p.id === editId);
    if (!item) return;
    if (titleEl) titleEl.textContent = 'Edit Planned Expense';
    if (idInput) idInput.value = item.id;
    if (dateInput) dateInput.value = item.date || today;
    if (descInput) descInput.value = item.description || '';
    if (amtInput) amtInput.value = item.amount || '';
    if (catSelect) catSelect.value = item.categoryId || '';
    if (methodSelect) methodSelect.value = item.paymentMethod || '';
    if (notesInput) notesInput.value = item.notes || '';
    if (btnSubmit) btnSubmit.textContent = 'Save Changes';
    if (btnSaveAndApprove) btnSaveAndApprove.style.display = 'inline-flex';
  } else {
    if (titleEl) titleEl.textContent = 'Add Planned / Future Expense';
    if (idInput) idInput.value = '';
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tomStr = `${tomorrow.getFullYear()}-${String(tomorrow.getMonth() + 1).padStart(2, '0')}-${String(tomorrow.getDate()).padStart(2, '0')}`;
    if (dateInput) dateInput.value = tomStr;
    if (descInput) descInput.value = '';
    if (amtInput) amtInput.value = '';
    if (catSelect) catSelect.value = '';
    if (methodSelect) methodSelect.value = '';
    if (notesInput) notesInput.value = '';
    if (btnSubmit) btnSubmit.textContent = 'Save Planned Expense';
    if (btnSaveAndApprove) btnSaveAndApprove.style.display = 'none';
  }

  modal.classList.add('active');
}

function handlePlannedExpenseSubmit(e) {
  if (e) e.preventDefault();

  const id = document.getElementById('plannedExpenseId')?.value || '';
  const date = document.getElementById('plannedExpenseDate')?.value || '';
  const desc = document.getElementById('plannedExpenseDescription')?.value?.trim() || '';
  const amt = resolveInputMathValue(document.getElementById('plannedExpenseAmount'));
  const categoryId = document.getElementById('plannedExpenseCategory')?.value || '';
  const paymentMethod = document.getElementById('plannedExpensePaymentMethod')?.value || '';
  const notes = document.getElementById('plannedExpenseNotes')?.value?.trim() || '';

  if (!desc) {
    showToast('Please enter a description or vendor name.', 'warning');
    return;
  }
  if (isNaN(amt) || amt <= 0) {
    showToast('Please enter a valid amount greater than zero.', 'warning');
    return;
  }
  if (!date) {
    showToast('Please select a target future date.', 'warning');
    return;
  }

  if (!Array.isArray(appState.plannedExpenses)) {
    appState.plannedExpenses = [];
  }

  const bType = categoryId ? getCategoryBudgetType(categoryId) : 'needs';

  if (id) {
    const item = appState.plannedExpenses.find(p => p.id === id);
    if (item) {
      item.date = date;
      item.description = desc;
      item.amount = amt;
      item.categoryId = categoryId;
      item.paymentMethod = paymentMethod;
      item.notes = notes;
      item.budgetType = bType;
      item.updatedAt = new Date().toISOString();
      showToast(`Updated planned expense "${desc}".`, 'success');
    }
  } else {
    const newId = 'pexp_' + Date.now().toString(36) + '_' + Math.random().toString(36).substr(2, 5);
    const newPlanned = {
      id: newId,
      date,
      description: desc,
      amount: amt,
      categoryId,
      paymentMethod,
      notes,
      budgetType: bType,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    appState.plannedExpenses.push(newPlanned);
    const cur = appState.currency || '$';
    showToast(`✓ Scheduled planned expense "${desc}" (${cur}${amt.toFixed(2)}) for ${date}!`, 'success');
  }

  closePlannedExpenseModal();
  saveData();
  if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback('success');
  updateAllViews();
  checkDuePlannedExpenses();
  renderPlannedExpensesTable();

  const dueModal = document.getElementById('duePlannedExpenseModal');
  if (dueModal && dueModal.classList.contains('active')) {
    openDuePlannedExpenseModal();
  }
}

function handlePlannedExpenseSubmitAndApprove(e) {
  if (e) e.preventDefault();
  const id = document.getElementById('plannedExpenseId')?.value || '';
  if (!id) {
    handlePlannedExpenseSubmit(e);
    return;
  }

  const date = document.getElementById('plannedExpenseDate')?.value || '';
  const desc = document.getElementById('plannedExpenseDescription')?.value?.trim() || '';
  const amt = resolveInputMathValue(document.getElementById('plannedExpenseAmount'));
  const categoryId = document.getElementById('plannedExpenseCategory')?.value || '';
  const paymentMethod = document.getElementById('plannedExpensePaymentMethod')?.value || '';
  const notes = document.getElementById('plannedExpenseNotes')?.value?.trim() || '';

  if (!desc) {
    showToast('Please enter a description or vendor name.', 'warning');
    return;
  }
  if (isNaN(amt) || amt <= 0) {
    showToast('Please enter a valid amount greater than zero.', 'warning');
    return;
  }

  const item = (appState.plannedExpenses || []).find(p => p.id === id);
  if (item) {
    const bType = categoryId ? getCategoryBudgetType(categoryId) : 'needs';
    if (date) item.date = date;
    item.description = desc;
    item.amount = amt;
    item.categoryId = categoryId;
    item.paymentMethod = paymentMethod;
    item.notes = notes;
    item.budgetType = bType;
    item.updatedAt = new Date().toISOString();
  }

  closePlannedExpenseModal();
  approvePlannedExpenseToActual(id);

  const dueModal = document.getElementById('duePlannedExpenseModal');
  if (dueModal && dueModal.classList.contains('active')) {
    openDuePlannedExpenseModal();
  }
}

function openDuePlannedExpenseModal() {
  if (typeof canAccessFeature === 'function' && !canAccessFeature('[FEAT-FUTURE-EXPENSES]')) {
    return;
  }
  const modal = document.getElementById('duePlannedExpenseModal');
  if (!modal) return;

  const today = (typeof billTodayStr === 'function') ? billTodayStr() : new Date().toISOString().split('T')[0];
  const dueItems = (appState.plannedExpenses || []).filter(item => item.date && item.date <= today);
  const cur = appState.currency || '$';

  const listEl = document.getElementById('duePlannedModalList');
  const countEl = document.getElementById('duePlannedModalCount');
  if (countEl) countEl.textContent = `${dueItems.length} item(s) due`;

  if (listEl) {
    if (dueItems.length === 0) {
      listEl.innerHTML = `
        <div style="text-align: center; padding: 30px; color: var(--text-secondary);">
          <div style="font-size: 2rem; margin-bottom: 8px;">🎉</div>
          <h4>No Planned Expenses Due!</h4>
          <p>All upcoming commitments are safely scheduled for future dates.</p>
        </div>
      `;
    } else {
      listEl.innerHTML = dueItems.map(item => {
        const cat = appState.categories.find(c => c.id === item.categoryId) || (item.categoryId ? { name: item.categoryId, icon: '🏷️' } : { name: 'Uncategorized', icon: '❓' });
        const isToday = item.date === today;
        return `
          <div class="due-modal-item-card">
            <div class="due-card-left">
              <span class="due-cat-icon">${cat.icon || '🏷️'}</span>
              <div class="due-card-info">
                <strong>${escapeHTML(item.description)}</strong>
                <div class="due-card-meta">
                  <span>${escapeHTML(cat.name)}</span>
                  <span>•</span>
                  <span>${formatShortDate(item.date)} (${isToday ? 'Today' : 'Overdue'})</span>
                  ${item.paymentMethod ? `<span>•</span> <span>${escapeHTML(item.paymentMethod)}</span>` : ''}
                </div>
              </div>
            </div>
            <div class="due-card-right">
              <span class="due-card-amount">${cur}${Number(item.amount).toFixed(2)}</span>
              <div class="due-card-actions">
                <button type="button" class="btn btn-sm btn-secondary btn-modal-edit-due" data-id="${item.id}" title="Edit details before approving">
                  ✏️ Edit
                </button>
                <button type="button" class="btn btn-sm btn-primary btn-modal-approve-due" data-id="${item.id}" title="Approve & Post to Actual">
                  ✓ Approve
                </button>
                <button type="button" class="btn btn-sm btn-secondary btn-modal-reschedule-due" data-id="${item.id}" title="Postpone">
                  📅 Postpone
                </button>
                <button type="button" class="btn btn-sm btn-ghost btn-modal-del-due" data-id="${item.id}" title="Delete / Skip">
                  🗑️
                </button>
              </div>
            </div>
          </div>
        `;
      }).join('');

      listEl.querySelectorAll('.btn-modal-edit-due').forEach(b => {
        b.addEventListener('click', () => {
          openPlannedExpenseModal(b.getAttribute('data-id'));
        });
      });
      listEl.querySelectorAll('.btn-modal-approve-due').forEach(b => {
        b.addEventListener('click', () => {
          approvePlannedExpenseToActual(b.getAttribute('data-id'));
          openDuePlannedExpenseModal();
        });
      });
      listEl.querySelectorAll('.btn-modal-reschedule-due').forEach(b => {
        b.addEventListener('click', () => {
          openReschedulePlannedModal(b.getAttribute('data-id'));
        });
      });
      listEl.querySelectorAll('.btn-modal-del-due').forEach(b => {
        b.addEventListener('click', () => {
          deletePlannedExpense(b.getAttribute('data-id'));
          openDuePlannedExpenseModal();
        });
      });
    }
  }

  modal.classList.add('active');
}

window.checkDuePlannedExpenses = checkDuePlannedExpenses;
window.openPlannedExpenseModal = openPlannedExpenseModal;
window.handlePlannedExpenseSubmit = handlePlannedExpenseSubmit;
window.handlePlannedExpenseSubmitAndApprove = handlePlannedExpenseSubmitAndApprove;
window.openDuePlannedExpenseModal = openDuePlannedExpenseModal;
